window.BANCO = [{"id":"D1-a-001","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual benefício da computação em nuvem permite implantar uma aplicação em várias Regiões da AWS com poucos cliques?","alternativas":[{"texto":"Tornar-se global em minutos","correta":true,"porque":"A infraestrutura global da AWS permite implantar em várias Regiões do mundo rapidamente, com poucos cliques."},{"texto":"Beneficiar-se de enormes economias de escala","correta":false,"porque":"Refere-se a custos variáveis menores graças ao volume agregado de clientes, não ao alcance geográfico."},{"texto":"Parar de gastar dinheiro com a operação de data centers","correta":false,"porque":"Trata de deixar de cuidar da infraestrutura física, não de implantar em várias Regiões."},{"texto":"Parar de adivinhar necessidades de capacidade","correta":false,"porque":"Refere-se a ajustar a capacidade à demanda real, não à expansão geográfica."}],"explicacao":"\"Go global in minutes\" é uma das seis vantagens da nuvem: implantar em várias Regiões e atender usuários do mundo todo com menor latência, com poucos cliques e baixo custo.","servicos":[],"dificuldade":1,"fonte":"usuario-A31"},{"id":"D1-a-002","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual afirmação MELHOR descreve a agilidade na AWS Cloud?","alternativas":[{"texto":"Permite hospedar aplicações em várias Regiões da AWS ao redor do mundo","correta":false,"porque":"Descreve o alcance global (go global in minutes), não a agilidade."},{"texto":"Permite pagar adiantado para reduzir custos","correta":false,"porque":"Descreve modelos de compromisso, como Reserved Instances, e não agilidade."},{"texto":"Permite provisionar recursos em minutos, apoiando uma inovação mais rápida","correta":true,"porque":"Reduzir de semanas para minutos o tempo de obtenção de recursos é a essência da agilidade."},{"texto":"Oferece hardware físico personalizável ao menor custo possível","correta":false,"porque":"A AWS não oferece hardware físico personalizável; o cliente consome recursos virtualizados padronizados."}],"explicacao":"Agilidade significa ter recursos de TI disponíveis em minutos, o que reduz o tempo e o custo de experimentar e acelera a inovação.","servicos":[],"dificuldade":1,"fonte":"usuario-B71"},{"id":"D1-a-003","dominio":1,"task":"1.1","tipo":"multipla","selecionar":2,"enunciado":"Quais características da AWS dão às organizações maior velocidade de execução e agilidade? (Selecione DUAS.)","alternativas":[{"texto":"Recursos prontamente disponíveis, com baixo tempo de provisionamento","correta":true,"porque":"Obter recursos em minutos, em vez de semanas, acelera a execução de projetos."},{"texto":"Capacidade de computação escalável conforme a necessidade","correta":true,"porque":"Escalar sem comprar hardware permite responder rapidamente a novas demandas."},{"texto":"Uso de serviços do AWS Free Tier","correta":false,"porque":"O Free Tier reduz o custo de experimentação inicial, mas tem limites e não é a fonte da velocidade de execução."},{"texto":"Acesso físico aos data centers da AWS","correta":false,"porque":"Clientes não têm acesso físico aos data centers da AWS."},{"texto":"Taxas menores de transferência de dados","correta":false,"porque":"Preço de transferência é questão de custo, não de velocidade ou agilidade."}],"explicacao":"Velocidade e agilidade vêm do provisionamento quase instantâneo e da capacidade de escalar sem adquirir infraestrutura física.","servicos":[],"dificuldade":2,"fonte":"usuario-B73"},{"id":"D1-a-004","dominio":1,"task":"1.1","tipo":"multipla","selecionar":2,"enunciado":"Na AWS, a elasticidade refere-se a quais conceitos? (Selecione DUAS.)","alternativas":[{"texto":"A rapidez com que uma instância do Amazon EC2 pode ser reiniciada","correta":false,"porque":"Tempo de reinicialização não tem relação com ajustar a capacidade à demanda."},{"texto":"A capacidade de ajustar os recursos conforme a demanda varia","correta":true,"porque":"Aumentar e reduzir recursos acompanhando a demanda é a definição de elasticidade."},{"texto":"A quantidade máxima de RAM que uma instância do Amazon EC2 suporta","correta":false,"porque":"É uma especificação do tipo de instância, não elasticidade."},{"texto":"O modelo de pagamento conforme o uso (pay-as-you-go)","correta":false,"porque":"É um modelo de preço; combina com a elasticidade, mas não é o mesmo conceito."},{"texto":"A facilidade de obter recursos quando necessários","correta":true,"porque":"Obter recursos sob demanda, sem compras antecipadas, faz parte da elasticidade."}],"explicacao":"Elasticidade é obter recursos com facilidade quando necessários e liberá-los quando não forem mais, acompanhando a demanda.","servicos":["EC2"],"dificuldade":2,"fonte":"usuario-B79"},{"id":"D1-a-005","dominio":1,"task":"1.1","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa tem clientes em muitos países. Quais recursos da AWS Cloud ajudam a reduzir a latência para esses clientes? (Selecione DUAS.)","alternativas":[{"texto":"Implantar a aplicação em várias Regiões da AWS, próximas aos clientes","correta":true,"porque":"Executar a aplicação perto dos usuários reduz a distância percorrida pela rede."},{"texto":"Usar as edge locations do Amazon CloudFront espalhadas pelo mundo","correta":true,"porque":"O CloudFront entrega conteúdo em cache a partir de edge locations próximas aos usuários."},{"texto":"Usar o Amazon Translate para traduzir a interface do site","correta":false,"porque":"O Translate traduz textos; não interfere na latência."},{"texto":"Usar o Amazon Comprehend para responder a usuários em vários idiomas","correta":false,"porque":"O Comprehend faz análise de linguagem natural; não reduz latência."},{"texto":"Usar um único Elastic Load Balancer para distribuir o tráfego entre Regiões","correta":false,"porque":"O Elastic Load Balancing é regional: distribui tráfego entre destinos de uma Região, não entre Regiões."}],"explicacao":"O alcance global da AWS (várias Regiões e uma ampla rede de edge locations) permite servir usuários de qualquer lugar com baixa latência.","servicos":["CloudFront","Translate","Comprehend","Elastic Load Balancing"],"dificuldade":2,"fonte":"kananinirav-k9#37"},{"id":"D1-a-006","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma empresa de comércio online precisa entregar novas funcionalidades de forma iterativa e com o MENOR tempo de lançamento no mercado. Qual benefício da AWS Cloud atende a esse objetivo?","alternativas":[{"texto":"Elasticidade","correta":false,"porque":"Ajusta a capacidade à demanda; não trata do tempo para lançar funcionalidades."},{"texto":"Agilidade","correta":true,"porque":"Recursos em minutos e serviços prontos permitem experimentar e lançar novidades rapidamente."},{"texto":"Alta disponibilidade","correta":false,"porque":"Mantém a aplicação acessível durante falhas; não acelera a entrega."},{"texto":"Confiabilidade","correta":false,"porque":"Trata de funcionar corretamente e se recuperar de falhas, não de reduzir o time to market."}],"explicacao":"Agilidade reduz o tempo para experimentar, desenvolver e lançar novas funcionalidades.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k19#48"},{"id":"D1-a-007","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Como a AWS Cloud pode aumentar a produtividade das equipes após a migração de um data center on-premises?","alternativas":[{"texto":"As equipes deixam de ter responsabilidades de segurança e conformidade","correta":false,"porque":"Pelo modelo de responsabilidade compartilhada, o cliente continua responsável pela segurança na nuvem."},{"texto":"O hardware da AWS é sempre mais rápido que o de qualquer data center local","correta":false,"porque":"Não há garantia de hardware sempre mais rápido; o ganho vem da disponibilidade imediata de recursos."},{"texto":"A AWS assume o gerenciamento de configuração das aplicações do cliente","correta":false,"porque":"A configuração das aplicações continua sendo responsabilidade do cliente."},{"texto":"As equipes não precisam esperar semanas pelo provisionamento de infraestrutura","correta":true,"porque":"Recursos ficam disponíveis em minutos, eliminando a espera por compra e instalação de hardware."}],"explicacao":"Na nuvem, as equipes obtêm infraestrutura sob demanda e dedicam o tempo a entregar valor, em vez de esperar por provisionamento.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k12#37"},{"id":"D1-a-008","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual cenário exemplifica AGILIDADE, e não elasticidade?","alternativas":[{"texto":"Uma equipe cria um ambiente de testes em minutos para validar uma ideia e o exclui no mesmo dia","correta":true,"porque":"Obter recursos rapidamente e descartá-los a baixo custo, para experimentar, é agilidade."},{"texto":"O número de instâncias aumenta durante um pico de vendas e diminui depois dele","correta":false,"porque":"Ajustar automaticamente a capacidade à demanda é elasticidade."},{"texto":"A aplicação continua acessível quando um de seus servidores falha","correta":false,"porque":"Continuar operando apesar de falhas é alta disponibilidade."},{"texto":"O preço por unidade de armazenamento cai à medida que a AWS cresce","correta":false,"porque":"Preços menores pelo volume agregado refletem economias de escala."}],"explicacao":"Agilidade é a velocidade e o baixo custo para obter recursos e experimentar; elasticidade é acompanhar a variação da demanda.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-009","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma empresa mantém um data center secundário quase ocioso apenas para recuperação de desastres. Qual vantagem a AWS Cloud oferece nesse cenário?","alternativas":[{"texto":"Garantir que a aplicação nunca fique indisponível, sem nenhuma configuração","correta":false,"porque":"Nenhum provedor garante disponibilidade total sem que o cliente arquitete para isso."},{"texto":"Eliminar completamente a necessidade de planejar a recuperação de desastres","correta":false,"porque":"O cliente continua responsável por planejar e testar sua estratégia de recuperação."},{"texto":"Manter recursos mínimos de recuperação e escalar só quando necessário, pagando pelo uso","correta":true,"porque":"Na nuvem, o ambiente de recuperação pode ficar reduzido e crescer apenas em um desastre, sem hardware ocioso."},{"texto":"Comprar servidores físicos com desconto para o site secundário","correta":false,"porque":"Na AWS o cliente não compra servidores físicos; consome recursos sob demanda."}],"explicacao":"A nuvem substitui a capacidade ociosa de um site secundário por recursos sob demanda, pagos apenas quando usados.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-010","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual benefício da AWS Cloud elimina a necessidade de estimar o uso futuro de infraestrutura antes de comprá-la?","alternativas":[{"texto":"A implantação rápida de aplicações em várias Regiões do mundo","correta":false,"porque":"Trata do alcance global, não do dimensionamento de capacidade."},{"texto":"A elasticidade da AWS Cloud","correta":true,"porque":"Como recursos são adicionados e removidos conforme a demanda real, não é preciso comprar capacidade com base em previsões."},{"texto":"Custos variáveis menores graças às economias de escala","correta":false,"porque":"Reduz o preço unitário, mas não elimina a necessidade de prever capacidade."},{"texto":"A segurança da AWS Cloud","correta":false,"porque":"Segurança não tem relação com prever o uso futuro de capacidade."}],"explicacao":"Com elasticidade, a capacidade acompanha a demanda real; o cliente deixa de comprar infraestrutura com base em estimativas.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k12#24"},{"id":"D1-a-011","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual afirmação diferencia corretamente elasticidade de escalabilidade?","alternativas":[{"texto":"Elasticidade é manter a aplicação no ar durante falhas, e escalabilidade é recuperar dados após desastres","correta":false,"porque":"Essas definições descrevem alta disponibilidade e recuperação de desastres."},{"texto":"Escalabilidade vale apenas para armazenamento, enquanto elasticidade vale apenas para recursos de computação","correta":false,"porque":"Os dois conceitos se aplicam a computação, armazenamento, bancos de dados e outros recursos."},{"texto":"Elasticidade exige compromisso de 1 ou 3 anos, enquanto escalabilidade está disponível sob demanda","correta":false,"porque":"Nenhum dos conceitos depende de prazo de compromisso; isso é característica de modelos de preço."},{"texto":"Escalabilidade é crescer para atender a mais demanda; elasticidade é aumentar e reduzir recursos acompanhando a demanda","correta":true,"porque":"A escalabilidade foca em suportar crescimento; a elasticidade acrescenta o ajuste nos dois sentidos, normalmente automático."}],"explicacao":"Escalabilidade: capacidade de crescer. Elasticidade: crescer e encolher dinamicamente conforme a demanda, pagando só pelo necessário.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-012","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual prática recomendada na AWS Cloud aproveita a elasticidade e a agilidade da computação em nuvem?","alternativas":[{"texto":"Escalar de forma dinâmica e preditiva para atender à demanda","correta":true,"porque":"Ajustar a capacidade dinamicamente, ou antecipando padrões previsíveis, usa a elasticidade e a agilidade da nuvem."},{"texto":"Provisionar capacidade com base no uso passado e em picos teóricos","correta":false,"porque":"É a prática típica do on-premises, que gera capacidade ociosa ou insuficiente."},{"texto":"Construir a aplicação em um data center com acesso físico liberado","correta":false,"porque":"Acesso físico não tem relação com elasticidade e não é oferecido pela AWS."},{"texto":"Manter servidores fixos dimensionados para o maior pico do ano","correta":false,"porque":"Dimensionar para o pico desperdiça recursos na maior parte do tempo."}],"explicacao":"Na nuvem, a capacidade deve acompanhar a demanda (escala dinâmica e preditiva), em vez de ser fixada por estimativas de pico.","servicos":["Auto Scaling"],"dificuldade":2,"fonte":"kananinirav-k20#38"},{"id":"D1-a-013","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Um sistema na AWS Cloud foi projetado para continuar operando mesmo quando um ou mais de seus componentes falham. Isso é um exemplo de quê?","alternativas":[{"texto":"Elasticidade","correta":false,"porque":"Elasticidade é ajustar a capacidade à demanda, não resistir a falhas."},{"texto":"Escalabilidade","correta":false,"porque":"Escalabilidade é a capacidade de crescer para atender a mais demanda."},{"texto":"Alta disponibilidade","correta":true,"porque":"Manter o sistema acessível apesar da falha de componentes é alta disponibilidade."},{"texto":"Agilidade","correta":false,"porque":"Agilidade é a velocidade para obter recursos e inovar."}],"explicacao":"Alta disponibilidade é a capacidade de um sistema continuar acessível, com mínimo tempo de inatividade, mesmo quando componentes falham.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k18#24"},{"id":"D1-a-014","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Por que é mais simples alcançar alta disponibilidade na AWS Cloud do que em um data center on-premises?","alternativas":[{"texto":"A AWS garante 100% de disponibilidade para qualquer aplicação, sem esforço do cliente","correta":false,"porque":"Não existe garantia de 100%; o cliente precisa arquitetar a aplicação para alta disponibilidade."},{"texto":"A AWS oferece vários data centers isolados em cada Região, sem que o cliente construa instalações","correta":true,"porque":"O cliente distribui recursos em várias Availability Zones sem investir em um segundo data center."},{"texto":"As instâncias do Amazon EC2 nunca falham, pois usam hardware redundante da AWS","correta":false,"porque":"Qualquer componente pode falhar; por isso se projeta para falhas."},{"texto":"A alta disponibilidade é ativada automaticamente em todas as contas e em todos os serviços","correta":false,"porque":"Em muitos serviços o cliente precisa escolher a configuração, como distribuir instâncias em várias AZs."}],"explicacao":"A infraestrutura global da AWS torna barato e rápido distribuir cargas por locais isolados, algo caro e demorado de construir on-premises.","servicos":["EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-015","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual benefício da computação em nuvem a AWS demonstra ao oferecer custos variáveis menores graças ao seu enorme volume de compras?","alternativas":[{"texto":"Preço conforme o uso (pay-as-you-go)","correta":false,"porque":"Descreve pagar apenas pelo que se usa, não o efeito do volume de compras sobre o preço."},{"texto":"Alta disponibilidade","correta":false,"porque":"Não tem relação com preço ou volume de compras."},{"texto":"Alcance global","correta":false,"porque":"Refere-se à presença geográfica da infraestrutura."},{"texto":"Economias de escala","correta":true,"porque":"Agregando o uso de milhões de clientes, a AWS obtém custos menores e os repassa em preços menores."}],"explicacao":"Economias de escala: o volume agregado de clientes permite à AWS operar com custo menor e cobrar preços variáveis menores.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k23#47"},{"id":"D1-a-016","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Como os clientes se beneficiam, na prática, das enormes economias de escala da AWS?","alternativas":[{"texto":"Com reduções periódicas de preço, resultado da eficiência operacional da AWS","correta":true,"porque":"A AWS repassa os ganhos de escala em reduções de preço ao longo do tempo."},{"texto":"Com novos tipos de instância do Amazon EC2 com o hardware mais recente","correta":false,"porque":"Lançar hardware novo é inovação, não efeito de economia de escala."},{"texto":"Com a capacidade de aumentar e reduzir recursos quando necessário","correta":false,"porque":"Isso é elasticidade."},{"texto":"Com hardware subjacente das instâncias que nunca apresenta falhas","correta":false,"porque":"Escala não elimina falhas de hardware, e nenhum hardware é infalível."}],"explicacao":"O benefício concreto da economia de escala é pagar menos: a AWS já reduziu preços muitas vezes à medida que cresceu.","servicos":["EC2"],"dificuldade":2,"fonte":"kananinirav-k9#25"},{"id":"D1-a-017","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual é um benefício de usar a AWS Cloud?","alternativas":[{"texto":"Segurança permissiva que elimina o trabalho administrativo","correta":false,"porque":"Segurança permissiva é um risco, e o cliente mantém responsabilidades de segurança."},{"texto":"Controle sobre o hardware de rede da nuvem","correta":false,"porque":"O hardware físico é gerenciado exclusivamente pela AWS."},{"texto":"Capacidade de concentrar-se em atividades que geram receita","correta":true,"porque":"Ao deixar a infraestrutura com a AWS, a empresa investe tempo no que diferencia o negócio."},{"texto":"Escolha dos fornecedores específicos do hardware da nuvem","correta":false,"porque":"O cliente não escolhe fabricantes de hardware na AWS."}],"explicacao":"Um benefício central da nuvem é parar de gastar esforço com trabalho pesado indiferenciado e focar nos clientes e no negócio.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k9#19"},{"id":"D1-a-018","dominio":1,"task":"1.1","tipo":"multipla","selecionar":2,"enunciado":"Quais são benefícios de desenvolver e executar uma nova aplicação na AWS Cloud em vez de on-premises? (Selecione DUAS.)","alternativas":[{"texto":"A AWS replica automaticamente os dados entre Regiões para maior durabilidade","correta":false,"porque":"Os dados ficam na Região escolhida; a replicação entre Regiões precisa ser configurada pelo cliente."},{"texto":"A AWS passa a operar a aplicação em nome do cliente","correta":false,"porque":"A operação da aplicação continua sendo responsabilidade do cliente."},{"texto":"A AWS facilita arquitetar para alta disponibilidade","correta":true,"porque":"Várias AZs e serviços gerenciados tornam a alta disponibilidade acessível sem construir data centers."},{"texto":"A AWS acomoda facilmente mudanças na demanda da aplicação","correta":true,"porque":"A elasticidade permite acompanhar a demanda sem comprar hardware."},{"texto":"A AWS aplica os patches de segurança do código da aplicação","correta":false,"porque":"O código e as dependências da aplicação são responsabilidade do cliente."}],"explicacao":"Alta disponibilidade e elasticidade estão ao alcance de qualquer cliente na AWS, sem investimento em infraestrutura física.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k12#11"},{"id":"D1-a-019","dominio":1,"task":"1.1","tipo":"multipla","selecionar":2,"enunciado":"Quais são benefícios de usar um serviço gerenciado da AWS, como o Amazon RDS? (Selecione DUAS.)","alternativas":[{"texto":"Controle completo sobre a infraestrutura subjacente","correta":false,"porque":"Em serviços gerenciados, a AWS controla a infraestrutura e o sistema operacional."},{"texto":"Permite entregar novas soluções mais rapidamente","correta":true,"porque":"Sem precisar instalar e manter o software base, a equipe entrega mais rápido."},{"texto":"Reduz a complexidade operacional","correta":true,"porque":"A AWS cuida de tarefas como provisionamento, patches e backups."},{"texto":"Elimina a necessidade de criptografar os dados","correta":false,"porque":"Proteger os dados continua sendo responsabilidade do cliente."},{"texto":"Permite que os desenvolvedores controlem todos os patches do sistema operacional","correta":false,"porque":"Em serviços gerenciados, a AWS aplica os patches do sistema operacional."}],"explicacao":"Serviços gerenciados transferem à AWS tarefas operacionais repetitivas, reduzindo complexidade e acelerando a entrega.","servicos":["RDS"],"dificuldade":2,"fonte":"kananinirav-k4#11"},{"id":"D1-a-020","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma empresa quer aproveitar a elasticidade da AWS Cloud para não pagar por servidores ociosos fora dos horários de pico. Qual recurso permite isso?","alternativas":[{"texto":"Implantar os recursos em outra Região","correta":false,"porque":"Mudar de Região não ajusta a capacidade à demanda."},{"texto":"Amazon EC2 Auto Scaling","correta":true,"porque":"Adiciona e remove instâncias automaticamente conforme a demanda, cobrando apenas pelo que roda."},{"texto":"Elastic Load Balancing","correta":false,"porque":"Distribui o tráfego entre instâncias, mas não adiciona nem remove capacidade."},{"texto":"Reserved Instances de 3 anos","correta":false,"porque":"São compromisso de capacidade fixa, o oposto de pagar só pelo necessário em cada momento."}],"explicacao":"O Auto Scaling é a forma clássica de colocar a elasticidade em prática: capacidade que cresce e encolhe com a demanda.","servicos":["Auto Scaling","Elastic Load Balancing"],"dificuldade":1,"fonte":"kananinirav-k8#35 (reescrita)"},{"id":"D1-a-021","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma empresa não quer mais lidar com racks, energia, refrigeração e manutenção de servidores físicos. Qual vantagem da computação em nuvem atende a esse objetivo?","alternativas":[{"texto":"Tornar-se global em minutos","correta":false,"porque":"Trata de implantar em várias Regiões, não de deixar de cuidar da infraestrutura física."},{"texto":"Parar de adivinhar necessidades de capacidade","correta":false,"porque":"Trata de ajustar a capacidade à demanda real."},{"texto":"Beneficiar-se de enormes economias de escala","correta":false,"porque":"Refere-se a preços menores pelo volume agregado de clientes, não ao fim da gestão de data centers."},{"texto":"Parar de gastar dinheiro com a operação e a manutenção de data centers","correta":true,"porque":"A AWS assume racks, energia, refrigeração e hardware, e a empresa foca no negócio."}],"explicacao":"Uma das seis vantagens da nuvem é deixar o trabalho pesado indiferenciado dos data centers com a AWS.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-022","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Qual característica da AWS Cloud permite que uma empresa obtenha recursos de TI quando precisar, sem compromisso inicial, pagando apenas pelo que consumir?","alternativas":[{"texto":"Autoatendimento sob demanda com pagamento conforme o uso","correta":true,"porque":"Recursos são provisionados quando necessários e cobrados apenas pelo consumo."},{"texto":"Compra antecipada de hardware dimensionado para o pico","correta":false,"porque":"É o modelo tradicional, com investimento inicial e capacidade ociosa."},{"texto":"Reserved Instances com pagamento All Upfront","correta":false,"porque":"Exigem compromisso de 1 ou 3 anos e pagamento antecipado."},{"texto":"Contratos de colocation de longo prazo","correta":false,"porque":"Colocation exige contrato e a compra do próprio hardware."}],"explicacao":"A proposta de valor da nuvem inclui autoatendimento sob demanda e pagamento conforme o uso, sem compromisso inicial.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-a-023","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma equipe distribuiu as instâncias de uma aplicação em duas Availability Zones atrás de um load balancer e configurou o Amazon EC2 Auto Scaling para adicionar instâncias nos picos. Qual afirmação associa corretamente cada medida ao benefício?","alternativas":[{"texto":"Várias AZs oferecem elasticidade; o Auto Scaling aumenta a disponibilidade","correta":false,"porque":"Inverte os conceitos: AZs isoladas evitam ponto único de falha; ajustar a capacidade é elasticidade."},{"texto":"As duas medidas servem principalmente para reduzir a latência global","correta":false,"porque":"Ambas ficam na mesma Região; reduzir latência global exige outras Regiões ou edge locations."},{"texto":"Várias AZs aumentam a disponibilidade; o Auto Scaling oferece elasticidade","correta":true,"porque":"Distribuir em AZs mantém a aplicação no ar se uma falhar; o Auto Scaling acompanha a demanda."},{"texto":"Várias AZs geram economias de escala; o Auto Scaling aumenta a agilidade","correta":false,"porque":"Economias de escala dizem respeito a preço, e o Auto Scaling se relaciona à elasticidade."}],"explicacao":"Alta disponibilidade vem da redundância em locais isolados (AZs); elasticidade vem do ajuste automático da capacidade (Auto Scaling).","servicos":["Auto Scaling","Elastic Load Balancing","EC2"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-024","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma aplicação teve forte crescimento internacional, e usuários de outros continentes reclamam de alta latência. Qual característica da AWS pode melhorar a experiência desses usuários?","alternativas":[{"texto":"Elasticidade","correta":false,"porque":"Ajusta a capacidade à demanda, mas não aproxima a aplicação dos usuários."},{"texto":"Alcance global","correta":true,"porque":"Regiões e edge locations no mundo todo permitem servir usuários de perto, com menor latência."},{"texto":"Durabilidade dos dados","correta":false,"porque":"Trata de não perder dados, não de latência."},{"texto":"Alta disponibilidade","correta":false,"porque":"Mantém a aplicação no ar durante falhas, mas não reduz a distância até os usuários."}],"explicacao":"O alcance global da AWS permite colocar aplicações e conteúdo perto dos usuários finais, reduzindo a latência.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k3#19"},{"id":"D1-a-025","dominio":1,"task":"1.1","tipo":"unica","enunciado":"Uma varejista quer lançar sua loja online em três novos países no mesmo trimestre, sem construir nem alugar data centers. Qual característica da infraestrutura global da AWS MAIS contribui para isso?","alternativas":[{"texto":"Acesso físico do cliente aos data centers da AWS para instalar seus servidores","correta":false,"porque":"Clientes não têm acesso físico nem instalam servidores próprios nos data centers da AWS."},{"texto":"Um data center central que atende todos os países com a mesma latência","correta":false,"porque":"A latência depende da distância; a AWS distribui a infraestrutura em várias Regiões justamente por isso."},{"texto":"AWS Outposts instalados em cada país, sob responsabilidade do cliente","correta":false,"porque":"Outposts levam infraestrutura AWS a locais do cliente e exigem instalação física; não é o caminho mais rápido."},{"texto":"Regiões já disponíveis em várias partes do mundo, prontas para uso sob demanda","correta":true,"porque":"Basta implantar nas Regiões existentes, em minutos e sem investimento inicial."}],"explicacao":"A velocidade de implantação da infraestrutura global vem de Regiões já construídas e prontas, que o cliente usa sob demanda.","servicos":["Outposts"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-026","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual recurso da AWS reúne os princípios centrais, os princípios de design e as melhores práticas de arquitetura para construir e operar cargas de trabalho na nuvem?","alternativas":[{"texto":"AWS Well-Architected Framework","correta":true,"porque":"Reúne princípios de design e boas práticas organizados em seis pilares."},{"texto":"AWS Reference Architecture Diagrams","correta":false,"porque":"São diagramas de exemplo para casos de uso específicos, não um framework de boas práticas."},{"texto":"Modelo de responsabilidade compartilhada da AWS","correta":false,"porque":"Define o que é responsabilidade da AWS e do cliente, não boas práticas de arquitetura."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz verificações automatizadas na conta; não é um conjunto de princípios de arquitetura."}],"explicacao":"O AWS Well-Architected Framework descreve conceitos, princípios de design e boas práticas para cargas de trabalho seguras, confiáveis, eficientes, econômicas e sustentáveis.","servicos":["Trusted Advisor"],"dificuldade":1,"fonte":"usuario-A64"},{"id":"D1-a-027","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual pilar do AWS Well-Architected Framework recomenda executar operações como código, usando infraestrutura como código (IaC)?","alternativas":[{"texto":"Segurança","correta":false,"porque":"Foca em proteger dados, sistemas e ativos."},{"texto":"Eficiência de Performance","correta":false,"porque":"Foca em usar recursos de computação de forma eficiente para atender aos requisitos."},{"texto":"Excelência Operacional","correta":true,"porque":"\"Perform operations as code\" é princípio de design da Excelência Operacional."},{"texto":"Otimização de Custos","correta":false,"porque":"Foca em evitar gastos desnecessários."}],"explicacao":"Excelência Operacional: executar e monitorar sistemas e melhorar continuamente processos; IaC é a forma de executar operações como código.","servicos":["CloudFormation"],"dificuldade":1,"fonte":"usuario-A36"},{"id":"D1-a-028","dominio":1,"task":"1.2","tipo":"multipla","selecionar":2,"enunciado":"Quais atividades se alinham ao pilar de Excelência Operacional do AWS Well-Architected Framework? (Selecione DUAS.)","alternativas":[{"texto":"Automatizar respostas operacionais rotineiras com runbooks, executadas sempre da mesma forma","correta":true,"porque":"Padronizar e automatizar procedimentos operacionais é prática de Excelência Operacional."},{"texto":"Fazer mudanças pequenas, frequentes e reversíveis nas cargas de trabalho","correta":true,"porque":"\"Make frequent, small, reversible changes\" é princípio de design da Excelência Operacional."},{"texto":"Replicar o banco de dados em várias Availability Zones para sobreviver à falha de uma zona","correta":false,"porque":"Resistir a falhas de infraestrutura é prática do pilar de Confiabilidade."},{"texto":"Criptografar os dados com o AWS KMS e aplicar permissões IAM de menor privilégio","correta":false,"porque":"Proteção de dados e menor privilégio pertencem ao pilar de Segurança."},{"texto":"Escolher o tipo de instância com melhor relação entre desempenho e requisitos","correta":false,"porque":"Selecionar os recursos certos para a carga é prática de Eficiência de Performance."}],"explicacao":"Excelência Operacional reúne práticas como operações como código, runbooks e mudanças pequenas, frequentes e reversíveis.","servicos":["KMS","IAM"],"dificuldade":2,"fonte":"usuario-B27 (reescrita)"},{"id":"D1-a-029","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual pilar do AWS Well-Architected Framework enfatiza selecionar e usar recursos de computação de forma eficiente para atender aos requisitos de DESEMPENHO da carga de trabalho, mantendo essa eficiência quando a demanda muda?","alternativas":[{"texto":"Confiabilidade","correta":false,"porque":"Foca em funcionar de forma consistente e se recuperar de falhas."},{"texto":"Eficiência de Performance","correta":true,"porque":"Trata de usar os recursos certos (tipo e quantidade) para os requisitos e manter essa eficiência com a mudança da demanda."},{"texto":"Otimização de Custos","correta":false,"porque":"Foca em entregar valor ao menor preço e evitar gastos desnecessários, não em atender requisitos de desempenho."},{"texto":"Excelência Operacional","correta":false,"porque":"Foca em executar, monitorar e melhorar processos operacionais."}],"explicacao":"Eficiência de Performance: selecionar e usar recursos de TI de forma eficiente para atender aos requisitos, ajustando-os conforme a demanda e a tecnologia evoluem.","servicos":[],"dificuldade":3,"fonte":"usuario-B38"},{"id":"D1-a-030","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Ao criar uma instância do Amazon RDS com implantação Multi-AZ, qual princípio de arquitetura em nuvem está sendo seguido?","alternativas":[{"texto":"Implementar acoplamento fraco (loose coupling)","correta":false,"porque":"Trata de reduzir dependências entre componentes, não de redundância do banco."},{"texto":"Automatizar tudo o que for possível","correta":false,"porque":"O Multi-AZ automatiza o failover, mas o objetivo do princípio aplicado é sobreviver a falhas."},{"texto":"Usar serviços, não servidores","correta":false,"porque":"O RDS é gerenciado, mas a escolha do Multi-AZ visa especificamente resistir a falhas."},{"texto":"Projetar para falhas (design for failure)","correta":true,"porque":"Uma réplica em espera em outra AZ assume se a instância principal falhar."}],"explicacao":"Design for failure: assumir que componentes vão falhar e eliminar pontos únicos de falha, como faz o RDS Multi-AZ.","servicos":["RDS"],"dificuldade":2,"fonte":"usuario-B81"},{"id":"D1-a-031","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Usar o AWS Config para registrar, auditar e avaliar mudanças nos recursos da AWS, garantindo rastreabilidade, é um exemplo de qual pilar do AWS Well-Architected Framework?","alternativas":[{"texto":"Segurança","correta":true,"porque":"\"Enable traceability\" (monitorar, alertar e auditar ações e mudanças) é princípio de design da Segurança."},{"texto":"Excelência Operacional","correta":false,"porque":"Embora use observabilidade, \"habilitar a rastreabilidade\" é princípio de design do pilar de Segurança."},{"texto":"Eficiência de Performance","correta":false,"porque":"Não trata de selecionar recursos para desempenho."},{"texto":"Otimização de Custos","correta":false,"porque":"Não trata de reduzir gastos."}],"explicacao":"Rastreabilidade (registrar e auditar mudanças e ações em tempo real) é um dos princípios de design do pilar de Segurança.","servicos":["Config"],"dificuldade":3,"fonte":"kananinirav-k20#50"},{"id":"D1-a-032","dominio":1,"task":"1.2","tipo":"multipla","selecionar":2,"enunciado":"Quais princípios de design da AWS Cloud ajudam a aumentar a confiabilidade? (Selecione DUAS.)","alternativas":[{"texto":"Usar arquitetura monolítica","correta":false,"porque":"Monólitos concentram dependências e aumentam o impacto de falhas."},{"texto":"Medir a eficiência geral","correta":false,"porque":"É princípio de design do pilar de Otimização de Custos."},{"texto":"Testar os procedimentos de recuperação","correta":true,"porque":"É princípio de design do pilar de Confiabilidade: validar como a carga se recupera."},{"texto":"Adotar um modelo de consumo","correta":false,"porque":"É princípio de design do pilar de Otimização de Custos."},{"texto":"Recuperar-se automaticamente de falhas","correta":true,"porque":"É princípio de design do pilar de Confiabilidade: monitorar KPIs e reagir automaticamente."}],"explicacao":"Princípios de Confiabilidade: recuperar-se automaticamente de falhas, testar a recuperação, escalar horizontalmente, parar de adivinhar capacidade e gerenciar mudanças por automação.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k23#34"},{"id":"D1-a-033","dominio":1,"task":"1.2","tipo":"multipla","selecionar":2,"enunciado":"Quais princípios de design estão relacionados ao pilar de Eficiência de Performance? (Selecione DUAS.)","alternativas":[{"texto":"Tornar-se global em minutos com arquiteturas em várias Regiões","correta":true,"porque":"Implantar em várias Regiões para reduzir latência é princípio da Eficiência de Performance."},{"texto":"Aplicar segurança em todas as camadas","correta":false,"porque":"É princípio de design do pilar de Segurança."},{"texto":"Implementar uma base sólida de identidade","correta":false,"porque":"É princípio de design do pilar de Segurança."},{"texto":"Usar arquiteturas serverless","correta":true,"porque":"Serverless elimina a gestão de servidores e é princípio da Eficiência de Performance."},{"texto":"Habilitar a rastreabilidade","correta":false,"porque":"É princípio de design do pilar de Segurança."}],"explicacao":"Princípios de Eficiência de Performance: democratizar tecnologias avançadas, tornar-se global em minutos, usar serverless, experimentar com mais frequência e considerar a afinidade mecânica.","servicos":["Lambda"],"dificuldade":3,"fonte":"kananinirav-k4#28"},{"id":"D1-a-034","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual é um benefício do acoplamento fraco (loose coupling) como princípio de design de arquitetura em nuvem?","alternativas":[{"texto":"Garante o tratamento de requisições com baixa latência","correta":false,"porque":"Desacoplar não garante baixa latência; o objetivo é isolar falhas e mudanças."},{"texto":"Permite que as aplicações tenham fluxos de trabalho dependentes","correta":false,"porque":"É o contrário: o acoplamento fraco reduz dependências."},{"texto":"Evita falhas em cascata entre componentes diferentes","correta":true,"porque":"Com menos dependências, a falha de um componente não derruba os demais."},{"texto":"Permite concentrar-se na operação do data center físico","correta":false,"porque":"Não tem relação com data centers físicos."}],"explicacao":"Loose coupling reduz interdependências: componentes podem falhar, escalar e mudar de forma independente, evitando falhas em cascata.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k16#18"},{"id":"D1-a-035","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Uma aplicação legada monolítica precisa ter seus componentes desacoplados para que se comuniquem de forma assíncrona. Qual serviço da AWS pode ser usado?","alternativas":[{"texto":"AWS Direct Connect","correta":false,"porque":"Fornece conexão de rede dedicada com a AWS; não desacopla componentes."},{"texto":"Amazon SQS","correta":true,"porque":"Filas de mensagens permitem que componentes troquem mensagens sem depender um do outro estar disponível."},{"texto":"Amazon CloudFront","correta":false,"porque":"É uma CDN para entregar conteúdo com baixa latência."},{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade."}],"explicacao":"Filas como o Amazon SQS são a forma clássica de aplicar o princípio de acoplamento fraco.","servicos":["SQS","Direct Connect","Artifact","CloudFront"],"dificuldade":2,"fonte":"kananinirav-k5#41"},{"id":"D1-a-036","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Uma equipe substituiu tarefas manuais, como criar servidores e reagir a alarmes, por scripts e serviços que respondem a eventos automaticamente. Qual princípio de design está sendo aplicado?","alternativas":[{"texto":"Tratar servidores como recursos fixos","correta":false,"porque":"É o oposto da prática recomendada de recursos descartáveis."},{"texto":"Provisionar capacidade para o pico máximo","correta":false,"porque":"Gera ociosidade e não tem relação com automação."},{"texto":"Projetar componentes fortemente acoplados","correta":false,"porque":"Acoplamento forte é contrário às boas práticas."},{"texto":"Automatizar sempre que possível","correta":true,"porque":"Substituir ações manuais por automação reduz erros e acelera respostas."}],"explicacao":"Automação é princípio recorrente do Well-Architected: reduz erros humanos, permite respostas consistentes e libera a equipe.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k2#24 (reescrita)"},{"id":"D1-a-037","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual princípio de design está alinhado às boas práticas da AWS Cloud?","alternativas":[{"texto":"Distribuir a carga de computação entre vários recursos","correta":true,"porque":"Escalar horizontalmente aumenta a disponibilidade agregada e reduz o impacto de falhas."},{"texto":"Concentrar vários serviços em uma única instância","correta":false,"porque":"Cria um ponto único de falha."},{"texto":"Criar dependências fixas entre os componentes","correta":false,"porque":"Dependências fixas aumentam o impacto de falhas."},{"texto":"Implantar as aplicações em uma única Availability Zone","correta":false,"porque":"Uma única AZ é ponto único de falha."}],"explicacao":"Escalar horizontalmente (distribuir a carga entre vários recursos menores) é princípio de design recomendado.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k19#11"},{"id":"D1-a-038","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Em vez de corrigir manualmente servidores de longa duração, uma equipe passou a substituí-los por novas instâncias criadas a partir de uma imagem padronizada. Qual princípio de design é esse?","alternativas":[{"texto":"Preferir capacidade reservada em vez de sob demanda","correta":false,"porque":"É decisão de modelo de preço, não de design."},{"texto":"Usar servidores em vez de serviços gerenciados","correta":false,"porque":"As boas práticas recomendam o contrário: preferir serviços gerenciados."},{"texto":"Usar recursos descartáveis em vez de servidores fixos","correta":true,"porque":"Recursos são recriados de forma padronizada em vez de mantidos e corrigidos indefinidamente."},{"texto":"Preferir acoplamento forte entre componentes","correta":false,"porque":"Acoplamento forte é contrário às boas práticas."}],"explicacao":"Na nuvem, servidores são descartáveis: substituí-los por versões novas e padronizadas é mais confiável que manter servidores fixos.","servicos":["EC2"],"dificuldade":2,"fonte":"kananinirav-k7#25 (reescrita)"},{"id":"D1-a-039","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual princípio geral de design do AWS Well-Architected Framework uma equipe aplica ao deixar de dimensionar a infraestrutura pelo pico estimado e passar a usar capacidade que aumenta e diminui automaticamente?","alternativas":[{"texto":"Testar sistemas em escala de produção","correta":false,"porque":"Trata de criar ambientes de teste com escala real sob demanda."},{"texto":"Parar de adivinhar suas necessidades de capacidade","correta":true,"porque":"Usar a capacidade necessária e escalar automaticamente elimina decisões baseadas em estimativas."},{"texto":"Permitir arquiteturas evolutivas","correta":false,"porque":"Trata de evoluir a arquitetura com o tempo, aproveitando a automação."},{"texto":"Melhorar por meio de game days","correta":false,"porque":"Trata de simular eventos para testar processos e equipes."}],"explicacao":"\"Stop guessing your capacity needs\" é um princípio geral de design: na nuvem se usa a capacidade necessária e se escala conforme a demanda.","servicos":["Auto Scaling"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-040","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Uma empresa cria sob demanda um ambiente idêntico ao de produção apenas para um teste de carga e o exclui ao final, pagando só pelas horas de uso. Qual princípio geral de design do AWS Well-Architected Framework está sendo aplicado?","alternativas":[{"texto":"Parar de adivinhar necessidades de capacidade","correta":false,"porque":"Refere-se a ajustar a capacidade da carga à demanda, não a criar ambientes de teste temporários."},{"texto":"Aplicar segurança em todas as camadas","correta":false,"porque":"É princípio de design do pilar de Segurança."},{"texto":"Conduzir arquiteturas com base em dados","correta":false,"porque":"Trata de usar dados coletados para orientar decisões de arquitetura."},{"texto":"Testar sistemas em escala de produção","correta":true,"porque":"A nuvem permite testar em escala real a baixo custo, pagando só enquanto o ambiente existe."}],"explicacao":"\"Test systems at production scale\": criar um ambiente de produção sob demanda para testes e descartá-lo ao final.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-041","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual pilar do AWS Well-Architected Framework concentra-se em minimizar os impactos ambientais da execução de cargas de trabalho na nuvem?","alternativas":[{"texto":"Sustentabilidade","correta":true,"porque":"É o sexto pilar, dedicado a reduzir o consumo de energia e o impacto ambiental das cargas."},{"texto":"Otimização de Custos","correta":false,"porque":"Foca em evitar gastos desnecessários, não em impacto ambiental."},{"texto":"Eficiência de Performance","correta":false,"porque":"Foca em usar recursos de forma eficiente para atender a requisitos de desempenho."},{"texto":"Excelência Operacional","correta":false,"porque":"Foca em executar, monitorar e melhorar processos operacionais."}],"explicacao":"O pilar de Sustentabilidade trata de minimizar os impactos ambientais, maximizando a utilização e reduzindo os recursos necessários.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-a-042","dominio":1,"task":"1.2","tipo":"multipla","selecionar":2,"enunciado":"Quais práticas estão alinhadas ao pilar de Sustentabilidade do AWS Well-Architected Framework? (Selecione DUAS.)","alternativas":[{"texto":"Maximizar a utilização dos recursos, evitando capacidade ociosa","correta":true,"porque":"Recursos ociosos consomem energia sem entregar valor; maximizar a utilização é princípio do pilar."},{"texto":"Usar serviços gerenciados, que compartilham a infraestrutura de forma eficiente","correta":true,"porque":"Serviços gerenciados distribuem a infraestrutura entre muitos clientes, reduzindo o impacto por carga."},{"texto":"Provisionar servidores extras para o pico máximo previsto","correta":false,"porque":"Gera capacidade ociosa e aumenta o consumo de energia."},{"texto":"Manter hardware antigo em uso sem avaliar opções mais eficientes","correta":false,"porque":"Contraria o princípio de adotar hardware e software novos e mais eficientes."},{"texto":"Replicar todos os dados em todas as Regiões por precaução","correta":false,"porque":"Aumenta armazenamento e transferência sem necessidade, ampliando o impacto ambiental."}],"explicacao":"Sustentabilidade: entender o impacto, definir metas, maximizar a utilização, adotar tecnologias mais eficientes, usar serviços gerenciados e reduzir o impacto downstream.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-043","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Segundo o AWS Well-Architected Framework, como a responsabilidade pela sustentabilidade é dividida entre a AWS e o cliente?","alternativas":[{"texto":"A AWS é responsável por toda a sustentabilidade das cargas de trabalho dos clientes","correta":false,"porque":"O cliente também é responsável: suas escolhas de arquitetura e uso definem o impacto das cargas."},{"texto":"O cliente é responsável pela eficiência energética dos data centers da AWS","correta":false,"porque":"Os data centers e a energia que os alimenta são responsabilidade da AWS."},{"texto":"A AWS cuida da sustentabilidade DA nuvem; o cliente, da sustentabilidade NA nuvem","correta":true,"porque":"A AWS otimiza a infraestrutura; o cliente otimiza o uso de recursos, dados e arquitetura."},{"texto":"A sustentabilidade é responsabilidade exclusiva do cliente, sem participação da AWS","correta":false,"porque":"A AWS responde pela eficiência da infraestrutura global."}],"explicacao":"Sustentabilidade também é compartilhada: a AWS é responsável pela infraestrutura eficiente; o cliente, por usar recursos e projetar cargas de forma eficiente.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-044","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Ao escolher a Região de uma nova carga de trabalho, uma empresa considera, além dos requisitos de negócio, suas metas de redução de emissões de carbono. Qual pilar do AWS Well-Architected Framework orienta essa decisão?","alternativas":[{"texto":"Confiabilidade","correta":false,"porque":"Trata de resistir a falhas e se recuperar delas, não de emissões."},{"texto":"Sustentabilidade","correta":true,"porque":"Escolher a Região considerando requisitos de negócio e metas de sustentabilidade é prática desse pilar."},{"texto":"Segurança","correta":false,"porque":"Trata da proteção de dados e sistemas."},{"texto":"Otimização de Custos","correta":false,"porque":"Considera o preço da Região; metas de emissões são tema do pilar de Sustentabilidade."}],"explicacao":"A seleção de Região é uma das áreas de boas práticas do pilar de Sustentabilidade.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-a-045","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual objetivo pertence ao pilar de Sustentabilidade, e NÃO ao de Otimização de Custos?","alternativas":[{"texto":"Entregar valor de negócio ao menor preço possível","correta":false,"porque":"É o objetivo central do pilar de Otimização de Custos."},{"texto":"Adotar um modelo de consumo, pagando só pelo que usa","correta":false,"porque":"É princípio de design do pilar de Otimização de Custos."},{"texto":"Analisar e atribuir despesas a cada equipe","correta":false,"porque":"É princípio de design do pilar de Otimização de Custos."},{"texto":"Reduzir a energia consumida por unidade de trabalho entregue","correta":true,"porque":"Medir e reduzir o impacto ambiental por unidade de trabalho é foco da Sustentabilidade."}],"explicacao":"Os dois pilares muitas vezes caminham juntos, mas a Sustentabilidade mede o impacto ambiental, enquanto a Otimização de Custos mede gastos.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-046","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual serviço da AWS permite revisar uma carga de trabalho em relação às boas práticas dos pilares do AWS Well-Architected Framework e gerar um plano de melhorias?","alternativas":[{"texto":"AWS Well-Architected Tool","correta":true,"porque":"Conduz revisões da carga pelos pilares, identifica riscos e gera um plano de melhorias."},{"texto":"AWS Config","correta":false,"porque":"Registra e avalia a configuração de recursos contra regras."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz verificações automáticas na conta, mas não conduz uma revisão da carga pelos pilares."},{"texto":"AWS Security Hub","correta":false,"porque":"Agrega achados de segurança e verifica padrões de conformidade."}],"explicacao":"O AWS Well-Architected Tool, gratuito no console, revisa cargas de trabalho contra as boas práticas do framework e acompanha as melhorias.","servicos":["Well-Architected Tool","Trusted Advisor","Config","Security Hub"],"dificuldade":1,"fonte":"autoral"},{"id":"D1-a-047","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual afirmação diferencia corretamente o AWS Well-Architected Tool do AWS Trusted Advisor?","alternativas":[{"texto":"O Well-Architected Tool aplica correções automaticamente nos recursos; o Trusted Advisor apenas gera relatórios","correta":false,"porque":"Nenhum dos dois aplica correções automaticamente por padrão; o Well-Architected Tool gera um plano de melhorias."},{"texto":"O Trusted Advisor avalia os seis pilares por questionário; o Well-Architected Tool avalia somente custos","correta":false,"porque":"É o contrário: o questionário pelos pilares é do Well-Architected Tool."},{"texto":"O Well-Architected Tool revisa a carga por perguntas; o Trusted Advisor verifica automaticamente a conta","correta":true,"porque":"Um é uma revisão guiada da arquitetura; o outro faz checagens automáticas nos recursos."},{"texto":"Os dois são o mesmo serviço, apresentado com nomes diferentes em consoles distintos","correta":false,"porque":"São serviços distintos, com propósitos complementares."}],"explicacao":"Well-Architected Tool: revisão guiada da carga pelos pilares. Trusted Advisor: verificações automáticas dos recursos da conta (custo, segurança, limites etc.).","servicos":["Well-Architected Tool","Trusted Advisor"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-048","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual pilar do AWS Well-Architected Framework inclui princípios como implementar a gestão financeira na nuvem, adotar um modelo de consumo e analisar e atribuir despesas?","alternativas":[{"texto":"Sustentabilidade","correta":false,"porque":"Foca em impacto ambiental, não em gestão financeira."},{"texto":"Otimização de Custos","correta":true,"porque":"Esses são princípios de design do pilar de Otimização de Custos."},{"texto":"Excelência Operacional","correta":false,"porque":"Foca em operações, monitoramento e melhoria de processos."},{"texto":"Eficiência de Performance","correta":false,"porque":"Foca em usar recursos de forma eficiente para atender a requisitos."}],"explicacao":"Otimização de Custos: gestão financeira na nuvem, modelo de consumo, medir eficiência, parar de gastar com trabalho indiferenciado e atribuir despesas.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-a-049","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual associação entre prática e pilar do AWS Well-Architected Framework está CORRETA?","alternativas":[{"texto":"Aplicar permissões IAM de menor privilégio → Excelência Operacional","correta":false,"porque":"Menor privilégio e base sólida de identidade pertencem ao pilar de Segurança."},{"texto":"Criptografar dados em repouso e em trânsito → Otimização de Custos","correta":false,"porque":"Proteção de dados pertence ao pilar de Segurança."},{"texto":"Escolher instâncias mais eficientes para reduzir a pegada de carbono → Segurança","correta":false,"porque":"Reduzir o impacto ambiental é tema do pilar de Sustentabilidade."},{"texto":"Monitorar e gerenciar as Service Quotas para evitar falhas por limite → Confiabilidade","correta":true,"porque":"Gerenciar cotas e restrições de serviço é área de boas práticas da Confiabilidade."}],"explicacao":"Diferenciar os pilares: identidade e criptografia são Segurança; cotas e recuperação são Confiabilidade; impacto ambiental é Sustentabilidade.","servicos":["Service Quotas","IAM"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-a-050","dominio":1,"task":"1.2","tipo":"unica","enunciado":"Qual pilar do AWS Well-Architected Framework trata da capacidade de uma carga de trabalho executar sua função de forma correta e consistente e se recuperar rapidamente de falhas?","alternativas":[{"texto":"Confiabilidade","correta":true,"porque":"Trata de executar a função esperada de forma consistente e se recuperar de falhas."},{"texto":"Excelência Operacional","correta":false,"porque":"Foca em executar, monitorar e melhorar processos operacionais."},{"texto":"Segurança","correta":false,"porque":"Foca em proteger dados, sistemas e ativos."},{"texto":"Eficiência de Performance","correta":false,"porque":"Foca em selecionar e usar recursos de forma eficiente."}],"explicacao":"Confiabilidade: a carga funciona corretamente e de forma consistente ao longo do ciclo de vida e se recupera de falhas.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-001","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma seguradora vai mover todas as cargas de produção para a AWS e precisa projetar uma arquitetura de nuvem escalável, com engenharia de plataforma, provisionamento automatizado e pipelines de entrega modernos. Segundo o AWS CAF, qual perspectiva trata dessas capacidades?","alternativas":[{"texto":"Perspectiva de Governança","correta":false,"porque":"Trata de gestão de programas, riscos, benefícios e finanças da nuvem, não da arquitetura técnica."},{"texto":"Perspectiva de Negócios","correta":false,"porque":"Garante que os investimentos em nuvem acelerem a estratégia e os resultados de negócio; não cuida da engenharia da plataforma."},{"texto":"Perspectiva de Plataforma","correta":true,"porque":"Reúne arquitetura e engenharia de plataforma, provisionamento e orquestração, desenvolvimento moderno de aplicações e CI/CD."},{"texto":"Perspectiva de Pessoas","correta":false,"porque":"Foca em cultura, liderança, fluência em nuvem e estrutura organizacional."}],"explicacao":"A perspectiva de Plataforma do AWS CAF ajuda a construir uma plataforma de nuvem híbrida escalável e corporativa, modernizar cargas e implementar novas soluções nativas de nuvem.","servicos":["AWS CAF"],"dificuldade":2,"fonte":"usuario-A32 (reescrita)"},{"id":"D1-b-002","dominio":1,"task":"1.3","tipo":"multipla","selecionar":2,"enunciado":"Quais capacidades pertencem à perspectiva de Governança do AWS CAF? (Selecione DUAS.)","alternativas":[{"texto":"Data Architecture","correta":false,"porque":"Arquitetura de dados é capacidade da perspectiva de Plataforma."},{"texto":"Data Protection","correta":false,"porque":"Proteção de dados é capacidade da perspectiva de Segurança."},{"texto":"Data Science","correta":false,"porque":"Ciência de dados é capacidade da perspectiva de Negócios."},{"texto":"Data Curation","correta":true,"porque":"Curadoria de dados (catalogar e organizar dados para uso) é capacidade da perspectiva de Governança."},{"texto":"Data Governance","correta":true,"porque":"Governança de dados (políticas de propriedade, qualidade e uso) pertence à perspectiva de Governança."}],"explicacao":"A perspectiva de Governança inclui gestão de programas e projetos, gestão de benefícios, gestão de riscos, gestão financeira da nuvem, gestão do portfólio de aplicações, governança de dados e curadoria de dados.","servicos":["AWS CAF"],"dificuldade":3,"fonte":"usuario-B26"},{"id":"D1-b-003","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa precisa coletar dados dos servidores on-premises, como hostnames, endereços IP e MAC, utilização e dependências entre sistemas, para planejar a migração. Qual serviço da AWS deve ser usado?","alternativas":[{"texto":"AWS Database Migration Service (AWS DMS)","correta":false,"porque":"Migra e replica bancos de dados; não faz inventário de servidores."},{"texto":"AWS Application Migration Service","correta":false,"porque":"Executa a migração (rehost) dos servidores, mas não é a ferramenta de descoberta e planejamento."},{"texto":"AWS DataSync","correta":false,"porque":"Transfere arquivos e objetos entre armazenamentos; não coleta dados de configuração de servidores."},{"texto":"AWS Application Discovery Service","correta":true,"porque":"Coleta configuração, utilização e dependências dos servidores on-premises para planejar a migração."}],"explicacao":"O AWS Application Discovery Service descobre o inventário on-premises (com ou sem agente) e alimenta o planejamento no AWS Migration Hub.","servicos":["AWS Application Discovery Service"],"dificuldade":1,"fonte":"usuario-B48"},{"id":"D1-b-004","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma equipe quer adotar capacidades de observabilidade, gerenciamento de eventos e gerenciamento de patches seguindo o AWS Cloud Adoption Framework (AWS CAF). Qual perspectiva do CAF reúne essas capacidades?","alternativas":[{"texto":"Operações (Operations)","correta":true,"porque":"É a perspectiva do CAF que garante que os serviços de nuvem sejam entregues no nível acordado, com observabilidade, eventos, incidentes e patches."},{"texto":"Eficiência de Performance (Performance Efficiency)","correta":false,"porque":"É um pilar do AWS Well-Architected Framework, não uma perspectiva do CAF."},{"texto":"Confiabilidade (Reliability)","correta":false,"porque":"É um pilar do AWS Well-Architected Framework, não uma perspectiva do CAF."},{"texto":"Sustentabilidade (Sustainability)","correta":false,"porque":"É um pilar do AWS Well-Architected Framework, não uma perspectiva do CAF."}],"explicacao":"Não confunda: o CAF tem 6 perspectivas (Negócios, Pessoas, Governança, Plataforma, Segurança, Operações); o Well-Architected tem 6 pilares.","servicos":["AWS CAF"],"dificuldade":2,"fonte":"usuario-B51 (reescrita)"},{"id":"D1-b-005","dominio":1,"task":"1.3","tipo":"multipla","selecionar":2,"enunciado":"Quais capacidades fazem parte da perspectiva de Plataforma do AWS CAF? (Selecione DUAS.)","alternativas":[{"texto":"Gerenciamento de desempenho e capacidade","correta":false,"porque":"É capacidade da perspectiva de Operações."},{"texto":"Engenharia de dados","correta":true,"porque":"Data engineering é capacidade da perspectiva de Plataforma."},{"texto":"Integração e entrega contínuas (CI/CD)","correta":true,"porque":"CI/CD é capacidade da perspectiva de Plataforma, junto com provisionamento e orquestração."},{"texto":"Proteção de infraestrutura","correta":false,"porque":"É capacidade da perspectiva de Segurança."},{"texto":"Gerenciamento de mudanças e releases","correta":false,"porque":"É capacidade da perspectiva de Operações."}],"explicacao":"Plataforma: arquitetura de plataforma, arquitetura de dados, engenharia de plataforma, engenharia de dados, provisionamento e orquestração, desenvolvimento moderno de aplicações e CI/CD.","servicos":["AWS CAF"],"dificuldade":3,"fonte":"usuario-B67"},{"id":"D1-b-006","dominio":1,"task":"1.3","tipo":"unica","enunciado":"A diretoria quer garantir que os investimentos em nuvem acelerem as metas de transformação digital e os resultados de negócio, com gestão de estratégia, de portfólio e de inovação. Qual perspectiva do AWS CAF aborda esse objetivo?","alternativas":[{"texto":"Plataforma","correta":false,"porque":"Cuida da arquitetura e engenharia técnica da nuvem, não da estratégia de negócio."},{"texto":"Negócios","correta":true,"porque":"A perspectiva de Negócios garante que a nuvem acelere ambições de transformação digital e resultados, com estratégia, portfólio, inovação e produtos."},{"texto":"Operações","correta":false,"porque":"Trata da entrega dos serviços de nuvem no nível acordado, não da estratégia."},{"texto":"Segurança","correta":false,"porque":"Trata de confidencialidade, integridade e disponibilidade de dados e cargas."}],"explicacao":"Perspectiva de Negócios: gestão de estratégia, portfólio, inovação, produtos, parcerias estratégicas, monetização de dados, business insight e ciência de dados.","servicos":["AWS CAF"],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-007","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa percebe resistência das equipes à nuvem e falta de habilidades. Ela quer desenvolver fluência em nuvem, evoluir a cultura e redesenhar a estrutura organizacional. Qual perspectiva do AWS CAF trata desses temas?","alternativas":[{"texto":"Governança","correta":false,"porque":"Orquestra programas, riscos e finanças da nuvem; não foca em cultura e capacitação."},{"texto":"Negócios","correta":false,"porque":"Foca em estratégia e resultados de negócio, não em pessoas e cultura."},{"texto":"Pessoas","correta":true,"porque":"A perspectiva de Pessoas cobre evolução cultural, liderança transformacional, fluência em nuvem, transformação da força de trabalho e design organizacional."},{"texto":"Operações","correta":false,"porque":"Trata de observabilidade, incidentes e entrega dos serviços, não de mudança cultural."}],"explicacao":"A perspectiva de Pessoas funciona como ponte entre tecnologia e negócio, acelerando a mudança cultural e a capacitação para a nuvem.","servicos":["AWS CAF"],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-008","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Qual perspectiva do AWS CAF inclui as capacidades de gerenciamento de identidade e acesso, detecção de ameaças e gerenciamento de vulnerabilidades?","alternativas":[{"texto":"Operações","correta":false,"porque":"Cobre observabilidade, eventos, patches e continuidade, mas não identidade e detecção de ameaças."},{"texto":"Plataforma","correta":false,"porque":"Cobre arquitetura, engenharia e CI/CD da plataforma de nuvem."},{"texto":"Governança","correta":false,"porque":"Cobre riscos e finanças da nuvem de forma ampla, sem as capacidades técnicas de segurança."},{"texto":"Segurança","correta":true,"porque":"A perspectiva de Segurança inclui IAM, detecção de ameaças, gestão de vulnerabilidades, proteção de dados e de infraestrutura e resposta a incidentes."}],"explicacao":"A perspectiva de Segurança ajuda a garantir confidencialidade, integridade e disponibilidade de dados e cargas de trabalho na nuvem.","servicos":["AWS CAF"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-009","dominio":1,"task":"1.3","tipo":"unica","enunciado":"O CFO quer que a adoção da nuvem tenha gestão financeira da nuvem, gestão de benefícios e gestão de riscos, maximizando o valor e minimizando os riscos da transformação. Qual perspectiva do AWS CAF reúne essas capacidades?","alternativas":[{"texto":"Negócios","correta":false,"porque":"Trata de estratégia, portfólio e inovação, mas a gestão financeira da nuvem e de riscos fica em Governança."},{"texto":"Governança","correta":true,"porque":"A perspectiva de Governança inclui gestão financeira da nuvem, de benefícios, de riscos e de programas e projetos."},{"texto":"Operações","correta":false,"porque":"Trata da operação diária dos serviços de nuvem, não de finanças e riscos do programa."},{"texto":"Pessoas","correta":false,"porque":"Trata de cultura, liderança e capacitação."}],"explicacao":"Governança orquestra as iniciativas de nuvem para maximizar benefícios e minimizar riscos, incluindo o controle financeiro (Cloud Financial Management).","servicos":["AWS CAF"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-010","dominio":1,"task":"1.3","tipo":"multipla","selecionar":3,"enunciado":"Quais perspectivas do AWS CAF são consideradas perspectivas técnicas? (Selecione TRÊS.)","alternativas":[{"texto":"Plataforma","correta":true,"porque":"É uma das três perspectivas técnicas, focada na plataforma de nuvem."},{"texto":"Negócios","correta":false,"porque":"É uma perspectiva de negócio, voltada a estratégia e resultados."},{"texto":"Segurança","correta":true,"porque":"É uma perspectiva técnica, focada em proteger dados e cargas."},{"texto":"Pessoas","correta":false,"porque":"É uma perspectiva de negócio, voltada a cultura e capacitação."},{"texto":"Operações","correta":true,"porque":"É uma perspectiva técnica, focada em entregar os serviços de nuvem com o nível acordado."},{"texto":"Governança","correta":false,"porque":"É uma perspectiva de negócio, voltada a riscos, finanças e programas."}],"explicacao":"Negócios, Pessoas e Governança são perspectivas de negócio; Plataforma, Segurança e Operações são perspectivas técnicas.","servicos":["AWS CAF"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-011","dominio":1,"task":"1.3","tipo":"multipla","selecionar":2,"enunciado":"Segundo o AWS CAF, quais são benefícios de negócio de uma transformação digital apoiada pela nuvem? (Selecione DUAS.)","alternativas":[{"texto":"Redução do risco de negócio","correta":true,"porque":"Menor risco de negócio (mais confiabilidade, desempenho e segurança) é um dos quatro benefícios citados pelo CAF."},{"texto":"Transferência total da responsabilidade de segurança para a AWS","correta":false,"porque":"O modelo de responsabilidade compartilhada continua valendo; o cliente segue responsável pela segurança na nuvem."},{"texto":"Melhoria do desempenho em ESG","correta":true,"porque":"Melhor desempenho ambiental, social e de governança (ESG) é benefício listado pelo CAF."},{"texto":"Eliminação dos custos operacionais de TI","correta":false,"porque":"A nuvem reduz e torna variáveis os custos, mas não os elimina."},{"texto":"Conformidade regulatória garantida automaticamente","correta":false,"porque":"A AWS oferece controles e relatórios, mas a conformidade da carga continua dependendo do cliente."}],"explicacao":"Os quatro benefícios do AWS CAF: menor risco de negócio, melhor desempenho em ESG, aumento de receita e maior eficiência operacional.","servicos":["AWS CAF"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-012","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa já identificou e priorizou suas oportunidades de transformação na nuvem. Agora precisa identificar lacunas de capacidade e dependências entre áreas e criar estratégias para melhorar sua prontidão. Em qual fase da jornada do AWS CAF ela está?","alternativas":[{"texto":"Envision","correta":false,"porque":"Envision é a fase anterior: identificar e priorizar oportunidades alinhadas aos objetivos estratégicos."},{"texto":"Align","correta":true,"porque":"Align identifica lacunas de capacidade nas seis perspectivas e dependências entre áreas, gerando o plano de prontidão."},{"texto":"Launch","correta":false,"porque":"Launch entrega iniciativas-piloto em produção e demonstra valor incremental."},{"texto":"Scale","correta":false,"porque":"Scale expande os pilotos e o valor de negócio para a escala desejada."}],"explicacao":"Fases da jornada do CAF, em ordem: Envision, Align, Launch e Scale.","servicos":["AWS CAF"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-b-013","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa precisa sair do data center em três meses, quando o contrato vence, e vai mover seus servidores para o Amazon EC2 sem alterar as aplicações. Qual estratégia de migração é essa?","alternativas":[{"texto":"Replatform","correta":false,"porque":"Replatform faz pequenas otimizações durante a migração, como trocar o banco por um serviço gerenciado."},{"texto":"Rehost","correta":true,"porque":"Rehost (lift and shift) move as aplicações sem mudanças, sendo a opção mais rápida para grandes volumes."},{"texto":"Refactor","correta":false,"porque":"Refactor reescreve a aplicação com recursos nativos de nuvem, o que leva mais tempo."},{"texto":"Relocate","correta":false,"porque":"Relocate move a infraestrutura no nível do hypervisor (ex.: VMware) sem converter para instâncias EC2."}],"explicacao":"Rehost, ou lift and shift, é a estratégia indicada quando o prazo é curto e não se quer alterar as aplicações.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-014","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Durante a migração, uma empresa mantém a arquitetura da aplicação, mas troca o MySQL autogerenciado pelo Amazon RDS for MySQL para reduzir a administração. Qual estratégia dos 7 Rs descreve essa decisão?","alternativas":[{"texto":"Rehost","correta":false,"porque":"No rehost nada é alterado; aqui houve troca do banco por um serviço gerenciado."},{"texto":"Refactor","correta":false,"porque":"Refactor muda a arquitetura da aplicação, o que não ocorreu."},{"texto":"Replatform","correta":true,"porque":"Replatform (lift, tinker and shift) faz otimizações pontuais, como adotar um banco gerenciado, sem mudar a arquitetura central."},{"texto":"Repurchase","correta":false,"porque":"Repurchase troca a aplicação por outro produto, geralmente SaaS."}],"explicacao":"Replatform obtém benefícios da nuvem com poucas mudanças, por exemplo migrando o banco para Amazon RDS.","servicos":["Amazon RDS"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-015","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma aplicação monolítica não suporta picos de demanda e demora a receber novos recursos. A empresa decide reescrevê-la em microsserviços com AWS Lambda e Amazon DynamoDB. Qual estratégia de migração é essa?","alternativas":[{"texto":"Replatform","correta":false,"porque":"Replatform faz ajustes pontuais sem redesenhar a aplicação."},{"texto":"Rehost","correta":false,"porque":"Rehost move a aplicação como está, mantendo o monólito."},{"texto":"Retain","correta":false,"porque":"Retain mantém a aplicação onde está, sem migrar."},{"texto":"Refactor (re-architect)","correta":true,"porque":"Refactor redesenha a aplicação com recursos nativos de nuvem para ganhar agilidade, escala e desempenho."}],"explicacao":"Refactor/re-architect é a estratégia de maior esforço e maior benefício, motivada por necessidades de negócio que a arquitetura atual não atende.","servicos":["AWS Lambda","Amazon DynamoDB"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-016","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa vai abandonar seu CRM instalado on-premises e passar a usar um CRM oferecido como software como serviço (SaaS). Qual estratégia de migração é essa?","alternativas":[{"texto":"Repurchase","correta":true,"porque":"Repurchase (drop and shop) troca a aplicação por outro produto, normalmente SaaS."},{"texto":"Retire","correta":false,"porque":"Retire desliga a aplicação sem substituí-la."},{"texto":"Replatform","correta":false,"porque":"Replatform mantém a mesma aplicação com pequenas otimizações."},{"texto":"Relocate","correta":false,"porque":"Relocate move a infraestrutura virtualizada para a nuvem sem trocar o software."}],"explicacao":"Repurchase substitui a solução atual por uma nova, geralmente com outro modelo de licenciamento (SaaS).","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-017","dominio":1,"task":"1.3","tipo":"unica","enunciado":"No levantamento do portfólio para a migração, a empresa descobre aplicações que não são mais usadas por ninguém. Qual estratégia é recomendada para elas?","alternativas":[{"texto":"Retain","correta":false,"porque":"Retain mantém a aplicação funcionando on-premises, o que continuaria gerando custo sem valor."},{"texto":"Retire","correta":true,"porque":"Retire desativa aplicações sem uso, reduzindo custos e a superfície de ataque."},{"texto":"Rehost","correta":false,"porque":"Migrar algo que ninguém usa só transfere o desperdício para a nuvem."},{"texto":"Repurchase","correta":false,"porque":"Não faz sentido comprar um substituto para uma aplicação sem uso."}],"explicacao":"Retire elimina aplicações desnecessárias identificadas na descoberta, simplificando e barateando a migração.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-018","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma aplicação depende de um mainframe que acabou de receber investimento e tem requisitos de latência com equipamentos locais. A empresa decide mantê-la on-premises e reavaliar no futuro. Qual estratégia de migração é essa?","alternativas":[{"texto":"Retire","correta":false,"porque":"Retire desativaria a aplicação, mas ela continua necessária."},{"texto":"Relocate","correta":false,"porque":"Relocate moveria a infraestrutura para a nuvem, o que não foi decidido."},{"texto":"Retain","correta":true,"porque":"Retain (revisit) mantém a aplicação no ambiente de origem por motivos de negócio, técnicos ou de investimento recente."},{"texto":"Rehost","correta":false,"porque":"Rehost migraria a aplicação para o EC2 agora."}],"explicacao":"Retain é usada para aplicações que ainda não devem migrar, como as com investimento recente, dependências ou requisitos de conformidade.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-019","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa executa centenas de VMs em VMware vSphere on-premises e quer movê-las rapidamente para a AWS sem comprar hardware, sem converter as VMs e sem mudar seus processos de operação. Qual estratégia de migração é essa?","alternativas":[{"texto":"Rehost","correta":false,"porque":"Rehost converte os servidores em instâncias EC2, alterando a forma de operar as VMs."},{"texto":"Replatform","correta":false,"porque":"Replatform inclui otimizações, como trocar componentes por serviços gerenciados."},{"texto":"Refactor","correta":false,"porque":"Refactor reescreve as aplicações, o oposto do que se pede."},{"texto":"Relocate","correta":true,"porque":"Relocate move a infraestrutura no nível do hypervisor (ex.: VMware Cloud on AWS) sem novo hardware, sem reescrever e sem mudar operações."}],"explicacao":"Relocate é o 7º R: transfere ambientes virtualizados inteiros para a nuvem mantendo a mesma plataforma de virtualização.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D1-b-020","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa usa várias ferramentas da AWS e de parceiros na migração e quer um local único para acompanhar o progresso da migração de todas as aplicações. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Migration Hub","correta":true,"porque":"Centraliza o acompanhamento do status das migrações feitas com diversas ferramentas da AWS e de parceiros."},{"texto":"AWS Application Discovery Service","correta":false,"porque":"Coleta dados dos servidores para o planejamento, mas não acompanha a execução da migração."},{"texto":"AWS Config","correta":false,"porque":"Registra e avalia configurações de recursos AWS; não acompanha projetos de migração."},{"texto":"Migration Evaluator","correta":false,"porque":"Gera o business case de custos antes da migração, não acompanha o progresso."}],"explicacao":"O AWS Migration Hub é o painel central para descobrir, planejar e acompanhar migrações de portfólio.","servicos":["AWS Migration Hub"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-021","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Antes de aprovar a migração, a diretoria pede um business case com a projeção dos custos na AWS, baseada na utilização real dos servidores on-premises e nas licenças existentes. Qual serviço da AWS ajuda a criar esse caso de negócio?","alternativas":[{"texto":"AWS Budgets","correta":false,"porque":"Define orçamentos e alertas sobre gastos já existentes na AWS."},{"texto":"AWS Cost Explorer","correta":false,"porque":"Analisa custos históricos e previstos de recursos que já estão na AWS."},{"texto":"Migration Evaluator","correta":true,"porque":"Coleta dados de utilização on-premises e gera um business case com custos projetados e opções de licenciamento na AWS."},{"texto":"AWS Migration Hub","correta":false,"porque":"Acompanha o progresso da migração, mas não constrói o business case financeiro."}],"explicacao":"O Migration Evaluator (antigo TSO Logic) cria business cases de migração baseados em dados, considerando rightsizing e licenças.","servicos":["Migration Evaluator"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-b-022","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa quer fazer rehost de centenas de servidores físicos e virtuais para o Amazon EC2, com replicação contínua em nível de bloco e cutover com mínimo tempo de inatividade. Qual serviço deve usar?","alternativas":[{"texto":"AWS Database Migration Service (AWS DMS)","correta":false,"porque":"Migra bancos de dados, não servidores inteiros."},{"texto":"AWS DataSync","correta":false,"porque":"Copia arquivos e objetos, não servidores completos com SO e aplicações."},{"texto":"AWS Application Discovery Service","correta":false,"porque":"Faz o inventário para planejamento; não replica servidores."},{"texto":"AWS Application Migration Service","correta":true,"porque":"O MGN replica continuamente os servidores de origem e automatiza a conversão e o cutover para o EC2."}],"explicacao":"O AWS Application Migration Service (MGN) é o serviço recomendado para lift and shift de servidores para a AWS.","servicos":["AWS Application Migration Service"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-023","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma empresa vai migrar um banco de dados de produção para a AWS e não pode deixar o sistema parado por horas. Qual abordagem MINIMIZA o tempo de inatividade?","alternativas":[{"texto":"Replicar continuamente o banco de origem para o destino e fazer o cutover após a sincronização","correta":true,"porque":"A replicação contínua (ex.: com AWS DMS) mantém a origem em uso até o destino estar sincronizado, reduzindo a parada ao cutover."},{"texto":"Gerar um backup completo, transportá-lo e restaurá-lo em uma janela de fim de semana","correta":false,"porque":"Exige parar as gravações durante todo o transporte e a restauração, gerando longa indisponibilidade."},{"texto":"Parar a aplicação, copiar os arquivos de dados para o Amazon S3 e reiniciar na AWS","correta":false,"porque":"Mantém o sistema parado durante toda a cópia, o oposto do requisito."},{"texto":"Copiar os arquivos do banco em execução com o AWS DataSync","correta":false,"porque":"Copiar arquivos de um banco ativo não garante consistência transacional nem replica alterações contínuas."}],"explicacao":"A replicação de banco de dados é uma estratégia de migração: carga inicial mais captura contínua de alterações (CDC) permite migrar com mínima parada.","servicos":["AWS DMS"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-b-024","dominio":1,"task":"1.3","tipo":"unica","enunciado":"Uma equipe procura guias, padrões e estratégias testados pela AWS e por parceiros para planejar e executar a migração e a modernização de suas cargas de trabalho. Qual recurso da AWS oferece esse conteúdo?","alternativas":[{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade e acordos da AWS, não guias de migração."},{"texto":"AWS Prescriptive Guidance","correta":true,"porque":"Reúne estratégias, guias e padrões validados pela AWS e parceiros para migração e modernização."},{"texto":"AWS re:Post","correta":false,"porque":"É uma comunidade de perguntas e respostas, não um acervo curado de padrões de migração."},{"texto":"AWS Marketplace","correta":false,"porque":"É um catálogo para comprar software de terceiros."}],"explicacao":"O AWS Prescriptive Guidance é um recurso de apoio à jornada para a nuvem, com estratégias, guias e padrões de migração.","servicos":["AWS Prescriptive Guidance"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-025","dominio":1,"task":"1.3","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa vai migrar do data center on-premises para a AWS e quer ajuda prática de especialistas na execução do projeto. Quais opções atendem a essa necessidade? (Selecione DUAS.)","alternativas":[{"texto":"Contratar o AWS Professional Services","correta":true,"porque":"A equipe global de especialistas da AWS ajuda a planejar e executar migrações, inclusive a configurar landing zones."},{"texto":"Abrir um caso no AWS Support","correta":false,"porque":"O AWS Support resolve problemas técnicos e dúvidas, mas não executa projetos de migração."},{"texto":"Escolher um parceiro da AWS Partner Network (APN)","correta":true,"porque":"Parceiros de consultoria da APN são especializados em conduzir migrações para a AWS."},{"texto":"Executar o AWS Trusted Advisor","correta":false,"porque":"Gera recomendações automatizadas sobre a conta, não ajuda prática em um projeto."},{"texto":"Comprar uma licença no AWS Marketplace","correta":false,"porque":"O Marketplace vende software e serviços de terceiros, não é um canal de apoio direto à migração."}],"explicacao":"Para ajuda prática na migração, recorra ao AWS Professional Services ou a parceiros da AWS Partner Network.","servicos":["AWS Professional Services","AWS Partner Network"],"dificuldade":2,"fonte":"kananinirav-k19#13 (reescrita)"},{"id":"D1-b-026","dominio":1,"task":"1.4","tipo":"multipla","selecionar":2,"enunciado":"Ao migrar do data center on-premises para a AWS e desativar o ambiente local, quais benefícios a empresa obtém? (Selecione DUAS.)","alternativas":[{"texto":"Adiamento do pagamento das despesas operacionais","correta":false,"porque":"A AWS cobra o uso conforme ele ocorre; não há adiamento de despesas operacionais."},{"texto":"Menor tempo para lançar produtos no mercado","correta":true,"porque":"Recursos ficam disponíveis em minutos, sem esperar compra e instalação de hardware, acelerando o time to market."},{"texto":"Redução do custo total de propriedade (TCO)","correta":true,"porque":"Elimina custos de hardware, instalações, energia e manutenção do data center, reduzindo o TCO."},{"texto":"Descontos de atacado na compra de servidores bare-metal","correta":false,"porque":"O cliente deixa de comprar servidores; a economia de escala vem dos preços menores dos serviços AWS."},{"texto":"Troca de custos variáveis baixos por grandes gastos de capital antecipados","correta":false,"porque":"É o inverso: a nuvem troca gastos de capital antecipados por custos variáveis."}],"explicacao":"Sair do data center reduz o TCO e aumenta a agilidade (menor time to market), trocando CapEx por custo variável.","servicos":[],"dificuldade":1,"fonte":"usuario-B32"},{"id":"D1-b-027","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa vai sair do data center on-premises e mover suas cargas para a AWS. Qual mudança financeira ela deve esperar?","alternativas":[{"texto":"Passar de despesa operacional variável (OpEx) para despesa de capital antecipada (CapEx)","correta":false,"porque":"É o oposto: na nuvem o investimento antecipado em hardware dá lugar ao pagamento pelo uso."},{"texto":"Eliminar tanto as despesas de capital quanto as despesas operacionais","correta":false,"porque":"O uso dos serviços AWS continua sendo uma despesa operacional."},{"texto":"Passar de despesa de capital antecipada (CapEx) para despesa operacional variável (OpEx)","correta":true,"porque":"Em vez de comprar servidores antecipadamente, a empresa paga mensalmente pelo que consome."},{"texto":"Passar a pagar uma taxa fixa mensal independente do uso","correta":false,"porque":"O modelo padrão da AWS é pay-as-you-go: o valor varia conforme o consumo."}],"explicacao":"Um benefício econômico central da nuvem é trocar CapEx (compra antecipada de infraestrutura) por OpEx variável.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k11#32"},{"id":"D1-b-028","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Qual item é um exemplo de custo FIXO?","alternativas":[{"texto":"O aluguel do espaço do data center, pago integralmente mesmo com servidores ociosos","correta":true,"porque":"Custo fixo não varia com o volume de uso; o aluguel é pago independentemente da carga."},{"texto":"O valor cobrado por GB transferido para a internet a partir da AWS","correta":false,"porque":"Cobrança por volume transferido é custo variável, proporcional ao uso."},{"texto":"As horas de instância Amazon EC2 On-Demand de um ambiente de testes","correta":false,"porque":"On-Demand é cobrado pelo tempo de uso: custo variável."},{"texto":"As invocações cobradas de uma função AWS Lambda","correta":false,"porque":"Lambda cobra por requisição e duração: custo variável."}],"explicacao":"Custo fixo independe do uso (aluguel, hardware comprado); custo variável acompanha o consumo, como no modelo pay-as-you-go da AWS.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-029","dominio":1,"task":"1.4","tipo":"multipla","selecionar":2,"enunciado":"Ao comparar o custo total de propriedade (TCO) da infraestrutura on-premises com o de uma arquitetura na nuvem, quais custos devem ser considerados? (Selecione DUAS.)","alternativas":[{"texto":"Taxas de processamento de cartão de crédito das transações da aplicação","correta":false,"porque":"São custos do negócio, iguais em qualquer infraestrutura."},{"texto":"Compra e instalação dos servidores no data center on-premises","correta":true,"porque":"O hardware e sua instalação são custos diretos da infraestrutura on-premises que a nuvem elimina."},{"texto":"Administração da infraestrutura: instalação de SO, patches, backups e recuperação de falhas","correta":true,"porque":"O trabalho de operar a infraestrutura é parte relevante do TCO e muda bastante na nuvem."},{"texto":"Testes de intrusão contratados de terceiros","correta":false,"porque":"São necessários nos dois cenários e não diferenciam a infraestrutura."},{"texto":"Custos de publicidade de uma campanha corporativa","correta":false,"porque":"Não têm relação com a infraestrutura de TI."}],"explicacao":"A análise de TCO compara os custos de infraestrutura e de operá-la: hardware, instalações, energia, pessoal de TI e administração.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k18#39"},{"id":"D1-b-030","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Qual custo deve ser incluído ao comparar o TCO on-premises com o TCO na AWS?","alternativas":[{"texto":"Gestão de projetos","correta":false,"porque":"Existe nos dois cenários e não depende da infraestrutura escolhida."},{"texto":"Análise de negócios","correta":false,"porque":"É atividade do negócio, independente de onde a infraestrutura roda."},{"texto":"Desenvolvimento de software","correta":false,"porque":"O código precisa ser escrito em qualquer ambiente."},{"texto":"Segurança física do data center","correta":true,"porque":"Vigilância, controle de acesso e instalações são custos on-premises que, na AWS, ficam a cargo do provedor."}],"explicacao":"No TCO entram os custos que mudam entre os cenários: instalações, segurança física, energia, hardware e pessoal de infraestrutura.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k17#2"},{"id":"D1-b-031","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Um varejista dimensiona seu data center para o pico da Black Friday. No restante do ano, a maior parte dos servidores roda com baixa utilização. Qual custo on-premises esse cenário ilustra e como a AWS o reduz?","alternativas":[{"texto":"Custo de transferência de dados, reduzido com o Amazon CloudFront","correta":false,"porque":"O problema descrito é capacidade ociosa paga, não tráfego de rede."},{"texto":"Custo de licenças, reduzido com o AWS License Manager","correta":false,"porque":"O License Manager controla licenças, mas não resolve servidores parados."},{"texto":"Custo de superprovisionamento, reduzido com capacidade sob demanda paga pelo uso","correta":true,"porque":"Na AWS a capacidade cresce e diminui com a demanda, e paga-se só pelo que se usa, sem hardware parado."},{"texto":"Custo de suporte, reduzido com o plano AWS Enterprise Support","correta":false,"porque":"Um plano de suporte não elimina capacidade ociosa e é um custo adicional."}],"explicacao":"On-premises é preciso comprar para o pico e pagar pelo hardware ocioso; na nuvem o custo variável acompanha a demanda.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-032","dominio":1,"task":"1.4","tipo":"multipla","selecionar":3,"enunciado":"Uma empresa está montando a análise de custos do seu data center próprio para compará-lo com a AWS. Quais custos de instalações on-premises costumam ser esquecidos e devem entrar na análise? (Selecione TRÊS.)","alternativas":[{"texto":"Energia elétrica dos servidores e equipamentos","correta":true,"porque":"O consumo de energia é um custo contínuo do data center que, na AWS, está embutido no preço do serviço."},{"texto":"Refrigeração do ambiente","correta":true,"porque":"Sistemas de ar-condicionado e seu consumo são custos relevantes on-premises."},{"texto":"Horas de instância Amazon EC2","correta":false,"porque":"É custo da AWS, não um custo de instalações on-premises."},{"texto":"Imóvel, aluguel ou espaço físico do data center","correta":true,"porque":"O espaço que abriga os racks tem custo de compra ou aluguel, impostos e manutenção."},{"texto":"Assinatura do plano AWS Business Support+","correta":false,"porque":"É um custo opcional da AWS, não das instalações próprias."},{"texto":"Armazenamento de objetos no Amazon S3","correta":false,"porque":"É custo de uso da AWS, não do data center próprio."}],"explicacao":"Custos de instalações (energia, refrigeração, imóvel e segurança física) muitas vezes ficam fora da conta on-premises, mas fazem parte do TCO.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-033","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa quer trazer para a AWS licenças de software cobradas por socket e por núcleo físico, com visibilidade do servidor físico usado. Qual opção do Amazon EC2 atende a esse requisito?","alternativas":[{"texto":"Dedicated Instances","correta":false,"porque":"Rodam em hardware dedicado ao cliente, mas não dão visibilidade nem controle de sockets e núcleos do servidor físico."},{"texto":"Dedicated Hosts","correta":true,"porque":"Oferecem um servidor físico inteiro, com visibilidade de sockets e núcleos, permitindo BYOL de licenças vinculadas ao servidor."},{"texto":"Spot Instances","correta":false,"porque":"Usam capacidade compartilhada e podem ser interrompidas; não atendem licenças por núcleo físico."},{"texto":"On-Demand Instances","correta":false,"porque":"Rodam em hardware compartilhado, sem visibilidade de sockets e núcleos."}],"explicacao":"Dedicated Hosts são a opção de EC2 para BYOL de licenças por socket, por núcleo ou por VM, além de requisitos de conformidade.","servicos":["Amazon EC2"],"dificuldade":3,"fonte":"kananinirav-k20#48 (reescrita)"},{"id":"D1-b-034","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Qual prática ajuda a REDUZIR custos ao migrar cargas de trabalho para a AWS?","alternativas":[{"texto":"Executar as cargas de produção em edge locations em vez de Regiões","correta":false,"porque":"Edge locations servem para cache e entrega de conteúdo, não para hospedar toda a produção."},{"texto":"Usar servidores autogerenciados em vez de serviços gerenciados","correta":false,"porque":"Autogerenciar aumenta o esforço operacional e o custo de pessoal."},{"texto":"Usar o AWS Outposts para todas as cargas de trabalho","correta":false,"porque":"Outposts levam infraestrutura AWS ao local do cliente para casos específicos, não para economizar em geral."},{"texto":"Reaproveitar licenças de software de terceiros que a empresa já possui (BYOL)","correta":true,"porque":"Trazer licenças existentes, quando os termos permitem, evita pagar a licença de novo embutida no preço."}],"explicacao":"BYOL (Bring Your Own License) aproveita o investimento em licenças já feito e reduz o custo da migração.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k5#40"},{"id":"D1-b-035","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa que leva suas licenças de software para a AWS (BYOL) quer controlar o uso das licenças e evitar exceder os limites contratados. Qual serviço ajuda nisso?","alternativas":[{"texto":"AWS License Manager","correta":true,"porque":"Gerencia licenças de software na AWS e on-premises, aplicando regras de uso para evitar excesso e riscos em auditorias."},{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade e acordos da AWS, não controle de licenças de software."},{"texto":"AWS Marketplace","correta":false,"porque":"Vende software de terceiros, mas não rastreia licenças trazidas pelo cliente."},{"texto":"AWS Budgets","correta":false,"porque":"Acompanha gastos frente a orçamentos, não contagem de licenças."}],"explicacao":"O AWS License Manager centraliza o controle de licenças (Microsoft, Oracle, SAP etc.), facilitando o BYOL com conformidade.","servicos":["AWS License Manager"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-036","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma startup precisa de servidores Windows Server na AWS, mas não possui nenhuma licença da Microsoft e não quer comprar licenças antecipadamente. Qual modelo de licenciamento é o MAIS adequado?","alternativas":[{"texto":"BYOL em Dedicated Hosts","correta":false,"porque":"BYOL exige licenças já adquiridas, que a startup não tem."},{"texto":"Comprar licenças perpétuas e importá-las para a AWS","correta":false,"porque":"Exige o investimento antecipado que a empresa quer evitar."},{"texto":"Licença incluída, usando AMIs de Windows Server do Amazon EC2","correta":true,"porque":"No modelo licença incluída, o custo da licença vem embutido no preço por uso da instância."},{"texto":"AWS License Manager para gerar novas licenças","correta":false,"porque":"O License Manager controla o uso de licenças, não as fornece."}],"explicacao":"Licença incluída: o custo da licença é pago junto com o uso do recurso; BYOL: o cliente reaproveita licenças que já possui.","servicos":["Amazon EC2"],"dificuldade":3,"fonte":"autoral"},{"id":"D1-b-037","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma equipe de TI gasta muitas horas aplicando patches manualmente em centenas de instâncias Amazon EC2. Qual benefício a empresa obtém ao automatizar essa tarefa com o AWS Systems Manager?","alternativas":[{"texto":"A AWS assume a responsabilidade pelos patches do sistema operacional das instâncias","correta":false,"porque":"No EC2 o patch do SO continua sendo responsabilidade do cliente, mesmo automatizado."},{"texto":"Menor esforço da equipe e menos erros humanos, com execução consistente","correta":true,"porque":"A automação reduz trabalho manual repetitivo, custo de pessoal e erros, aplicando o mesmo processo em toda a frota."},{"texto":"Eliminação da cobrança pelas instâncias durante o patch","correta":false,"porque":"As instâncias continuam sendo cobradas normalmente."},{"texto":"Dispensa de testar as aplicações após atualizações","correta":false,"porque":"Automatizar o patch não elimina a necessidade de testes."}],"explicacao":"A automação reduz custo operacional e erros humanos e libera a equipe para trabalho de maior valor.","servicos":["AWS Systems Manager"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-038","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa vai migrar seu banco de dados on-premises para o Amazon RDS. O que ela deve fazer para manter os custos do RDS no MÍNIMO?","alternativas":[{"texto":"Fazer o rightsizing antes e depois da migração","correta":true,"porque":"Dimensionar a instância pela utilização real antes da migração e ajustar após observar a carga evita pagar por capacidade sobrando."},{"texto":"Usar uma arquitetura multi-Região ativo-passivo","correta":false,"porque":"Aumenta a resiliência, mas também aumenta o custo."},{"texto":"Combinar Capacity Reservations com Savings Plans","correta":false,"porque":"Capacity Reservations são do EC2 e reservam capacidade sem desconto; não reduzem o custo por si."},{"texto":"Usar uma arquitetura multi-Região ativo-ativo","correta":false,"porque":"Duplica a infraestrutura e eleva o custo."}],"explicacao":"Rightsizing é ajustar tipo e tamanho dos recursos à demanda real; deve ser feito na migração e de forma contínua.","servicos":["Amazon RDS"],"dificuldade":2,"fonte":"kananinirav-k3#4"},{"id":"D1-b-039","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Qual serviço da AWS analisa as métricas de utilização das instâncias Amazon EC2 e recomenda tipos e tamanhos mais adequados para reduzir custos e melhorar o desempenho?","alternativas":[{"texto":"AWS Cost Explorer","correta":false,"porque":"Analisa e projeta gastos; o rightsizing baseado em utilização é o foco do Compute Optimizer."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Coleta as métricas, mas não gera recomendações de tipo de instância."},{"texto":"AWS Budgets","correta":false,"porque":"Alerta quando os gastos ultrapassam orçamentos, sem recomendar tamanhos."},{"texto":"AWS Compute Optimizer","correta":true,"porque":"Usa machine learning sobre o histórico de utilização para recomendar o rightsizing de EC2, Auto Scaling, EBS, Lambda e outros."}],"explicacao":"O AWS Compute Optimizer é a ferramenta de rightsizing: identifica recursos superdimensionados ou subdimensionados.","servicos":["AWS Compute Optimizer"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-040","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma instância Amazon EC2 de produção roda o mês inteiro com cerca de 10% de uso de CPU e memória. Qual ação representa o rightsizing desse recurso?","alternativas":[{"texto":"Comprar uma Reserved Instance do mesmo tipo atual","correta":false,"porque":"Dá desconto, mas mantém pagando por capacidade que não é usada."},{"texto":"Migrar a instância para um Dedicated Host","correta":false,"porque":"Aumenta o custo e não ajusta o tamanho à carga."},{"texto":"Adicionar mais instâncias iguais atrás de um load balancer","correta":false,"porque":"Aumenta a capacidade ociosa e o custo."},{"texto":"Trocar a instância por um tipo menor, compatível com a carga real","correta":true,"porque":"Rightsizing é adequar tipo e tamanho do recurso à utilização observada."}],"explicacao":"Faça o rightsizing antes de comprar compromissos (RIs/Savings Plans); caso contrário, você reserva desperdício.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-041","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa monta manualmente cada novo ambiente de testes, o que leva dias e gera diferenças entre os ambientes. Qual abordagem traz ambientes idênticos, rápidos de criar e fáceis de remover quando não forem mais necessários?","alternativas":[{"texto":"Documentar o passo a passo em uma planilha compartilhada","correta":false,"porque":"Continua manual: lento e sujeito a erros e divergências."},{"texto":"Infraestrutura como código com o AWS CloudFormation","correta":true,"porque":"Templates criam e excluem ambientes repetíveis e consistentes em minutos, evitando recursos esquecidos e erros manuais."},{"texto":"Manter um ambiente de testes permanente para todas as equipes","correta":false,"porque":"Gera custo contínuo e conflitos entre equipes."},{"texto":"Usar o AWS Trusted Advisor para criar os ambientes","correta":false,"porque":"O Trusted Advisor faz recomendações; não provisiona ambientes."}],"explicacao":"Automação com infraestrutura como código reduz tempo, erros e custo, pois os ambientes podem ser criados e destruídos sob demanda.","servicos":["AWS CloudFormation"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-042","dominio":1,"task":"1.4","tipo":"unica","enunciado":"As instâncias Amazon EC2 de desenvolvimento de uma empresa ficam ligadas 24 horas por dia, mas só são usadas em horário comercial. Qual medida reduz o custo com o MENOR esforço operacional contínuo?","alternativas":[{"texto":"Automatizar o desligamento fora do horário e o religamento no início do expediente","correta":true,"porque":"Com cobrança por uso, parar instâncias automaticamente fora do horário elimina horas pagas sem uso, sem depender de ação manual."},{"texto":"Pedir aos desenvolvedores que desliguem as instâncias ao sair","correta":false,"porque":"Depende de ação manual e costuma falhar."},{"texto":"Comprar Reserved Instances de 3 anos para essas instâncias","correta":false,"porque":"Dá desconto, mas continua pagando pelas horas ociosas."},{"texto":"Migrar as instâncias para Dedicated Hosts","correta":false,"porque":"Aumenta o custo e não resolve as horas ociosas."}],"explicacao":"Automatizar o liga/desliga de ambientes não produtivos é um benefício direto da automação e do custo variável da nuvem.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-043","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa migrou para a AWS e percebeu que o preço por GB armazenado no Amazon S3 diminuiu ao longo dos anos, sem nenhuma ação da equipe. Qual conceito de economia da nuvem explica essa redução?","alternativas":[{"texto":"Rightsizing contínuo dos recursos","correta":false,"porque":"Rightsizing exige ação do cliente para ajustar o tamanho dos recursos; aqui a redução veio da AWS."},{"texto":"Troca de custo variável por custo fixo","correta":false,"porque":"É o inverso do modelo da nuvem, que troca despesas fixas (CapEx) por variáveis (OpEx)."},{"texto":"Economias de escala da AWS repassadas em reduções de preço","correta":true,"porque":"Com o uso agregado de milhões de clientes, a AWS reduz seus custos e repassa a economia em quedas periódicas de preço."},{"texto":"Desconto por compromisso de Savings Plans","correta":false,"porque":"Savings Plans exigem compromisso de gasto por 1 ou 3 anos e não se aplicam ao armazenamento S3."}],"explicacao":"Economias de escala: a AWS já reduziu preços dezenas de vezes desde o lançamento, repassando ao cliente os ganhos de operar em grande volume.","servicos":["Amazon S3"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-044","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa ainda cria e configura servidores manualmente e registra muitos erros humanos e atrasos. Qual benefício econômico ela obtém ao automatizar o provisionamento na AWS com infraestrutura como código?","alternativas":[{"texto":"Desconto automático de Reserved Instances nos recursos criados por template","correta":false,"porque":"IaC não altera o modelo de preço; descontos dependem de compromissos como RIs e Savings Plans."},{"texto":"Menos horas de trabalho operacional e menos retrabalho causado por erros","correta":true,"porque":"Automatizar torna o provisionamento rápido, repetível e consistente, reduzindo custo de mão de obra e de falhas."},{"texto":"Isenção de cobrança pelos recursos provisionados por automação","correta":false,"porque":"Recursos criados por automação são cobrados normalmente; o CloudFormation em si não tem custo adicional."},{"texto":"Eliminação da responsabilidade do cliente pela segurança dos recursos","correta":false,"porque":"A automação não muda o modelo de responsabilidade compartilhada."}],"explicacao":"Automação (IaC, scripts, Auto Scaling) reduz esforço manual e erros, liberando a equipe para atividades de maior valor: é um dos aspectos de economia da nuvem.","servicos":["AWS CloudFormation"],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-045","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa vai criar novas aplicações na AWS em vez de usar recursos on-premises. Qual despesa é reduzida ao usar a AWS?","alternativas":[{"texto":"O custo de escrever código personalizado em Java ou Node.js","correta":false,"porque":"O desenvolvimento do código continua necessário em qualquer ambiente."},{"texto":"Os testes de intrusão de segurança da aplicação","correta":false,"porque":"A segurança da aplicação continua sendo responsabilidade do cliente."},{"texto":"A escrita de casos de teste para aplicações de terceiros","correta":false,"porque":"Testes de software não dependem da infraestrutura."},{"texto":"A compra do hardware necessário para suportar as novas aplicações","correta":true,"porque":"Na AWS não é preciso comprar servidores antecipadamente; paga-se pelos recursos usados."}],"explicacao":"A nuvem elimina o investimento em hardware próprio, um custo fixo e antecipado do modelo on-premises.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k18#32"},{"id":"D1-b-046","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Hoje, a equipe de TI de uma empresa gasta a maior parte do tempo trocando discos, instalando racks e mantendo o data center. Qual vantagem econômica a migração para a AWS traz em relação a esse custo de pessoal?","alternativas":[{"texto":"A empresa pode concentrar a equipe em atividades que diferenciam o negócio","correta":true,"porque":"A AWS assume o trabalho pesado indiferenciado da infraestrutura física, liberando o pessoal para projetos de valor."},{"texto":"A empresa deixa de ter qualquer conta de TI","correta":false,"porque":"Continua pagando pelos serviços usados na AWS."},{"texto":"A empresa pode deixar os servidores sem patches","correta":false,"porque":"Patches do sistema operacional em EC2 continuam sendo responsabilidade do cliente."},{"texto":"A AWS passa a operar as aplicações do cliente","correta":false,"porque":"A AWS cuida da infraestrutura; as aplicações continuam com o cliente."}],"explicacao":"Parte do TCO on-premises é o custo de pessoal para manter instalações e hardware; na AWS esse trabalho fica com o provedor.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k11#41 (reescrita)"},{"id":"D1-b-047","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Uma empresa de ingressos tem picos de acesso apenas em poucos dias por mês, quando abre vendas de grandes shows. Qual característica econômica da AWS MAIS beneficia esse padrão de uso?","alternativas":[{"texto":"Contratos de capacidade fixa de longo prazo","correta":false,"porque":"Capacidade fixa ficaria ociosa na maior parte do mês."},{"texto":"Custo variável, pagando apenas pelos recursos consumidos em cada momento","correta":true,"porque":"Com pay-as-you-go, a empresa paga mais nos picos e menos no restante do mês, sem manter capacidade ociosa."},{"texto":"Compra antecipada de servidores com desconto","correta":false,"porque":"Esse é o modelo de CapEx on-premises, que leva a hardware ocioso fora dos picos."},{"texto":"Uso de Dedicated Hosts para isolamento físico","correta":false,"porque":"Isolamento físico não resolve a variação de demanda e custa mais."}],"explicacao":"Cargas variáveis se beneficiam do custo variável: o gasto acompanha a demanda, sem pagar pelo pico o tempo todo.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-048","dominio":1,"task":"1.4","tipo":"unica","enunciado":"Qual item é classificado como despesa de capital (CapEx)?","alternativas":[{"texto":"A fatura mensal dos serviços AWS usados no mês","correta":false,"porque":"É despesa operacional (OpEx), paga conforme o uso."},{"texto":"O salário mensal dos administradores de sistemas","correta":false,"porque":"Despesas recorrentes com pessoal são OpEx."},{"texto":"A compra de servidores e storage para um novo data center","correta":true,"porque":"Aquisição antecipada de ativos físicos que serão depreciados é CapEx."},{"texto":"A conta de energia elétrica do escritório","correta":false,"porque":"Contas recorrentes de consumo são OpEx."}],"explicacao":"CapEx é investimento antecipado em ativos físicos; OpEx é despesa contínua com a operação, como o consumo de serviços de nuvem.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D1-b-049","dominio":1,"task":"1.4","tipo":"multipla","selecionar":2,"enunciado":"Quais são benefícios econômicos de automatizar o provisionamento e a operação da infraestrutura na AWS? (Selecione DUAS.)","alternativas":[{"texto":"Redução de erros humanos e do retrabalho que eles geram","correta":true,"porque":"Processos automatizados se repetem do mesmo jeito, evitando falhas manuais caras."},{"texto":"Eliminação de toda a responsabilidade do cliente pela segurança","correta":false,"porque":"A responsabilidade compartilhada continua valendo, com ou sem automação."},{"texto":"Desconto automático de 72% em todas as instâncias","correta":false,"porque":"Descontos dependem de compromissos (RIs, Savings Plans), não de automação."},{"texto":"Menos horas de trabalho manual da equipe em tarefas repetitivas","correta":true,"porque":"A automação reduz o custo de pessoal com tarefas operacionais rotineiras."},{"texto":"Dispensa de monitorar os recursos em produção","correta":false,"porque":"Monitoramento continua necessário; a automação inclusive depende dele."}],"explicacao":"A automação (IaC, scripts, Auto Scaling) reduz custo operacional, erros e tempo de entrega.","servicos":[],"dificuldade":2,"fonte":"autoral"},{"id":"D1-b-050","dominio":1,"task":"1.4","tipo":"unica","enunciado":"A cada quatro anos, uma empresa precisa substituir todos os servidores do seu data center por estarem obsoletos. Como a AWS elimina esse custo do ciclo de renovação de hardware?","alternativas":[{"texto":"A AWS mantém e renova o hardware físico, e o cliente usa os recursos pagando pelo consumo","correta":true,"porque":"A renovação de hardware é responsabilidade da AWS, sem novo investimento de capital pelo cliente."},{"texto":"O cliente envia seus servidores antigos para a AWS reaproveitá-los","correta":false,"porque":"A AWS não recebe hardware dos clientes para reuso."},{"texto":"O cliente compra servidores com desconto pelo AWS Marketplace","correta":false,"porque":"O Marketplace vende software e serviços, e comprar hardware manteria o ciclo de CapEx."},{"texto":"O cliente contrata Dedicated Hosts, que nunca precisam ser substituídos","correta":false,"porque":"Dedicated Hosts também rodam em hardware mantido pela AWS; não são ativos do cliente."}],"explicacao":"Na nuvem, depreciação e renovação de hardware deixam de ser custos do cliente.","servicos":[],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-001","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Segundo o modelo de responsabilidade compartilhada da AWS, quais itens são de responsabilidade do cliente? (Selecione DUAS.)","alternativas":[{"texto":"Segurança física do backbone de rede global da AWS","correta":false,"porque":"É segurança DA nuvem: a AWS protege a rede física global."},{"texto":"Criar IAM users e roles dentro da conta","correta":true,"porque":"Gestão de identidades e acessos na própria conta é segurança NA nuvem, do cliente."},{"texto":"Validar a conformidade da infraestrutura da AWS com auditorias externas","correta":false,"porque":"A AWS contrata auditores independentes e publica os relatórios no AWS Artifact."},{"texto":"Impedir que funcionários da AWS acessem os data centers sem autorização","correta":false,"porque":"Controle de acesso físico aos data centers é responsabilidade exclusiva da AWS."},{"texto":"Aplicar patches no sistema operacional de uma instância Amazon EC2","correta":true,"porque":"O SO convidado do EC2 (IaaS) é gerenciado pelo cliente."}],"explicacao":"O cliente cuida do que coloca na nuvem (identidades, SO convidado, dados, configurações); a AWS cuida da infraestrutura física e global.","servicos":["IAM","EC2"],"dificuldade":1,"fonte":"usuario-A03"},{"id":"D2-a-002","dominio":2,"task":"2.1","tipo":"unica","enunciado":"A aplicação web de um cliente, executada em instâncias Amazon EC2, sofreu um ataque de SQL injection. O cliente abriu uma reclamação com a AWS. Qual resposta ele deve esperar?","alternativas":[{"texto":"A AWS reforçará a infraestrutura física para evitar novos incidentes","correta":false,"porque":"SQL injection explora o código da aplicação, não a infraestrutura física da AWS."},{"texto":"A segurança da aplicação é do cliente, conforme o modelo de responsabilidade compartilhada","correta":true,"porque":"Código, validação de entrada e proteção da aplicação são segurança NA nuvem, do cliente."},{"texto":"A AWS e o cliente devem contratar juntos um auditor independente","correta":false,"porque":"Não existe essa obrigação; a análise do incidente na aplicação cabe ao cliente."},{"texto":"A AWS responderá que o cliente deveria ter aplicado patches no SO da instância","correta":false,"porque":"Patch de SO não corrige falha de validação de entrada; a causa está no código da aplicação."}],"explicacao":"A segurança das aplicações que o cliente implanta (incluindo proteção contra SQL injection, por exemplo com AWS WAF) é responsabilidade do cliente.","servicos":["EC2"],"dificuldade":1,"fonte":"usuario-A35"},{"id":"D2-a-003","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada da AWS, qual item é um controle COMPARTILHADO entre a AWS e o cliente?","alternativas":[{"texto":"Aplicação de patches no sistema operacional do host físico","correta":false,"porque":"O SO do host e a virtualização são responsabilidade exclusiva da AWS."},{"texto":"Criptografia de dados do lado do cliente (client-side)","correta":false,"porque":"Criptografar dados antes de enviá-los é responsabilidade exclusiva do cliente."},{"texto":"Proteção física e ambiental dos data centers","correta":false,"porque":"É um controle herdado: o cliente o recebe integralmente da AWS."},{"texto":"Conscientização e treinamento (awareness & training)","correta":true,"porque":"A AWS treina seus funcionários e o cliente treina os seus: o controle é compartilhado."}],"explicacao":"Controles compartilhados (patch management, configuration management, awareness & training) existem nas duas camadas, cada parte cuidando da sua.","servicos":[],"dificuldade":1,"fonte":"usuario-B25"},{"id":"D2-a-004","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada, quais controles o cliente HERDA integralmente da AWS ao usar a nuvem?","alternativas":[{"texto":"Controles físicos e ambientais dos data centers","correta":true,"porque":"Energia, refrigeração, acesso físico e proteção contra incêndio são da AWS; o cliente herda esses controles."},{"texto":"Gestão de patches do sistema operacional convidado","correta":false,"porque":"Patch management é controle compartilhado: o SO convidado é do cliente."},{"texto":"Gestão de configuração dos recursos implantados","correta":false,"porque":"Configuration management é compartilhado: o cliente configura seus SOs, bancos e aplicações."},{"texto":"Gestão de usuários e permissões no IAM","correta":false,"porque":"Identidades e permissões na conta são responsabilidade do cliente."}],"explicacao":"Controles herdados são aqueles que o cliente recebe totalmente da AWS, como os controles físicos e ambientais da infraestrutura.","servicos":[],"dificuldade":3,"fonte":"usuario-B30 (reescrita)"},{"id":"D2-a-005","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa usa Amazon WorkSpaces para fornecer desktops virtuais. Segundo o modelo de responsabilidade compartilhada, qual tarefa continua sendo do cliente?","alternativas":[{"texto":"Manter os servidores físicos que hospedam os WorkSpaces","correta":false,"porque":"O hardware subjacente é mantido pela AWS."},{"texto":"Atualizar o hipervisor que executa os desktops","correta":false,"porque":"A camada de virtualização é responsabilidade da AWS."},{"texto":"Atualizar as aplicações instaladas pelo cliente dentro do desktop","correta":true,"porque":"Software que o cliente instala e gerencia no WorkSpace é responsabilidade dele."},{"texto":"Garantir a redundância da rede entre as Availability Zones","correta":false,"porque":"A rede e as AZs da infraestrutura global são operadas pela AWS."}],"explicacao":"Mesmo em serviços gerenciados de end-user computing, as aplicações e os dados que o cliente coloca no ambiente são responsabilidade dele.","servicos":["WorkSpaces"],"dificuldade":2,"fonte":"usuario-B46 (reescrita)"},{"id":"D2-a-006","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa de e-commerce começou a usar a AWS. Quais responsabilidades de segurança estão no escopo da empresa segundo o modelo de responsabilidade compartilhada? (Selecione DUAS.)","alternativas":[{"texto":"Restringir o acesso físico aos hosts que executam suas instâncias Amazon EC2","correta":false,"porque":"Acesso físico ao hardware é controlado exclusivamente pela AWS."},{"texto":"Apagar os volumes Amazon EBS de forma segura antes do descarte do hardware","correta":false,"porque":"O descarte seguro de mídias de armazenamento é feito pela AWS."},{"texto":"Escolher e gerenciar as configurações de criptografia dos dados no Amazon S3","correta":true,"porque":"Decidir se e como criptografar os dados (SSE-S3, SSE-KMS, client-side) é do cliente."},{"texto":"Instalar patches de segurança em instâncias Linux do Amazon EC2","correta":true,"porque":"O SO convidado de instâncias EC2 é mantido pelo cliente."},{"texto":"Aplicar patches no mecanismo de banco de dados de instâncias Amazon RDS","correta":false,"porque":"No RDS, a AWS aplica os patches do SO e do engine, na janela de manutenção definida pelo cliente."}],"explicacao":"Criptografia de dados e patch do SO convidado no EC2 são segurança NA nuvem; hardware, descarte de mídia e patches gerenciados do RDS são da AWS.","servicos":["S3","EC2","RDS"],"dificuldade":2,"fonte":"usuario-B56"},{"id":"D2-a-007","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Quais são responsabilidades do cliente ao usar o AWS Lambda? (Selecione DUAS.)","alternativas":[{"texto":"Garantir a segurança dentro do código da função","correta":true,"porque":"Validação de entrada, tratamento de segredos e dependências do código são do cliente."},{"texto":"Provisionar e escalar os servidores que executam as funções","correta":false,"porque":"No Lambda, a AWS gerencia servidores e escalabilidade automaticamente."},{"texto":"Aplicar patches no sistema operacional do ambiente de execução","correta":false,"porque":"O SO e o runtime gerenciado são atualizados pela AWS."},{"texto":"Escrever e atualizar o código da função","correta":true,"porque":"O código é do cliente; a AWS apenas o executa."},{"texto":"Proteger a infraestrutura física subjacente","correta":false,"porque":"A infraestrutura física é sempre responsabilidade da AWS."}],"explicacao":"Em serviços serverless como o Lambda, a responsabilidade do cliente se concentra em código, dados e permissões (IAM).","servicos":["Lambda"],"dificuldade":2,"fonte":"usuario-B59"},{"id":"D2-a-008","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Quais controles de segurança são gerenciados pelo cliente, e não pela AWS, segundo o modelo de responsabilidade compartilhada? (Selecione DUAS.)","alternativas":[{"texto":"Aplicar patches no sistema operacional do Amazon RDS","correta":false,"porque":"No RDS, os patches do SO são aplicados pela AWS."},{"texto":"Atualizar o firmware da infraestrutura de rede da AWS","correta":false,"porque":"Firmware de equipamentos de rede é responsabilidade da AWS."},{"texto":"Gerenciar a criptografia dos dados","correta":true,"porque":"O cliente decide quais dados criptografar e como gerenciar as chaves."},{"texto":"Manter o controle de acesso físico às instalações de uma Região","correta":false,"porque":"Acesso físico é controle exclusivo da AWS."},{"texto":"Conceder acesso de menor privilégio aos usuários do IAM","correta":true,"porque":"Definir permissões no IAM é responsabilidade do cliente."}],"explicacao":"Dados (incluindo criptografia) e identidades/permissões são sempre responsabilidade do cliente, em qualquer serviço.","servicos":["IAM","KMS"],"dificuldade":2,"fonte":"usuario-B60"},{"id":"D2-a-009","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Qual atividade é de inteira responsabilidade do cliente ao executar uma carga de trabalho IaaS no Amazon EC2?","alternativas":[{"texto":"Aplicar patches nos componentes do hipervisor","correta":false,"porque":"O hipervisor é gerenciado pela AWS."},{"texto":"Configurar security groups e tabelas de rotas para o tráfego da aplicação","correta":true,"porque":"A configuração de rede virtual e firewall da VPC é feita pelo cliente."},{"texto":"Manter controles físicos e ambientais no data center","correta":false,"porque":"São controles herdados da AWS."},{"texto":"Manter os componentes da infraestrutura de rede subjacente","correta":false,"porque":"A rede física é responsabilidade da AWS."}],"explicacao":"No IaaS o cliente controla rede virtual (security groups, NACLs, rotas), SO convidado e aplicações.","servicos":["EC2","VPC"],"dificuldade":2,"fonte":"usuario-B63"},{"id":"D2-a-010","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada da AWS, qual tarefa é de responsabilidade do cliente?","alternativas":[{"texto":"Manter a configuração dos dispositivos de infraestrutura","correta":false,"porque":"Dispositivos de infraestrutura são configurados pela AWS."},{"texto":"Gerenciar o SO do host e a camada de virtualização","correta":false,"porque":"Host e virtualização são responsabilidade da AWS."},{"texto":"Manter o software que opera as Availability Zones","correta":false,"porque":"O software da infraestrutura global é da AWS."},{"texto":"Gerenciar os sistemas operacionais convidados (guest OS)","correta":true,"porque":"O SO das instâncias é do cliente, incluindo patches e configuração."}],"explicacao":"Guest OS = cliente; host OS, virtualização e infraestrutura = AWS.","servicos":["EC2"],"dificuldade":1,"fonte":"usuario-B72"},{"id":"D2-a-011","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Qual tarefa é de responsabilidade da AWS quando uma carga de trabalho usa o Amazon RDS?","alternativas":[{"texto":"Instalar e aplicar patches no software do mecanismo de banco de dados","correta":true,"porque":"No RDS a AWS gerencia instalação e patches do engine e do SO."},{"texto":"Criar as tabelas do banco de dados","correta":false,"porque":"A modelagem e a criação de tabelas são do cliente."},{"texto":"Atualizar o esquema do banco de dados","correta":false,"porque":"Alterações de esquema são decisões do cliente."},{"texto":"Excluir registros obsoletos do banco de dados","correta":false,"porque":"O conteúdo e o ciclo de vida dos dados são do cliente."}],"explicacao":"Em um banco gerenciado, a AWS cuida de SO, engine e infraestrutura; o cliente cuida de esquema, dados e acessos.","servicos":["RDS"],"dificuldade":1,"fonte":"usuario-B83"},{"id":"D2-a-012","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Em qual serviço o cliente é responsável pela configuração do sistema operacional, pelos patches de segurança e pela configuração de rede da instância?","alternativas":[{"texto":"Amazon RDS","correta":false,"porque":"No RDS a AWS gerencia o SO e os patches do banco."},{"texto":"Amazon ElastiCache","correta":false,"porque":"É gerenciado: a AWS mantém os nós e o software."},{"texto":"Amazon EC2","correta":true,"porque":"No EC2 (IaaS) o cliente gerencia o SO convidado, seus patches e a rede da instância."},{"texto":"AWS Fargate","correta":false,"porque":"No Fargate não há SO de host para o cliente gerenciar."}],"explicacao":"Quanto mais próximo do IaaS (EC2), mais responsabilidade operacional e de segurança fica com o cliente.","servicos":["EC2","RDS","ElastiCache","Fargate"],"dificuldade":1,"fonte":"kananinirav-k12#12"},{"id":"D2-a-013","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Quais são exemplos de controles compartilhados no modelo de responsabilidade compartilhada da AWS? (Selecione DUAS.)","alternativas":[{"texto":"Gestão de patches (patch management)","correta":true,"porque":"A AWS corrige a infraestrutura; o cliente corrige SO convidado e aplicações."},{"texto":"Gestão de usuários do IAM","correta":false,"porque":"Usuários e permissões na conta são exclusivamente do cliente."},{"texto":"Operação dos data centers","correta":false,"porque":"É responsabilidade exclusiva da AWS (controle herdado)."},{"texto":"Gestão de configuração (configuration management)","correta":true,"porque":"A AWS configura a infraestrutura; o cliente configura SOs, bancos e aplicações."},{"texto":"Controles ambientais (energia e refrigeração)","correta":false,"porque":"São controles herdados da AWS."}],"explicacao":"Patch management, configuration management e awareness & training são os três controles compartilhados citados pela AWS.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k1#38"},{"id":"D2-a-014","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Qual afirmação sobre o modelo de responsabilidade compartilhada da AWS é verdadeira?","alternativas":[{"texto":"A segurança dos serviços IaaS é inteiramente da AWS","correta":false,"porque":"No IaaS o cliente tem a maior parcela de responsabilidade (SO, rede, aplicações)."},{"texto":"As responsabilidades variam conforme os serviços utilizados","correta":true,"porque":"A divisão muda entre EC2, RDS, Lambda etc.: quanto mais gerenciado, menos o cliente gerencia."},{"texto":"O patch do SO convidado é sempre responsabilidade da AWS","correta":false,"porque":"No EC2 o patch do SO convidado é do cliente."},{"texto":"A segurança dos serviços gerenciados é inteiramente do cliente","correta":false,"porque":"Em serviços gerenciados a AWS assume SO, plataforma e infraestrutura."}],"explicacao":"A linha de responsabilidade se desloca conforme o tipo de serviço: IaaS, serviços gerenciados ou serverless.","servicos":[],"dificuldade":1,"fonte":"kananinirav-k1#5"},{"id":"D2-a-015","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada, quem é responsável por operar e escalar a infraestrutura que executa as tabelas do Amazon DynamoDB?","alternativas":[{"texto":"A equipe de segurança do cliente","correta":false,"porque":"O cliente não gerencia servidores no DynamoDB."},{"texto":"A equipe de desenvolvimento do cliente","correta":false,"porque":"Os desenvolvedores definem tabelas e acesso, não a infraestrutura."},{"texto":"A equipe de DevOps do cliente","correta":false,"porque":"Não há servidores ou SO para a equipe de operações do cliente administrar."},{"texto":"A AWS","correta":true,"porque":"O DynamoDB é serverless: a AWS opera, corrige e escala a infraestrutura."}],"explicacao":"No DynamoDB o cliente cuida de dados, permissões IAM e configurações (como modo de capacidade); a AWS cuida da infraestrutura.","servicos":["DynamoDB"],"dificuldade":2,"fonte":"kananinirav-k7#38 (reescrita)"},{"id":"D2-a-016","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada, qual das opções é responsabilidade do cliente?","alternativas":[{"texto":"Instalar patches do SO de instâncias Amazon EC2 que executam um banco de dados","correta":true,"porque":"Banco autogerenciado no EC2: SO e software do banco são do cliente."},{"texto":"Instalar patches de segurança nos hipervisores da AWS","correta":false,"porque":"O hipervisor é mantido pela AWS."},{"texto":"Instalar patches do SO dos servidores do Amazon DynamoDB","correta":false,"porque":"O DynamoDB é totalmente gerenciado pela AWS."},{"texto":"Instalar patches do SO de instâncias de banco do Amazon RDS","correta":false,"porque":"No RDS os patches do SO são aplicados pela AWS."}],"explicacao":"Um banco instalado no EC2 deixa SO, engine e patches com o cliente; no RDS ou DynamoDB isso passa para a AWS.","servicos":["EC2","RDS","DynamoDB"],"dificuldade":2,"fonte":"kananinirav-k20#40"},{"id":"D2-a-017","dominio":2,"task":"2.1","tipo":"unica","enunciado":"No modelo de responsabilidade compartilhada, o que significa a responsabilidade da AWS pela \"segurança DA nuvem\"?","alternativas":[{"texto":"Proteger os dados que o cliente armazena nos serviços","correta":false,"porque":"Proteger os dados é segurança NA nuvem, do cliente."},{"texto":"Configurar as permissões IAM de cada conta","correta":false,"porque":"Permissões IAM são configuradas pelo cliente."},{"texto":"Proteger hardware, software, rede e instalações que executam os serviços","correta":true,"porque":"É a infraestrutura global que a AWS opera e protege."},{"texto":"Corrigir as vulnerabilidades das aplicações do cliente","correta":false,"porque":"As aplicações do cliente são responsabilidade dele."}],"explicacao":"Segurança DA nuvem (AWS) = infraestrutura; segurança NA nuvem (cliente) = o que ele coloca e configura na nuvem.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D2-a-018","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Qual tarefa é de responsabilidade da AWS?","alternativas":[{"texto":"Criar IAM users e grupos","correta":false,"porque":"Identidades na conta são criadas pelo cliente."},{"texto":"Destruir fisicamente as mídias de armazenamento no fim da vida útil","correta":true,"porque":"O descarte seguro de mídias segue padrões do setor e é feito pela AWS."},{"texto":"Aplicar patches no SO convidado das instâncias","correta":false,"porque":"O SO convidado é do cliente."},{"texto":"Configurar as opções de segurança das instâncias Amazon EC2","correta":false,"porque":"Security groups e hardening da instância são do cliente."}],"explicacao":"A AWS é responsável pelo ciclo de vida do hardware, incluindo o descarte seguro de dispositivos de armazenamento.","servicos":[],"dificuldade":2,"fonte":"kananinirav-k17#8"},{"id":"D2-a-019","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada, qual tarefa é da AWS?","alternativas":[{"texto":"Habilitar criptografia server-side nos objetos do Amazon S3","correta":false,"porque":"Escolher e habilitar a criptografia é decisão do cliente."},{"texto":"Aplicar políticas de segurança do IAM","correta":false,"porque":"Políticas IAM são definidas e aplicadas pelo cliente."},{"texto":"Aplicar patches no SO de uma instância Amazon EC2","correta":false,"porque":"O SO convidado do EC2 é do cliente."},{"texto":"Aplicar atualizações no hipervisor","correta":true,"porque":"A camada de virtualização é mantida pela AWS."}],"explicacao":"Hipervisor e host pertencem à infraestrutura da AWS; criptografia, IAM e SO convidado ficam com o cliente.","servicos":["EC2","S3","IAM"],"dificuldade":2,"fonte":"kananinirav-k22#33"},{"id":"D2-a-020","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa executa contêineres no Amazon ECS com AWS Fargate. Segundo o modelo de responsabilidade compartilhada, qual tarefa é do cliente?","alternativas":[{"texto":"Manter as imagens de contêiner e o código da aplicação seguros","correta":true,"porque":"Imagens, dependências, código e permissões das tarefas são do cliente."},{"texto":"Aplicar patches no SO dos hosts que executam as tarefas","correta":false,"porque":"No Fargate a AWS gerencia e corrige os hosts."},{"texto":"Escalar a frota de instâncias EC2 do cluster","correta":false,"porque":"Com Fargate não existe frota de instâncias para o cliente gerenciar."},{"texto":"Manter o runtime de contêiner instalado nos servidores","correta":false,"porque":"O runtime e o host são mantidos pela AWS."}],"explicacao":"No Fargate (serverless para contêineres) a AWS gerencia hosts e SO; o cliente cuida das imagens, do código, dos dados e do IAM.","servicos":["Fargate","ECS"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-021","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa armazena documentos no Amazon S3. Segundo o modelo de responsabilidade compartilhada, qual tarefa é do cliente?","alternativas":[{"texto":"Replicar os objetos entre dispositivos para garantir a durabilidade","correta":false,"porque":"A durabilidade da infraestrutura do S3 é responsabilidade da AWS."},{"texto":"Manter os servidores de armazenamento do serviço","correta":false,"porque":"Servidores e discos do S3 são da AWS."},{"texto":"Configurar bucket policies e o Block Public Access","correta":true,"porque":"Quem pode acessar os dados é uma configuração do cliente."},{"texto":"Aplicar patches no software que executa o S3","correta":false,"porque":"O software do serviço é mantido pela AWS."}],"explicacao":"No S3 a AWS opera o serviço; o cliente controla acesso (bucket policies, IAM, Block Public Access), criptografia e classificação dos dados.","servicos":["S3"],"dificuldade":1,"fonte":"autoral"},{"id":"D2-a-022","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa migra uma API de instâncias Amazon EC2 para o AWS Lambda. Qual responsabilidade deixa de ser do cliente e passa para a AWS?","alternativas":[{"texto":"Definir as permissões IAM da função","correta":false,"porque":"Permissões continuam sendo configuradas pelo cliente."},{"texto":"Aplicar patches no sistema operacional e no runtime","correta":true,"porque":"No Lambda, a AWS mantém o SO e o runtime gerenciado."},{"texto":"Proteger os dados processados pela API","correta":false,"porque":"Os dados continuam sendo do cliente."},{"texto":"Corrigir vulnerabilidades no código da API","correta":false,"porque":"O código continua sendo do cliente."}],"explicacao":"Ao sair do IaaS para o serverless, SO, runtime e escalabilidade passam para a AWS; código, dados e IAM continuam com o cliente.","servicos":["Lambda","EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-023","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa migra um banco MySQL instalado no Amazon EC2 para o Amazon RDS for MySQL. Qual responsabilidade CONTINUA com o cliente?","alternativas":[{"texto":"Aplicar patches no SO do servidor de banco","correta":false,"porque":"No RDS a AWS aplica os patches do SO."},{"texto":"Instalar o software do mecanismo MySQL","correta":false,"porque":"O RDS provisiona e mantém o engine."},{"texto":"Substituir o hardware do servidor quando ele falhar","correta":false,"porque":"Hardware é sempre responsabilidade da AWS."},{"texto":"Gerenciar usuários do banco e o acesso de rede via security groups","correta":true,"porque":"Contas do banco, permissões e regras de rede são configuradas pelo cliente."}],"explicacao":"Com o RDS a AWS assume SO, engine e hardware; o cliente mantém dados, usuários, acesso de rede e configurações do banco.","servicos":["RDS","EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-024","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Qual responsabilidade é do cliente em TODOS os serviços da AWS, seja Amazon EC2, Amazon RDS, AWS Lambda ou Amazon DynamoDB?","alternativas":[{"texto":"Proteger os dados e gerenciar quem pode acessá-los","correta":true,"porque":"Dados e gestão de acesso (IAM) nunca deixam de ser do cliente."},{"texto":"Aplicar patches no sistema operacional","correta":false,"porque":"Em RDS, Lambda e DynamoDB o SO é gerenciado pela AWS."},{"texto":"Manter o software do serviço atualizado","correta":false,"porque":"O software dos serviços gerenciados é mantido pela AWS."},{"texto":"Planejar a capacidade dos servidores","correta":false,"porque":"Em serviços serverless não há servidores para dimensionar."}],"explicacao":"Independentemente do serviço, o cliente sempre é responsável pelos seus dados, pela classificação deles e pelo controle de acesso.","servicos":["EC2","RDS","Lambda","DynamoDB"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-025","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Patch management é um controle compartilhado. Como essa responsabilidade é dividida em uma carga de trabalho no Amazon EC2?","alternativas":[{"texto":"A AWS corrige o SO convidado e o cliente corrige as aplicações","correta":false,"porque":"O SO convidado das instâncias é do cliente, não da AWS."},{"texto":"O cliente corrige o hipervisor e a AWS corrige o SO convidado","correta":false,"porque":"É o inverso: o hipervisor é da AWS e o SO convidado é do cliente."},{"texto":"A AWS corrige a infraestrutura e o cliente corrige o SO convidado e as aplicações","correta":true,"porque":"Cada parte corrige a camada que controla."},{"texto":"A AWS corrige tudo automaticamente, desde que o cliente habilite o recurso","correta":false,"porque":"A AWS não aplica patches no SO convidado do EC2 por conta própria; o cliente pode automatizar com Systems Manager."}],"explicacao":"Em controles compartilhados cada parte cuida da sua camada: AWS = infraestrutura; cliente = SO convidado, aplicações e dados.","servicos":["EC2","Systems Manager"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-026","dominio":2,"task":"2.1","tipo":"multipla","selecionar":2,"enunciado":"Segundo o modelo de responsabilidade compartilhada, quais atividades são do cliente? (Selecione DUAS.)","alternativas":[{"texto":"Aplicar patches nos componentes de SO do Amazon RDS","correta":false,"porque":"No RDS a AWS aplica os patches do SO."},{"texto":"Criptografar os dados no lado do cliente (client-side)","correta":true,"porque":"Criptografar antes de enviar à AWS é decisão e tarefa do cliente."},{"texto":"Treinar a equipe dos data centers da AWS","correta":false,"porque":"A AWS treina seus próprios funcionários."},{"texto":"Configurar Network ACLs na VPC","correta":true,"porque":"As regras de rede da VPC são configuradas pelo cliente."},{"texto":"Manter os controles ambientais do data center","correta":false,"porque":"São controles herdados da AWS."}],"explicacao":"Criptografia client-side e regras de rede da VPC (NACLs, security groups) são segurança NA nuvem.","servicos":["VPC","RDS"],"dificuldade":2,"fonte":"kananinirav-k9#22"},{"id":"D2-a-027","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Segundo o modelo de responsabilidade compartilhada, qual item é responsabilidade EXCLUSIVA da AWS?","alternativas":[{"texto":"Segurança das aplicações","correta":false,"porque":"Aplicações são do cliente."},{"texto":"Gerenciamento das edge locations","correta":true,"porque":"Edge locations fazem parte da infraestrutura global operada pela AWS."},{"texto":"Gestão de patches","correta":false,"porque":"Patch management é um controle compartilhado."},{"texto":"Dados do lado do cliente","correta":false,"porque":"Dados são sempre do cliente."}],"explicacao":"Regiões, AZs e edge locations são infraestrutura global: segurança DA nuvem, exclusiva da AWS.","servicos":["CloudFront"],"dificuldade":2,"fonte":"kananinirav-k9#11"},{"id":"D2-a-028","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma empresa executa contêineres no Amazon ECS sobre instâncias EC2 e quer deixar de ser responsável por aplicar patches no SO dos hosts. Qual opção atende com o MENOR esforço operacional?","alternativas":[{"texto":"Usar instâncias EC2 Dedicated Hosts","correta":false,"porque":"Dedicated Hosts dão hardware dedicado, mas o SO continua sendo do cliente."},{"texto":"Armazenar as imagens no Amazon ECR","correta":false,"porque":"O ECR guarda imagens, mas não muda quem gerencia o SO dos hosts."},{"texto":"Usar o Amazon EKS com nós EC2 autogerenciados","correta":false,"porque":"Nós EC2 autogerenciados continuam exigindo patches do cliente."},{"texto":"Migrar os contêineres para o AWS Fargate","correta":true,"porque":"Com Fargate a AWS gerencia os hosts e seus patches."}],"explicacao":"Fargate remove do cliente a gestão de servidores e SO dos hosts de contêineres.","servicos":["Fargate","ECS"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-029","dominio":2,"task":"2.1","tipo":"unica","enunciado":"No Amazon RDS, quem decide se a instância terá implantação Multi-AZ e por quantos dias os backups automáticos serão retidos?","alternativas":[{"texto":"O cliente, que configura essas opções e a AWS as executa","correta":true,"porque":"Multi-AZ e período de retenção são configurações escolhidas pelo cliente."},{"texto":"A AWS, porque o RDS é um serviço gerenciado","correta":false,"porque":"A AWS executa failover e backups, mas a escolha dessas opções é do cliente."},{"texto":"A AWS, apenas para bancos em produção","correta":false,"porque":"A AWS não classifica as cargas do cliente nem decide por ele."},{"texto":"O AWS Support, mediante abertura de caso","correta":false,"porque":"São configurações de autoatendimento no console, API ou CLI."}],"explicacao":"Mesmo em serviços gerenciados, configuration management é compartilhado: o cliente escolhe as opções e a AWS opera a infraestrutura.","servicos":["RDS"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-030","dominio":2,"task":"2.1","tipo":"unica","enunciado":"Uma aplicação executada em uma única instância Amazon EC2 ficou fora do ar durante uma falha em uma Availability Zone. Segundo o modelo de responsabilidade compartilhada, a quem cabe tornar essa carga de trabalho resiliente?","alternativas":[{"texto":"À AWS, que deve mover a instância para outra AZ automaticamente","correta":false,"porque":"O EC2 não migra instâncias entre AZs automaticamente."},{"texto":"À AWS, porque disponibilidade é sempre responsabilidade do provedor","correta":false,"porque":"A AWS garante a infraestrutura das AZs, não a arquitetura da carga do cliente."},{"texto":"Ao cliente, que deve distribuir a aplicação em várias AZs","correta":true,"porque":"Projetar redundância (multi-AZ, Auto Scaling, backups) é do cliente."},{"texto":"Ao AWS Support, que deve restaurar a instância","correta":false,"porque":"O Support orienta, mas não é responsável pela arquitetura do cliente."}],"explicacao":"A AWS oferece AZs isoladas e confiáveis; usar essa infraestrutura para criar resiliência é responsabilidade do cliente.","servicos":["EC2"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-031","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa de capital aberto sujeita à lei Sarbanes-Oxley (SOX) precisa apresentar aos auditores os relatórios SOC 1 e SOC 2 da AWS. Onde ela obtém esses documentos?","alternativas":[{"texto":"AWS Certificate Manager (ACM)","correta":false,"porque":"O ACM gerencia certificados SSL/TLS, não relatórios de auditoria."},{"texto":"AWS Artifact","correta":true,"porque":"O Artifact dá acesso sob demanda aos relatórios de conformidade da AWS, como SOC, ISO e PCI."},{"texto":"AWS Security Hub","correta":false,"porque":"O Security Hub avalia a postura de segurança da conta do cliente, não fornece relatórios de auditoria da AWS."},{"texto":"AWS GovCloud (US)","correta":false,"porque":"GovCloud é uma Região isolada para cargas reguladas dos EUA, não um repositório de relatórios."}],"explicacao":"O AWS Artifact é o portal self-service para baixar relatórios de conformidade da AWS (SOC, PCI, ISO) e aceitar acordos.","servicos":["Artifact"],"dificuldade":1,"fonte":"usuario-A29"},{"id":"D2-a-032","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa quer exigir uma autenticação adicional antes que versões de objetos de um bucket do Amazon S3 possam ser excluídas permanentemente. Qual recurso atende a esse requisito?","alternativas":[{"texto":"S3 server access logging","correta":false,"porque":"Registra as requisições ao bucket, mas não impede exclusões (é um controle de detecção)."},{"texto":"Criptografia padrão SSE-S3","correta":false,"porque":"Protege a confidencialidade dos dados em repouso, não impede exclusões."},{"texto":"S3 Lifecycle policy","correta":false,"porque":"Automatiza transições e expirações; pode até excluir objetos, não protegê-los."},{"texto":"S3 Versioning com MFA Delete","correta":true,"porque":"MFA Delete exige um código MFA para excluir versões permanentemente ou mudar o estado do versionamento."}],"explicacao":"MFA Delete, habilitado pelo root user em um bucket com versionamento, é um controle preventivo contra exclusões acidentais ou maliciosas.","servicos":["S3"],"dificuldade":2,"fonte":"usuario-A34 (reescrita)"},{"id":"D2-a-033","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual serviço da AWS avalia continuamente se as configurações dos recursos de uma conta estão de acordo com um conjunto definido de regras?","alternativas":[{"texto":"AWS Config","correta":true,"porque":"O Config registra as configurações e as avalia continuamente com Config rules."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas, logs e alarmes de desempenho, não conformidade de configuração."},{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade da própria AWS."},{"texto":"AWS IAM","correta":false,"porque":"Gerencia identidades e permissões, não avalia a configuração dos recursos."}],"explicacao":"AWS Config = inventário, histórico de configuração e avaliação contínua de conformidade com regras.","servicos":["Config"],"dificuldade":1,"fonte":"usuario-A47"},{"id":"D2-a-034","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual serviço gerenciado da AWS permite criar e controlar chaves criptográficas usadas para criptografar dados e assinar mensagens, sem que o cliente precise operar um módulo de hardware próprio?","alternativas":[{"texto":"AWS Systems Manager","correta":false,"porque":"Gerencia operações em instâncias e guarda parâmetros, não chaves criptográficas."},{"texto":"AWS CloudHSM","correta":false,"porque":"Fornece HSMs dedicados que o cliente opera e gerencia (cluster, usuários, chaves)."},{"texto":"AWS Key Management Service (AWS KMS)","correta":true,"porque":"O KMS é gerenciado: a AWS opera os HSMs e o cliente controla as chaves e suas políticas."},{"texto":"AWS IAM","correta":false,"porque":"Controla permissões, inclusive de uso de chaves, mas não cria chaves criptográficas."}],"explicacao":"KMS é o serviço gerenciado de chaves integrado à maioria dos serviços; CloudHSM é a opção de HSM dedicado operado pelo cliente.","servicos":["KMS","CloudHSM"],"dificuldade":1,"fonte":"usuario-A61"},{"id":"D2-a-035","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa precisa identificar qual IAM user encerrou uma instância Amazon EC2 de produção. Qual serviço ela deve usar?","alternativas":[{"texto":"Amazon CloudWatch","correta":false,"porque":"Mostra métricas e alarmes da instância, não quem fez a chamada de API."},{"texto":"AWS CloudTrail","correta":true,"porque":"Registra cada chamada de API com identidade, horário, IP de origem e ação, como TerminateInstances."},{"texto":"AWS Config","correta":false,"porque":"Registra a mudança de configuração do recurso, mas o autor da ação vem do CloudTrail."},{"texto":"AWS Systems Manager","correta":false,"porque":"Gerencia e automatiza operações em instâncias, não audita chamadas de API."}],"explicacao":"CloudTrail responde \"quem fez o quê, quando e de onde\" na conta AWS.","servicos":["CloudTrail"],"dificuldade":1,"fonte":"usuario-B06"},{"id":"D2-a-036","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual serviço da AWS ajuda a proteger uma conta monitorando continuamente atividades maliciosas e gerando alertas sobre ameaças detectadas?","alternativas":[{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz verificações de boas práticas, não detecção de ameaças em tempo real."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas e logs, mas não analisa ameaças por conta própria."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra atividades, mas não as analisa para detectar ameaças."},{"texto":"Amazon GuardDuty","correta":true,"porque":"Analisa CloudTrail, VPC Flow Logs e DNS com inteligência de ameaças e ML para gerar achados."}],"explicacao":"GuardDuty é o serviço gerenciado de detecção de ameaças: basta habilitar, sem agentes nem infraestrutura.","servicos":["GuardDuty"],"dificuldade":1,"fonte":"usuario-B09"},{"id":"D2-a-037","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual é o principal caso de uso do AWS Control Tower?","alternativas":[{"texto":"Configurar e governar uma landing zone multi-conta segura seguindo boas práticas","correta":true,"porque":"O Control Tower automatiza a landing zone com Organizations, guardrails (controls) e contas compartilhadas."},{"texto":"Implantar automaticamente aplicações populares, como WordPress, em uma conta","correta":false,"porque":"Isso descreve AMIs do Marketplace ou Lightsail, não governança multi-conta."},{"texto":"Centralizar todos os tipos de arquivos de log em um único repositório","correta":false,"porque":"O Control Tower cria uma conta de log archive, mas esse não é o seu propósito principal."},{"texto":"Detectar ameaças e comportamentos anômalos nas contas","correta":false,"porque":"Detecção de ameaças é função do GuardDuty."}],"explicacao":"Control Tower = maneira mais fácil de montar e governar um ambiente multi-conta (landing zone) com controles preventivos e de detecção.","servicos":["Control Tower","Organizations"],"dificuldade":2,"fonte":"usuario-B21"},{"id":"D2-a-038","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Quando o Amazon EBS criptografa volumes e snapshots, qual serviço da AWS ele usa para gerenciar as chaves?","alternativas":[{"texto":"AWS Shield","correta":false,"porque":"Protege contra DDoS, não gerencia chaves."},{"texto":"AWS Secrets Manager","correta":false,"porque":"Armazena e rotaciona segredos como senhas, não as chaves de criptografia do EBS."},{"texto":"AWS KMS","correta":true,"porque":"A criptografia do EBS usa chaves do KMS (gerenciada pela AWS ou pelo cliente)."},{"texto":"AWS Certificate Manager (ACM)","correta":false,"porque":"Fornece certificados TLS para criptografia em trânsito, não em repouso."}],"explicacao":"EBS, S3 (SSE-KMS), RDS e muitos outros serviços integram-se ao KMS para criptografia em repouso.","servicos":["EBS","KMS"],"dificuldade":2,"fonte":"usuario-B35 (reescrita)"},{"id":"D2-a-039","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual serviço da AWS consolida achados de segurança e verificações de conformidade de várias contas e serviços em uma visão unificada?","alternativas":[{"texto":"AWS Config","correta":false,"porque":"Avalia configurações, mas não agrega achados de GuardDuty, Inspector e Macie."},{"texto":"AWS Security Hub","correta":true,"porque":"Agrega achados de vários serviços e contas e verifica padrões como CIS e AWS Foundational Security Best Practices."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra chamadas de API, não consolida achados de segurança."},{"texto":"AWS Systems Manager","correta":false,"porque":"Gerencia operações de instâncias e recursos, não postura de segurança."}],"explicacao":"Security Hub = painel central de postura de segurança e conformidade com padrões.","servicos":["Security Hub"],"dificuldade":1,"fonte":"usuario-B41"},{"id":"D2-a-040","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa quer governar centralmente várias contas AWS, automatizar a criação de contas, aplicar service control policies (SCPs) e consolidar o faturamento. Qual serviço atende a esses requisitos?","alternativas":[{"texto":"AWS Cost Explorer","correta":false,"porque":"Analisa custos, mas não cria contas nem aplica SCPs."},{"texto":"AWS Budgets","correta":false,"porque":"Define orçamentos e alertas de custo, não governança de contas."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Recomenda boas práticas, não gerencia contas."},{"texto":"AWS Organizations","correta":true,"porque":"Agrupa contas em OUs, aplica SCPs, cria contas via API e oferece consolidated billing."}],"explicacao":"Organizations é a base da governança multi-conta: OUs, SCPs e consolidated billing.","servicos":["Organizations"],"dificuldade":2,"fonte":"usuario-B47"},{"id":"D2-a-041","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Qual serviço da AWS ajuda a descobrir e proteger dados sensíveis, como PII, armazenados no Amazon S3?","alternativas":[{"texto":"Amazon Macie","correta":true,"porque":"Usa ML e correspondência de padrões para encontrar dados sensíveis e avaliar a segurança dos buckets."},{"texto":"Amazon GuardDuty","correta":false,"porque":"Detecta ameaças e atividade maliciosa, não classifica o conteúdo dos dados."},{"texto":"IAM Access Analyzer","correta":false,"porque":"Identifica recursos compartilhados externamente, sem inspecionar o conteúdo."},{"texto":"Amazon Detective","correta":false,"porque":"Investiga a causa raiz de achados, não descobre dados sensíveis."}],"explicacao":"Macie = descoberta e classificação de dados sensíveis (PII, dados financeiros, credenciais) no S3.","servicos":["Macie"],"dificuldade":1,"fonte":"usuario-B54"},{"id":"D2-a-042","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa precisa de um serviço automatizado de gerenciamento de vulnerabilidades que faça varreduras contínuas de software vulnerável e exposição de rede nas cargas de trabalho. Qual serviço deve usar?","alternativas":[{"texto":"Amazon GuardDuty","correta":false,"porque":"Detecta ameaças em logs, não varre vulnerabilidades de software."},{"texto":"AWS Security Hub","correta":false,"porque":"Agrega achados do Inspector, mas não faz as varreduras."},{"texto":"Amazon Inspector","correta":true,"porque":"Varre continuamente EC2, imagens no ECR e funções Lambda em busca de CVEs e exposição de rede."},{"texto":"AWS Shield","correta":false,"porque":"Protege contra DDoS."}],"explicacao":"Inspector = gerenciamento contínuo de vulnerabilidades (CVEs) em EC2, ECR e Lambda.","servicos":["Inspector"],"dificuldade":2,"fonte":"usuario-B76"},{"id":"D2-a-043","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa vai lançar um e-commerce que processa dados de cartão de crédito e precisa consultar os relatórios de conformidade da AWS e revisar e aceitar acordos com a AWS. Qual serviço oferece acesso sob demanda a esses itens?","alternativas":[{"texto":"AWS Certificate Manager","correta":false,"porque":"Gerencia certificados TLS, não relatórios nem acordos."},{"texto":"AWS Artifact","correta":true,"porque":"Artifact Reports traz relatórios como o PCI DSS AOC; Artifact Agreements permite aceitar acordos como o BAA."},{"texto":"AWS Config","correta":false,"porque":"Avalia a configuração dos recursos do cliente."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra chamadas de API."}],"explicacao":"O Artifact tem duas partes: Reports (relatórios de auditoria) e Agreements (acordos como BAA e NDA).","servicos":["Artifact"],"dificuldade":2,"fonte":"kananinirav-k22#4"},{"id":"D2-a-044","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Um auditor externo pediu a lista de todos os IAM users da conta com o status das senhas, das access keys e do MFA. Qual é a forma MAIS simples de fornecer essa informação?","alternativas":[{"texto":"Criar um IAM user para o auditor com permissões de administrador","correta":false,"porque":"Viola o menor privilégio e não gera o relatório pedido."},{"texto":"Tirar capturas de tela da página de cada usuário no console","correta":false,"porque":"É manual, trabalhoso e sujeito a erros."},{"texto":"Baixar o relatório do AWS Trusted Advisor","correta":false,"porque":"Traz verificações de boas práticas, não o status de credenciais de cada usuário."},{"texto":"Baixar o IAM credential report e entregá-lo ao auditor","correta":true,"porque":"O credential report lista todos os usuários e o status de senhas, access keys e MFA em CSV."}],"explicacao":"IAM credential report = relatório da conta com o status de todas as credenciais dos usuários IAM.","servicos":["IAM"],"dificuldade":2,"fonte":"kananinirav-k23#41"},{"id":"D2-a-045","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Para aplicar o menor privilégio, um administrador quer saber quais serviços um IAM role usou de fato e quando foi o último acesso, para remover permissões não utilizadas. Qual recurso fornece essa informação?","alternativas":[{"texto":"Informações de último acesso (Access Advisor) do IAM","correta":true,"porque":"Mostra os serviços permitidos e a data do último acesso de cada um."},{"texto":"IAM credential report","correta":false,"porque":"Mostra o status das credenciais dos usuários, não os serviços acessados por uma role."},{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade da AWS."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas e logs, não as permissões usadas."}],"explicacao":"O Access Advisor (último acesso) ajuda a refinar políticas removendo permissões que nunca são usadas.","servicos":["IAM"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-046","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma lei local exige que os dados de clientes de uma empresa fiquem armazenados dentro do país. Como a empresa atende a esse requisito na AWS?","alternativas":[{"texto":"Habilitando o AWS Shield Advanced na conta","correta":false,"porque":"Shield protege contra DDoS, não define onde os dados ficam."},{"texto":"Usando edge locations do Amazon CloudFront no país","correta":false,"porque":"Edge locations armazenam cópias em cache; a origem dos dados continua onde o cliente definiu."},{"texto":"Implantando os recursos em uma Região da AWS localizada no país","correta":true,"porque":"Os dados ficam na Região escolhida; a AWS não os move sem ação do cliente."},{"texto":"Pedindo ao AWS Support que mantenha os dados no país","correta":false,"porque":"O controle da localização é do cliente, pela escolha da Região."}],"explicacao":"O cliente controla em qual Região seus dados ficam, o que permite atender requisitos de soberania e residência de dados.","servicos":[],"dificuldade":1,"fonte":"autoral"},{"id":"D2-a-047","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma agência governamental dos EUA precisa executar cargas de trabalho sensíveis sujeitas a requisitos como FedRAMP High e ITAR, operadas apenas por pessoal dos EUA. Qual opção da AWS atende a esse requisito?","alternativas":[{"texto":"Uma Região comum dos EUA com Dedicated Instances","correta":false,"porque":"Dedicated Instances isolam hardware, mas não atendem a requisitos como ITAR."},{"texto":"AWS GovCloud (US)","correta":true,"porque":"São Regiões isoladas para cargas reguladas do governo dos EUA, operadas por cidadãos americanos."},{"texto":"AWS Outposts em um data center público","correta":false,"porque":"Outposts leva a AWS para o local do cliente, mas não é a oferta para conformidade governamental."},{"texto":"AWS Control Tower com guardrails obrigatórios","correta":false,"porque":"Ajuda na governança, mas não muda onde nem por quem a infraestrutura é operada."}],"explicacao":"GovCloud (US) atende requisitos regulatórios e de conformidade específicos do governo americano (FedRAMP High, ITAR, CJIS).","servicos":["GovCloud"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-048","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa quer proteger os dados trafegados entre os navegadores dos usuários e seu Application Load Balancer, usando certificados públicos renovados automaticamente sem custo adicional. Qual serviço deve usar?","alternativas":[{"texto":"AWS KMS","correta":false,"porque":"Gerencia chaves de criptografia em repouso e de aplicações, não certificados TLS públicos."},{"texto":"AWS CloudHSM","correta":false,"porque":"Fornece HSM dedicado; não emite certificados públicos para o ALB."},{"texto":"AWS Secrets Manager","correta":false,"porque":"Armazena e rotaciona segredos, não implanta certificados no ALB."},{"texto":"AWS Certificate Manager (ACM)","correta":true,"porque":"Emite e renova automaticamente certificados TLS públicos, gratuitos para uso com ALB e CloudFront."}],"explicacao":"Criptografia em trânsito usa TLS; o ACM provisiona e renova os certificados para serviços integrados.","servicos":["ACM","Elastic Load Balancing"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-049","dominio":2,"task":"2.2","tipo":"multipla","selecionar":2,"enunciado":"Quais opções protegem dados EM REPOUSO armazenados em um bucket do Amazon S3? (Selecione DUAS.)","alternativas":[{"texto":"Exigir HTTPS (TLS) em todas as requisições ao bucket","correta":false,"porque":"TLS protege os dados em trânsito, não em repouso."},{"texto":"Usar criptografia server-side com chaves do AWS KMS (SSE-KMS)","correta":true,"porque":"O S3 criptografa os objetos ao gravá-los com chaves gerenciadas no KMS."},{"texto":"Criptografar os dados no cliente antes do upload","correta":true,"porque":"Com client-side encryption os dados já chegam cifrados ao S3."},{"texto":"Habilitar o Amazon Macie no bucket","correta":false,"porque":"O Macie descobre dados sensíveis, mas não os criptografa."},{"texto":"Habilitar o S3 Transfer Acceleration","correta":false,"porque":"Acelera transferências pela rede de borda; não criptografa os dados armazenados."}],"explicacao":"Em repouso: SSE-S3, SSE-KMS ou client-side. Em trânsito: TLS/HTTPS.","servicos":["S3","KMS"],"dificuldade":2,"fonte":"kananinirav-k7#1 (reescrita)"},{"id":"D2-a-050","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa envia novos objetos para o Amazon S3 sem configurar nenhuma opção de criptografia. O que acontece com esses objetos em repouso?","alternativas":[{"texto":"São criptografados automaticamente com SSE-S3","correta":true,"porque":"O S3 usa criptografia server-side com chaves gerenciadas pelo S3 por padrão, sem custo."},{"texto":"Ficam sem criptografia até o cliente habilitar SSE-KMS","correta":false,"porque":"Desde 2023 o S3 aplica criptografia padrão a todos os novos objetos."},{"texto":"São criptografados com chaves do cliente armazenadas no CloudHSM","correta":false,"porque":"O CloudHSM só é usado se o cliente o configurar explicitamente."},{"texto":"São criptografados apenas se o bucket for público","correta":false,"porque":"A criptografia padrão vale para todos os buckets, independentemente do acesso."}],"explicacao":"O S3 criptografa todos os novos objetos com SSE-S3 por padrão; o cliente pode escolher SSE-KMS para ter controle e auditoria das chaves.","servicos":["S3"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-051","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa precisa atender requisitos contratuais e regulatórios que exigem chaves de criptografia em HSMs single-tenant dedicados, sob controle exclusivo do cliente. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Secrets Manager","correta":false,"porque":"Armazena segredos, não fornece HSM dedicado."},{"texto":"AWS KMS com chaves gerenciadas pela AWS","correta":false,"porque":"O KMS usa HSMs multi-tenant operados pela AWS, sem dedicação de hardware."},{"texto":"AWS CloudHSM","correta":true,"porque":"Fornece HSMs dedicados (validados FIPS 140) em que só o cliente gerencia as chaves."},{"texto":"AWS Directory Service","correta":false,"porque":"Fornece Active Directory gerenciado, não armazenamento de chaves."}],"explicacao":"CloudHSM = hardware dedicado e controle exclusivo das chaves; KMS = serviço gerenciado e integrado, multi-tenant.","servicos":["CloudHSM","KMS"],"dificuldade":3,"fonte":"kananinirav-k19#42"},{"id":"D2-a-052","dominio":2,"task":"2.2","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa precisa garantir a criptografia dos dados EM TRÂNSITO entre os usuários e sua aplicação e entre a aplicação e o banco de dados. Quais opções atendem a esse requisito? (Selecione DUAS.)","alternativas":[{"texto":"Habilitar a criptografia de volumes Amazon EBS","correta":false,"porque":"Protege dados em repouso nos volumes."},{"texto":"Configurar HTTPS no load balancer com um certificado do ACM","correta":true,"porque":"HTTPS (TLS) cifra o tráfego entre os usuários e a aplicação."},{"texto":"Habilitar a criptografia do Amazon RDS com AWS KMS","correta":false,"porque":"Cifra o armazenamento do banco, ou seja, dados em repouso."},{"texto":"Exigir conexões SSL/TLS ao banco de dados Amazon RDS","correta":true,"porque":"TLS na conexão com o banco protege os dados em trânsito."},{"texto":"Habilitar o versionamento do Amazon S3","correta":false,"porque":"Protege contra sobrescrita e exclusão, não é criptografia."}],"explicacao":"Em trânsito = TLS (HTTPS, conexões SSL ao banco, VPN). Em repouso = criptografia de armazenamento com KMS.","servicos":["ACM","RDS","KMS"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-053","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa criou uma trilha do AWS CloudTrail para guardar o histórico de chamadas de API por vários anos. Onde a trilha entrega os arquivos de log?","alternativas":[{"texto":"Em volumes Amazon EBS anexados a uma instância","correta":false,"porque":"O CloudTrail não grava logs em volumes EBS."},{"texto":"Em um bucket do Amazon S3","correta":true,"porque":"As trilhas entregam logs em um bucket S3 (opcionalmente também no CloudWatch Logs)."},{"texto":"No AWS Artifact","correta":false,"porque":"O Artifact guarda relatórios de conformidade da AWS, não logs do cliente."},{"texto":"No AWS Config","correta":false,"porque":"O Config registra configurações, não os arquivos de log do CloudTrail."}],"explicacao":"O histórico de eventos guarda 90 dias; para retenção longa, a trilha entrega logs no S3, onde podem ser criptografados com KMS e consultados com Athena.","servicos":["CloudTrail","S3"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-054","dominio":2,"task":"2.2","tipo":"multipla","selecionar":2,"enunciado":"Durante uma investigação de segurança, uma equipe precisa saber quais chamadas de API foram feitas na conta e quais conexões de rede chegaram às instâncias EC2. Quais fontes de log devem ser consultadas? (Selecione DUAS.)","alternativas":[{"texto":"AWS CloudTrail","correta":true,"porque":"Registra as chamadas de API (quem, o quê, quando e de onde) feitas na conta."},{"texto":"VPC Flow Logs","correta":true,"porque":"Registram metadados do tráfego IP aceito e rejeitado nas interfaces de rede da VPC."},{"texto":"AWS Artifact","correta":false,"porque":"Disponibiliza relatórios de conformidade da AWS, não logs da conta do cliente."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Dá recomendações de boas práticas, não registros de atividade ou de tráfego."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos; não tem relação com logs de segurança."}],"explicacao":"Para investigar: CloudTrail responde 'quem fez qual chamada de API'; VPC Flow Logs responde 'qual tráfego de rede ocorreu'.","servicos":["AWS CloudTrail","VPC"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-a-055","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa precisa de registros detalhados de cada requisição feita a um bucket do Amazon S3, incluindo o solicitante, o objeto e o código de resposta, para auditorias de acesso. Qual recurso fornece esses registros?","alternativas":[{"texto":"S3 server access logging","correta":true,"porque":"Grava em outro bucket um registro de cada requisição ao bucket de origem."},{"texto":"Amazon Macie","correta":false,"porque":"Identifica dados sensíveis no bucket, não registra cada requisição."},{"texto":"VPC Flow Logs","correta":false,"porque":"Registram tráfego IP da VPC, não requisições a objetos do S3."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Verifica permissões de buckets, mas não registra requisições."}],"explicacao":"Logs de acesso do S3 ficam em um bucket de destino; eventos de dados do CloudTrail são outra opção para auditar operações em objetos.","servicos":["S3"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-056","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa quer ser notificada quando a utilização de CPU de suas instâncias Amazon EC2 ficar acima de 80% por 10 minutos. Qual solução atende com o MENOR esforço?","alternativas":[{"texto":"Uma trilha do AWS CloudTrail com filtro por instância","correta":false,"porque":"O CloudTrail registra chamadas de API, não métricas de desempenho."},{"texto":"Uma regra do AWS Config para instâncias EC2","correta":false,"porque":"O Config avalia configurações, não utilização de CPU."},{"texto":"Um alarme do Amazon CloudWatch que publica em um tópico do Amazon SNS","correta":true,"porque":"O CloudWatch coleta a métrica CPUUtilization e o alarme dispara a notificação via SNS."},{"texto":"Uma verificação do AWS Trusted Advisor","correta":false,"porque":"O Trusted Advisor aponta instâncias subutilizadas, mas não alerta em tempo real sobre limites de CPU."}],"explicacao":"CloudWatch = monitoramento: métricas, logs, dashboards e alarmes que podem notificar via SNS ou acionar ações.","servicos":["CloudWatch","SNS"],"dificuldade":1,"fonte":"autoral"},{"id":"D2-a-057","dominio":2,"task":"2.2","tipo":"unica","enunciado":"O Amazon GuardDuty gerou um achado sobre o uso suspeito de credenciais. A equipe de segurança quer analisar e visualizar os dados relacionados para encontrar a causa raiz. Qual serviço deve usar?","alternativas":[{"texto":"Amazon Inspector","correta":false,"porque":"Varre vulnerabilidades de software; não investiga achados."},{"texto":"Amazon Detective","correta":true,"porque":"Organiza logs em gráficos de comportamento para investigar a causa raiz de achados de segurança."},{"texto":"Amazon Macie","correta":false,"porque":"Descobre dados sensíveis no S3."},{"texto":"AWS Security Hub","correta":false,"porque":"Agrega e prioriza achados, mas não faz a análise investigativa da causa raiz."}],"explicacao":"GuardDuty detecta, Security Hub agrega, Detective investiga, Inspector varre vulnerabilidades e Macie encontra dados sensíveis.","servicos":["Detective","GuardDuty"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-058","dominio":2,"task":"2.2","tipo":"unica","enunciado":"Uma empresa quer implantar de uma só vez, em várias contas, um conjunto de regras do AWS Config com ações de remediação, alinhado a um padrão como PCI DSS. Qual recurso deve usar?","alternativas":[{"texto":"AWS Artifact Agreements","correta":false,"porque":"Gerencia acordos com a AWS, não regras de configuração."},{"texto":"Trilhas organizacionais do AWS CloudTrail","correta":false,"porque":"Centralizam logs de API, mas não avaliam conformidade de configurações."},{"texto":"Insights do Amazon CloudWatch Logs","correta":false,"porque":"Consultam logs, não avaliam regras de configuração."},{"texto":"Conformance packs do AWS Config","correta":true,"porque":"Empacotam regras do Config e remediações para implantação em contas e Regiões."}],"explicacao":"Conformance packs = coleções de Config rules e remediações implantadas como uma unidade, inclusive em Organizations.","servicos":["Config"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-a-059","dominio":2,"task":"2.2","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços ajudam uma empresa a auditar e monitorar alterações nos recursos do seu ambiente AWS? (Selecione DUAS.)","alternativas":[{"texto":"AWS CloudTrail","correta":true,"porque":"Registra as chamadas de API que fizeram as alterações e quem as fez."},{"texto":"Amazon Comprehend","correta":false,"porque":"É um serviço de processamento de linguagem natural."},{"texto":"AWS X-Ray","correta":false,"porque":"Faz tracing de requisições em aplicações distribuídas."},{"texto":"AWS Config","correta":true,"porque":"Registra o histórico de configuração de cada recurso e avalia a conformidade."},{"texto":"AWS Transit Gateway","correta":false,"porque":"Conecta VPCs e redes on-premises."}],"explicacao":"CloudTrail mostra quem mudou o quê (API); Config mostra como estava e como ficou a configuração.","servicos":["CloudTrail","Config"],"dificuldade":2,"fonte":"kananinirav-k2#37"},{"id":"D2-a-060","dominio":2,"task":"2.2","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa de saúde dos EUA vai processar informações de saúde protegidas (PHI) na AWS e precisa cumprir a HIPAA. Quais ações são necessárias? (Selecione DUAS.)","alternativas":[{"texto":"Aceitar o Business Associate Addendum (BAA) no AWS Artifact","correta":true,"porque":"O BAA é exigido para processar PHI na AWS e é aceito em Artifact Agreements."},{"texto":"Solicitar à AWS a certificação HIPAA da aplicação","correta":false,"porque":"A AWS não certifica as aplicações dos clientes."},{"texto":"Implantar a carga obrigatoriamente na AWS GovCloud (US)","correta":false,"porque":"Não é obrigatório; várias Regiões comerciais oferecem serviços elegíveis para HIPAA."},{"texto":"Usar serviços elegíveis para HIPAA e configurá-los com os controles adequados","correta":true,"porque":"A AWS fornece serviços elegíveis; configurá-los corretamente é responsabilidade do cliente."},{"texto":"Contratar o AWS Shield Advanced","correta":false,"porque":"Proteção contra DDoS não é requisito da HIPAA."}],"explicacao":"Conformidade é compartilhada: a AWS fornece serviços elegíveis e acordos; o cliente aceita o BAA e configura sua carga de forma conforme.","servicos":["Artifact"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-001","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma rede de agências de viagem vai habilitar MFA para funcionários que vivem viajando e prefere uma opção que não exija hardware dedicado. Qual opção de MFA é a MAIS adequada?","alternativas":[{"texto":"Dispositivo MFA virtual (aplicativo autenticador no smartphone)","correta":true,"porque":"Roda em um app no celular que o funcionário já carrega, sem hardware extra, e é suportado pelo IAM."},{"texto":"Token TOTP de hardware","correta":false,"porque":"É suportado pelo IAM, mas exige um dispositivo físico dedicado, o que a empresa quer evitar."},{"texto":"Chave de segurança FIDO (U2F)","correta":false,"porque":"Também é um dispositivo físico que precisa ser carregado e pode ser perdido em viagem."},{"texto":"Senha de uso único enviada por e-mail corporativo","correta":false,"porque":"Não é um tipo de MFA suportado pelo IAM para login no console."}],"explicacao":"O IAM suporta MFA virtual (app autenticador), chaves de segurança FIDO e tokens TOTP de hardware; o MFA virtual é o único que dispensa hardware dedicado.","servicos":["IAM"],"dificuldade":1,"fonte":"usuario-A01"},{"id":"D2-b-002","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Qual recurso da AWS fornece credenciais temporárias da AWS tanto a usuários que fizeram login por redes sociais quanto a visitantes anônimos (não autenticados) de um aplicativo móvel?","alternativas":[{"texto":"Amazon Cognito user pool","correta":false,"porque":"É um diretório de usuários para cadastro e login; emite tokens da aplicação, não credenciais da AWS para convidados."},{"texto":"Amazon Cognito identity pool","correta":true,"porque":"Troca tokens de provedores de identidade por credenciais temporárias da AWS e também suporta identidades não autenticadas (convidados)."},{"texto":"AWS IAM Identity Center","correta":false,"porque":"Centraliza o acesso da força de trabalho a contas e aplicações, não de usuários finais anônimos de apps."},{"texto":"AWS AppSync","correta":false,"porque":"É um serviço de APIs GraphQL; não distribui credenciais temporárias da AWS."}],"explicacao":"No Cognito, o user pool autentica (diretório de usuários) e o identity pool autoriza, entregando credenciais temporárias da AWS, inclusive para convidados.","servicos":["Cognito"],"dificuldade":3,"fonte":"usuario-A17"},{"id":"D2-b-003","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma startup acabou de migrar para a AWS e precisa definir o que cada funcionário pode ou não fazer. Qual elemento do IAM expressa e impõe essas permissões?","alternativas":[{"texto":"IAM user","correta":false,"porque":"É uma identidade; sozinho não define permissões, que vêm das políticas anexadas."},{"texto":"IAM group","correta":false,"porque":"Agrupa usuários para facilitar a gestão, mas as permissões vêm das políticas anexadas ao grupo."},{"texto":"IAM policy","correta":true,"porque":"É o documento JSON que define quais ações são permitidas ou negadas em quais recursos."},{"texto":"IAM role","correta":false,"porque":"É uma identidade assumível com credenciais temporárias; suas permissões também vêm de políticas."}],"explicacao":"No IAM, identidades (users, groups, roles) recebem permissões por meio de políticas (policies), que são documentos JSON.","servicos":["IAM"],"dificuldade":1,"fonte":"usuario-A25"},{"id":"D2-b-004","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Um usuário do IAM recebe duas políticas: uma permite (Allow) excluir objetos de um bucket S3 e outra nega (Deny) explicitamente a mesma ação. O que acontece quando ele tenta excluir um objeto?","alternativas":[{"texto":"A exclusão é permitida, porque o Allow foi anexado primeiro","correta":false,"porque":"A ordem de anexação das políticas não influencia a avaliação."},{"texto":"A exclusão é negada, porque um Deny explícito sempre prevalece","correta":true,"porque":"Na avaliação do IAM, um Deny explícito sobrepõe qualquer Allow."},{"texto":"A exclusão é permitida, porque o Allow é mais específico","correta":false,"porque":"Especificidade não importa: o Deny explícito vence."},{"texto":"A AWS pede aprovação do root user para decidir","correta":false,"porque":"Não existe aprovação em tempo real pelo root; a avaliação de políticas é automática."}],"explicacao":"Por padrão tudo é negado (deny implícito); um Allow concede acesso; um Deny explícito sempre prevalece sobre qualquer Allow.","servicos":["IAM"],"dificuldade":2,"fonte":"usuario-A46 (reescrita)"},{"id":"D2-b-005","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Vários usuários do IAM precisam do mesmo conjunto de permissões. Qual abordagem permite manter essas permissões com o MENOR esforço?","alternativas":[{"texto":"Criar um IAM group, anexar as políticas a ele e adicionar os usuários ao grupo","correta":true,"porque":"Uma alteração na política do grupo vale para todos os membros de uma só vez."},{"texto":"Anexar a mesma política individualmente a cada usuário","correta":false,"porque":"Funciona, mas cada mudança precisa ser repetida usuário por usuário."},{"texto":"Anexar a política a uma IAM role e anexar a role a cada usuário","correta":false,"porque":"Roles não são anexadas a usuários; elas são assumidas temporariamente."},{"texto":"Usar uma role entre contas para conceder as permissões aos usuários","correta":false,"porque":"Roles entre contas servem para acesso a recursos de outra conta, não para agrupar permissões de usuários."}],"explicacao":"IAM groups simplificam a gestão: as permissões ficam no grupo e os usuários herdam ao entrar nele.","servicos":["IAM"],"dificuldade":1,"fonte":"usuario-A56"},{"id":"D2-b-006","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"Quais tipos de política podem conceder acesso a objetos de um bucket do Amazon S3? (Selecione DUAS.)","alternativas":[{"texto":"Políticas de roteamento do Amazon Route 53","correta":false,"porque":"Controlam respostas de DNS, não permissões de acesso a dados."},{"texto":"Regras de network ACL","correta":false,"porque":"Filtram tráfego de rede em sub-redes da VPC; não concedem permissões de API do S3."},{"texto":"Regras de Security Group","correta":false,"porque":"Controlam tráfego de rede de instâncias e não se aplicam a permissões de buckets."},{"texto":"Políticas baseadas em identidade anexadas a usuários do IAM","correta":true,"porque":"Podem permitir ações do S3, como s3:GetObject, para o usuário ao qual estão anexadas."},{"texto":"Bucket policies","correta":true,"porque":"São políticas baseadas em recurso anexadas ao bucket e definem quem pode acessá-lo."}],"explicacao":"O acesso ao S3 é concedido por políticas de identidade (users, groups, roles) e por políticas de recurso (bucket policies).","servicos":["IAM","S3"],"dificuldade":2,"fonte":"usuario-A60"},{"id":"D2-b-007","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa usa o Amazon CloudFront na frente de um bucket do Amazon S3 e quer que os objetos só possam ser obtidos pela distribuição, nunca diretamente pela URL do bucket. Qual recurso deve usar?","alternativas":[{"texto":"Server Name Indication (SNI)","correta":false,"porque":"Serve para apresentar o certificado TLS correto por nome de host, não para restringir acesso à origem."},{"texto":"Origin Access Control (OAC)","correta":true,"porque":"Permite que somente a distribuição do CloudFront leia o bucket, por meio de uma bucket policy restritiva."},{"texto":"Service control policies (SCPs)","correta":false,"porque":"Limitam as permissões máximas de contas no AWS Organizations, não quem acessa um bucket por uma distribuição."},{"texto":"Sticky sessions","correta":false,"porque":"É afinidade de sessão em load balancers, sem relação com o acesso ao S3."}],"explicacao":"Com Origin Access Control, o bucket aceita leituras apenas do CloudFront, bloqueando o acesso direto pela URL do S3.","servicos":["CloudFront","S3"],"dificuldade":2,"fonte":"usuario-B13"},{"id":"D2-b-008","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa de EdTech quer que os usuários finais de seus aplicativos web e mobile se autentiquem por um provedor de identidade externo antes de acessar as aplicações, sem construir a própria camada de autenticação. Qual serviço da AWS atende?","alternativas":[{"texto":"AWS IAM Identity Center","correta":false,"porque":"É voltado ao acesso da força de trabalho a contas AWS e aplicações corporativas, não a clientes de um app."},{"texto":"AWS IAM","correta":false,"porque":"Gerencia identidades que acessam recursos da AWS, não milhões de usuários finais de uma aplicação."},{"texto":"Amazon Cognito","correta":true,"porque":"Oferece autenticação e gestão de usuários finais para apps web e mobile, com federação a provedores externos."},{"texto":"AWS Directory Service","correta":false,"porque":"Fornece Microsoft Active Directory gerenciado, não um serviço de login para usuários de apps."}],"explicacao":"Amazon Cognito é o serviço de identidade para usuários finais de aplicações web e mobile, inclusive com login federado (Google, Apple, SAML).","servicos":["Cognito"],"dificuldade":1,"fonte":"usuario-B18"},{"id":"D2-b-009","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Usar o IAM para conceder acesso apenas aos recursos necessários para executar uma tarefa específica é um conceito conhecido como:","alternativas":[{"texto":"Acesso sob demanda","correta":false,"porque":"Não é o nome do princípio de segurança recomendado pela AWS."},{"texto":"Acesso por token","correta":false,"porque":"Descreve um mecanismo de autenticação, não um princípio de concessão de permissões."},{"texto":"Acesso restrito","correta":false,"porque":"É um termo genérico, não o princípio formal usado pela AWS."},{"texto":"Princípio do menor privilégio","correta":true,"porque":"É exatamente conceder só as permissões necessárias para a tarefa, e nada além."}],"explicacao":"Menor privilégio (least privilege): conceder apenas as permissões necessárias para a tarefa, reduzindo o impacto de erros e credenciais comprometidas.","servicos":["IAM"],"dificuldade":1,"fonte":"usuario-B52"},{"id":"D2-b-010","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Qual serviço ou recurso da AWS identifica se um bucket do Amazon S3 ou uma IAM role foi compartilhado com uma entidade externa à conta?","alternativas":[{"texto":"AWS IAM Access Analyzer","correta":true,"porque":"Analisa políticas de recursos e aponta acessos concedidos a entidades fora da conta ou da organização."},{"texto":"AWS Service Catalog","correta":false,"porque":"Gerencia catálogos de produtos aprovados para implantação, não analisa compartilhamento externo."},{"texto":"AWS Systems Manager","correta":false,"porque":"Gerencia e opera recursos como instâncias, não avalia políticas de acesso externo."},{"texto":"AWS Organizations","correta":false,"porque":"Agrupa e governa contas, mas não identifica recursos compartilhados externamente."}],"explicacao":"O IAM Access Analyzer encontra recursos (buckets, roles, chaves KMS etc.) acessíveis por entidades externas e ajuda a validar o menor privilégio.","servicos":["IAM Access Analyzer"],"dificuldade":2,"fonte":"usuario-B65"},{"id":"D2-b-011","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"Em quais situações uma empresa deve criar um IAM user em vez de uma IAM role? (Selecione DUAS.)","alternativas":[{"texto":"Quando precisa adicionar administradores a um IAM group","correta":true,"porque":"IAM groups contêm apenas IAM users; roles não podem ser membros de grupos."},{"texto":"Quando os funcionários já se autenticam no Active Directory corporativo e querem SSO na AWS","correta":false,"porque":"Usa-se federação ou IAM Identity Center, que funcionam com roles e credenciais temporárias."},{"texto":"Quando precisa de credenciais de longo prazo para um desenvolvedor específico","correta":true,"porque":"IAM users têm credenciais permanentes (senha e access keys) associadas a uma pessoa."},{"texto":"Quando um aplicativo móvel precisa de permissões temporárias para enviar fotos ao Amazon S3","correta":false,"porque":"Usa-se Cognito com roles, que fornecem credenciais temporárias."},{"texto":"Quando uma aplicação em uma instância Amazon EC2 precisa acessar outros serviços da AWS","correta":false,"porque":"O recomendado é uma role anexada à instância, com credenciais temporárias."}],"explicacao":"IAM users representam pessoas ou sistemas com credenciais de longo prazo; roles fornecem credenciais temporárias para serviços, apps e identidades federadas.","servicos":["IAM"],"dificuldade":2,"fonte":"usuario-B75"},{"id":"D2-b-012","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"Quais ações são práticas recomendadas de segurança no uso do AWS IAM? (Selecione DUAS.)","alternativas":[{"texto":"Usar access keys para entrar no AWS Management Console","correta":false,"porque":"O console usa nome de usuário e senha; access keys são para acesso programático."},{"texto":"Configurar uma política de senha forte","correta":true,"porque":"Exige complexidade e expiração, dificultando senhas fracas."},{"texto":"Usar IAM users permanentes em vez de roles para acesso entre contas","correta":false,"porque":"Roles com credenciais temporárias são a prática recomendada entre contas."},{"texto":"Compartilhar credenciais entre usuários da mesma Região","correta":false,"porque":"Credenciais nunca devem ser compartilhadas; cada pessoa deve ter a sua identidade."},{"texto":"Rotacionar access keys regularmente","correta":true,"porque":"Reduz a janela de uso de uma chave vazada."}],"explicacao":"Boas práticas do IAM incluem política de senha forte, MFA, rotação de access keys, roles para acesso temporário e menor privilégio.","servicos":["IAM"],"dificuldade":1,"fonte":"usuario-B87"},{"id":"D2-b-013","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"Quais tarefas só podem ser realizadas com as credenciais do root user da conta AWS? (Selecione DUAS.)","alternativas":[{"texto":"Criar uma nova política do IAM","correta":false,"porque":"Qualquer identidade com as permissões do IAM adequadas pode criar políticas."},{"texto":"Fechar a conta AWS","correta":true,"porque":"Encerrar a conta é uma tarefa reservada ao root user."},{"texto":"Gerar access keys para IAM users","correta":false,"porque":"Administradores do IAM podem gerar access keys para outros usuários."},{"texto":"Anexar uma role a uma instância Amazon EC2","correta":false,"porque":"É uma operação comum feita por IAM users ou roles com permissão."},{"texto":"Alterar o plano de AWS Support","correta":true,"porque":"Mudar ou cancelar o plano de suporte exige o root user."}],"explicacao":"Tarefas exclusivas do root incluem fechar a conta, alterar o plano de suporte e alterar configurações da conta, como e-mail e senha do root.","servicos":["IAM"],"dificuldade":2,"fonte":"kananinirav-k21#49"},{"id":"D2-b-014","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Qual destas tarefas exige que o administrador entre com o root user da conta AWS?","alternativas":[{"texto":"Visualizar as faturas no console de Billing","correta":false,"porque":"IAM users podem ver faturas quando o acesso do IAM ao Billing está ativado e há permissão."},{"texto":"Alterar o e-mail de login e a senha do root user","correta":true,"porque":"Mudar as configurações da conta ligadas ao root, como e-mail e senha, é tarefa exclusiva do root."},{"texto":"Criar um IAM user com permissões administrativas","correta":false,"porque":"Qualquer identidade com permissão no IAM pode criar usuários administrativos."},{"texto":"Ativar uma trilha do AWS CloudTrail em todas as Regiões","correta":false,"porque":"Administradores do IAM com as permissões certas podem criar trilhas."}],"explicacao":"Use o root apenas para o que só ele pode fazer, como alterar configurações da conta (e-mail, senha do root) e fechar a conta.","servicos":["IAM"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-015","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Um administrador aplicou por engano uma bucket policy que nega todas as ações a todos os principals, inclusive aos administradores do IAM. Quem pode corrigir a situação removendo essa política?","alternativas":[{"texto":"Um IAM user com a política AdministratorAccess","correta":false,"porque":"Uma negação explícita prevalece sobre qualquer permissão concedida, inclusive de administrador."},{"texto":"A equipe do AWS Support, editando a política","correta":false,"porque":"A AWS não altera políticas de recursos do cliente; isso é responsabilidade do cliente."},{"texto":"O root user da conta dona do bucket","correta":true,"porque":"O root pode excluir uma bucket policy que bloqueou todos os principals; é uma das tarefas exclusivas do root."},{"texto":"A management account, por meio de uma SCP","correta":false,"porque":"SCPs apenas limitam permissões; não concedem acesso nem removem bucket policies."}],"explicacao":"Se uma bucket policy negar acesso a todos, só o root user da conta pode removê-la; negação explícita vence qualquer Allow no IAM.","servicos":["IAM","S3"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-016","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa quer vender no Reserved Instance Marketplace as Reserved Instances que não usa mais. Qual identidade precisa fazer o registro como vendedor?","alternativas":[{"texto":"Um IAM user com a política AdministratorAccess","correta":false,"porque":"Mesmo com acesso administrativo, um IAM user não pode fazer esse registro."},{"texto":"Uma IAM role com permissões de Billing","correta":false,"porque":"Permissões de faturamento não habilitam o registro como vendedor."},{"texto":"Um usuário do IAM Identity Center com permission set de administrador","correta":false,"porque":"O usuário acessa a conta assumindo uma IAM role gerada pelo permission set, que não pode executar tarefas exclusivas do root."},{"texto":"O root user da conta AWS","correta":true,"porque":"O registro como vendedor no Reserved Instance Marketplace é uma tarefa exclusiva do root."}],"explicacao":"Registrar-se como vendedor de Reserved Instances no Marketplace está na lista de tarefas que exigem o root user.","servicos":["IAM"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-017","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Qual prática ajuda a proteger o root user de uma conta AWS?","alternativas":[{"texto":"Excluir as access keys do root user e não criar novas","correta":true,"porque":"Sem access keys, o root não pode ser usado programaticamente se a chave vazar."},{"texto":"Ativar MFA no root e usá-lo para todo o trabalho diário","correta":false,"porque":"MFA é recomendado, mas o root não deve ser usado no dia a dia."},{"texto":"Acessar o root somente pelo celular pessoal do administrador","correta":false,"porque":"O dispositivo usado não protege a credencial nem reduz o uso indevido."},{"texto":"Compartilhar a senha do root apenas com pessoas de confiança","correta":false,"porque":"As credenciais do root nunca devem ser compartilhadas."}],"explicacao":"Proteja o root: ative MFA, não crie (ou exclua) access keys do root e use-o apenas nas tarefas que exigem o root.","servicos":["IAM"],"dificuldade":1,"fonte":"kananinirav-k6#22"},{"id":"D2-b-018","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Um administrador criou uma conta AWS e usa o root user no dia a dia para criar instâncias e configurar serviços. Qual é a recomendação da AWS?","alternativas":[{"texto":"Continuar usando o root, já que ele tem MFA ativado","correta":false,"porque":"MFA reduz o risco de login indevido, mas não justifica usar credenciais irrestritas no dia a dia."},{"texto":"Criar identidades administrativas no IAM Identity Center ou no IAM e reservar o root para tarefas que o exigem","correta":true,"porque":"Separa o uso cotidiano das credenciais mais poderosas da conta."},{"texto":"Criar access keys do root para automatizar as tarefas","correta":false,"porque":"Access keys do root são desaconselhadas: dão acesso irrestrito se vazarem."},{"texto":"Compartilhar o root com a equipe de operações, protegido por senha forte","correta":false,"porque":"Credenciais do root não devem ser compartilhadas, independentemente da senha."}],"explicacao":"O root user tem acesso irrestrito; use identidades com menor privilégio no dia a dia e o root só nas tarefas exclusivas dele.","servicos":["IAM","IAM Identity Center"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-019","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"O administrador da conta AWS de uma empresa foi desligado. Ele criou vários IAM users e access keys e talvez conheça as credenciais do root user. O que a empresa deve fazer de imediato? (Selecione DUAS.)","alternativas":[{"texto":"Alterar a senha e o e-mail do root user e ativar MFA","correta":true,"porque":"Bloqueia o acesso ao root caso ele conheça as credenciais."},{"texto":"Mover os recursos para outra Região da AWS","correta":false,"porque":"Credenciais do IAM valem em todas as Regiões; mudar de Região não protege nada."},{"texto":"Desativar e rotacionar todas as access keys que ele possa ter usado","correta":true,"porque":"Impede o uso de chaves que ele conhecia ou criou."},{"texto":"Baixar todas as políticas anexadas para um local seguro","correta":false,"porque":"Não impede nenhum acesso indevido."},{"texto":"Fechar a conta AWS e criar uma nova","correta":false,"porque":"É desproporcional e interromperia as cargas de trabalho."}],"explicacao":"Com suspeita de credenciais comprometidas, rotacione access keys e senhas, proteja o root (senha, e-mail, MFA) e revise as identidades criadas.","servicos":["IAM"],"dificuldade":2,"fonte":"kananinirav-k8#33 (reescrita)"},{"id":"D2-b-020","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma aplicação em uma instância Amazon EC2 precisa gravar dados em um bucket do Amazon S3 sem usar credenciais de longo prazo. Qual é a MELHOR opção?","alternativas":[{"texto":"Gravar access keys de um IAM user no código da aplicação","correta":false,"porque":"São credenciais de longo prazo e podem vazar pelo código."},{"texto":"Usar um Amazon Cognito user pool","correta":false,"porque":"Serve para autenticar usuários finais de aplicações, não para dar permissão a uma instância."},{"texto":"Anexar uma IAM role à instância","correta":true,"porque":"A role entrega credenciais temporárias, rotacionadas automaticamente, à aplicação."},{"texto":"Tornar o bucket público para escrita","correta":false,"porque":"Exporia o bucket a qualquer pessoa na internet."}],"explicacao":"Para serviços da AWS (como EC2) acessarem outros serviços, use IAM roles: credenciais temporárias, sem chaves no código.","servicos":["IAM","EC2","S3"],"dificuldade":1,"fonte":"kananinirav-k21#43"},{"id":"D2-b-021","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa quer conceder rapidamente acesso somente leitura ao Amazon S3, usando uma política pronta que a AWS cria e mantém atualizada. Qual tipo de política deve usar?","alternativas":[{"texto":"Política gerenciada pelo cliente (customer managed policy)","correta":false,"porque":"É criada e mantida pela própria empresa, não pela AWS."},{"texto":"Política em linha (inline policy)","correta":false,"porque":"É escrita pela empresa e embutida em uma única identidade."},{"texto":"Service control policy (SCP)","correta":false,"porque":"Limita permissões máximas de contas no Organizations e não concede acesso."},{"texto":"Política gerenciada pela AWS (AWS managed policy)","correta":true,"porque":"É criada e atualizada pela AWS para casos de uso comuns, como AmazonS3ReadOnlyAccess."}],"explicacao":"Políticas gerenciadas pela AWS são prontas e mantidas pela AWS; as gerenciadas pelo cliente são criadas pela empresa e podem ser reutilizadas.","servicos":["IAM"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-022","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma política precisa ficar estritamente vinculada a um único IAM user, sem poder ser anexada a outras identidades, e deve ser excluída junto com ele. Qual tipo de política atende?","alternativas":[{"texto":"Inline policy","correta":true,"porque":"Fica embutida em uma única identidade, numa relação 1:1, e é excluída junto com ela."},{"texto":"AWS managed policy","correta":false,"porque":"É uma política independente, mantida pela AWS e anexável a muitas identidades."},{"texto":"Customer managed policy","correta":false,"porque":"É independente e reutilizável; continua existindo se o usuário for excluído."},{"texto":"Service control policy (SCP)","correta":false,"porque":"Aplica-se a contas e OUs do Organizations, não a um usuário específico."}],"explicacao":"Inline policies têm relação estrita 1:1 com a identidade; políticas gerenciadas (AWS ou cliente) são objetos independentes e reutilizáveis.","servicos":["IAM"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-023","dominio":2,"task":"2.3","tipo":"unica","enunciado":"A equipe de segurança quer escrever suas próprias permissões em uma política reutilizável por vários users, groups e roles, com controle de versões e alteração centralizada. Qual tipo de política deve criar?","alternativas":[{"texto":"AWS managed policy","correta":false,"porque":"A empresa não pode editar seu conteúdo, pois ela é mantida pela AWS."},{"texto":"Customer managed policy","correta":true,"porque":"É criada e mantida pela empresa, pode ser anexada a várias identidades e guarda versões."},{"texto":"Inline policy","correta":false,"porque":"Fica embutida em uma única identidade e não pode ser reutilizada."},{"texto":"Access control list (ACL) do Amazon S3","correta":false,"porque":"Controla acesso a buckets e objetos, não permissões gerais de identidades do IAM."}],"explicacao":"Customer managed policies oferecem controle total e reutilização; são a escolha quando as políticas da AWS são amplas demais para o menor privilégio.","servicos":["IAM"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-024","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa com várias contas no AWS Organizations quer que os funcionários façam login uma única vez e acessem as contas e as aplicações de negócio atribuídas a eles, com gestão centralizada. Qual serviço atende com o MENOR esforço operacional?","alternativas":[{"texto":"Amazon Cognito","correta":false,"porque":"É voltado a usuários finais de aplicações web e mobile, não à força de trabalho em várias contas."},{"texto":"IAM users criados em cada conta","correta":false,"porque":"Duplica credenciais de longo prazo em cada conta, com mais esforço e menos segurança."},{"texto":"AWS IAM Identity Center","correta":true,"porque":"Oferece SSO da força de trabalho para várias contas e aplicações, com gestão central de acesso."},{"texto":"AWS Directory Service","correta":false,"porque":"Fornece Active Directory gerenciado, mas sozinho não oferece SSO entre contas AWS."}],"explicacao":"IAM Identity Center (sucessor do AWS SSO) centraliza o acesso da força de trabalho a várias contas e aplicações.","servicos":["IAM Identity Center","Organizations"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-025","dominio":2,"task":"2.3","tipo":"unica","enunciado":"No AWS IAM Identity Center, qual recurso define o nível de acesso que um usuário ou grupo recebe em uma conta AWS atribuída?","alternativas":[{"texto":"Service control policy (SCP)","correta":false,"porque":"Limita as permissões máximas da conta, mas não concede acesso a usuários."},{"texto":"IAM group criado em cada conta","correta":false,"porque":"O Identity Center não depende de IAM groups locais em cada conta."},{"texto":"Amazon Cognito identity pool","correta":false,"porque":"Fornece credenciais a usuários de aplicativos, não à força de trabalho no Identity Center."},{"texto":"Permission set","correta":true,"porque":"É um modelo de permissões que o Identity Center provisiona como role em cada conta atribuída."}],"explicacao":"No IAM Identity Center, usuários e grupos são atribuídos a contas com permission sets, que viram roles nas contas de destino.","servicos":["IAM Identity Center"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-026","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Qual recurso permite que funcionários entrem nas contas AWS usando as credenciais corporativas que já possuem, sem criar IAM users para eles?","alternativas":[{"texto":"Federação de identidades (por exemplo, SAML 2.0)","correta":true,"porque":"Confia no provedor de identidade corporativo e concede acesso temporário por roles."},{"texto":"Access keys","correta":false,"porque":"São credenciais de longo prazo de IAM users para acesso programático."},{"texto":"Política de senha do IAM","correta":false,"porque":"Define regras de senha para IAM users; não reutiliza credenciais corporativas."},{"texto":"Autenticação multifator (MFA)","correta":false,"porque":"Adiciona um fator de autenticação, mas não permite usar as credenciais corporativas."}],"explicacao":"Federação permite usar um IdP externo (SAML 2.0, OIDC, Active Directory) para acessar a AWS com credenciais temporárias.","servicos":["IAM","IAM Identity Center"],"dificuldade":1,"fonte":"kananinirav-k7#45"},{"id":"D2-b-027","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa quer um Microsoft Active Directory gerenciado na AWS para aplicações compatíveis com AD, com possibilidade de integrá-lo ao AD local. Qual serviço deve usar?","alternativas":[{"texto":"Amazon Cognito","correta":false,"porque":"Gerencia usuários finais de aplicações web e mobile, não um Active Directory."},{"texto":"AWS Directory Service","correta":true,"porque":"Oferece AWS Managed Microsoft AD e AD Connector para integração com o AD local."},{"texto":"AWS IAM Identity Center","correta":false,"porque":"Pode usar o AD como fonte de identidades, mas não fornece um Active Directory gerenciado."},{"texto":"Amazon Cloud Directory","correta":false,"porque":"É um armazenamento de diretórios hierárquicos para aplicações, não um Active Directory."}],"explicacao":"AWS Directory Service fornece Active Directory gerenciado e conectores, base comum para federação com identidades corporativas.","servicos":["Directory Service"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-028","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Auditores que trabalham em uma conta AWS de auditoria precisam de acesso somente leitura a recursos de uma conta de produção, sem criar credenciais de longo prazo na produção. Qual é a MELHOR abordagem?","alternativas":[{"texto":"Criar IAM users compartilhados na conta de produção","correta":false,"porque":"Gera credenciais de longo prazo compartilhadas, contra as boas práticas."},{"texto":"Entregar aos auditores as access keys do root user da produção","correta":false,"porque":"Daria acesso irrestrito e viola as práticas de proteção do root."},{"texto":"Criar na conta de produção uma IAM role confiável pela conta de auditoria, que os auditores assumem","correta":true,"porque":"Roles entre contas entregam credenciais temporárias e permissões limitadas."},{"texto":"Aplicar uma SCP na conta de auditoria","correta":false,"porque":"SCPs apenas limitam permissões; não concedem acesso a outra conta."}],"explicacao":"Para acesso entre contas, use IAM roles com relação de confiança: credenciais temporárias e menor privilégio.","servicos":["IAM"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-029","dominio":2,"task":"2.3","tipo":"multipla","selecionar":2,"enunciado":"Quais componentes de credencial um IAM user precisa para acessar a AWS de forma programática, pela AWS CLI ou por um SDK? (Selecione DUAS.)","alternativas":[{"texto":"Nome de usuário e senha do console","correta":false,"porque":"São usados para entrar no AWS Management Console, não para chamadas de API."},{"texto":"Key pair do Amazon EC2","correta":false,"porque":"Serve para acesso SSH/RDP a instâncias, não para chamadas à API da AWS."},{"texto":"Access key ID","correta":true,"porque":"É a parte pública da access key, que identifica a credencial."},{"texto":"Chave do AWS KMS","correta":false,"porque":"É usada para criptografar dados, não para autenticar chamadas de API."},{"texto":"Secret access key","correta":true,"porque":"É a parte secreta da access key, usada para assinar as requisições."}],"explicacao":"Acesso programático usa access keys (access key ID + secret access key); o console usa nome de usuário, senha e, idealmente, MFA.","servicos":["IAM","CLI"],"dificuldade":1,"fonte":"kananinirav-k11#20"},{"id":"D2-b-030","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa quer garantir que os usuários do AWS Management Console cumpram requisitos de complexidade de senha. Como deve configurar isso?","alternativas":[{"texto":"Com uma política do IAM anexada aos usuários","correta":false,"porque":"Políticas do IAM definem permissões, não regras de complexidade de senha."},{"texto":"Com uma service control policy (SCP) do Organizations","correta":false,"porque":"SCPs limitam permissões máximas, não regras de senha."},{"texto":"Com um insight gerenciado do AWS Security Hub","correta":false,"porque":"Insights agrupam achados de segurança; não aplicam regras de senha."},{"texto":"Com a política de senha da conta (IAM account password policy)","correta":true,"porque":"Define tamanho mínimo, tipos de caracteres, expiração e reutilização para IAM users."}],"explicacao":"A password policy do IAM impõe regras de complexidade, expiração e não reutilização para senhas de IAM users.","servicos":["IAM"],"dificuldade":1,"fonte":"kananinirav-k23#8"},{"id":"D2-b-031","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma aplicação guarda a senha do banco Amazon RDS no próprio código. A equipe quer armazená-la com segurança e com rotação automática periódica. Qual serviço deve usar?","alternativas":[{"texto":"AWS Secrets Manager","correta":true,"porque":"Armazena segredos criptografados e os rotaciona automaticamente, com integração nativa ao RDS."},{"texto":"AWS Systems Manager Parameter Store","correta":false,"porque":"Armazena parâmetros e segredos simples, mas não tem rotação automática nativa."},{"texto":"AWS Key Management Service (AWS KMS)","correta":false,"porque":"Gerencia chaves de criptografia, não armazena nem rotaciona senhas de banco."},{"texto":"AWS IAM","correta":false,"porque":"Gerencia identidades e permissões, não segredos de aplicação."}],"explicacao":"Secrets Manager guarda e rotaciona segredos automaticamente; o Parameter Store guarda parâmetros e segredos simples, sem rotação nativa.","servicos":["Secrets Manager","RDS"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-032","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma equipe precisa guardar centralmente parâmetros de configuração, como URLs e nomes de ambiente, e alguns valores criptografados. Não há necessidade de rotação automática e o requisito é o MENOR custo. Qual opção atende?","alternativas":[{"texto":"AWS Secrets Manager","correta":false,"porque":"Atende tecnicamente, mas cobra por segredo armazenado; o diferencial dele é a rotação, que não é necessária."},{"texto":"AWS Systems Manager Parameter Store","correta":true,"porque":"Armazena parâmetros em texto ou criptografados com KMS; parâmetros padrão não têm custo adicional."},{"texto":"AWS Config","correta":false,"porque":"Registra a configuração de recursos da AWS para conformidade, não parâmetros de aplicação."},{"texto":"AWS Certificate Manager (ACM)","correta":false,"porque":"Gerencia certificados SSL/TLS, não parâmetros de configuração."}],"explicacao":"Parameter Store é a opção econômica para configurações e segredos simples; Secrets Manager se justifica quando há rotação automática.","servicos":["Systems Manager","Secrets Manager"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-033","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Um aplicativo móvel precisa de um diretório de usuários com cadastro, login, recuperação de senha e MFA para seus clientes. Qual componente atende?","alternativas":[{"texto":"Amazon Cognito identity pool","correta":false,"porque":"Entrega credenciais temporárias da AWS; não é um diretório de usuários."},{"texto":"AWS IAM Identity Center","correta":false,"porque":"Gerencia identidades da força de trabalho, não de clientes de um app."},{"texto":"Amazon Cognito user pool","correta":true,"porque":"É o diretório de usuários do Cognito, com sign-up, sign-in, recuperação de senha e MFA."},{"texto":"IAM group","correta":false,"porque":"Agrupa IAM users da conta, não usuários finais de aplicativos."}],"explicacao":"Cognito user pool = autenticação e diretório de usuários; identity pool = autorização com credenciais temporárias da AWS.","servicos":["Cognito"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-034","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Uma empresa usa o AWS Organizations e quer impedir que as contas de desenvolvimento usem determinados serviços, independentemente das permissões do IAM nessas contas. O que deve usar?","alternativas":[{"texto":"Políticas do IAM em cada conta","correta":false,"porque":"Podem ser alteradas pelos administradores das próprias contas."},{"texto":"Regras do AWS Config","correta":false,"porque":"Avaliam a conformidade das configurações, mas não impedem chamadas de API."},{"texto":"AWS IAM Access Analyzer","correta":false,"porque":"Identifica acessos externos e valida políticas, mas não bloqueia serviços."},{"texto":"Service control policies (SCPs)","correta":true,"porque":"Definem as permissões máximas das contas; nem os administradores locais conseguem ultrapassá-las."}],"explicacao":"SCPs são guardrails de permissões no Organizations: limitam o que contas e OUs podem fazer, mas não concedem permissões.","servicos":["Organizations","IAM"],"dificuldade":2,"fonte":"kananinirav-k3#33"},{"id":"D2-b-035","dominio":2,"task":"2.3","tipo":"unica","enunciado":"Um novo IAM user, sem nenhuma política anexada, tenta criar um bucket do Amazon S3 e recebe erro de acesso negado. Qual é a causa?","alternativas":[{"texto":"Por padrão, toda ação é negada implicitamente até que uma política a permita","correta":true,"porque":"No IAM, novas identidades começam sem permissões; o acesso precisa ser concedido explicitamente."},{"texto":"Somente o root user pode criar buckets do S3","correta":false,"porque":"Qualquer identidade com a permissão s3:CreateBucket pode criar buckets."},{"texto":"O usuário precisa ser ativado pelo AWS Support","correta":false,"porque":"IAM users ficam ativos assim que criados; o AWS Support não participa."},{"texto":"O Amazon S3 exige MFA para qualquer criação de bucket","correta":false,"porque":"O S3 não exige MFA por padrão para criar buckets."}],"explicacao":"Avaliação de políticas do IAM: negação implícita por padrão, um Allow concede o acesso e um Deny explícito sempre prevalece.","servicos":["IAM","S3"],"dificuldade":2,"fonte":"kananinirav-k5#25 (reescrita)"},{"id":"D2-b-036","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Qual serviço da AWS permite escrever regras que filtram requisições HTTP(S) por atributos como IP de origem, cabeçalhos ou padrões de caminho (path) da URL?","alternativas":[{"texto":"Security Groups","correta":false,"porque":"Filtram tráfego por protocolo, porta e IP no nível da instância, sem inspecionar cabeçalhos ou caminhos HTTP."},{"texto":"AWS WAF","correta":true,"porque":"É um firewall de aplicações web que inspeciona requisições HTTP(S) com regras sobre IP, cabeçalhos, URI, query strings e corpo."},{"texto":"Network ACLs","correta":false,"porque":"Filtram tráfego por IP, porta e protocolo na sub-rede, sem visibilidade da camada de aplicação."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz recomendações de boas práticas; não filtra tráfego."}],"explicacao":"AWS WAF atua na camada 7 (HTTP/HTTPS); Security Groups e NACLs atuam nas camadas 3/4 (IP, porta, protocolo).","servicos":["WAF"],"dificuldade":1,"fonte":"usuario-A19"},{"id":"D2-b-037","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Qual serviço da AWS protege aplicações web públicas contra explorações comuns, como SQL injection e cross-site scripting (XSS)?","alternativas":[{"texto":"AWS Shield Standard","correta":false,"porque":"Protege contra DDoS nas camadas de rede e transporte, não contra injeção de código na aplicação."},{"texto":"Security Groups","correta":false,"porque":"Permitem ou bloqueiam portas e IPs, sem inspecionar o conteúdo das requisições."},{"texto":"AWS WAF","correta":true,"porque":"Oferece regras, inclusive gerenciadas, que bloqueiam padrões de SQL injection e XSS nas requisições."},{"texto":"Amazon Inspector","correta":false,"porque":"Varre vulnerabilidades de software (CVEs) e exposição de rede, mas não bloqueia requisições maliciosas."}],"explicacao":"Ataques na camada de aplicação, como SQL injection e XSS, são bloqueados pelo AWS WAF.","servicos":["WAF"],"dificuldade":1,"fonte":"usuario-B55 (reescrita)"},{"id":"D2-b-038","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Qual serviço da AWS protege recursos contra ataques DDoS comuns de forma proativa e sempre ativa?","alternativas":[{"texto":"AWS WAF","correta":false,"porque":"Filtra requisições na camada de aplicação; ajuda contra floods HTTP, mas não é o serviço dedicado a DDoS."},{"texto":"Amazon Inspector","correta":false,"porque":"Varre vulnerabilidades em cargas de trabalho, não mitiga tráfego de ataque."},{"texto":"Security Groups da VPC","correta":false,"porque":"Controlam portas e IPs permitidos, mas não mitigam ataques volumétricos."},{"texto":"AWS Shield","correta":true,"porque":"Faz detecção sempre ativa e mitigação automática inline de ataques DDoS."}],"explicacao":"AWS Shield é o serviço gerenciado de proteção contra DDoS; o Shield Standard já protege todos os clientes sem custo adicional.","servicos":["Shield"],"dificuldade":1,"fonte":"usuario-B11"},{"id":"D2-b-039","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa precisa de proteção contra ataques DDoS de grande escala no seu site e exige suporte 24/7 de especialistas da AWS durante um ataque. Qual serviço atende a esses requisitos?","alternativas":[{"texto":"AWS Shield Advanced","correta":true,"porque":"Proteção avançada contra DDoS com acesso 24/7 à Shield Response Team (SRT)."},{"texto":"AWS Shield Standard","correta":false,"porque":"É gratuito e automático, mas não inclui acesso à equipe de resposta da AWS."},{"texto":"AWS Firewall Manager","correta":false,"porque":"Gerencia centralmente regras de segurança, mas não oferece uma equipe de resposta a ataques."},{"texto":"AWS WAF","correta":false,"porque":"Filtra requisições web, mas sozinho não inclui suporte especializado durante ataques DDoS."}],"explicacao":"Shield Advanced é pago e acrescenta detecção avançada, Shield Response Team 24/7 e proteção de custos ao Shield Standard.","servicos":["Shield"],"dificuldade":2,"fonte":"usuario-B57"},{"id":"D2-b-040","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Um cliente quer fazer testes de intrusão (penetration testing) em suas próprias instâncias Amazon EC2 e Elastic Load Balancers. O que a política da AWS exige?","alternativas":[{"texto":"Abrir um caso no AWS Support e aguardar aprovação","correta":false,"porque":"A exigência de aprovação prévia deixou de existir para os serviços listados."},{"texto":"Realizar os testes sem aprovação prévia da AWS, seguindo a política","correta":true,"porque":"A AWS permite pentest sem aprovação prévia em serviços listados, como EC2, ELB, RDS e Lambda."},{"texto":"Contratar a AWS para executar os testes","correta":false,"porque":"A AWS não executa pentest nas cargas de trabalho dos clientes."},{"texto":"Usar somente o Amazon Inspector, pois pentest manual é proibido","correta":false,"porque":"O Inspector faz varredura de vulnerabilidades, mas pentest manual também é permitido."}],"explicacao":"Clientes podem fazer pentest sem aprovação prévia nos serviços da lista permitida, desde que sigam a política de testes da AWS.","servicos":["EC2"],"dificuldade":2,"fonte":"usuario-B53 (reescrita)"},{"id":"D2-b-041","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa quer monitorar Security Groups mal configurados que permitem acesso irrestrito (0.0.0.0/0) a portas específicas. Qual serviço da AWS ajuda de forma MAIS simples?","alternativas":[{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas e logs, mas não avalia regras de Security Groups contra boas práticas."},{"texto":"Amazon GuardDuty","correta":false,"porque":"Detecta ameaças em logs, mas não revisa regras de Security Groups."},{"texto":"AWS Trusted Advisor","correta":true,"porque":"Tem verificação de segurança que aponta Security Groups com portas abertas sem restrição."},{"texto":"AWS Health Dashboard","correta":false,"porque":"Informa eventos e saúde dos serviços da AWS, não configurações do cliente."}],"explicacao":"As verificações de segurança do Trusted Advisor identificam portas irrestritas em Security Groups, entre outros problemas.","servicos":["Trusted Advisor"],"dificuldade":1,"fonte":"usuario-B70"},{"id":"D2-b-042","dominio":2,"task":"2.4","tipo":"multipla","selecionar":3,"enunciado":"Um usuário quer um único relatório que mostre a situação de várias verificações de segurança da conta. Quais itens o AWS Trusted Advisor verifica? (Selecione TRÊS.)","alternativas":[{"texto":"Security Groups com acesso irrestrito a portas","correta":true,"porque":"É uma das verificações de segurança clássicas do Trusted Advisor."},{"texto":"Chamadas de API feitas a partir de IPs maliciosos conhecidos","correta":false,"porque":"Detecção de ameaças em logs é função do Amazon GuardDuty."},{"texto":"Buckets do Amazon S3 com permissões de acesso abertas","correta":true,"porque":"O Trusted Advisor alerta sobre buckets com permissão de listagem ou escrita aberta."},{"texto":"Vulnerabilidades de software (CVEs) em imagens de contêiner","correta":false,"porque":"Varredura de CVEs é função do Amazon Inspector."},{"texto":"Se o MFA está ativado no root user","correta":true,"porque":"É uma verificação de segurança do Trusted Advisor."},{"texto":"Dados pessoais (PII) armazenados em buckets do S3","correta":false,"porque":"Identificar dados sensíveis é função do Amazon Macie."}],"explicacao":"O Trusted Advisor compara a configuração da conta com boas práticas: MFA no root, buckets abertos, Security Groups irrestritos, entre outras.","servicos":["Trusted Advisor"],"dificuldade":2,"fonte":"kananinirav-k20#47 (reescrita)"},{"id":"D2-b-043","dominio":2,"task":"2.4","tipo":"unica","enunciado":"O que o AWS Trusted Advisor faz ao detectar que access keys da conta foram publicadas em repositórios de código públicos?","alternativas":[{"texto":"Gera um relatório de conformidade no AWS Artifact","correta":false,"porque":"O Artifact disponibiliza relatórios de auditoria da AWS, não alertas da conta do cliente."},{"texto":"Cria uma regra no AWS WAF para bloquear quem usar a chave","correta":false,"porque":"O Trusted Advisor não cria regras de WAF; e access keys não passam pelo WAF."},{"texto":"Abre uma investigação no Amazon Detective","correta":false,"porque":"O Trusted Advisor não aciona o Detective; ele apenas aponta o problema."},{"texto":"Sinaliza as chaves expostas para o cliente rotacioná-las","correta":true,"porque":"A verificação de access keys expostas aponta chaves encontradas em repositórios públicos."}],"explicacao":"Entre as verificações de segurança do Trusted Advisor está a de access keys expostas publicamente.","servicos":["Trusted Advisor","IAM"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-044","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Qual afirmação descreve o AWS Shield Standard?","alternativas":[{"texto":"É automático e sem custo adicional contra DDoS comuns","correta":true,"porque":"É a proteção básica de DDoS incluída para todos os clientes."},{"texto":"Precisa ser assinado e cobra uma taxa mensal por organização","correta":false,"porque":"Essa é uma característica do Shield Advanced."},{"texto":"Inclui acesso 24/7 à Shield Response Team","correta":false,"porque":"A SRT faz parte apenas do Shield Advanced."},{"texto":"Reembolsa custos de escalabilidade causados por ataques","correta":false,"porque":"A proteção de custos é exclusiva do Shield Advanced."}],"explicacao":"Shield Standard: gratuito, automático, contra ataques comuns de camada 3/4. Shield Advanced: pago, com SRT, proteção de custos e visibilidade avançada.","servicos":["Shield"],"dificuldade":2,"fonte":"kananinirav-k18#31 (reescrita)"},{"id":"D2-b-045","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa teme que um ataque DDoS faça seu Auto Scaling e o Amazon CloudFront escalarem e gerem uma fatura muito alta. Qual recurso oferece proteção de custos contra esse cenário?","alternativas":[{"texto":"AWS Shield Standard","correta":false,"porque":"Mitiga ataques comuns, mas não oferece proteção de custos."},{"texto":"AWS Shield Advanced","correta":true,"porque":"Inclui proteção de custos: créditos para picos de uso causados por ataques DDoS em recursos protegidos."},{"texto":"AWS Budgets","correta":false,"porque":"Avisa quando os gastos passam de um limite, mas não compensa custos causados por ataques."},{"texto":"AWS WAF","correta":false,"porque":"Bloqueia requisições maliciosas, mas não oferece créditos por custos de ataques."}],"explicacao":"A proteção de custos (DDoS cost protection) é um benefício exclusivo do Shield Advanced.","servicos":["Shield"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-046","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa com dezenas de contas no AWS Organizations quer configurar e gerenciar centralmente as regras do AWS WAF em todas as contas e aplicações. Qual serviço deve usar?","alternativas":[{"texto":"AWS Shield Advanced","correta":false,"porque":"Protege contra DDoS, mas não é a ferramenta de gestão central de regras de WAF."},{"texto":"AWS Config","correta":false,"porque":"Avalia a conformidade das configurações, mas não implanta regras de WAF."},{"texto":"AWS Firewall Manager","correta":true,"porque":"Administra centralmente regras de WAF, proteções do Shield Advanced e Security Groups em várias contas."},{"texto":"Amazon GuardDuty","correta":false,"porque":"Detecta ameaças a partir de logs, mas não gerencia regras de firewall."}],"explicacao":"Firewall Manager é a gestão central de segurança de rede (WAF, Shield Advanced, Security Groups) em toda a organização.","servicos":["Firewall Manager","WAF","Organizations"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-047","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa padronizou um firewall de próxima geração de um fornecedor específico e quer usar o mesmo produto na AWS, com cobrança integrada à fatura da AWS. Onde ela deve obtê-lo?","alternativas":[{"texto":"AWS Artifact","correta":false,"porque":"Disponibiliza relatórios de conformidade da AWS, não produtos de terceiros."},{"texto":"AWS Marketplace","correta":true,"porque":"Catálogo de software de terceiros (inclusive segurança) pronto para rodar na AWS, com cobrança na fatura da AWS."},{"texto":"AWS Service Catalog","correta":false,"porque":"Publica produtos aprovados internamente pela própria organização; não é a loja de fornecedores."},{"texto":"AWS Firewall Manager","correta":false,"porque":"Gerencia centralmente WAF, Shield Advanced e Security Groups; não vende produtos de terceiros."}],"explicacao":"Produtos de segurança de terceiros (firewalls, antivírus, SIEM) estão disponíveis no AWS Marketplace, com faturamento consolidado na conta AWS.","servicos":["AWS Marketplace"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-048","dominio":2,"task":"2.4","tipo":"unica","enunciado":"O Amazon GuardDuty gerou um achado de possível credencial comprometida. A equipe agora precisa analisar a causa raiz e visualizar as entidades e atividades relacionadas ao longo do tempo. Qual serviço deve usar?","alternativas":[{"texto":"Amazon Inspector","correta":false,"porque":"Varre vulnerabilidades de software e exposição de rede; não investiga incidentes."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Verifica boas práticas de configuração; não analisa causa raiz de achados."},{"texto":"Amazon Detective","correta":true,"porque":"Correlaciona logs e cria gráficos de comportamento para investigar a causa raiz de achados de segurança."},{"texto":"Amazon Macie","correta":false,"porque":"Descobre dados sensíveis no Amazon S3; não investiga credenciais comprometidas."}],"explicacao":"GuardDuty detecta a ameaça; Detective investiga a causa raiz; Security Hub agrega os achados.","servicos":["Amazon Detective","Amazon GuardDuty"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-049","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Onde os clientes encontram um catálogo de soluções de segurança de fornecedores terceiros, como firewalls e antivírus, prontas para implantar na AWS?","alternativas":[{"texto":"AWS Service Catalog","correta":false,"porque":"Gerencia catálogos de produtos aprovados internamente pela empresa, não de fornecedores externos."},{"texto":"AWS Marketplace","correta":true,"porque":"É o catálogo digital de software de terceiros, incluindo produtos de segurança, com implantação e cobrança pela AWS."},{"texto":"AWS Artifact","correta":false,"porque":"Disponibiliza relatórios de conformidade e acordos, não software."},{"texto":"AWS Security Hub","correta":false,"porque":"Agrega achados de segurança, mas não é uma loja de produtos."}],"explicacao":"O AWS Marketplace reúne produtos de segurança de terceiros (firewalls, IDS/IPS, antimalware) para comprar e implantar na AWS.","servicos":["Marketplace"],"dificuldade":1,"fonte":"kananinirav-k18#18 (reescrita)"},{"id":"D2-b-050","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa usa um firewall de próxima geração de um fornecedor no data center e quer a mesma solução na AWS, paga por hora de uso e cobrada na fatura da AWS. Como deve obtê-la?","alternativas":[{"texto":"Pedindo ao AWS Support que instale o software","correta":false,"porque":"O AWS Support não instala software de terceiros nas contas dos clientes."},{"texto":"Usando o AWS Firewall Manager para importar a licença","correta":false,"porque":"O Firewall Manager gerencia regras de serviços da AWS, não vende software de terceiros."},{"texto":"Assinando o produto do fornecedor no AWS Marketplace","correta":true,"porque":"O Marketplace oferece software de terceiros com cobrança por uso integrada à fatura da AWS."},{"texto":"Comprando o software pelo AWS Artifact","correta":false,"porque":"O Artifact fornece documentos de conformidade, não software."}],"explicacao":"O AWS Marketplace permite usar ferramentas de segurança de terceiros conhecidas, com preço por uso ou BYOL e faturamento consolidado na AWS.","servicos":["Marketplace"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-051","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Um administrador procura respostas da AWS para dúvidas e problemas comuns, como \"como restringir o acesso a um bucket do S3?\". Qual recurso oferece artigos e vídeos com essas respostas?","alternativas":[{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade, não guias de solução de problemas."},{"texto":"AWS Health Dashboard","correta":false,"porque":"Mostra eventos e a saúde dos serviços, não respostas a dúvidas comuns."},{"texto":"AWS Marketplace","correta":false,"porque":"É um catálogo de software de terceiros."},{"texto":"AWS Knowledge Center","correta":true,"porque":"Reúne respostas da AWS às perguntas e solicitações mais frequentes dos clientes."}],"explicacao":"O AWS Knowledge Center é a base de perguntas frequentes e soluções publicadas pela AWS.","servicos":["AWS Support"],"dificuldade":1,"fonte":"autoral"},{"id":"D2-b-052","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Qual recurso da AWS reúne em um só lugar informações sobre segurança da nuvem, conformidade, boletins de segurança e serviços de segurança da AWS?","alternativas":[{"texto":"AWS Security Center","correta":true,"porque":"É o portal central de segurança da AWS, com boletins, conformidade, boas práticas e serviços."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Verifica a conta do cliente, mas não é um portal de informações de segurança."},{"texto":"AWS Security Hub","correta":false,"porque":"Agrega achados de segurança da conta, não conteúdo informativo da AWS."},{"texto":"AWS Service Catalog","correta":false,"porque":"Gerencia produtos de TI aprovados pela empresa."}],"explicacao":"O AWS Security Center (aws.amazon.com/security) centraliza informações de segurança, conformidade e boletins da AWS.","servicos":["AWS Support"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-053","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma equipe quer acompanhar artigos de especialistas da AWS sobre novos recursos de segurança, boas práticas e guias passo a passo. Qual fonte é a MAIS indicada?","alternativas":[{"texto":"AWS Artifact","correta":false,"porque":"Oferece relatórios de auditoria e acordos, não artigos técnicos."},{"texto":"AWS Security Blog","correta":true,"porque":"Publica posts de especialistas da AWS sobre recursos, boas práticas e soluções de segurança."},{"texto":"AWS Health Dashboard","correta":false,"porque":"Informa eventos operacionais dos serviços."},{"texto":"AWS Marketplace","correta":false,"porque":"Vende software de terceiros, não publica artigos de boas práticas."}],"explicacao":"O AWS Security Blog é a fonte de artigos e novidades de segurança escritos por especialistas da AWS.","servicos":["AWS Support"],"dificuldade":1,"fonte":"autoral"},{"id":"D2-b-054","dominio":2,"task":"2.4","tipo":"multipla","selecionar":2,"enunciado":"Quais recursos de informação sobre segurança a AWS oferece gratuitamente a qualquer cliente? (Selecione DUAS.)","alternativas":[{"texto":"Technical Account Manager (TAM) designado","correta":false,"porque":"Está incluído apenas nos planos Enterprise Support e Unified Operations."},{"texto":"AWS Knowledge Center","correta":true,"porque":"É público e gratuito, com respostas a dúvidas comuns."},{"texto":"AWS Professional Services","correta":false,"porque":"É uma consultoria paga da AWS."},{"texto":"AWS Security Blog","correta":true,"porque":"É público e gratuito, com artigos de especialistas da AWS."},{"texto":"Shield Response Team (SRT)","correta":false,"porque":"O acesso é exclusivo de clientes do Shield Advanced."}],"explicacao":"Security Blog, Knowledge Center e Security Center são gratuitos; TAM, SRT e Professional Services dependem de planos ou contratos pagos.","servicos":["AWS Support","Shield"],"dificuldade":2,"fonte":"kananinirav-k7#32 (reescrita)"},{"id":"D2-b-055","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Segundo a política de testes de segurança da AWS, qual atividade NÃO pode ser feita livremente pelo cliente em seus próprios recursos?","alternativas":[{"texto":"Pentest em instâncias Amazon EC2","correta":false,"porque":"O EC2 está na lista de serviços que podem ser testados sem aprovação prévia."},{"texto":"Varredura de portas nas próprias instâncias","correta":false,"porque":"Varrer as próprias instâncias faz parte de testes permitidos."},{"texto":"Simular ataques de negação de serviço (DoS/DDoS) ou flooding de requisições","correta":true,"porque":"Testes de DoS/DDoS são proibidos fora da política específica de testes de DDoS, com fornecedor autorizado."},{"texto":"Pentest em funções AWS Lambda","correta":false,"porque":"O Lambda está na lista de serviços permitidos para testes."}],"explicacao":"Pentest é permitido sem aprovação nos serviços listados; DoS, flooding e ataques à infraestrutura da AWS são proibidos.","servicos":["EC2","Lambda"],"dificuldade":3,"fonte":"autoral"},{"id":"D2-b-056","dominio":2,"task":"2.4","tipo":"multipla","selecionar":2,"enunciado":"A quais recursos o AWS WAF pode ser associado diretamente para proteger aplicações? (Selecione DUAS.)","alternativas":[{"texto":"Application Load Balancers","correta":true,"porque":"O WAF pode ser associado a ALBs para filtrar requisições HTTP(S)."},{"texto":"NAT gateways","correta":false,"porque":"Fazem tradução de endereços para saída à internet e não suportam WAF."},{"texto":"Distribuições do Amazon CloudFront","correta":true,"porque":"O WAF protege distribuições do CloudFront nas edge locations."},{"texto":"Instâncias de banco Amazon RDS","correta":false,"porque":"Não recebem tráfego HTTP de clientes web e não se associam ao WAF."},{"texto":"Volumes do Amazon EBS","correta":false,"porque":"São armazenamento em bloco; não recebem tráfego HTTP."}],"explicacao":"O AWS WAF protege recursos que recebem HTTP(S), como CloudFront, Application Load Balancer e API Gateway.","servicos":["WAF","CloudFront","Elastic Load Balancing"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-057","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Um site está recebendo milhares de requisições por minuto de alguns poucos endereços IP, típicas de bots. A empresa quer limitar automaticamente quantas requisições cada IP pode fazer. Qual recurso deve usar?","alternativas":[{"texto":"Regra de entrada em um Security Group","correta":false,"porque":"Permite ou nega portas e IPs, mas não limita a taxa de requisições."},{"texto":"Política de senha do IAM","correta":false,"porque":"Controla senhas de IAM users, sem relação com tráfego web."},{"texto":"Verificação do AWS Trusted Advisor","correta":false,"porque":"Aponta problemas de configuração, mas não bloqueia tráfego."},{"texto":"Regra baseada em taxa (rate-based rule) do AWS WAF","correta":true,"porque":"Bloqueia temporariamente IPs que excedem um limite de requisições em um intervalo."}],"explicacao":"Regras baseadas em taxa do WAF mitigam floods HTTP e bots limitando requisições por IP.","servicos":["WAF"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-058","dominio":2,"task":"2.4","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS ajudam a proteger uma aplicação web contra ataques DDoS? (Selecione DUAS.)","alternativas":[{"texto":"Amazon CloudFront","correta":true,"porque":"Distribui e absorve o tráfego nas edge locations e integra-se ao Shield e ao WAF."},{"texto":"Amazon Macie","correta":false,"porque":"Descobre dados sensíveis no S3, sem relação com DDoS."},{"texto":"AWS Shield","correta":true,"porque":"É o serviço dedicado de proteção contra DDoS."},{"texto":"Amazon Inspector","correta":false,"porque":"Varre vulnerabilidades, mas não mitiga tráfego de ataque."},{"texto":"AWS Secrets Manager","correta":false,"porque":"Armazena e rotaciona segredos; não mitiga ataques."}],"explicacao":"Uma arquitetura resistente a DDoS combina Shield com serviços de borda como CloudFront (e Route 53), além do WAF na camada 7.","servicos":["Shield","CloudFront"],"dificuldade":2,"fonte":"kananinirav-k12#21 (reescrita)"},{"id":"D2-b-059","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa só pode atender clientes no Brasil e precisa bloquear requisições web vindas de outros países para sua aplicação atrás de um Application Load Balancer. Qual serviço atende?","alternativas":[{"texto":"AWS WAF com regra de correspondência geográfica","correta":true,"porque":"Regras geográficas do WAF permitem ou bloqueiam requisições pelo país de origem."},{"texto":"AWS Shield Standard","correta":false,"porque":"Mitiga DDoS, mas não filtra requisições por país."},{"texto":"Network ACLs","correta":false,"porque":"Filtram faixas de IP, mas não têm regras por país."},{"texto":"AWS Firewall Manager sozinho","correta":false,"porque":"Gerencia políticas centralmente, mas a filtragem em si é feita pelo WAF."}],"explicacao":"AWS WAF permite regras de geolocalização (geo match) para restringir acesso por país.","servicos":["WAF","Elastic Load Balancing"],"dificuldade":2,"fonte":"autoral"},{"id":"D2-b-060","dominio":2,"task":"2.4","tipo":"unica","enunciado":"Uma empresa quer proteger seu site contra DDoS avançados, bloquear SQL injection e administrar essas proteções de forma centralizada em todas as contas da organização. Qual combinação atende?","alternativas":[{"texto":"GuardDuty, Inspector e Security Hub","correta":false,"porque":"Detectam ameaças e vulnerabilidades, mas não bloqueiam tráfego de ataque."},{"texto":"Shield Advanced, AWS WAF e AWS Firewall Manager","correta":true,"porque":"Shield Advanced cuida de DDoS, WAF bloqueia ataques na aplicação e Firewall Manager centraliza a gestão."},{"texto":"Shield Standard, Security Groups e AWS Config","correta":false,"porque":"Não bloqueiam SQL injection nem centralizam regras de WAF entre contas."},{"texto":"Amazon Macie, AWS WAF e SCPs","correta":false,"porque":"Macie descobre dados sensíveis e SCPs limitam permissões; nenhum gerencia proteção de rede."}],"explicacao":"Shield (DDoS), WAF (camada 7) e Firewall Manager (gestão central) se complementam na proteção de aplicações web.","servicos":["Shield","WAF","Firewall Manager"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-a-001","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Em qual modelo de serviço de computação em nuvem se enquadram as instâncias Amazon EC2?","alternativas":[{"texto":"Infrastructure as a Service (IaaS)","correta":true,"porque":"O EC2 entrega servidores virtuais, rede e armazenamento; o cliente gerencia SO, software e dados."},{"texto":"Platform as a Service (PaaS)","correta":false,"porque":"No PaaS o provedor gerencia SO e runtime (ex.: Elastic Beanstalk); no EC2 o SO é do cliente."},{"texto":"Software as a Service (SaaS)","correta":false,"porque":"SaaS é um software pronto consumido pelo usuário final, não capacidade de computação bruta."},{"texto":"Function as a Service (FaaS)","correta":false,"porque":"FaaS executa funções acionadas por eventos (ex.: Lambda), sem servidores visíveis ao cliente."}],"explicacao":"IaaS fornece blocos básicos de infraestrutura (computação, rede, armazenamento) com o maior controle para o cliente; EC2 é o exemplo clássico.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"usuario-A18"},{"id":"D3-a-002","dominio":3,"task":"3.1","tipo":"unica","enunciado":"No modelo Platform as a Service (PaaS), qual item normalmente continua sob gestão do cliente?","alternativas":[{"texto":"Patches do sistema operacional e do runtime","correta":false,"porque":"No PaaS o provedor mantém o SO e o runtime da plataforma."},{"texto":"Código da aplicação e seus dados","correta":true,"porque":"No PaaS o cliente se concentra na aplicação que implanta e nos dados que ela usa."},{"texto":"Hardware físico dos servidores","correta":false,"porque":"O hardware é responsabilidade do provedor em todos os modelos de nuvem (IaaS, PaaS e SaaS)."},{"texto":"Camada de virtualização (hypervisor)","correta":false,"porque":"A virtualização é gerenciada pelo provedor, inclusive no IaaS."}],"explicacao":"Quanto mais alto o modelo (IaaS → PaaS → SaaS), menos o cliente gerencia: no PaaS ele cuida basicamente da aplicação e dos dados.","servicos":["AWS Elastic Beanstalk"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-a-003","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Qual modelo de serviço de computação em nuvem um produto de e-mail web como o Gmail representa?","alternativas":[{"texto":"Platform as a Service (PaaS)","correta":false,"porque":"PaaS oferece uma plataforma para o cliente implantar o próprio código, não um aplicativo pronto."},{"texto":"Function as a Service (FaaS)","correta":false,"porque":"FaaS executa funções do cliente acionadas por eventos; o usuário de e-mail não implanta código."},{"texto":"Software as a Service (SaaS)","correta":true,"porque":"O usuário consome um aplicativo completo, gerenciado pelo provedor, sem cuidar de infraestrutura ou plataforma."},{"texto":"Infrastructure as a Service (IaaS)","correta":false,"porque":"IaaS entrega servidores, rede e armazenamento para o cliente montar a própria solução."}],"explicacao":"SaaS é o software pronto entregue pela internet: o provedor gerencia tudo e o cliente apenas usa a aplicação.","servicos":[],"dificuldade":1,"fonte":"usuario-B34"},{"id":"D3-a-004","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Os servidores web de uma empresa rodam no Amazon EC2 e chamam uma API RESTful que continua em execução no data center on-premises da empresa. Qual modelo de implantação descreve essa configuração?","alternativas":[{"texto":"Arquitetura serverless","correta":false,"porque":"Serverless dispensa gerenciar servidores; aqui há instâncias EC2 e servidores próprios on-premises."},{"texto":"Software as a Service (SaaS)","correta":false,"porque":"SaaS é um modelo de serviço de software pronto, não a combinação de nuvem com data center próprio."},{"texto":"Platform as a Service (PaaS)","correta":false,"porque":"PaaS é um modelo de serviço; não descreve a integração entre nuvem e on-premises."},{"texto":"Nuvem híbrida","correta":true,"porque":"Parte da carga roda na AWS e parte no data center on-premises, conectadas entre si."}],"explicacao":"Implantação híbrida conecta recursos na nuvem a infraestrutura on-premises, algo comum em migrações graduais ou por requisitos de latência e regulação.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"usuario-A51"},{"id":"D3-a-005","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Qual framework de desenvolvimento permite definir recursos de nuvem como código em linguagens como TypeScript ou Python e provisioná-los por meio do AWS CloudFormation?","alternativas":[{"texto":"AWS Cloud Development Kit (AWS CDK)","correta":true,"porque":"O CDK usa linguagens de programação para definir a infraestrutura e a sintetiza em templates do CloudFormation."},{"texto":"AWS CLI","correta":false,"porque":"A CLI executa comandos pontuais ou scripts, mas não é um framework de IaC que gera templates do CloudFormation."},{"texto":"AWS CodeBuild","correta":false,"porque":"O CodeBuild compila e testa código em pipelines; não define recursos de infraestrutura."},{"texto":"AWS Systems Manager","correta":false,"porque":"O Systems Manager gerencia e automatiza operações em instâncias, não define infraestrutura como código."}],"explicacao":"AWS CDK = IaC em linguagens de programação familiares; o resultado é implantado como stacks do CloudFormation.","servicos":["AWS CDK","AWS CloudFormation"],"dificuldade":2,"fonte":"usuario-B82"},{"id":"D3-a-006","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Qual mecanismo permite que desenvolvedores acessem serviços da AWS diretamente a partir do código de suas aplicações?","alternativas":[{"texto":"AWS Management Console","correta":false,"porque":"O Console é uma interface web para uso interativo por pessoas, não por código de aplicação."},{"texto":"AWS SDKs","correta":true,"porque":"Os SDKs oferecem bibliotecas em várias linguagens (Python, Java, JavaScript etc.) que chamam as APIs da AWS a partir do código."},{"texto":"AWS CodePipeline","correta":false,"porque":"O CodePipeline orquestra pipelines de CI/CD, não é uma biblioteca para chamar serviços."},{"texto":"AWS Config","correta":false,"porque":"O Config registra e avalia configurações de recursos; não é um meio de acesso programático."}],"explicacao":"SDKs são bibliotecas por linguagem de programação que encapsulam as chamadas às APIs da AWS dentro das aplicações.","servicos":["AWS SDK"],"dificuldade":1,"fonte":"kananinirav-k9#17"},{"id":"D3-a-007","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Qual serviço permite descrever a infraestrutura em templates JSON ou YAML e provisioná-la de forma automatizada como uma stack?","alternativas":[{"texto":"AWS CodePipeline","correta":false,"porque":"O CodePipeline automatiza etapas de entrega de software; pode acionar o CloudFormation, mas não define os recursos."},{"texto":"AWS Config","correta":false,"porque":"O Config audita configurações existentes; não cria recursos a partir de templates."},{"texto":"AWS CloudFormation","correta":true,"porque":"O CloudFormation provisiona e atualiza recursos a partir de templates declarativos, agrupados em stacks."},{"texto":"Amazon CloudWatch","correta":false,"porque":"O CloudWatch monitora métricas e logs; não provisiona infraestrutura."}],"explicacao":"AWS CloudFormation é o serviço de infraestrutura como código (IaC) da AWS: templates declarativos viram stacks de recursos.","servicos":["AWS CloudFormation"],"dificuldade":1,"fonte":"kananinirav-k18#12 (reescrita)"},{"id":"D3-a-008","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Uma empresa precisa recriar com frequência ambientes idênticos de desenvolvimento, teste e produção em várias Regiões, sem erros manuais. Qual abordagem é a MELHOR?","alternativas":[{"texto":"Criar cada ambiente pelo Management Console seguindo um checklist","correta":false,"porque":"Processos manuais no Console são lentos, sujeitos a erro e difíceis de reproduzir com fidelidade."},{"texto":"Digitar comandos da AWS CLI manualmente em cada ambiente","correta":false,"porque":"Comandos digitados um a um ainda são uma operação pontual e propensa a divergências entre ambientes."},{"texto":"Abrir um caso no AWS Support para replicar os ambientes","correta":false,"porque":"O AWS Support não provisiona ambientes do cliente; isso é responsabilidade do cliente."},{"texto":"Definir a infraestrutura em templates do AWS CloudFormation","correta":true,"porque":"O mesmo template pode ser implantado repetidamente em várias Regiões e contas, sempre com o mesmo resultado."}],"explicacao":"Para processos repetíveis use IaC (CloudFormation/CDK); o Console serve melhor para operações pontuais e exploração.","servicos":["AWS CloudFormation"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-009","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Um gerente sem experiência em programação precisa, uma única vez, conferir visualmente as configurações de um bucket do Amazon S3. Qual é a forma MAIS simples?","alternativas":[{"texto":"AWS Management Console","correta":true,"porque":"A interface web gráfica é ideal para tarefas pontuais e exploração sem escrever comandos ou código."},{"texto":"AWS CLI","correta":false,"porque":"Exige instalar a ferramenta, configurar credenciais e conhecer comandos, o que é excessivo para quem não programa."},{"texto":"AWS SDK para Python","correta":false,"porque":"Exige escrever código, o que não faz sentido para uma consulta visual única."},{"texto":"Template do AWS CloudFormation","correta":false,"porque":"IaC serve para provisionar recursos de forma repetível, não para inspecionar uma configuração uma vez."}],"explicacao":"O Management Console é a interface web para operações pontuais e interativas; CLI, SDK e IaC brilham em automação.","servicos":["AWS Management Console"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-010","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Um administrador quer automatizar tarefas rotineiras na AWS usando scripts de shell no terminal, sem desenvolver uma aplicação. Qual ferramenta é a MAIS adequada?","alternativas":[{"texto":"AWS SDK","correta":false,"porque":"O SDK é para integrar chamadas à AWS dentro do código de aplicações em uma linguagem de programação."},{"texto":"AWS CLI","correta":true,"porque":"A CLI permite controlar serviços por comandos no terminal e encadeá-los em scripts de shell."},{"texto":"AWS Management Console","correta":false,"porque":"O Console é interativo e gráfico; não se presta a scripts de automação."},{"texto":"AWS CDK","correta":false,"porque":"O CDK define infraestrutura como código para provisionamento, não para tarefas operacionais rotineiras via shell."}],"explicacao":"AWS CLI: ferramenta de linha de comando unificada para gerenciar serviços e automatizar tarefas por scripts.","servicos":["AWS CLI"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-011","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Qual afirmação sobre o AWS Management Console, a AWS CLI e os AWS SDKs está correta?","alternativas":[{"texto":"Somente o Console cria recursos; a CLI e os SDKs apenas consultam","correta":false,"porque":"CLI e SDKs criam, alteram e excluem recursos tanto quanto o Console."},{"texto":"A CLI dispensa autenticação quando usada a partir de um notebook corporativo","correta":false,"porque":"Toda chamada precisa ser autenticada e autorizada, seja por access keys ou credenciais temporárias."},{"texto":"Todos enviam requisições às mesmas APIs da AWS","correta":true,"porque":"Console, CLI e SDKs são formas diferentes de chamar as mesmas APIs, sujeitas às mesmas permissões IAM."},{"texto":"Cada ferramenta usa permissões próprias, separadas do IAM","correta":false,"porque":"As permissões vêm sempre do IAM, independentemente da ferramenta usada."}],"explicacao":"Tudo na AWS é API: Console, CLI, SDK e IaC são camadas de acesso sobre as mesmas APIs e respeitam as mesmas políticas IAM.","servicos":["AWS Management Console","AWS CLI","AWS SDK"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-a-012","dominio":3,"task":"3.1","tipo":"multipla","selecionar":2,"enunciado":"Quais são benefícios de gerenciar a infraestrutura como código (IaC) com AWS CloudFormation ou AWS CDK? (Selecione DUAS.)","alternativas":[{"texto":"Implantações consistentes e repetíveis em vários ambientes","correta":true,"porque":"O mesmo código gera sempre a mesma infraestrutura, eliminando divergências entre ambientes."},{"texto":"Dispensa de permissões IAM para criar recursos","correta":false,"porque":"Quem implanta (ou a role usada pela stack) continua precisando de permissões IAM."},{"texto":"Versionamento e revisão das mudanças como código-fonte","correta":true,"porque":"Templates ficam em controle de versão, permitindo revisão, histórico e rollback de mudanças."},{"texto":"Desconto automático no preço dos recursos provisionados","correta":false,"porque":"IaC não altera preços; os recursos são cobrados normalmente."},{"texto":"Fim da necessidade de monitorar os recursos criados","correta":false,"porque":"Recursos provisionados por IaC continuam precisando de monitoramento (ex.: CloudWatch)."}],"explicacao":"IaC traz repetibilidade, consistência, versionamento e automação; não muda preços nem dispensa segurança ou monitoramento.","servicos":["AWS CloudFormation","AWS CDK"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-013","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Uma empresa desativou seu data center e passou a executar todas as cargas de trabalho na AWS. Qual modelo de implantação ela adota?","alternativas":[{"texto":"Híbrido","correta":false,"porque":"Híbrido combina nuvem com infraestrutura on-premises, que a empresa não tem mais."},{"texto":"On-premises (nuvem privada)","correta":false,"porque":"On-premises usa data center próprio, justamente o que foi desativado."},{"texto":"Infrastructure as a Service (IaaS)","correta":false,"porque":"IaaS é um modelo de serviço, não um modelo de implantação."},{"texto":"Nuvem (cloud)","correta":true,"porque":"Toda a aplicação roda na nuvem, o que permite trocar despesas de capital por despesas operacionais."}],"explicacao":"Modelos de implantação: nuvem (tudo na nuvem), híbrido (nuvem + on-premises) e on-premises (data center próprio, também chamado nuvem privada).","servicos":[],"dificuldade":2,"fonte":"kananinirav-k16#5 (reescrita)"},{"id":"D3-a-014","dominio":3,"task":"3.1","tipo":"unica","enunciado":"Um desenvolvedor vai usar a AWS CLI em seu notebook com um IAM user. Que tipo de credencial ele precisa configurar?","alternativas":[{"texto":"Access key ID e secret access key","correta":true,"porque":"O acesso programático de um IAM user pela CLI e pelos SDKs é autenticado com access keys."},{"texto":"Nome de usuário e senha do Console","correta":false,"porque":"Usuário e senha servem para o login no Management Console, não para chamadas programáticas."},{"texto":"Par de chaves do Amazon EC2","correta":false,"porque":"O par de chaves EC2 dá acesso SSH a instâncias, não às APIs da AWS."},{"texto":"API key do Amazon API Gateway","correta":false,"porque":"API keys do API Gateway controlam o uso de APIs do cliente publicadas no serviço, não o acesso à AWS."}],"explicacao":"CLI e SDKs usam access keys (ou credenciais temporárias, como as do IAM Identity Center) para assinar as chamadas às APIs da AWS.","servicos":["AWS CLI","IAM"],"dificuldade":2,"fonte":"kananinirav-k18#27"},{"id":"D3-a-015","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual é a relação correta entre Regiões, Zonas de Disponibilidade (AZs) e edge locations da AWS?","alternativas":[{"texto":"Cada AZ contém várias Regiões; as edge locations ficam dentro das AZs","correta":false,"porque":"A hierarquia é inversa: Regiões contêm AZs, e edge locations não ficam dentro de AZs."},{"texto":"Cada edge location é uma AZ reduzida que hospeda o Amazon EC2","correta":false,"porque":"Edge locations são pontos de presença para CloudFront, Route 53 e afins; não são AZs nem hospedam EC2 comum."},{"texto":"Cada Região contém várias AZs; as edge locations ficam fora dessa estrutura","correta":true,"porque":"Regiões agrupam AZs; as edge locations são bem mais numerosas e ficam perto dos usuários finais."},{"texto":"Região e AZ são sinônimos; as edge locations são data centers da AZ","correta":false,"porque":"Região é uma área geográfica; AZ é um ou mais data centers dentro dela; edge location é outra coisa."}],"explicacao":"Região ⊃ AZs (data centers isolados); edge locations são pontos de presença separados, mais numerosos que Regiões, usados para entrega de conteúdo e DNS.","servicos":["AWS Global Infrastructure"],"dificuldade":1,"fonte":"kananinirav-k6#1 (reescrita)"},{"id":"D3-a-016","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual é a ordem dos componentes da infraestrutura global da AWS por área geográfica de cobertura, do MAIOR para o MENOR?","alternativas":[{"texto":"Edge locations, Zonas de Disponibilidade, Regiões","correta":false,"porque":"Edge locations são pontos de presença pequenos e não abrangem AZs ou Regiões."},{"texto":"Regiões, Zonas de Disponibilidade, edge locations","correta":true,"porque":"A Região é a área geográfica que contém as AZs; a edge location é um ponto de presença menor."},{"texto":"Zonas de Disponibilidade, edge locations, Regiões","correta":false,"porque":"A AZ fica dentro de uma Região, portanto não pode ser maior que ela."},{"texto":"Regiões, edge locations, Zonas de Disponibilidade","correta":false,"porque":"Uma edge location não contém AZs; a AZ é um ou mais data centers completos."}],"explicacao":"Região (área geográfica) > Zona de Disponibilidade (um ou mais data centers) > edge location (ponto de presença perto dos usuários).","servicos":["AWS Global Infrastructure"],"dificuldade":1,"fonte":"usuario-A13"},{"id":"D3-a-017","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual componente da infraestrutura global da AWS consiste em um ou mais data centers distintos, com energia, rede e conectividade redundantes, dentro de uma Região?","alternativas":[{"texto":"Edge location","correta":false,"porque":"Edge locations são pontos de presença para cache e DNS, não conjuntos de data centers de uma Região."},{"texto":"Local Zone","correta":false,"porque":"Local Zone estende uma Região para perto de uma área metropolitana; não é o bloco básico de cada Região."},{"texto":"Região da AWS","correta":false,"porque":"A Região é a área geográfica que agrupa várias AZs."},{"texto":"Zona de Disponibilidade","correta":true,"porque":"Cada AZ é formada por um ou mais data centers com infraestrutura redundante e isolada das demais AZs."}],"explicacao":"Uma Zona de Disponibilidade é um ou mais data centers discretos, com energia, rede e conectividade redundantes, dentro de uma Região.","servicos":["AWS Global Infrastructure"],"dificuldade":1,"fonte":"kananinirav-k8#45"},{"id":"D3-a-018","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual componente da infraestrutura da AWS se correlaciona diretamente com uma subnet de VPC?","alternativas":[{"texto":"Uma Zona de Disponibilidade","correta":true,"porque":"Cada subnet fica inteiramente em uma única AZ; a VPC é que abrange a Região."},{"texto":"Uma Região da AWS","correta":false,"porque":"A Região corresponde à VPC inteira, não a uma subnet."},{"texto":"Uma edge location do CloudFront","correta":false,"porque":"Edge locations não hospedam subnets de VPC."},{"texto":"Um único servidor físico","correta":false,"porque":"Uma subnet é uma faixa de IPs lógica numa AZ, não um servidor."}],"explicacao":"VPC = Região; subnet = AZ. Para alta disponibilidade, distribua recursos em subnets de AZs diferentes.","servicos":["Amazon VPC"],"dificuldade":2,"fonte":"usuario-A58"},{"id":"D3-a-019","dominio":3,"task":"3.2","tipo":"unica","enunciado":"As Zonas de Disponibilidade de uma Região ficam separadas por uma distância significativa, mas dentro de cerca de 100 km umas das outras. Qual é o principal objetivo desse espaçamento?","alternativas":[{"texto":"Maximizar a área geográfica coberta pela Região","correta":false,"porque":"A cobertura para usuários vem de Regiões e edge locations, não do espaçamento entre AZs."},{"texto":"Evitar que um único desastre localizado afete várias AZs ao mesmo tempo","correta":true,"porque":"A distância isola falhas (incêndio, enchente, queda de energia), enquanto a proximidade mantém baixa latência entre AZs."},{"texto":"Reduzir o custo dos terrenos onde ficam os data centers","correta":false,"porque":"O critério de projeto é isolamento de falhas, não preço de terreno."},{"texto":"Diminuir a latência para usuários finais próximos","correta":false,"porque":"Baixa latência para usuários finais é papel de Regiões próximas e edge locations."}],"explicacao":"AZs são fisicamente separadas para não compartilharem um ponto único de falha, mas próximas o bastante para replicação síncrona com baixa latência.","servicos":["AWS Global Infrastructure"],"dificuldade":2,"fonte":"usuario-B15"},{"id":"D3-a-020","dominio":3,"task":"3.2","tipo":"multipla","selecionar":2,"enunciado":"Quais afirmações sobre as Zonas de Disponibilidade da AWS são verdadeiras? (Selecione DUAS.)","alternativas":[{"texto":"Cada AZ tem energia, refrigeração e rede independentes das demais","correta":true,"porque":"A infraestrutura independente evita que uma falha em uma AZ derrube as outras."},{"texto":"As AZs de uma Região são interligadas por rede de baixa latência e alta largura de banda","correta":true,"porque":"Isso permite replicar dados de forma síncrona e distribuir aplicações entre AZs."},{"texto":"Cada AZ é sempre um único data center","correta":false,"porque":"Uma AZ pode ser composta por um ou mais data centers."},{"texto":"AZs de Regiões diferentes compartilham a mesma infraestrutura elétrica","correta":false,"porque":"Regiões são totalmente isoladas umas das outras; não compartilham infraestrutura."},{"texto":"Cada AZ funciona também como edge location do Amazon CloudFront","correta":false,"porque":"Edge locations são pontos de presença próprios, distintos das AZs."}],"explicacao":"AZs não compartilham ponto único de falha e são conectadas por links redundantes de baixa latência, o que viabiliza arquiteturas multi-AZ.","servicos":["AWS Global Infrastructure"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-021","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Uma empresa está criando uma arquitetura para uma carga de trabalho crítica que precisa de alta disponibilidade. Qual é a prática recomendada?","alternativas":[{"texto":"Escalar verticalmente, usando um tipo de instância EC2 maior","correta":false,"porque":"Uma instância maior continua sendo um ponto único de falha."},{"texto":"Colocar os componentes em um placement group para reduzir a latência entre eles","correta":false,"porque":"Placement group em cluster concentra instâncias, o que melhora latência mas não disponibilidade."},{"texto":"Distribuir os componentes da aplicação em várias Zonas de Disponibilidade da Região","correta":true,"porque":"Se uma AZ falhar, as instâncias nas outras AZs continuam atendendo."},{"texto":"Usar um Auto Scaling group limitado a uma única Zona de Disponibilidade","correta":false,"porque":"O Auto Scaling substitui instâncias, mas não protege contra a falha da AZ inteira."}],"explicacao":"Multi-AZ é a forma padrão de alta disponibilidade na AWS: elimina a AZ como ponto único de falha.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"usuario-B20"},{"id":"D3-a-022","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Um portal web acessado por usuários do mundo todo precisa da MAIOR redundância e tolerância a falhas possível. Como as instâncias Amazon EC2 devem ser distribuídas?","alternativas":[{"texto":"Em várias Zonas de Disponibilidade de uma única Região","correta":false,"porque":"Protege contra a falha de uma AZ, mas não contra a indisponibilidade de uma Região inteira."},{"texto":"Em três Regiões, com uma única Zona de Disponibilidade em cada","correta":false,"porque":"A falha de uma AZ derruba toda a capacidade daquela Região."},{"texto":"Em uma única Zona de Disponibilidade, com instâncias maiores","correta":false,"porque":"Concentra tudo em um ponto único de falha."},{"texto":"Em várias Zonas de Disponibilidade em mais de uma Região","correta":true,"porque":"Combina proteção contra falha de AZ e de Região, o nível mais alto de redundância."}],"explicacao":"Multi-AZ protege contra falha de data center; multi-Região adiciona proteção contra falha regional. As duas juntas dão a maior tolerância a falhas.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"usuario-A38"},{"id":"D3-a-023","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Uma empresa quer garantir a continuidade dos negócios mesmo diante de uma catástrofe natural que afete toda uma área geográfica. Qual parte da infraestrutura global ela deve usar para replicar seus recursos?","alternativas":[{"texto":"Várias Regiões da AWS","correta":true,"porque":"Regiões são geograficamente distantes e isoladas, então um desastre em uma não afeta a outra."},{"texto":"Edge locations","correta":false,"porque":"Edge locations armazenam conteúdo em cache; não hospedam a infraestrutura de recuperação."},{"texto":"Várias Zonas de Disponibilidade","correta":false,"porque":"AZs ficam na mesma Região (até ~100 km); um desastre de grande escala pode atingir todas."},{"texto":"Amazon Route 53","correta":false,"porque":"O Route 53 pode direcionar tráfego no failover, mas não é onde os recursos são replicados."}],"explicacao":"Recuperação de desastres contra eventos regionais exige replicar dados e recursos em outra Região.","servicos":["AWS Global Infrastructure"],"dificuldade":1,"fonte":"usuario-B78"},{"id":"D3-a-024","dominio":3,"task":"3.2","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa está escolhendo a Região da AWS para lançar uma nova aplicação. Quais fatores ela deve considerar? (Selecione DUAS.)","alternativas":[{"texto":"Faixas de desconto por volume exclusivas de cada Região","correta":false,"porque":"Não existem faixas de desconto por volume específicas por Região; o que varia é o preço dos serviços."},{"texto":"Baixa latência entre os usuários finais e a Região","correta":true,"porque":"Regiões mais próximas dos usuários reduzem a latência da aplicação."},{"texto":"Proximidade para visitar fisicamente o data center da AWS","correta":false,"porque":"Clientes não visitam os data centers da AWS."},{"texto":"Requisitos regulatórios e de soberania de dados do país","correta":true,"porque":"Leis podem exigir que os dados fiquem armazenados em determinado país ou jurisdição."},{"texto":"Diferenças de nível de segurança entre as Zonas de Disponibilidade","correta":false,"porque":"Todas as AZs seguem os mesmos controles de segurança da AWS."}],"explicacao":"Critérios de escolha de Região: conformidade e soberania de dados, latência para os usuários, disponibilidade de serviços e preço.","servicos":["AWS Global Infrastructure"],"dificuldade":2,"fonte":"usuario-A09"},{"id":"D3-a-025","dominio":3,"task":"3.2","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS são globais, e não regionais? (Selecione DUAS.)","alternativas":[{"texto":"Amazon RDS","correta":false,"porque":"Instâncias RDS são criadas em uma Região específica."},{"texto":"AWS Identity and Access Management (IAM)","correta":true,"porque":"Usuários, grupos, roles e políticas IAM valem para todas as Regiões da conta."},{"texto":"Amazon DynamoDB","correta":false,"porque":"Tabelas DynamoDB são regionais; Global Tables apenas as replicam entre Regiões."},{"texto":"AWS Batch","correta":false,"porque":"Ambientes de computação do Batch são criados por Região."},{"texto":"Amazon CloudFront","correta":true,"porque":"Uma distribuição CloudFront é global e usa a rede de edge locations no mundo todo."}],"explicacao":"Exemplos de serviços globais: IAM, CloudFront, Route 53 e Organizations. A maioria dos serviços (EC2, RDS, Lambda, DynamoDB) é regional.","servicos":["IAM","Amazon CloudFront"],"dificuldade":2,"fonte":"usuario-A14"},{"id":"D3-a-026","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual dos serviços a seguir tem escopo regional, ou seja, seus recursos são criados em uma Região específica?","alternativas":[{"texto":"Amazon Route 53","correta":false,"porque":"O Route 53 é um serviço global de DNS servido a partir de edge locations."},{"texto":"AWS Identity and Access Management (IAM)","correta":false,"porque":"O IAM é global: suas identidades valem em todas as Regiões."},{"texto":"Amazon CloudFront","correta":false,"porque":"O CloudFront é global e usa edge locations no mundo todo."},{"texto":"AWS Lambda","correta":true,"porque":"Funções Lambda são implantadas e executadas em uma Região escolhida pelo cliente."}],"explicacao":"Saber o escopo do serviço evita surpresas: Lambda, EC2, RDS e DynamoDB são regionais; IAM, Route 53 e CloudFront são globais.","servicos":["AWS Lambda"],"dificuldade":2,"fonte":"usuario-A27 (reescrita)"},{"id":"D3-a-027","dominio":3,"task":"3.2","tipo":"multipla","selecionar":2,"enunciado":"Quais recursos da AWS são zonais, isto é, ficam atrelados a uma única Zona de Disponibilidade? (Selecione DUAS.)","alternativas":[{"texto":"Instância Amazon EC2","correta":true,"porque":"Cada instância é lançada em uma subnet, que pertence a uma única AZ."},{"texto":"Hosted zone do Amazon Route 53","correta":false,"porque":"O Route 53 é um serviço global."},{"texto":"Bucket do Amazon S3","correta":false,"porque":"Buckets S3 são regionais e, nas classes padrão, guardam dados em várias AZs."},{"texto":"IAM role","correta":false,"porque":"Recursos IAM são globais."},{"texto":"Volume Amazon EBS","correta":true,"porque":"Um volume EBS existe em uma AZ e só pode ser anexado a instâncias da mesma AZ."}],"explicacao":"EC2 e EBS são zonais: por isso alta disponibilidade exige instâncias e dados distribuídos em várias AZs (ou snapshots, que são regionais).","servicos":["Amazon EC2","Amazon EBS"],"dificuldade":3,"fonte":"usuario-B16"},{"id":"D3-a-028","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Qual é a principal função das edge locations da AWS?","alternativas":[{"texto":"Hospedar instâncias Amazon EC2 mais perto dos usuários","correta":false,"porque":"Edge locations não executam instâncias EC2 comuns; para isso existem Regiões e Local Zones."},{"texto":"Armazenar em cache e entregar conteúdo mais perto dos usuários, reduzindo a latência","correta":true,"porque":"O CloudFront guarda cópias do conteúdo nas edge locations e atende os usuários a partir do ponto mais próximo."},{"texto":"Guardar cópias de backup de bancos de dados RDS","correta":false,"porque":"Backups do RDS ficam no S3 da Região, não em edge locations."},{"texto":"Substituir as AZs em Regiões com pouca capacidade","correta":false,"porque":"Edge locations não substituem AZs nem executam cargas de trabalho regionais."}],"explicacao":"Edge locations são pontos de presença usados por CloudFront, Route 53, Global Accelerator e Shield para servir usuários com baixa latência.","servicos":["Amazon CloudFront"],"dificuldade":1,"fonte":"kananinirav-k12#4 (reescrita)"},{"id":"D3-a-029","dominio":3,"task":"3.2","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS usam a rede de edge locations para atender os usuários? (Selecione DUAS.)","alternativas":[{"texto":"Amazon CloudFront","correta":true,"porque":"A CDN da AWS armazena conteúdo em cache nas edge locations."},{"texto":"Amazon RDS","correta":false,"porque":"O RDS roda em AZs de uma Região, não em edge locations."},{"texto":"AWS Global Accelerator","correta":true,"porque":"Recebe o tráfego na edge location mais próxima e o leva pela rede global da AWS até a aplicação."},{"texto":"Amazon EBS","correta":false,"porque":"Volumes EBS ficam em uma AZ, anexados a instâncias EC2."},{"texto":"Amazon ElastiCache","correta":false,"porque":"O ElastiCache é um cache em memória dentro da VPC em uma Região, não em edge locations."}],"explicacao":"CloudFront, Global Accelerator, Route 53 e Shield operam a partir das edge locations; bancos, volumes e caches de aplicação ficam nas Regiões.","servicos":["Amazon CloudFront","AWS Global Accelerator"],"dificuldade":2,"fonte":"kananinirav-k17#27 (reescrita)"},{"id":"D3-a-030","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Uma empresa de edição de vídeo precisa executar estações de renderização com latência de um dígito de milissegundo para usuários em uma grande cidade que fica longe da Região AWS mais próxima. Qual opção atende a esse requisito?","alternativas":[{"texto":"AWS Local Zones","correta":true,"porque":"Local Zones estendem uma Região para áreas metropolitanas, levando computação e armazenamento para perto dos usuários."},{"texto":"Edge locations do Amazon CloudFront","correta":false,"porque":"Edge locations armazenam conteúdo em cache, mas não executam estações de renderização."},{"texto":"Uma nova Zona de Disponibilidade na Região atual","correta":false,"porque":"Clientes não criam AZs, e uma AZ continua na área geográfica da Região."},{"texto":"AWS Direct Connect","correta":false,"porque":"Direct Connect cria um link dedicado até a AWS, mas a computação continuaria distante na Região."}],"explicacao":"Local Zones são extensões de uma Região perto de grandes centros urbanos para cargas que exigem latência muito baixa para usuários locais.","servicos":["AWS Local Zones"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-a-031","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Uma empresa japonesa hospeda sua aplicação na Região de Tóquio e abriu filiais nos Estados Unidos, cujos usuários reclamam de lentidão em uma aplicação dinâmica e interativa. Qual é a MELHOR forma de reduzir a latência para eles?","alternativas":[{"texto":"Usar instâncias EC2 maiores na Região de Tóquio","correta":false,"porque":"Mais capacidade não reduz a distância física entre usuários e servidores."},{"texto":"Distribuir a aplicação em mais Zonas de Disponibilidade em Tóquio","correta":false,"porque":"Multi-AZ aumenta a disponibilidade, mas as AZs continuam no Japão."},{"texto":"Ativar o AWS Shield Advanced","correta":false,"porque":"O Shield Advanced protege contra DDoS, não reduz latência."},{"texto":"Implantar a aplicação também em uma Região nos Estados Unidos","correta":true,"porque":"Executar a aplicação perto dos usuários reduz a latência de forma estrutural."}],"explicacao":"Atender usuários em outro continente com baixa latência é um dos motivos para usar várias Regiões.","servicos":["AWS Global Infrastructure"],"dificuldade":2,"fonte":"kananinirav-k1#10 (reescrita)"},{"id":"D3-a-032","dominio":3,"task":"3.2","tipo":"unica","enunciado":"Uma lei exige que os dados pessoais de clientes de um banco europeu permaneçam armazenados na União Europeia. O que a empresa deve fazer na AWS?","alternativas":[{"texto":"Usar edge locations na Europa para todos os dados","correta":false,"porque":"Edge locations armazenam cópias temporárias em cache; não são o local de armazenamento primário dos dados."},{"texto":"Armazenar os dados em Regiões da AWS localizadas na UE","correta":true,"porque":"A AWS não move dados do cliente para fora da Região escolhida sem ação do próprio cliente."},{"texto":"Ativar a replicação entre Regiões para os Estados Unidos","correta":false,"porque":"Isso copiaria os dados para fora da UE, violando a exigência."},{"texto":"Distribuir os dados em várias AZs de qualquer Região","correta":false,"porque":"AZs ficam dentro da Região; escolher uma Região fora da UE descumpre a lei."}],"explicacao":"Soberania e residência de dados são atendidas escolhendo a Região: o cliente controla onde os dados ficam e se são replicados.","servicos":["AWS Global Infrastructure"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-033","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Dentro de uma instância EC2, onde uma aplicação consulta informações da própria instância, como ID da instância, tipo, IP e credenciais da role IAM associada?","alternativas":[{"texto":"No user data da instância","correta":false,"porque":"User data é o script ou dado fornecido pelo cliente para rodar na inicialização, não as informações geradas sobre a instância."},{"texto":"Em uma resource tag","correta":false,"porque":"Tags são rótulos chave-valor definidos pelo cliente para organizar recursos."},{"texto":"Na Amazon Machine Image (AMI)","correta":false,"porque":"A AMI é o modelo usado para lançar a instância; não contém dados da instância em execução."},{"texto":"No instance metadata","correta":true,"porque":"O serviço de metadados expõe à própria instância dados como ID, tipo, rede e credenciais temporárias da role."}],"explicacao":"Instance metadata = dados sobre a instância em execução, acessíveis de dentro dela; user data = instruções fornecidas pelo cliente para a inicialização.","servicos":["Amazon EC2"],"dificuldade":3,"fonte":"usuario-A05"},{"id":"D3-a-034","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa quer que cada nova instância EC2 instale automaticamente um servidor web e baixe a aplicação no primeiro boot. Qual recurso do EC2 deve ser usado?","alternativas":[{"texto":"Instance metadata","correta":false,"porque":"Metadados descrevem a instância; não executam instruções de configuração."},{"texto":"User data","correta":true,"porque":"O script de user data é executado na inicialização e automatiza a configuração da instância."},{"texto":"Tags de instância","correta":false,"porque":"Tags apenas rotulam recursos; não executam comandos."},{"texto":"Security Group","correta":false,"porque":"Security Groups filtram tráfego de rede; não configuram software."}],"explicacao":"User data permite passar um script que roda no boot da instância (bootstrapping), automatizando instalação e configuração.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-a-035","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Um cliente passou muito tempo configurando uma instância EC2 e agora quer lançar outras instâncias com configuração idêntica. Qual é a forma MAIS simples?","alternativas":[{"texto":"Criar uma regra do AWS Config a partir da instância original","correta":false,"porque":"O Config avalia conformidade de configurações; não lança instâncias."},{"texto":"Criar um snapshot do volume EBS e anexá-lo a uma instância vazia","correta":false,"porque":"Um snapshot copia um volume, mas não é o modelo completo de lançamento da instância."},{"texto":"Criar uma AMI a partir da instância e lançar as novas instâncias com ela","correta":true,"porque":"A AMI contém SO, software e configurações, servindo de modelo para quantas instâncias forem necessárias."},{"texto":"Adicionar as mesmas tags às novas instâncias","correta":false,"porque":"Tags organizam recursos, mas não copiam software ou configuração."}],"explicacao":"A Amazon Machine Image (AMI) é o modelo de software usado para lançar instâncias EC2 pré-configuradas e idênticas.","servicos":["Amazon EC2","AMI"],"dificuldade":1,"fonte":"kananinirav-k3#32"},{"id":"D3-a-036","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Qual recurso do EC2 permite rotular instâncias por ambiente (desenvolvimento, homologação, produção) para organizá-las e filtrá-las?","alternativas":[{"texto":"User data","correta":false,"porque":"User data executa instruções na inicialização; não serve para classificar recursos."},{"texto":"Instance metadata","correta":false,"porque":"Metadados são gerados pela AWS sobre a instância; não são rótulos de organização."},{"texto":"Tipo de instância","correta":false,"porque":"O tipo define CPU, memória e rede, não o ambiente a que a instância pertence."},{"texto":"Tags","correta":true,"porque":"Tags são pares chave-valor, como Ambiente=Produção, usados para organizar, filtrar e controlar recursos."}],"explicacao":"Tags rotulam recursos AWS com pares chave-valor para organização, automação, controle de acesso e alocação de custos.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"usuario-A07"},{"id":"D3-a-037","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa vai executar um banco de dados em memória de alto desempenho no Amazon EC2, que precisa de muita RAM para processar grandes conjuntos de dados. Qual família de instância é a MAIS adequada?","alternativas":[{"texto":"Otimizada para computação","correta":false,"porque":"Prioriza CPU de alto desempenho, não grande quantidade de memória por vCPU."},{"texto":"Otimizada para memória","correta":true,"porque":"Oferece alta proporção de memória por vCPU, ideal para bancos e caches em memória e análise em tempo real."},{"texto":"Otimizada para armazenamento","correta":false,"porque":"Foca em I/O de disco local alto e sequencial, não em RAM."},{"texto":"Computação acelerada","correta":false,"porque":"Usa GPUs e outros aceleradores para ML e gráficos, não grande capacidade de memória."}],"explicacao":"Memory optimized (ex.: R, X) atende cargas que processam grandes volumes de dados em memória.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-a-038","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa executa modelagem científica, transcodificação de mídia em lote e servidores de jogos que dependem de processadores de alto desempenho. Qual família de instância EC2 deve ser usada?","alternativas":[{"texto":"Uso geral","correta":false,"porque":"Equilibra CPU, memória e rede, sem priorizar desempenho de CPU."},{"texto":"Otimizada para memória","correta":false,"porque":"Prioriza grande quantidade de RAM, não processamento intenso."},{"texto":"Otimizada para computação","correta":true,"porque":"Oferece alta proporção de CPU, ideal para HPC, processamento em lote, transcodificação e jogos."},{"texto":"Otimizada para armazenamento","correta":false,"porque":"Prioriza I/O de disco local, não poder de processamento."}],"explicacao":"Compute optimized (ex.: C) atende cargas limitadas por CPU: HPC, modelagem científica, servidores de jogos e transcodificação.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-039","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma carga de data warehouse distribuído exige acesso de leitura e gravação sequencial muito alto a grandes conjuntos de dados em armazenamento local da instância. Qual família de instância EC2 é a MAIS adequada?","alternativas":[{"texto":"Otimizada para armazenamento","correta":true,"porque":"Foi projetada para alto IOPS e throughput em armazenamento local, como data warehouses e sistemas de arquivos distribuídos."},{"texto":"Computação acelerada","correta":false,"porque":"Usa GPUs e aceleradores para ML e gráficos, não I/O de disco local."},{"texto":"Uso geral","correta":false,"porque":"Atende cargas equilibradas, sem otimização específica para I/O de disco."},{"texto":"Otimizada para computação","correta":false,"porque":"Prioriza CPU, não throughput de armazenamento local."}],"explicacao":"Storage optimized (ex.: I, D) atende cargas com muitas leituras e gravações sequenciais em grandes volumes de dados locais.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-040","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma equipe de pesquisa precisa treinar modelos de deep learning e fazer renderização gráfica usando GPUs no Amazon EC2. Qual família de instância atende a esse requisito?","alternativas":[{"texto":"Otimizada para memória","correta":false,"porque":"Oferece muita RAM, mas não aceleradores de hardware como GPUs."},{"texto":"Uso geral","correta":false,"porque":"Atende servidores web e repositórios de código, sem GPUs."},{"texto":"Otimizada para armazenamento","correta":false,"porque":"Foca em I/O de disco local, não em processamento por GPU."},{"texto":"Computação acelerada","correta":true,"porque":"Usa GPUs ou outros aceleradores de hardware para ML, gráficos e cálculos de ponto flutuante."}],"explicacao":"Accelerated computing (ex.: P, G, Inf, Trn) usa coprocessadores de hardware para ML, renderização e computação científica.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-a-041","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa vai hospedar servidores web e repositórios de código com uso equilibrado de CPU, memória e rede, sem nenhum recurso dominante. Qual família de instância EC2 é a escolha MAIS adequada?","alternativas":[{"texto":"Otimizada para computação","correta":false,"porque":"Seria indicada se a carga fosse limitada por CPU, o que não é o caso."},{"texto":"Uso geral","correta":true,"porque":"Equilibra computação, memória e rede, sendo indicada para servidores web e repositórios de código."},{"texto":"Otimizada para memória","correta":false,"porque":"Seria indicada para conjuntos de dados grandes em memória, não para uso equilibrado."},{"texto":"Computação acelerada","correta":false,"porque":"GPUs e aceleradores encarecem e não trazem benefício a cargas web comuns."}],"explicacao":"General purpose (ex.: M, T) equilibra recursos e é o ponto de partida para cargas sem gargalo dominante.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-042","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa quer executar contêineres Docker em um serviço de orquestração gerenciado da AWS, sem adotar Kubernetes. Qual serviço deve ser usado?","alternativas":[{"texto":"Amazon Elastic Container Registry (Amazon ECR)","correta":false,"porque":"O ECR armazena imagens de contêiner; não orquestra a execução."},{"texto":"Amazon Elastic Kubernetes Service (Amazon EKS)","correta":false,"porque":"O EKS orquestra contêineres com Kubernetes, que a empresa não quer usar."},{"texto":"Amazon Elastic Container Service (Amazon ECS)","correta":true,"porque":"O ECS é o orquestrador de contêineres próprio da AWS, totalmente gerenciado."},{"texto":"AWS Elastic Beanstalk","correta":false,"porque":"O Beanstalk implanta aplicações; não é o serviço de orquestração de contêineres em si."}],"explicacao":"ECS = orquestração de contêineres nativa da AWS; EKS = Kubernetes gerenciado; ECR = registro de imagens.","servicos":["Amazon ECS"],"dificuldade":2,"fonte":"kananinirav-k21#42 (reescrita)"},{"id":"D3-a-043","dominio":3,"task":"3.3","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa já usa Kubernetes on-premises e quer migrar suas aplicações em contêiner para a AWS, mantendo as mesmas ferramentas e guardando as imagens em um registro privado gerenciado. Quais serviços atendem a esses requisitos? (Selecione DUAS.)","alternativas":[{"texto":"Amazon EKS","correta":true,"porque":"Executa Kubernetes gerenciado e compatível com as ferramentas que a empresa já usa."},{"texto":"Amazon ECR","correta":true,"porque":"É o registro gerenciado e privado de imagens de contêiner da AWS."},{"texto":"Amazon ECS","correta":false,"porque":"Usa orquestração própria da AWS, não Kubernetes."},{"texto":"AWS Batch","correta":false,"porque":"Gerencia jobs em lote; não é uma plataforma Kubernetes nem um registro de imagens."},{"texto":"Amazon Lightsail","correta":false,"porque":"Oferece servidores virtuais simples a preço fixo, sem foco em Kubernetes."}],"explicacao":"EKS roda Kubernetes gerenciado; ECR guarda as imagens que ECS, EKS e Fargate executam.","servicos":["Amazon EKS","Amazon ECR"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-a-044","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa quer executar contêineres no Amazon ECS ou no Amazon EKS sem provisionar, aplicar patches ou escalar instâncias EC2. Qual opção atende a esse requisito?","alternativas":[{"texto":"AWS Lambda","correta":false,"porque":"O Lambda executa funções orientadas a eventos; não é o motor de computação de tarefas do ECS ou EKS."},{"texto":"Amazon EC2 Auto Scaling","correta":false,"porque":"Escala instâncias, mas o cliente continua gerenciando os servidores."},{"texto":"Amazon ECR","correta":false,"porque":"O ECR apenas armazena imagens de contêiner."},{"texto":"AWS Fargate","correta":true,"porque":"É o motor serverless para contêineres do ECS e do EKS: a AWS gerencia a infraestrutura."}],"explicacao":"Fargate executa contêineres sem servidores para gerenciar; o cliente define CPU e memória por tarefa ou pod.","servicos":["AWS Fargate"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-a-045","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma equipe precisa executar código de curta duração sempre que um arquivo é enviado a um bucket do Amazon S3, pagando apenas pelo tempo de execução e sem gerenciar servidores ou contêineres. Qual serviço é o MAIS adequado?","alternativas":[{"texto":"AWS Lambda","correta":true,"porque":"Executa funções acionadas por eventos (como uploads no S3) e cobra por requisição e duração."},{"texto":"AWS Fargate","correta":false,"porque":"É serverless, mas para executar contêineres; aqui o caso é uma função curta acionada por evento."},{"texto":"Amazon EC2","correta":false,"porque":"Exige provisionar e gerenciar servidores e cobra enquanto a instância estiver ativa."},{"texto":"AWS Elastic Beanstalk","correta":false,"porque":"Provisiona e mantém recursos como instâncias EC2, que continuam ativos e são cobrados mesmo sem eventos."}],"explicacao":"Lambda = funções orientadas a eventos e de curta duração (até 15 min); Fargate = contêineres sem gerenciar servidores.","servicos":["AWS Lambda"],"dificuldade":3,"fonte":"usuario-A11 (reescrita)"},{"id":"D3-a-046","dominio":3,"task":"3.3","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços fazem parte da plataforma serverless da AWS, em que o cliente não provisiona nem administra servidores? (Selecione DUAS.)","alternativas":[{"texto":"Amazon OpenSearch Service (domínio provisionado)","correta":false,"porque":"Em domínios provisionados o cliente escolhe e dimensiona as instâncias do cluster."},{"texto":"Amazon API Gateway","correta":true,"porque":"Publica e escala APIs sem que o cliente gerencie servidores."},{"texto":"Amazon EMR em clusters EC2","correta":false,"porque":"O cliente escolhe tipos e quantidades de instâncias do cluster."},{"texto":"Amazon ElastiCache (cluster provisionado)","correta":false,"porque":"Em clusters provisionados o cliente escolhe os tipos e a quantidade de nós."},{"texto":"AWS Lambda","correta":true,"porque":"Executa código sem servidores, com escalabilidade automática e cobrança por uso."}],"explicacao":"Serverless: sem servidores para gerenciar, escala automática e cobrança por uso. Exemplos: Lambda, Fargate, API Gateway, DynamoDB, S3, SQS.","servicos":["Amazon API Gateway","AWS Lambda"],"dificuldade":2,"fonte":"usuario-B28 (reescrita)"},{"id":"D3-a-047","dominio":3,"task":"3.3","tipo":"multipla","selecionar":2,"enunciado":"Para criar uma aplicação web na AWS que seja ao mesmo tempo altamente disponível e elasticamente escalável, quais serviços contribuem MAIS? (Selecione DUAS.)","alternativas":[{"texto":"Amazon EC2 Auto Scaling","correta":true,"porque":"Ajusta automaticamente o número de instâncias à demanda e substitui instâncias com falha."},{"texto":"AWS AppConfig","correta":false,"porque":"Gerencia configurações de aplicação; não escala nem distribui tráfego (e está fora do escopo da prova)."},{"texto":"Amazon SQS","correta":false,"porque":"Desacopla componentes com filas, mas não distribui tráfego web nem ajusta a capacidade."},{"texto":"Elastic Load Balancing (ELB)","correta":true,"porque":"Distribui o tráfego entre instâncias saudáveis em várias AZs."},{"texto":"AWS CloudFormation","correta":false,"porque":"Automatiza o provisionamento, mas sozinho não escala nem distribui tráfego em tempo de execução."}],"explicacao":"Auto Scaling (elasticidade) + Elastic Load Balancing (distribuição de tráfego e health checks) em várias AZs é o padrão de aplicação web resiliente.","servicos":["Amazon EC2 Auto Scaling","Elastic Load Balancing"],"dificuldade":1,"fonte":"usuario-A06"},{"id":"D3-a-048","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma aplicação web precisa distribuir requisições HTTP/HTTPS entre instâncias, roteando por caminho da URL (por exemplo, /api e /imagens) para grupos diferentes de destinos. Qual load balancer é o MAIS adequado?","alternativas":[{"texto":"Network Load Balancer","correta":false,"porque":"Opera na camada 4 (TCP/UDP) com altíssimo desempenho, sem roteamento por conteúdo HTTP."},{"texto":"Application Load Balancer","correta":true,"porque":"Opera na camada 7 e roteia por caminho, host e cabeçalhos HTTP."},{"texto":"Gateway Load Balancer","correta":false,"porque":"Serve para inserir appliances virtuais de terceiros (como firewalls) no fluxo de tráfego."},{"texto":"Amazon Route 53","correta":false,"porque":"Faz roteamento DNS, sem inspecionar o caminho da URL de cada requisição."}],"explicacao":"ALB = camada 7 (HTTP/HTTPS, regras por caminho e host); NLB = camada 4 (TCP/UDP, milhões de requisições por segundo e baixíssima latência).","servicos":["Elastic Load Balancing"],"dificuldade":3,"fonte":"kananinirav-k3#25 (reescrita)"},{"id":"D3-a-049","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma agência pequena precisa lançar rapidamente uma aplicação web em PHP sem provisionar manualmente instâncias, load balancer e Auto Scaling, mas mantendo acesso aos recursos subjacentes. Qual serviço atende a esse requisito?","alternativas":[{"texto":"Amazon ECS","correta":false,"porque":"Exige empacotar a aplicação em contêineres e configurar o serviço de orquestração."},{"texto":"AWS Elastic Beanstalk","correta":true,"porque":"Recebe o código e provisiona automaticamente capacidade, balanceamento, Auto Scaling e monitoramento de saúde."},{"texto":"Amazon EKS","correta":false,"porque":"Exige conhecimento de Kubernetes e configuração dos clusters."},{"texto":"AWS CloudFormation","correta":false,"porque":"Automatiza recursos, mas a equipe teria de escrever e manter os templates de toda a infraestrutura."}],"explicacao":"Elastic Beanstalk é PaaS: você envia o código e ele cuida do provisionamento, balanceamento, Auto Scaling e health monitoring.","servicos":["AWS Elastic Beanstalk"],"dificuldade":2,"fonte":"usuario-B04"},{"id":"D3-a-050","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma nova equipe, sem experiência com a AWS, quer colocar no ar um site WordPress simples com o MENOR esforço e um preço mensal previsível. Qual serviço é o MAIS adequado?","alternativas":[{"texto":"Amazon EC2 configurado manualmente","correta":false,"porque":"Exige escolher AMI, rede, armazenamento e segurança, o que é esforço demais para iniciantes."},{"texto":"AWS Elastic Beanstalk","correta":false,"porque":"Atende aplicações em várias linguagens, mas é mais complexo que o necessário para um WordPress simples."},{"texto":"AWS Batch","correta":false,"porque":"Executa jobs em lote, não hospeda sites."},{"texto":"Amazon Lightsail","correta":true,"porque":"Oferece servidores virtuais com blueprints prontos (como WordPress) e planos mensais de preço fixo."}],"explicacao":"Lightsail é a forma mais simples de começar na AWS: VPS com aplicativos pré-configurados e preço mensal previsível.","servicos":["Amazon Lightsail"],"dificuldade":1,"fonte":"usuario-A16"},{"id":"D3-a-051","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Engenheiros gastam muito tempo gerenciando software de agendamento para executar milhares de jobs de computação em lote. Qual serviço da AWS provisiona automaticamente a capacidade ideal e executa esses jobs?","alternativas":[{"texto":"AWS Step Functions","correta":false,"porque":"Orquestra fluxos de trabalho entre serviços, mas não dimensiona a capacidade para os jobs."},{"texto":"AWS Batch","correta":true,"porque":"Gerencia filas e agendamento de jobs e provisiona automaticamente a computação adequada a cada lote."},{"texto":"Amazon Lightsail","correta":false,"porque":"Fornece servidores virtuais simples, sem gerenciamento de jobs em lote."},{"texto":"Amazon EC2 Auto Scaling","correta":false,"porque":"Escala instâncias, mas não gerencia filas, agendamento ou dependências de jobs."}],"explicacao":"AWS Batch executa cargas de computação em lote de qualquer escala, cuidando de filas, agendamento e provisionamento.","servicos":["AWS Batch"],"dificuldade":2,"fonte":"kananinirav-k8#21 (reescrita)"},{"id":"D3-a-052","dominio":3,"task":"3.3","tipo":"unica","enunciado":"Uma empresa precisa coletar, processar e armazenar dados em seu próprio data center, por requisitos de latência e residência, usando os mesmos serviços, APIs e ferramentas da AWS. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Storage Gateway","correta":false,"porque":"Conecta o armazenamento on-premises à nuvem, mas não executa serviços de computação da AWS localmente."},{"texto":"AWS Direct Connect","correta":false,"porque":"Fornece conexão de rede dedicada, sem levar infraestrutura da AWS para o local."},{"texto":"AWS Outposts","correta":true,"porque":"Instala racks e servidores gerenciados pela AWS no data center do cliente, executando serviços como EC2, EBS e ECS."},{"texto":"AWS Local Zones","correta":false,"porque":"Ficam em instalações da AWS perto de grandes cidades, não no data center do cliente."}],"explicacao":"Outposts leva infraestrutura e serviços da AWS para o on-premises, com a mesma experiência e APIs, ideal para arquiteturas híbridas.","servicos":["AWS Outposts"],"dificuldade":3,"fonte":"usuario-B45 (reescrita)"},{"id":"D3-b-001","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Um site com milhões de leitores no mundo todo usa um banco Amazon RDS que está sobrecarregado por consultas de leitura. Qual é a MELHOR forma de aumentar a capacidade de leitura do banco?","alternativas":[{"texto":"Criar Read Replicas do Amazon RDS","correta":true,"porque":"Réplicas de leitura recebem cópias assíncronas e absorvem consultas, aliviando a instância primária."},{"texto":"Habilitar uma implantação Multi-AZ","correta":false,"porque":"A instância standby do Multi-AZ clássico serve para failover e não atende leituras."},{"texto":"Enfileirar as requisições no Amazon SQS","correta":false,"porque":"Desacopla componentes, mas não aumenta a capacidade de leitura do banco."},{"texto":"Aumentar o armazenamento provisionado da instância","correta":false,"porque":"Mais espaço em disco não distribui a carga de consultas."}],"explicacao":"Read Replicas escalam leituras horizontalmente; Multi-AZ é para alta disponibilidade, não para desempenho de leitura.","servicos":["Amazon RDS"],"dificuldade":1,"fonte":"usuario-A33"},{"id":"D3-b-002","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Qual recurso do Amazon RDS deve ser habilitado para obter alta disponibilidade com failover automático do banco de dados?","alternativas":[{"texto":"Amazon RDS Performance Insights","correta":false,"porque":"Ajuda a analisar desempenho de consultas; não oferece failover."},{"texto":"Implantação Amazon RDS Multi-AZ","correta":true,"porque":"Mantém uma standby síncrona em outra AZ e faz failover automático mantendo o mesmo endpoint."},{"texto":"Snapshots manuais do Amazon RDS","correta":false,"porque":"Permitem restaurar dados, mas a restauração é manual e gera nova instância."},{"texto":"Read Replica na mesma Zona de Disponibilidade","correta":false,"porque":"Escala leituras; a promoção é manual e, na mesma AZ, não protege contra falha da zona."}],"explicacao":"RDS Multi-AZ replica de forma síncrona para uma standby em outra AZ e faz failover automático.","servicos":["Amazon RDS"],"dificuldade":1,"fonte":"usuario-A62"},{"id":"D3-b-003","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma equipe precisa migrar um banco MySQL on-premises para o Amazon RDS for MySQL com o mínimo de tempo de inatividade. Qual serviço da AWS atende a essa tarefa?","alternativas":[{"texto":"AWS Schema Conversion Tool (AWS SCT)","correta":false,"porque":"Converte esquemas entre engines diferentes; numa migração MySQL para MySQL não há conversão a fazer."},{"texto":"AWS Glue","correta":false,"porque":"É um serviço de ETL e catálogo de dados, não de migração de bancos com replicação contínua."},{"texto":"AWS Database Migration Service (AWS DMS)","correta":true,"porque":"Migra bancos para a AWS mantendo a origem operacional, com replicação contínua (CDC)."},{"texto":"AWS Application Migration Service","correta":false,"porque":"Faz rehost de servidores inteiros, não migração para um banco gerenciado."}],"explicacao":"Migração homogênea (mesma engine) usa apenas o DMS; o SCT só é necessário quando a engine muda.","servicos":["AWS DMS"],"dificuldade":2,"fonte":"usuario-B08"},{"id":"D3-b-004","dominio":3,"task":"3.4","tipo":"multipla","selecionar":2,"enunciado":"Uma startup precisa executar um banco Microsoft SQL Server na AWS. Quais opções permitem hospedar esse banco? (Selecione DUAS.)","alternativas":[{"texto":"Amazon RDS for SQL Server","correta":true,"porque":"O RDS oferece SQL Server como engine gerenciada."},{"texto":"Amazon Neptune","correta":false,"porque":"É um banco de grafos; não executa SQL Server."},{"texto":"Amazon EC2 com SQL Server instalado","correta":true,"porque":"O cliente pode instalar e gerenciar o SQL Server em uma instância EC2 (autogerenciado)."},{"texto":"Amazon Aurora","correta":false,"porque":"O Aurora é compatível apenas com MySQL e PostgreSQL."},{"texto":"Amazon Redshift","correta":false,"porque":"É um data warehouse analítico, não uma engine SQL Server."}],"explicacao":"SQL Server roda na AWS de forma gerenciada no RDS ou autogerenciada no EC2; Aurora suporta só MySQL e PostgreSQL.","servicos":["Amazon RDS","Amazon EC2"],"dificuldade":2,"fonte":"usuario-B22 (reescrita)"},{"id":"D3-b-005","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Qual serviço da AWS executa um banco PostgreSQL gerenciado para processamento de transações online (OLTP)?","alternativas":[{"texto":"Amazon DynamoDB","correta":false,"porque":"É NoSQL chave-valor, não executa a engine PostgreSQL."},{"texto":"Amazon Athena","correta":false,"porque":"Executa consultas SQL ad hoc sobre dados no S3; não é um banco transacional."},{"texto":"Amazon EMR","correta":false,"porque":"Processa big data com Spark/Hadoop; não é banco OLTP."},{"texto":"Amazon RDS","correta":true,"porque":"O RDS oferece PostgreSQL gerenciado, adequado a cargas transacionais."}],"explicacao":"Amazon RDS é o serviço relacional gerenciado para OLTP com engines como PostgreSQL, MySQL, MariaDB, Oracle e SQL Server.","servicos":["Amazon RDS"],"dificuldade":1,"fonte":"usuario-B74"},{"id":"D3-b-006","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma empresa precisa executar um banco relacional que exige acesso ao sistema operacional e uma versão de software não suportada pelos serviços gerenciados. Qual opção da AWS atende a esse requisito?","alternativas":[{"texto":"Amazon RDS","correta":false,"porque":"É gerenciado e só suporta as engines e versões oferecidas pela AWS, com acesso limitado ao sistema operacional."},{"texto":"Amazon EC2","correta":true,"porque":"Permite instalar qualquer software de banco com controle total do sistema operacional (autogerenciado)."},{"texto":"Amazon Aurora","correta":false,"porque":"É gerenciado e limitado a compatibilidade com MySQL e PostgreSQL."},{"texto":"Amazon DynamoDB","correta":false,"porque":"É um NoSQL serverless; não executa software relacional do cliente."}],"explicacao":"Banco no EC2 dá controle total (SO, versão, configuração), mas o cliente assume patches, backups e alta disponibilidade.","servicos":["Amazon EC2"],"dificuldade":2,"fonte":"kananinirav-k7#22 (reescrita)"},{"id":"D3-b-007","dominio":3,"task":"3.4","tipo":"multipla","selecionar":2,"enunciado":"Quais são benefícios de usar o Amazon RDS em vez de instalar um banco relacional em instâncias Amazon EC2? (Selecione DUAS.)","alternativas":[{"texto":"Backups automatizados","correta":true,"porque":"O RDS faz backups automáticos com recuperação point-in-time."},{"texto":"Modelagem do esquema do banco","correta":false,"porque":"O esquema continua sendo responsabilidade do cliente."},{"texto":"Criação de índices nas tabelas","correta":false,"porque":"Índices e otimização de consultas continuam com o cliente."},{"texto":"Aplicação de patches no software do banco","correta":true,"porque":"A AWS aplica patches no SO e na engine na janela de manutenção."},{"texto":"Gestão de processos de ETL","correta":false,"porque":"ETL não é função do RDS; é tarefa de serviços como o AWS Glue."}],"explicacao":"No RDS a AWS cuida de provisionamento, patches, backups e alta disponibilidade; esquema, índices e consultas ficam com o cliente.","servicos":["Amazon RDS","Amazon EC2"],"dificuldade":2,"fonte":"kananinirav-k22#40"},{"id":"D3-b-008","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Qual banco de dados gerenciado da AWS é compatível com MySQL e PostgreSQL, aumenta o armazenamento automaticamente conforme a necessidade e mantém seis cópias dos dados em três Zonas de Disponibilidade?","alternativas":[{"texto":"Amazon RDS for MySQL","correta":false,"porque":"É compatível só com MySQL e não usa o volume de cluster com seis cópias em três AZs."},{"texto":"Amazon Redshift","correta":false,"porque":"É um data warehouse colunar para análise, não um banco transacional compatível com MySQL."},{"texto":"Amazon Aurora","correta":true,"porque":"Aurora usa armazenamento distribuído que cresce sozinho e replica seis cópias em três AZs."},{"texto":"Amazon DocumentDB","correta":false,"porque":"É um banco de documentos compatível com MongoDB."}],"explicacao":"Aurora é o banco relacional nativo da AWS, compatível com MySQL/PostgreSQL, com mais desempenho e armazenamento auto escalável.","servicos":["Amazon Aurora"],"dificuldade":2,"fonte":"kananinirav-k16#33 (reescrita)"},{"id":"D3-b-009","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Um desenvolvedor precisa de um banco NoSQL de chave-valor, serverless, com latência de milissegundos em qualquer escala e sem gerenciar servidores ou software. Qual serviço atende a esse requisito?","alternativas":[{"texto":"Amazon DynamoDB","correta":true,"porque":"É NoSQL chave-valor e documento, totalmente gerenciado e serverless, com latência de milissegundos."},{"texto":"Amazon Aurora","correta":false,"porque":"É relacional, não NoSQL chave-valor."},{"texto":"Amazon RDS","correta":false,"porque":"Oferece engines relacionais em instâncias de banco."},{"texto":"Amazon Neptune","correta":false,"porque":"É NoSQL, mas de grafos, voltado a relacionamentos."}],"explicacao":"DynamoDB é o NoSQL chave-valor serverless da AWS, escalável e com latência de milissegundos.","servicos":["Amazon DynamoDB"],"dificuldade":1,"fonte":"kananinirav-k21#1 (reescrita)"},{"id":"D3-b-010","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma aplicação de leilões usa Amazon DynamoDB e precisa reduzir a latência de leituras de milissegundos para microssegundos sem alterar a lógica de acesso aos dados. O que deve ser usado?","alternativas":[{"texto":"Amazon CloudFront","correta":false,"porque":"Faz cache de conteúdo web em edge locations, não de itens do DynamoDB."},{"texto":"Read Replicas do Amazon RDS","correta":false,"porque":"Aplicam-se a bancos RDS, não ao DynamoDB."},{"texto":"DynamoDB Accelerator (DAX)","correta":true,"porque":"É um cache em memória totalmente gerenciado e compatível com a API do DynamoDB, com leituras em microssegundos."},{"texto":"DynamoDB global tables","correta":false,"porque":"Replicam tabelas entre Regiões, mas não reduzem a latência para microssegundos."}],"explicacao":"DAX é o cache em memória nativo do DynamoDB: leituras em microssegundos com mudanças mínimas na aplicação.","servicos":["Amazon DynamoDB","DAX"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-b-011","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Qual serviço é o MAIS adequado para armazenar em memória os resultados de consultas frequentes a um banco relacional, reduzindo a carga sobre ele?","alternativas":[{"texto":"Amazon SQS","correta":false,"porque":"É uma fila de mensagens, não um cache de consultas."},{"texto":"Amazon EC2 instance store","correta":false,"porque":"É disco efêmero local de uma instância, não um cache gerenciado compartilhado."},{"texto":"Amazon S3","correta":false,"porque":"É armazenamento de objetos, sem latência de submilissegundos de um cache em memória."},{"texto":"Amazon ElastiCache","correta":true,"porque":"Oferece Redis/Valkey/Memcached gerenciados em memória, com latência de submilissegundos."}],"explicacao":"ElastiCache é o armazenamento de dados em memória gerenciado, usado como cache para aliviar bancos e acelerar aplicações.","servicos":["Amazon ElastiCache"],"dificuldade":1,"fonte":"kananinirav-k10#20"},{"id":"D3-b-012","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma empresa executa um banco MongoDB autogerenciado em instâncias EC2 e quer migrar para um serviço gerenciado compatível, com o MENOR esforço de mudança na aplicação. Qual serviço deve usar?","alternativas":[{"texto":"Amazon DynamoDB","correta":false,"porque":"É NoSQL gerenciado, mas exigiria reescrever o acesso aos dados, pois não é compatível com MongoDB."},{"texto":"Amazon DocumentDB","correta":true,"porque":"É um banco de documentos gerenciado com compatibilidade com MongoDB."},{"texto":"Amazon Neptune","correta":false,"porque":"É um banco de grafos."},{"texto":"Amazon ElastiCache","correta":false,"porque":"É um cache em memória, não um banco de documentos."}],"explicacao":"Amazon DocumentDB (compatível com MongoDB) é o banco de documentos JSON gerenciado da AWS.","servicos":["Amazon DocumentDB"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-013","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma rede social precisa armazenar e consultar rapidamente relacionamentos altamente conectados, como amigos de amigos e recomendações. Qual banco de dados da AWS é o MAIS adequado?","alternativas":[{"texto":"Amazon Redshift","correta":false,"porque":"É data warehouse para análises em lote, não para percorrer relacionamentos."},{"texto":"Amazon RDS for MySQL","correta":false,"porque":"Relacionamentos profundos exigem muitos joins, o que é ineficiente nesse cenário."},{"texto":"Amazon Neptune","correta":true,"porque":"É um banco de grafos gerenciado, otimizado para navegar relacionamentos."},{"texto":"Amazon DocumentDB","correta":false,"porque":"Armazena documentos JSON, sem otimização para consultas de grafo."}],"explicacao":"Amazon Neptune é o banco de grafos da AWS: redes sociais, recomendações, detecção de fraude e grafos de conhecimento.","servicos":["Amazon Neptune"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-b-014","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma empresa quer consolidar petabytes de dados históricos de vendas e executar consultas SQL analíticas complexas para relatórios de BI. Qual serviço da AWS é o MAIS adequado?","alternativas":[{"texto":"Amazon Redshift","correta":true,"porque":"É um data warehouse colunar gerenciado, otimizado para consultas analíticas (OLAP) em grande escala."},{"texto":"Amazon RDS for PostgreSQL","correta":false,"porque":"É otimizado para transações (OLTP), não para análise de petabytes."},{"texto":"Amazon DynamoDB","correta":false,"porque":"É NoSQL chave-valor, sem suporte a consultas SQL analíticas complexas."},{"texto":"Amazon ElastiCache","correta":false,"porque":"É cache em memória, não armazenamento analítico de longo prazo."}],"explicacao":"Redshift é o data warehouse da AWS (OLAP); RDS e Aurora atendem cargas transacionais (OLTP).","servicos":["Amazon Redshift"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-015","dominio":3,"task":"3.4","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa quer migrar um banco Oracle on-premises para o Amazon Aurora PostgreSQL. Quais ferramentas da AWS devem ser usadas? (Selecione DUAS.)","alternativas":[{"texto":"AWS Schema Conversion Tool (AWS SCT)","correta":true,"porque":"Converte o esquema e o código do Oracle para PostgreSQL, necessário em migração heterogênea."},{"texto":"AWS DataSync","correta":false,"porque":"Transfere arquivos e objetos, não converte nem replica bancos."},{"texto":"AWS Database Migration Service (AWS DMS)","correta":true,"porque":"Move os dados da origem Oracle para o Aurora, com replicação contínua."},{"texto":"AWS Application Migration Service","correta":false,"porque":"Replica servidores inteiros (rehost), sem trocar a engine do banco."},{"texto":"AWS Storage Gateway","correta":false,"porque":"Integra armazenamento on-premises à nuvem, não migra bancos."}],"explicacao":"Migração heterogênea (engines diferentes): SCT converte o esquema e DMS migra os dados.","servicos":["AWS DMS","AWS SCT"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-b-016","dominio":3,"task":"3.4","tipo":"unica","enunciado":"Uma empresa usa Amazon RDS na Região us-east-1 e quer oferecer leituras de baixa latência a usuários na Europa, além de ter uma cópia dos dados que possa ser promovida em caso de falha da Região. Qual recurso atende a esses requisitos?","alternativas":[{"texto":"Implantação Multi-AZ","correta":false,"porque":"Protege contra falha de AZ dentro da mesma Região e a standby não atende leituras."},{"texto":"Snapshots automáticos","correta":false,"porque":"Ficam na Região de origem por padrão e não atendem leituras."},{"texto":"Provisioned IOPS","correta":false,"porque":"Melhora o desempenho de armazenamento, sem criar cópia em outra Região."},{"texto":"Read Replica entre Regiões","correta":true,"porque":"Atende leituras perto dos usuários europeus e pode ser promovida a primária em um desastre regional."}],"explicacao":"Read Replicas entre Regiões servem a leituras globais e à recuperação de desastres; Multi-AZ é alta disponibilidade dentro de uma Região.","servicos":["Amazon RDS"],"dificuldade":3,"fonte":"kananinirav-k16#7 (reescrita)"},{"id":"D3-b-017","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um cliente quer reduzir custos do Amazon S3 com dados acessados com pouca frequência. Os dados são uma cópia secundária que pode ser recriada, mas as leituras exigem latência de milissegundos. Qual classe de armazenamento é a MENOS cara para esse caso?","alternativas":[{"texto":"S3 Glacier Deep Archive","correta":false,"porque":"É a mais barata, mas a recuperação leva horas."},{"texto":"S3 Standard","correta":false,"porque":"Atende a latência, mas custa mais que as classes IA para dados pouco acessados."},{"texto":"S3 One Zone-IA","correta":true,"porque":"Armazena em uma só AZ, custa menos que o Standard-IA e mantém acesso em milissegundos; serve para dados recriáveis."},{"texto":"S3 Glacier Flexible Retrieval","correta":false,"porque":"A recuperação leva de minutos a horas, sem leitura em milissegundos."}],"explicacao":"One Zone-IA é a opção de acesso infrequente mais barata com leitura imediata, para dados que podem ser reproduzidos se a AZ for perdida.","servicos":["Amazon S3"],"dificuldade":3,"fonte":"usuario-A02"},{"id":"D3-b-018","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Qual opção de armazenamento oferece armazenamento em bloco temporário, fisicamente ligado ao host, com leitura e gravação muito rápidas para uma instância EC2?","alternativas":[{"texto":"EBS Provisioned IOPS SSD (io2)","correta":false,"porque":"É rápido, mas é armazenamento persistente acessado pela rede, não temporário."},{"texto":"Amazon EFS","correta":false,"porque":"É armazenamento de arquivos compartilhado e persistente."},{"texto":"EBS Throughput Optimized HDD (st1)","correta":false,"porque":"É HDD persistente para throughput sequencial, não temporário."},{"texto":"Instance store","correta":true,"porque":"Discos locais do host: muito rápidos, mas efêmeros, perdidos ao parar ou encerrar a instância."}],"explicacao":"Instance store é bloco efêmero de alto desempenho, ideal para cache, buffers e dados temporários.","servicos":["Amazon EC2"],"dificuldade":1,"fonte":"usuario-A08"},{"id":"D3-b-019","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma startup hospedou um site estático no Amazon S3, mas os visitantes recebem erros de acesso negado. O que deve ser ajustado para resolver o problema?","alternativas":[{"texto":"Corrigir a bucket policy para permitir leitura pública dos objetos","correta":true,"porque":"Um site estático exige permissão de leitura para os visitantes, concedida pela bucket policy."},{"texto":"Habilitar a S3 Cross-Region Replication","correta":false,"porque":"Replica objetos para outra Região, sem alterar permissões de acesso."},{"texto":"Desabilitar a criptografia do bucket","correta":false,"porque":"A criptografia padrão (SSE-S3) é transparente e não causa acesso negado."},{"texto":"Ativar o S3 Versioning","correta":false,"porque":"Mantém versões de objetos, sem relação com permissões."}],"explicacao":"No S3, o acesso é controlado por bucket policies, Block Public Access e IAM; site público exige leitura liberada na política.","servicos":["Amazon S3"],"dificuldade":1,"fonte":"usuario-A10"},{"id":"D3-b-020","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa grava vídeos grandes no S3 Standard. Após o upload, cada vídeo é baixado uma única vez pelo cliente e raramente volta a ser lido, mas precisa estar disponível em milissegundos quando solicitado. Qual mudança reduz MAIS o custo de armazenamento?","alternativas":[{"texto":"Criar uma lifecycle policy que mova os vídeos para S3 Glacier Flexible Retrieval","correta":false,"porque":"A recuperação levaria minutos a horas, o que viola o requisito de milissegundos."},{"texto":"Criar uma lifecycle policy que mova os vídeos para S3 Standard-IA após 30 dias","correta":false,"porque":"Reduz custo, mas os vídeos ficam 30 dias no Standard antes da transição."},{"texto":"Gravar os vídeos diretamente na classe S3 Standard-IA","correta":true,"porque":"Evita o período no Standard e já paga a tarifa de acesso infrequente com leitura em milissegundos."},{"texto":"Habilitar o S3 Versioning no bucket","correta":false,"porque":"Versionamento aumenta o armazenamento ao reter versões antigas."}],"explicacao":"Se o padrão de acesso infrequente já é conhecido no upload, gravar direto em Standard-IA economiza mais que esperar a transição por lifecycle.","servicos":["Amazon S3"],"dificuldade":3,"fonte":"usuario-A21 (reescrita)"},{"id":"D3-b-021","dominio":3,"task":"3.6","tipo":"multipla","selecionar":2,"enunciado":"Quais alternativas descrevem corretamente o Amazon S3? (Selecione DUAS.)","alternativas":[{"texto":"Um dispositivo de borda para transferência de grandes volumes de dados","correta":false,"porque":"Descreve o AWS Snowball Edge."},{"texto":"Um sistema de armazenamento de objetos altamente durável","correta":true,"porque":"O S3 armazena objetos com durabilidade de 11 noves (99,999999999%)."},{"texto":"Um sistema de arquivos compartilhado compatível com Windows","correta":false,"porque":"Descreve o Amazon FSx for Windows File Server."},{"texto":"Um serviço de armazenamento com capacidade praticamente ilimitada","correta":true,"porque":"Não há limite para o volume total de dados armazenados em um bucket."},{"texto":"Um volume em bloco anexado a uma instância EC2","correta":false,"porque":"Descreve o Amazon EBS."}],"explicacao":"Amazon S3 é armazenamento de objetos durável e escalável sem limite prático de capacidade.","servicos":["Amazon S3"],"dificuldade":1,"fonte":"usuario-A22"},{"id":"D3-b-022","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um estúdio envia diariamente para o Amazon S3 gravações 4K de vários gigabytes cada. O que o estúdio deve usar para MINIMIZAR o tempo de upload de cada arquivo?","alternativas":[{"texto":"A API BatchWriteItem","correta":false,"porque":"É uma API do DynamoDB, não do S3."},{"texto":"A classe S3 Intelligent-Tiering","correta":false,"porque":"Otimiza custo de armazenamento, não velocidade de upload."},{"texto":"Cross-Origin Resource Sharing (CORS) no bucket","correta":false,"porque":"Controla acesso entre domínios no navegador, sem efeito na velocidade."},{"texto":"S3 Multipart Upload","correta":true,"porque":"Divide o arquivo em partes enviadas em paralelo, acelerando uploads grandes e permitindo reenviar só partes com falha."}],"explicacao":"Multipart Upload é recomendado para objetos grandes (acima de ~100 MB) e paraleliza o envio.","servicos":["Amazon S3"],"dificuldade":2,"fonte":"usuario-A39"},{"id":"D3-b-023","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma regulamentação exige que todos os datasets de um instituto, armazenados no Amazon S3, sejam mantidos também em uma Região da AWS distante. Qual é a forma MAIS eficiente de atender a esse requisito?","alternativas":[{"texto":"Executar um job noturno em EC2 para copiar os novos objetos","correta":false,"porque":"Funciona, mas exige código e servidor para manter, com atraso de até um dia."},{"texto":"Habilitar a S3 Cross-Region Replication (CRR)","correta":true,"porque":"Replica automaticamente cada novo objeto para um bucket em outra Região, sem código."},{"texto":"Habilitar a S3 Same-Region Replication (SRR)","correta":false,"porque":"Replica dentro da mesma Região e não atende ao requisito geográfico."},{"texto":"Criar uma função Lambda que copie cada objeto enviado","correta":false,"porque":"Resolve com código personalizado; é menos eficiente que um recurso nativo."}],"explicacao":"CRR replica objetos de forma automática e assíncrona entre Regiões (exige versionamento nos dois buckets).","servicos":["Amazon S3"],"dificuldade":2,"fonte":"usuario-A42"},{"id":"D3-b-024","dominio":3,"task":"3.6","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS são adequados para armazenar dados que mudam rapidamente e exigem baixa latência de leitura e gravação? (Selecione DUAS.)","alternativas":[{"texto":"Amazon S3 Glacier Deep Archive","correta":false,"porque":"É arquivamento de longo prazo com recuperação em horas."},{"texto":"Amazon EBS","correta":true,"porque":"Volumes em bloco de baixa latência, ideais para dados alterados com frequência, como bancos e sistemas de arquivos."},{"texto":"AWS Glue","correta":false,"porque":"É serviço de ETL e catálogo de dados, não armazenamento."},{"texto":"Amazon RDS","correta":true,"porque":"Bancos relacionais suportam leituras e gravações frequentes com baixa latência."},{"texto":"AWS Storage Gateway Tape Gateway","correta":false,"porque":"Fitas virtuais servem a backup e arquivamento, não a dados de mudança rápida."}],"explicacao":"Dados transacionais e voláteis pedem armazenamento em bloco (EBS) ou bancos de dados; arquivamento e fitas servem a dados frios.","servicos":["Amazon EBS","Amazon RDS"],"dificuldade":2,"fonte":"usuario-A44"},{"id":"D3-b-025","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Qual recurso move automaticamente objetos de um bucket do Amazon S3 para uma classe de armazenamento MAIS barata após um número definido de dias, e pode expirá-los depois?","alternativas":[{"texto":"Uma access control list (ACL) do S3","correta":false,"porque":"Concede permissões a objetos e buckets; não move dados."},{"texto":"AWS Transfer Family","correta":false,"porque":"Fornece SFTP/FTPS para dentro do S3; não gerencia classes."},{"texto":"Uma S3 Lifecycle policy","correta":true,"porque":"Define transições entre classes e expiração de objetos com base na idade."},{"texto":"AWS Storage Gateway","correta":false,"porque":"Conecta armazenamento on-premises à nuvem; não faz transição entre classes."}],"explicacao":"Lifecycle policies automatizam transições (ex.: Standard → Standard-IA → Glacier) e exclusões com base na idade dos objetos.","servicos":["Amazon S3"],"dificuldade":1,"fonte":"usuario-A55"},{"id":"D3-b-026","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um cluster de processamento de logs em EC2 lê grandes arquivos de forma sequencial e com frequência. A empresa quer volumes Amazon EBS de bom throughput com o MENOR custo. Qual tipo de volume deve escolher?","alternativas":[{"texto":"Throughput Optimized HDD (st1)","correta":true,"porque":"HDD de baixo custo, projetado para cargas frequentes e sequenciais que exigem throughput, como big data e logs."},{"texto":"Cold HDD (sc1)","correta":false,"porque":"É o mais barato, mas para dados acessados raramente e com throughput menor."},{"texto":"Provisioned IOPS SSD (io2)","correta":false,"porque":"Atende cargas de IOPS críticas, como bancos de dados, com custo alto."},{"texto":"General Purpose SSD (gp3)","correta":false,"porque":"É versátil, mas custa mais por GB que o st1 para throughput sequencial."}],"explicacao":"EBS: gp3 (uso geral SSD), io2 (IOPS alto e crítico), st1 (HDD para throughput frequente) e sc1 (HDD frio, mais barato).","servicos":["Amazon EBS"],"dificuldade":3,"fonte":"usuario-B01 (reescrita)"},{"id":"D3-b-027","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Usuários em outros continentes precisam enviar e baixar objetos de um bucket do Amazon S3 específico MAIS rapidamente pela internet pública. Qual recurso do S3 atende a esse objetivo?","alternativas":[{"texto":"Amazon Route 53","correta":false,"porque":"Resolve nomes DNS; não acelera transferências de objetos."},{"texto":"S3 Transfer Acceleration","correta":true,"porque":"Encaminha as transferências por edge locations do CloudFront e pela rede global da AWS."},{"texto":"Elastic Load Balancing","correta":false,"porque":"Distribui tráfego entre destinos como EC2; não se aplica a buckets S3."},{"texto":"S3 Same-Region Replication","correta":false,"porque":"Copia objetos na mesma Região, sem reduzir a distância até usuários remotos."}],"explicacao":"S3 Transfer Acceleration usa edge locations para acelerar transferências de longa distância de e para um bucket.","servicos":["Amazon S3"],"dificuldade":2,"fonte":"usuario-B02"},{"id":"D3-b-028","dominio":3,"task":"3.6","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS fornecem armazenamento em nível de bloco? (Selecione DUAS.)","alternativas":[{"texto":"Amazon Elastic Block Store (EBS)","correta":true,"porque":"Fornece volumes em bloco persistentes para instâncias EC2."},{"texto":"Amazon Elastic File System (EFS)","correta":false,"porque":"É armazenamento de arquivos (NFS)."},{"texto":"Amazon S3","correta":false,"porque":"É armazenamento de objetos."},{"texto":"Amazon FSx for Windows File Server","correta":false,"porque":"É armazenamento de arquivos via SMB."},{"texto":"Amazon EC2 instance store","correta":true,"porque":"Fornece armazenamento em bloco temporário em discos do host."}],"explicacao":"Bloco: EBS e instance store. Arquivo: EFS e FSx. Objeto: S3.","servicos":["Amazon EBS","Amazon EC2"],"dificuldade":1,"fonte":"usuario-B03"},{"id":"D3-b-029","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa precisa transferir dezenas de terabytes de arquivos de um servidor NFS on-premises para o Amazon S3 pela rede, de forma automatizada, com verificação de integridade e agendamento. Qual serviço é o MAIS adequado?","alternativas":[{"texto":"AWS Site-to-Site VPN","correta":false,"porque":"Cria um túnel criptografado entre as redes, mas não automatiza nem gerencia a cópia de arquivos."},{"texto":"AWS Storage Gateway (File Gateway)","correta":false,"porque":"Oferece acesso híbrido contínuo a arquivos com cache local; não é a ferramenta de migração em massa agendada."},{"texto":"AWS Transit Gateway","correta":false,"porque":"Interconecta VPCs e redes on-premises; não transfere dados."},{"texto":"AWS DataSync","correta":true,"porque":"Automatiza e acelera a transferência online de arquivos (NFS, SMB, HDFS) para S3, EFS e FSx, com verificação de integridade e agendamento."}],"explicacao":"Transferência online em massa de arquivos para a AWS = DataSync. Observação: o AWS Snowball Edge não está mais disponível para novos clientes; a AWS indica DataSync (online) ou AWS Data Transfer Terminal (física).","servicos":["AWS DataSync"],"dificuldade":2,"fonte":"usuario-B07 (reescrita)"},{"id":"D3-b-030","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Qual classe de armazenamento do Amazon S3 é a MELHOR para dados com padrão de acesso desconhecido ou que muda ao longo do tempo?","alternativas":[{"texto":"S3 Intelligent-Tiering","correta":true,"porque":"Move objetos automaticamente entre camadas de acesso conforme o uso, sem taxa de recuperação."},{"texto":"S3 Glacier Flexible Retrieval","correta":false,"porque":"É para arquivamento, com recuperação em minutos a horas."},{"texto":"S3 Standard","correta":false,"porque":"É para acesso frequente; cobra caro por dados que deixam de ser acessados."},{"texto":"S3 Standard-IA","correta":false,"porque":"Cobra recuperação por GB e só compensa para dados sabidamente infrequentes."}],"explicacao":"Intelligent-Tiering otimiza custo automaticamente quando o padrão de acesso é imprevisível.","servicos":["Amazon S3"],"dificuldade":1,"fonte":"kananinirav-k2#4"},{"id":"D3-b-031","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um banco precisa reter registros por 10 anos para conformidade. Os dados quase nunca são lidos e, quando necessário, podem ser recuperados em até 48 horas. Qual classe do Amazon S3 tem o MENOR custo de armazenamento?","alternativas":[{"texto":"S3 Glacier Instant Retrieval","correta":false,"porque":"Oferece recuperação em milissegundos, custando mais que o necessário."},{"texto":"S3 Glacier Flexible Retrieval","correta":false,"porque":"É barata, mas o armazenamento custa mais que o Deep Archive."},{"texto":"S3 Glacier Deep Archive","correta":true,"porque":"É a classe mais barata do S3, com recuperação em até 12 horas (ou 48 h no modo em lote)."},{"texto":"S3 One Zone-IA","correta":false,"porque":"É para acesso infrequente com leitura imediata, mais cara e com menor resiliência."}],"explicacao":"Deep Archive é o menor custo para retenção de longo prazo (7–10+ anos) quando horas de espera são aceitáveis.","servicos":["Amazon S3"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-032","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um hospital arquiva imagens médicas acessadas cerca de uma vez por trimestre, mas que devem abrir em milissegundos quando um médico as solicita. Qual classe do Amazon S3 é a MAIS econômica?","alternativas":[{"texto":"S3 Glacier Deep Archive","correta":false,"porque":"A recuperação leva horas."},{"texto":"S3 Glacier Instant Retrieval","correta":true,"porque":"É arquivamento de baixo custo para dados raramente acessados com recuperação em milissegundos."},{"texto":"S3 Glacier Flexible Retrieval","correta":false,"porque":"A recuperação leva de minutos a horas."},{"texto":"S3 Standard","correta":false,"porque":"Atende a latência, mas custa mais para dados acessados uma vez por trimestre."}],"explicacao":"Glacier Instant Retrieval: dados de arquivo acessados ~1 vez por trimestre que precisam de leitura imediata.","servicos":["Amazon S3"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-b-033","dominio":3,"task":"3.6","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa quer proteger objetos críticos do Amazon S3 contra exclusão ou sobrescrita acidental. Quais recursos ajudam nisso? (Selecione DUAS.)","alternativas":[{"texto":"S3 Versioning","correta":true,"porque":"Mantém versões anteriores, permitindo recuperar objetos excluídos ou sobrescritos."},{"texto":"S3 Lifecycle policies","correta":false,"porque":"Movem ou expiram objetos; podem até excluir dados, não protegê-los."},{"texto":"MFA Delete","correta":true,"porque":"Exige MFA para excluir versões permanentemente ou desligar o versionamento."},{"texto":"S3 Transfer Acceleration","correta":false,"porque":"Acelera transferências; não protege contra exclusão."},{"texto":"S3 Intelligent-Tiering","correta":false,"porque":"Otimiza custos por camada de acesso; não protege objetos."}],"explicacao":"Versionamento preserva versões anteriores e MFA Delete adiciona proteção extra contra exclusões permanentes.","servicos":["Amazon S3"],"dificuldade":2,"fonte":"kananinirav-k7#33 (reescrita)"},{"id":"D3-b-034","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Um administrador precisa usar os dados de um volume Amazon EBS em uma instância EC2 de outra Zona de Disponibilidade. Qual é a abordagem correta?","alternativas":[{"texto":"Desanexar o volume e anexá-lo diretamente à instância na outra AZ","correta":false,"porque":"Volumes EBS são zonais e só podem ser anexados a instâncias da mesma AZ."},{"texto":"Converter o volume em instance store","correta":false,"porque":"Não há essa conversão; instance store é efêmero e ligado ao host."},{"texto":"Habilitar a S3 Cross-Region Replication no volume","correta":false,"porque":"CRR se aplica a buckets S3, não a volumes EBS."},{"texto":"Criar um snapshot e restaurar um novo volume na AZ de destino","correta":true,"porque":"Snapshots são incrementais, ficam armazenados de forma regional e permitem criar volumes em qualquer AZ."}],"explicacao":"EBS é zonal; snapshots servem de backup e permitem mover dados entre AZs (e copiar entre Regiões).","servicos":["Amazon EBS"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-035","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Várias instâncias EC2 Linux, em diferentes Zonas de Disponibilidade, precisam acessar simultaneamente o mesmo sistema de arquivos, que deve crescer automaticamente. Qual serviço atende a esse requisito?","alternativas":[{"texto":"Amazon EBS","correta":false,"porque":"Volumes EBS são zonais e, em geral, anexados a uma única instância."},{"texto":"Amazon EFS","correta":true,"porque":"Sistema de arquivos NFS gerenciado e elástico, montável por muitas instâncias Linux em várias AZs."},{"texto":"Amazon S3","correta":false,"porque":"É armazenamento de objetos, não um sistema de arquivos montável nativamente."},{"texto":"Instance store","correta":false,"porque":"É local e efêmero, ligado a uma única instância."}],"explicacao":"Amazon EFS é o sistema de arquivos compartilhado, elástico e multi-AZ para cargas Linux.","servicos":["Amazon EFS"],"dificuldade":2,"fonte":"kananinirav-k20#27 (reescrita)"},{"id":"D3-b-036","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa migra servidores Windows que usam compartilhamentos de arquivos SMB integrados ao Microsoft Active Directory. Qual serviço gerenciado da AWS deve ser usado para esses compartilhamentos?","alternativas":[{"texto":"Amazon EFS","correta":false,"porque":"Usa o protocolo NFS e é voltado a cargas Linux."},{"texto":"Amazon FSx for Lustre","correta":false,"porque":"É um sistema de arquivos para computação de alto desempenho, não compartilhamentos Windows com AD."},{"texto":"Amazon FSx for Windows File Server","correta":true,"porque":"Fornece compartilhamentos SMB nativos do Windows, integrados ao Active Directory."},{"texto":"Amazon S3","correta":false,"porque":"É armazenamento de objetos, sem compartilhamento SMB nativo."}],"explicacao":"FSx for Windows File Server = sistema de arquivos Windows gerenciado (SMB, NTFS, AD); EFS = NFS para Linux.","servicos":["Amazon FSx"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-037","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa usa storage NAS NetApp on-premises e quer levar seus dados para a AWS mantendo os recursos do ONTAP, como snapshots e acesso por NFS e SMB. Qual serviço deve escolher?","alternativas":[{"texto":"Amazon FSx for NetApp ONTAP","correta":true,"porque":"Oferece sistemas de arquivos ONTAP totalmente gerenciados, com NFS, SMB e iSCSI."},{"texto":"Amazon EFS","correta":false,"porque":"Oferece só NFS, sem os recursos de gerenciamento de dados do ONTAP."},{"texto":"AWS Storage Gateway File Gateway","correta":false,"porque":"Expõe buckets S3 como compartilhamentos on-premises; não executa ONTAP."},{"texto":"Amazon EBS","correta":false,"porque":"É armazenamento em bloco para uma instância, não um NAS compartilhado."}],"explicacao":"A família FSx oferece sistemas de arquivos de terceiros gerenciados: Windows File Server, NetApp ONTAP, OpenZFS e Lustre.","servicos":["Amazon FSx"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-b-038","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Aplicações on-premises precisam usar armazenamento na nuvem AWS por meio de protocolos padrão de arquivo, com cache local para acesso de baixa latência aos dados mais usados. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Direct Connect","correta":false,"porque":"É uma conexão de rede dedicada, não um serviço de armazenamento."},{"texto":"AWS Snowball Edge","correta":false,"porque":"Faz transferência offline em lote, sem integração contínua por protocolo de arquivo."},{"texto":"Amazon EFS","correta":false,"porque":"É um sistema de arquivos na nuvem sem cache local híbrido gerenciado."},{"texto":"AWS Storage Gateway","correta":true,"porque":"Serviço híbrido (File, Volume e Tape Gateway) que expõe armazenamento AWS on-premises com cache local."}],"explicacao":"Storage Gateway conecta o ambiente on-premises ao armazenamento da AWS com cache local: file, volume e tape gateway.","servicos":["AWS Storage Gateway"],"dificuldade":2,"fonte":"kananinirav-k16#14 (reescrita)"},{"id":"D3-b-039","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa quer definir políticas centralizadas de backup e retenção para volumes EBS, bancos RDS, tabelas DynamoDB e sistemas de arquivos EFS em várias contas. Qual serviço deve usar?","alternativas":[{"texto":"AWS Elastic Disaster Recovery","correta":false,"porque":"Replica servidores para recuperação rápida, não gerencia políticas de backup de vários serviços."},{"texto":"AWS Backup","correta":true,"porque":"Centraliza e automatiza backups de vários serviços AWS com planos de backup e retenção, inclusive entre contas."},{"texto":"S3 Lifecycle policies","correta":false,"porque":"Gerenciam classes e expiração de objetos S3 apenas."},{"texto":"AWS Storage Gateway","correta":false,"porque":"Integra armazenamento on-premises à nuvem; não orquestra backups de serviços AWS."}],"explicacao":"AWS Backup é o serviço de backup centralizado e baseado em políticas para EBS, RDS, DynamoDB, EFS, FSx, EC2 e outros.","servicos":["AWS Backup"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-b-040","dominio":3,"task":"3.6","tipo":"unica","enunciado":"Uma empresa quer replicar continuamente seus servidores on-premises para a AWS, de forma a recuperá-los em minutos após um desastre e com baixo custo enquanto não há falha. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Backup","correta":false,"porque":"Faz backups agendados, sem replicação contínua de servidores para recuperação em minutos."},{"texto":"Amazon S3 Cross-Region Replication","correta":false,"porque":"Replica objetos S3, não servidores inteiros."},{"texto":"AWS Elastic Disaster Recovery","correta":true,"porque":"Replica servidores em nível de bloco para uma área de staging de baixo custo e os inicia rapidamente na AWS."},{"texto":"AWS Database Migration Service","correta":false,"porque":"Migra e replica bancos de dados, não servidores completos."}],"explicacao":"Elastic Disaster Recovery (AWS DRS) oferece RPO de segundos e RTO de minutos para servidores físicos, virtuais ou na nuvem.","servicos":["AWS Elastic Disaster Recovery"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-001","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual serviço permite provisionar uma rede virtual logicamente isolada na AWS, com faixa de IPs e subnets próprias, onde as cargas de trabalho são executadas?","alternativas":[{"texto":"Amazon VPC","correta":true,"porque":"Cria uma rede virtual isolada na qual o cliente define a faixa CIDR, as subnets, as route tables e os gateways."},{"texto":"Internet Gateway","correta":false,"porque":"É um componente anexado à VPC para comunicação com a internet; não é a rede em si."},{"texto":"Amazon EC2","correta":false,"porque":"Fornece servidores virtuais que rodam dentro de uma VPC, mas não cria a rede."},{"texto":"AWS Elastic Beanstalk","correta":false,"porque":"Implanta e gerencia aplicações; usa uma VPC, mas não é o serviço que a define."}],"explicacao":"A Amazon VPC é a rede privada virtual do cliente na AWS: ele controla endereçamento, subnets, roteamento e gateways.","servicos":["Amazon VPC"],"dificuldade":1,"fonte":"usuario-A28"},{"id":"D3-c-002","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual componente permite que instâncias EC2 em uma subnet pública se comuniquem com a internet?","alternativas":[{"texto":"NAT Gateway","correta":false,"porque":"Dá apenas saída à internet para instâncias em subnets privadas e depende ele próprio de um Internet Gateway."},{"texto":"Internet Gateway","correta":true,"porque":"Anexado à VPC e referenciado na route table, permite tráfego de entrada e saída entre a subnet pública e a internet."},{"texto":"VPC endpoint","correta":false,"porque":"Conecta a VPC de forma privada a serviços da AWS, sem dar acesso à internet."},{"texto":"Amazon API Gateway","correta":false,"porque":"Cria e publica APIs; não é um componente de roteamento da VPC."}],"explicacao":"Uma subnet é pública quando sua route table tem rota para um Internet Gateway; é ele que liga a VPC à internet.","servicos":["Amazon VPC","Internet Gateway"],"dificuldade":1,"fonte":"usuario-B24"},{"id":"D3-c-003","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Instâncias EC2 em uma subnet privada precisam baixar atualizações da internet, mas não podem receber conexões iniciadas de fora. O que deve ser adicionado à arquitetura?","alternativas":[{"texto":"Uma rota da subnet privada direto para o Internet Gateway","correta":false,"porque":"Tornaria a subnet pública e, com IPs públicos, exporia as instâncias a conexões de entrada."},{"texto":"Uma conexão de VPC peering","correta":false,"porque":"Liga duas VPCs por IPs privados; não fornece acesso à internet."},{"texto":"Um NAT Gateway em uma subnet pública","correta":true,"porque":"Permite que instâncias privadas iniciem conexões de saída para a internet e bloqueia conexões iniciadas de fora."},{"texto":"Um Virtual Private Gateway","correta":false,"porque":"É o ponto de terminação de VPN na VPC; não dá acesso à internet."}],"explicacao":"NAT Gateway: saída para a internet a partir de subnets privadas, sem permitir entrada. A route table da subnet privada aponta para ele.","servicos":["NAT Gateway","Amazon VPC"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-004","dominio":3,"task":"3.5","tipo":"multipla","selecionar":2,"enunciado":"Quais afirmações sobre Security Groups e network ACLs são verdadeiras? (Selecione DUAS.)","alternativas":[{"texto":"Uma network ACL é stateful: o tráfego de retorno de uma requisição de saída é permitido automaticamente.","correta":false,"porque":"A network ACL é stateless: o tráfego de retorno precisa de regra explícita."},{"texto":"Um Security Group contém regras numeradas e as avalia em ordem numérica.","correta":false,"porque":"O Security Group avalia todas as regras em conjunto antes de decidir; regras numeradas são da network ACL."},{"texto":"Uma network ACL contém regras numeradas e as avalia em ordem para permitir ou negar o tráfego.","correta":true,"porque":"A NACL processa as regras da menor para a maior numeração e aplica a primeira que corresponder."},{"texto":"Um Security Group é stateless: o tráfego de retorno exige uma regra de allow própria.","correta":false,"porque":"O Security Group é stateful, então o retorno não precisa de regra."},{"texto":"Um Security Group é stateful: o tráfego de retorno de uma requisição permitida é liberado automaticamente.","correta":true,"porque":"O Security Group rastreia o estado da conexão e libera a resposta automaticamente."}],"explicacao":"Security Group: nível de instância, stateful, só regras de allow. Network ACL: nível de subnet, stateless, regras numeradas de allow e deny.","servicos":["Security Group","Network ACL"],"dificuldade":2,"fonte":"usuario-A57"},{"id":"D3-c-005","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual controle de segurança da Amazon VPC filtra o tráfego no nível da subnet e aceita tanto regras de permissão (allow) quanto de negação (deny)?","alternativas":[{"texto":"Security Group","correta":false,"porque":"Atua no nível da instância (interface de rede) e só aceita regras de allow."},{"texto":"AWS Config","correta":false,"porque":"Registra e avalia configurações de recursos; não filtra tráfego."},{"texto":"Políticas do IAM","correta":false,"porque":"Controlam permissões de chamadas às APIs da AWS, não tráfego de rede."},{"texto":"Network ACL","correta":true,"porque":"É o firewall stateless associado à subnet, com regras numeradas de allow e deny; útil, por exemplo, para bloquear um IP específico."}],"explicacao":"A network ACL é a camada de proteção da subnet; o Security Group protege a instância. Bloquear explicitamente um IP só é possível com NACL.","servicos":["Network ACL","Security Group"],"dificuldade":2,"fonte":"usuario-B33 (reescrita)"},{"id":"D3-c-006","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual recurso conecta duas VPCs para que as instâncias se comuniquem usando endereços IP privados?","alternativas":[{"texto":"VPC endpoint","correta":false,"porque":"Conecta a VPC de forma privada a serviços da AWS ou a serviços via PrivateLink, não duas VPCs inteiras."},{"texto":"NAT Gateway","correta":false,"porque":"Fornece saída à internet para subnets privadas; não liga VPCs."},{"texto":"VPC peering","correta":true,"porque":"Cria uma conexão de rede ponto a ponto entre duas VPCs (mesma conta, outra conta ou outra Região) usando IPs privados."},{"texto":"AWS Direct Connect","correta":false,"porque":"Liga um ambiente on-premises à AWS por link dedicado, não duas VPCs entre si."}],"explicacao":"VPC peering liga duas VPCs com IPs privados; não é transitivo, por isso muitas VPCs pedem Transit Gateway.","servicos":["VPC peering"],"dificuldade":1,"fonte":"usuario-B62"},{"id":"D3-c-007","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Uma empresa tem centenas de VPCs em várias contas e quer interligá-las, e também à rede on-premises, por um hub central, sem gerenciar dezenas de conexões ponto a ponto. Qual serviço atende?","alternativas":[{"texto":"AWS Transit Gateway","correta":true,"porque":"Funciona como hub regional que conecta milhares de VPCs e redes on-premises, simplificando o roteamento."},{"texto":"VPC peering","correta":false,"porque":"É ponto a ponto e não transitivo: centenas de VPCs exigiriam uma malha enorme de conexões."},{"texto":"AWS Direct Connect","correta":false,"porque":"Fornece link dedicado com o on-premises, mas não interliga VPCs entre si."},{"texto":"AWS Global Accelerator","correta":false,"porque":"Melhora o caminho de usuários da internet até aplicações; não conecta VPCs."}],"explicacao":"Transit Gateway é o modelo hub-and-spoke para conectar muitas VPCs e redes on-premises em escala.","servicos":["AWS Transit Gateway"],"dificuldade":2,"fonte":"kananinirav-k21#37 (reescrita)"},{"id":"D3-c-008","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Aplicações em uma subnet privada precisam acessar o Amazon S3 e outros serviços da AWS sem que o tráfego passe pela internet e sem Internet Gateway ou NAT Gateway. O que deve ser usado?","alternativas":[{"texto":"AWS Direct Connect","correta":false,"porque":"Liga o data center on-premises à AWS; não resolve o acesso privado a partir da VPC."},{"texto":"VPC peering","correta":false,"porque":"Liga VPCs entre si; não dá acesso privado aos endpoints dos serviços da AWS."},{"texto":"Um Elastic IP nas instâncias","correta":false,"porque":"É um IP público: o acesso continuaria pela internet e exigiria Internet Gateway."},{"texto":"VPC endpoints","correta":true,"porque":"Gateway endpoints (S3, DynamoDB) e interface endpoints (AWS PrivateLink) mantêm o tráfego na rede da AWS."}],"explicacao":"VPC endpoints, inclusive os baseados em AWS PrivateLink, dão acesso privado a serviços da AWS e de terceiros sem expor o tráfego à internet.","servicos":["VPC endpoints","AWS PrivateLink"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-009","dominio":3,"task":"3.5","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços estabelecem um link de rede entre um data center on-premises e recursos hospedados na AWS? (Selecione DUAS.)","alternativas":[{"texto":"Amazon Connect","correta":false,"porque":"É um serviço de contact center em nuvem, apesar do nome."},{"texto":"AWS Directory Service","correta":false,"porque":"Fornece Active Directory gerenciado; não cria conexão de rede."},{"texto":"AWS Direct Connect","correta":true,"porque":"Cria uma conexão física dedicada e privada entre o on-premises e a AWS."},{"texto":"AWS Site-to-Site VPN","correta":true,"porque":"Cria túneis IPsec criptografados pela internet entre a rede local e a VPC."},{"texto":"Amazon Route 53","correta":false,"porque":"É um serviço de DNS; resolve nomes, não cria links de rede."}],"explicacao":"Conectividade híbrida: Site-to-Site VPN (rápida, pela internet, criptografada) e Direct Connect (dedicada, privada, latência consistente).","servicos":["AWS Direct Connect","AWS Site-to-Site VPN"],"dificuldade":1,"fonte":"usuario-B37"},{"id":"D3-c-010","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Funcionários em home office precisam acessar com segurança, a partir de seus notebooks, recursos em uma Amazon VPC. Qual serviço atende a esse requisito?","alternativas":[{"texto":"AWS Site-to-Site VPN","correta":false,"porque":"Liga redes inteiras (data center ou escritório) à VPC, não dispositivos individuais."},{"texto":"AWS Direct Connect","correta":false,"porque":"É um link físico dedicado entre uma instalação e a AWS; não atende usuários remotos."},{"texto":"AWS Client VPN","correta":true,"porque":"É uma VPN gerenciada baseada em cliente que permite a cada usuário se conectar à VPC de qualquer lugar."},{"texto":"AWS Transit Gateway","correta":false,"porque":"Interliga VPCs e redes; não fornece acesso de usuários finais."}],"explicacao":"Client VPN: usuário individual para a AWS. Site-to-Site VPN: rede para a AWS. Direct Connect: link dedicado.","servicos":["AWS Client VPN","AWS Site-to-Site VPN"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-011","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual das ações a seguir pode ser realizada com o Amazon Route 53?","alternativas":[{"texto":"Criptografar dados em trânsito pela internet","correta":false,"porque":"Criptografia em trânsito usa TLS e certificados (ex.: ACM), não o DNS."},{"texto":"Registrar nomes de domínio","correta":true,"porque":"Além de DNS gerenciado, o Route 53 é um registrador de domínios."},{"texto":"Gerar e gerenciar certificados SSL/TLS","correta":false,"porque":"Essa é a função do AWS Certificate Manager (ACM)."},{"texto":"Estabelecer uma conexão de rede dedicada com a AWS","correta":false,"porque":"Essa é a função do AWS Direct Connect."}],"explicacao":"Route 53 = registro de domínios + DNS gerenciado + health checks + políticas de roteamento.","servicos":["Amazon Route 53"],"dificuldade":1,"fonte":"usuario-B68"},{"id":"D3-c-012","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Uma aplicação roda em duas Regiões da AWS. A empresa quer que o Amazon Route 53 envie cada usuário para a Região que oferece a MENOR latência para ele. Qual política de roteamento deve ser usada?","alternativas":[{"texto":"Simple routing","correta":false,"porque":"Retorna um único registro sem considerar a latência do usuário."},{"texto":"Weighted routing","correta":false,"porque":"Distribui o tráfego por pesos definidos (ex.: 80/20), não pela latência."},{"texto":"Failover routing","correta":false,"porque":"Envia o tráfego ao recurso secundário só quando o primário falha no health check."},{"texto":"Latency-based routing","correta":true,"porque":"Responde com o endpoint da Região que apresenta a menor latência medida para o usuário."}],"explicacao":"Políticas do Route 53: simple, weighted, latency, failover, geolocation, geoproximity e multivalue; cada uma atende a um objetivo de roteamento.","servicos":["Amazon Route 53"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-013","dominio":3,"task":"3.5","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS mantêm os usuários alheios a falhas breves ao enviar as requisições apenas para os recursos de back-end que continuam saudáveis? (Selecione DUAS.)","alternativas":[{"texto":"Elastic Load Balancing","correta":true,"porque":"Faz health checks nos destinos e distribui requisições somente para os saudáveis."},{"texto":"Amazon ECS Service Connect","correta":false,"porque":"Facilita a comunicação entre serviços dentro do ECS; não é o ponto de entrada dos usuários."},{"texto":"Amazon EC2 Auto Scaling","correta":false,"porque":"Substitui instâncias com falha e ajusta a capacidade, mas não roteia as requisições."},{"texto":"Amazon Route 53","correta":true,"porque":"Com health checks e failover, deixa de responder com endpoints não saudáveis no DNS."},{"texto":"Route tables da VPC","correta":false,"porque":"Definem rotas por faixa de IP, sem verificar a saúde das aplicações."}],"explicacao":"ELB (dentro da Região) e Route 53 com health checks (no DNS, inclusive entre Regiões) direcionam tráfego só para destinos saudáveis.","servicos":["Elastic Load Balancing","Amazon Route 53"],"dificuldade":2,"fonte":"usuario-A26"},{"id":"D3-c-014","dominio":3,"task":"3.5","tipo":"multipla","selecionar":2,"enunciado":"Usuários do mundo todo reclamam do carregamento lento das imagens em alta resolução de um blog de viagens. Quais serviços a equipe deve combinar para entregar esses arquivos com a MENOR latência? (Selecione DUAS.)","alternativas":[{"texto":"AWS Storage Gateway","correta":false,"porque":"Integra armazenamento on-premises à nuvem; não entrega conteúdo a usuários globais."},{"texto":"Amazon CloudFront","correta":true,"porque":"CDN que guarda cópias das imagens em cache nas edge locations próximas aos usuários."},{"texto":"Amazon S3","correta":true,"porque":"Armazena as imagens de forma durável e serve de origem para a distribuição do CloudFront."},{"texto":"Amazon S3 Glacier Flexible Retrieval","correta":false,"porque":"É uma classe de arquivamento, com recuperação em minutos ou horas."},{"texto":"Amazon Elastic File System","correta":false,"porque":"É um sistema de arquivos para instâncias, não uma solução de entrega global."}],"explicacao":"O par clássico para conteúdo estático global é S3 como origem e CloudFront como CDN.","servicos":["Amazon CloudFront","Amazon S3"],"dificuldade":2,"fonte":"usuario-A40"},{"id":"D3-c-015","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual serviço da AWS entrega também as páginas dinâmicas de uma aplicação web a usuários de qualquer lugar do mundo com baixa latência?","alternativas":[{"texto":"Amazon S3","correta":false,"porque":"Armazena e serve objetos estáticos; não gera nem acelera conteúdo dinâmico."},{"texto":"Amazon Route 53","correta":false,"porque":"Resolve nomes DNS; não entrega o conteúdo das páginas."},{"texto":"Elastic Load Balancing","correta":false,"porque":"Distribui requisições dentro de uma Região; não aproxima o conteúdo dos usuários."},{"texto":"Amazon CloudFront","correta":true,"porque":"Acelera conteúdo estático e dinâmico usando edge locations e a rede global da AWS até a origem."}],"explicacao":"CloudFront não serve só arquivos estáticos: também acelera conteúdo dinâmico, APIs e streaming.","servicos":["Amazon CloudFront"],"dificuldade":2,"fonte":"usuario-A50"},{"id":"D3-c-016","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Uma empresa quer reduzir a latência para usuários do mundo todo que baixam vídeos e imagens do seu site, sem alterar a origem. Qual serviço da AWS deve usar?","alternativas":[{"texto":"Amazon S3 Transfer Acceleration","correta":false,"porque":"Acelera transferências, sobretudo uploads, para um bucket S3; não faz cache para os usuários."},{"texto":"Amazon CloudFront","correta":true,"porque":"É a CDN da AWS: armazena o conteúdo em cache nas edge locations e o entrega com baixa latência."},{"texto":"AWS Global Accelerator","correta":false,"porque":"Otimiza o caminho de rede até a aplicação, mas não faz cache de conteúdo."},{"texto":"Amazon Route 53","correta":false,"porque":"Faz a resolução DNS; não armazena nem entrega o conteúdo."}],"explicacao":"Cache em edge location = CloudFront. Global Accelerator não faz cache; S3 Transfer Acceleration foca em envio para o S3.","servicos":["Amazon CloudFront"],"dificuldade":2,"fonte":"usuario-B36 (reescrita)"},{"id":"D3-c-017","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Qual é um benefício do AWS Global Accelerator?","alternativas":[{"texto":"Aumenta a capacidade de CPU das instâncias EC2","correta":false,"porque":"Não altera o desempenho de computação das instâncias."},{"texto":"Reduz o custo das instâncias de servidor","correta":false,"porque":"É um serviço pago à parte; não reduz o preço de servidores."},{"texto":"Menor latência e mais disponibilidade para as aplicações","correta":true,"porque":"Leva o tráfego pela rede global da AWS por IPs anycast estáticos até endpoints saudáveis."},{"texto":"Armazenamento de dados altamente durável","correta":false,"porque":"Não armazena dados; durabilidade é característica de serviços como o S3."}],"explicacao":"Global Accelerator: IPs estáticos e rede global da AWS para TCP/UDP, com failover entre endpoints regionais e sem cache.","servicos":["AWS Global Accelerator"],"dificuldade":2,"fonte":"usuario-A48"},{"id":"D3-c-018","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Uma equipe quer criar, publicar e proteger APIs REST que acionam funções AWS Lambda, com controle de limite de requisições (throttling). Qual serviço deve usar?","alternativas":[{"texto":"Amazon API Gateway","correta":true,"porque":"Serviço gerenciado para criar, publicar, proteger e monitorar APIs REST, HTTP e WebSocket em qualquer escala."},{"texto":"Elastic Load Balancing","correta":false,"porque":"Distribui tráfego entre destinos, mas não oferece gestão de APIs como chaves e throttling por cliente."},{"texto":"Amazon CloudFront","correta":false,"porque":"Acelera a entrega de conteúdo; não é a ferramenta para definir e publicar APIs."},{"texto":"AWS Step Functions","correta":false,"porque":"Orquestra fluxos de trabalho; não expõe APIs para clientes externos."}],"explicacao":"API Gateway é a porta de entrada gerenciada para APIs, muito usada com Lambda em arquiteturas serverless.","servicos":["Amazon API Gateway"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-c-019","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Para investigar problemas de conectividade entre instâncias EC2, a equipe precisa registrar informações sobre o tráfego IP aceito e rejeitado nas interfaces de rede da VPC. Qual recurso deve usar?","alternativas":[{"texto":"VPC Flow Logs","correta":true,"porque":"Capturam metadados do tráfego IP (origem, destino, porta, ACCEPT/REJECT) das interfaces de rede."},{"texto":"AWS CloudHSM","correta":false,"porque":"Fornece HSMs dedicados para chaves criptográficas; não registra tráfego."},{"texto":"AWS Certificate Manager (ACM)","correta":false,"porque":"Gerencia certificados SSL/TLS; não captura informações de rede."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra chamadas de API, não o tráfego IP entre instâncias."}],"explicacao":"VPC Flow Logs mostram o tráfego aceito ou rejeitado por Security Groups e NACLs, o que ajuda a diagnosticar conectividade.","servicos":["VPC Flow Logs"],"dificuldade":2,"fonte":"usuario-B49"},{"id":"D3-c-020","dominio":3,"task":"3.5","tipo":"unica","enunciado":"Uma empresa quer identificar automaticamente instâncias EC2 com portas alcançáveis a partir da internet, além de vulnerabilidades de software conhecidas (CVEs). Qual serviço atende?","alternativas":[{"texto":"Amazon GuardDuty","correta":false,"porque":"Detecta ameaças e atividades maliciosas analisando logs, não a exposição de rede nem as CVEs."},{"texto":"Amazon Inspector","correta":true,"porque":"Avalia continuamente vulnerabilidades e a alcançabilidade de rede de EC2, imagens no ECR e funções Lambda."},{"texto":"Amazon Detective","correta":false,"porque":"Ajuda a investigar a causa raiz de achados de segurança; não varre vulnerabilidades."},{"texto":"Amazon Macie","correta":false,"porque":"Descobre dados sensíveis (PII) no Amazon S3."}],"explicacao":"Inspector = vulnerabilidades (CVEs) e exposição de rede indesejada. GuardDuty = detecção de ameaças por logs.","servicos":["Amazon Inspector"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-021","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Qual serviço da AWS executa frameworks open source de big data, como Apache Spark e Hadoop, em clusters gerenciados para cargas de ETL e analytics a baixo custo?","alternativas":[{"texto":"Amazon OpenSearch Service","correta":false,"porque":"Serve para busca, análise de logs e observabilidade, não para executar Spark e Hadoop."},{"texto":"Amazon Redshift","correta":false,"porque":"É um data warehouse para consultas SQL analíticas, não uma plataforma de clusters Spark e Hadoop."},{"texto":"Amazon RDS","correta":false,"porque":"É um banco relacional gerenciado para cargas transacionais."},{"texto":"Amazon EMR","correta":true,"porque":"Plataforma gerenciada de big data que roda Spark, Hadoop, Hive e outros frameworks, inclusive em instâncias Spot."}],"explicacao":"EMR = clusters gerenciados de frameworks open source de big data (Spark, Hadoop) para processar grandes volumes de dados.","servicos":["Amazon EMR"],"dificuldade":1,"fonte":"usuario-A04"},{"id":"D3-c-022","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Uma startup está criando um chatbot que precisa entender a entrada falada e digitada dos clientes. Qual serviço da AWS ajuda a entregar essa interface conversacional?","alternativas":[{"texto":"Amazon Lex","correta":true,"porque":"Cria interfaces conversacionais de voz e texto, com reconhecimento de fala e compreensão de linguagem natural."},{"texto":"Amazon Polly","correta":false,"porque":"Converte texto em fala; não interpreta a intenção do usuário."},{"texto":"Amazon Personalize","correta":false,"porque":"Gera recomendações personalizadas; não cria chatbots."},{"texto":"Amazon Translate","correta":false,"porque":"Traduz texto entre idiomas; não conduz uma conversa."}],"explicacao":"Lex é o serviço de chatbots (a mesma tecnologia da Alexa): entende fala e texto e reconhece intenções.","servicos":["Amazon Lex"],"dificuldade":1,"fonte":"usuario-A24"},{"id":"D3-c-023","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Para ingerir e processar em tempo real grandes volumes de dados de streaming, como cliques de um site e telemetria, qual serviço da AWS é a escolha natural?","alternativas":[{"texto":"AWS CloudTrail","correta":false,"porque":"Registra chamadas de API para auditoria; não é uma plataforma de streaming de dados."},{"texto":"Amazon Kinesis Data Streams","correta":true,"porque":"Captura e armazena fluxos contínuos de dados para processamento em tempo real por várias aplicações."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Coleta métricas e logs para monitoramento, não para ingerir streams de dados de negócio."},{"texto":"AWS Glue","correta":false,"porque":"Faz ETL e catalogação de dados, com foco em jobs e não em ingestão de streams em tempo real."}],"explicacao":"Kinesis é a família de serviços de streaming em tempo real: Data Streams para ingestão e processamento, Data Firehose para entrega a destinos.","servicos":["Amazon Kinesis"],"dificuldade":2,"fonte":"usuario-A54 (reescrita)"},{"id":"D3-c-024","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Qual capacidade o Amazon Rekognition oferece pronta para uso, sem treinar um modelo personalizado?","alternativas":[{"texto":"Extrair texto e tabelas de formulários digitalizados","correta":false,"porque":"Extração de texto, formulários e tabelas de documentos é o foco do Amazon Textract."},{"texto":"Identificar objetos, pessoas e cenas em imagens e vídeos","correta":true,"porque":"É uma análise pré-treinada de imagem e vídeo, que também detecta rostos e conteúdo impróprio."},{"texto":"Redimensionar imagens em massa","correta":false,"porque":"É processamento de imagem comum, não um recurso de visão computacional do Rekognition."},{"texto":"Converter fala de vídeos em legendas","correta":false,"porque":"Transcrever áudio em texto é a função do Amazon Transcribe."}],"explicacao":"Rekognition = visão computacional pronta: rótulos de objetos e cenas, análise facial e moderação de conteúdo em imagens e vídeos.","servicos":["Amazon Rekognition"],"dificuldade":2,"fonte":"usuario-A65 (reescrita)"},{"id":"D3-c-025","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Qual serviço da AWS é totalmente gerenciado e serverless, usado especificamente para descobrir, catalogar e executar jobs de extração, transformação e carga (ETL) de dados?","alternativas":[{"texto":"Amazon Athena","correta":false,"porque":"Consulta dados no S3 com SQL; não é a ferramenta de ETL e catalogação."},{"texto":"Amazon EMR","correta":false,"porque":"Executa ETL com Spark e Hadoop, mas em clusters que o cliente dimensiona; não é a opção ETL serverless dedicada."},{"texto":"AWS Glue","correta":true,"porque":"Serviço serverless de integração de dados com crawlers, Data Catalog e jobs de ETL."},{"texto":"Amazon Kinesis Data Streams","correta":false,"porque":"Ingere streams em tempo real; não cataloga nem transforma dados em lote."}],"explicacao":"Glue = ETL serverless + Data Catalog, que também é usado pelo Athena para consultar dados no S3.","servicos":["AWS Glue"],"dificuldade":2,"fonte":"usuario-B85"},{"id":"D3-c-026","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Cientistas de dados querem construir, treinar e implantar modelos próprios de machine learning em um ambiente totalmente gerenciado. Qual serviço deve ser usado?","alternativas":[{"texto":"Amazon Rekognition","correta":false,"porque":"Oferece visão computacional pré-treinada; não é uma plataforma para construir modelos próprios de qualquer tipo."},{"texto":"Amazon Comprehend","correta":false,"porque":"É um serviço de PLN pronto, para entidades e sentimento, e não uma plataforma geral de ML."},{"texto":"Amazon SageMaker AI","correta":true,"porque":"Cobre todo o ciclo de ML: preparar dados, construir, treinar, ajustar e implantar modelos."},{"texto":"Amazon EMR","correta":false,"porque":"Processa big data em clusters, mas não é o serviço gerenciado de ponta a ponta para ML."}],"explicacao":"SageMaker AI é a plataforma para modelos de ML personalizados; os serviços de IA prontos (Rekognition, Comprehend etc.) dispensam treinar modelos.","servicos":["Amazon SageMaker AI"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-c-027","dominio":3,"task":"3.7","tipo":"multipla","selecionar":2,"enunciado":"Uma empresa quer analisar as gravações das ligações do seu SAC: converter o áudio em texto e depois identificar o sentimento (positivo ou negativo) de cada cliente. Quais serviços devem ser usados? (Selecione DUAS.)","alternativas":[{"texto":"Amazon Transcribe","correta":true,"porque":"Converte fala em texto (speech-to-text) a partir das gravações."},{"texto":"Amazon Polly","correta":false,"porque":"Faz o contrário: converte texto em fala realista."},{"texto":"Amazon Comprehend","correta":true,"porque":"Usa processamento de linguagem natural para detectar sentimento, entidades e frases-chave no texto."},{"texto":"Amazon Translate","correta":false,"porque":"Traduz texto entre idiomas; não analisa sentimento."},{"texto":"Amazon Rekognition","correta":false,"porque":"Analisa imagens e vídeos, não áudio nem texto."}],"explicacao":"Transcribe (fala para texto), Polly (texto para fala), Translate (tradução) e Comprehend (PLN e sentimento) se combinam em pipelines de análise.","servicos":["Amazon Transcribe","Amazon Comprehend"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-028","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Uma seguradora recebe milhares de formulários digitalizados e quer extrair automaticamente texto, campos e tabelas, indo além de um OCR simples. Qual serviço atende?","alternativas":[{"texto":"Amazon Comprehend","correta":false,"porque":"Analisa texto já extraído (sentimento, entidades), mas não lê documentos digitalizados."},{"texto":"Amazon Rekognition","correta":false,"porque":"Detecta objetos e textos simples em imagens, mas não interpreta a estrutura de formulários e tabelas."},{"texto":"Amazon Transcribe","correta":false,"porque":"Converte áudio em texto; não processa documentos."},{"texto":"Amazon Textract","correta":true,"porque":"Extrai texto, pares chave-valor de formulários e tabelas de documentos digitalizados com ML."}],"explicacao":"Textract = extração inteligente de documentos (formulários e tabelas), além do OCR tradicional.","servicos":["Amazon Textract"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-029","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Uma empresa quer que os funcionários façam perguntas em linguagem natural e recebam respostas baseadas em documentos, wikis e sistemas internos da empresa, respeitando as permissões de acesso. Qual serviço da AWS atende?","alternativas":[{"texto":"Amazon Q Developer","correta":false,"porque":"É o assistente de IA generativa voltado a desenvolvedores: código, IDE e operações na AWS."},{"texto":"Amazon Q Business","correta":true,"porque":"Assistente de IA generativa que se conecta às fontes de dados corporativas e responde respeitando as permissões."},{"texto":"Amazon Lex","correta":false,"porque":"Cria chatbots com intenções definidas pelo desenvolvedor, não um assistente sobre todo o conteúdo corporativo."},{"texto":"Amazon Comprehend","correta":false,"porque":"Extrai entidades e sentimento de textos; não responde perguntas sobre os dados da empresa."}],"explicacao":"Amazon Q Business = assistente generativo sobre os dados da empresa; Amazon Q Developer = assistente para desenvolvimento e operação na AWS.","servicos":["Amazon Q Business","Amazon Q Developer"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-030","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Analistas querem executar consultas SQL ad hoc diretamente sobre arquivos de log armazenados no Amazon S3, sem provisionar servidores e pagando apenas pelos dados verificados. Qual serviço deve ser usado?","alternativas":[{"texto":"Amazon Redshift","correta":false,"porque":"É um data warehouse para análises recorrentes em grande escala; exige carregar dados ou configurar o ambiente."},{"texto":"Amazon OpenSearch Service","correta":false,"porque":"Exige ingerir os dados em um domínio para busca e análise; não consulta o S3 com SQL sob demanda."},{"texto":"Amazon Athena","correta":true,"porque":"É um serviço de consulta serverless que roda SQL sobre dados no S3 e cobra pelos dados verificados."},{"texto":"Amazon RDS","correta":false,"porque":"É um banco relacional transacional; os dados teriam de ser importados para ele."}],"explicacao":"Athena = SQL serverless direto no S3, sem infraestrutura, com cobrança por dados verificados.","servicos":["Amazon Athena"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-031","dominio":3,"task":"3.7","tipo":"unica","enunciado":"Uma empresa tem várias fontes de dados e quer consolidá-las em um único data warehouse para executar consultas analíticas complexas com alto desempenho. Qual serviço deve usar?","alternativas":[{"texto":"Amazon Redshift","correta":true,"porque":"É o data warehouse em escala de petabytes da AWS, com armazenamento colunar e processamento paralelo."},{"texto":"Amazon DynamoDB","correta":false,"porque":"É um banco NoSQL de chave-valor para cargas transacionais de baixa latência."},{"texto":"Amazon Athena","correta":false,"porque":"Consulta dados no S3 de forma ad hoc; não é o data warehouse que consolida as fontes."},{"texto":"Amazon Quick","correta":false,"porque":"Faz BI e dashboards sobre os dados, mas não armazena nem consolida o data warehouse."}],"explicacao":"Redshift = data warehouse (OLAP) para consultas analíticas sobre dados consolidados; RDS e DynamoDB atendem a cargas transacionais.","servicos":["Amazon Redshift"],"dificuldade":1,"fonte":"kananinirav-k22#42"},{"id":"D3-c-032","dominio":3,"task":"3.7","tipo":"unica","enunciado":"A diretoria quer dashboards interativos e relatórios de BI, inclusive com perguntas em linguagem natural, sobre dados no Redshift e no S3. Qual serviço da AWS atende?","alternativas":[{"texto":"Amazon Athena","correta":false,"porque":"Executa consultas SQL, mas não cria dashboards nem visualizações para usuários de negócio."},{"texto":"Amazon OpenSearch Service","correta":false,"porque":"Seus painéis focam em busca, logs e observabilidade, não em BI corporativo."},{"texto":"AWS Glue","correta":false,"porque":"Prepara e cataloga os dados (ETL), mas não os visualiza."},{"texto":"Amazon Quick (antigo QuickSight)","correta":true,"porque":"É o serviço de BI da AWS: dashboards interativos, relatórios e recursos de IA para consultar dados em linguagem natural."}],"explicacao":"Amazon Quick (antigo QuickSight) é o serviço de BI e visualização da AWS, hoje com recursos de IA generativa.","servicos":["Amazon Quick"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-c-033","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Qual serviço da AWS orquestra aplicações distribuídas e microsserviços serverless, coordenando vários serviços por meio de state machines visuais com tratamento de erros e novas tentativas?","alternativas":[{"texto":"Amazon API Gateway","correta":false,"porque":"Publica e protege APIs, mas não coordena as etapas de um fluxo de trabalho."},{"texto":"AWS Batch","correta":false,"porque":"Executa jobs de computação em lote; não orquestra serviços em state machines."},{"texto":"AWS Step Functions","correta":true,"porque":"Coordena serviços da AWS em fluxos de trabalho visuais, com estados, ramificações, retries e cobrança por transição de estado."},{"texto":"Amazon SQS","correta":false,"porque":"Enfileira mensagens entre componentes, mas não define a sequência e a lógica de um fluxo."}],"explicacao":"Step Functions é o orquestrador serverless da AWS: define o fluxo de trabalho como uma state machine e trata falhas sem código de coordenação.","servicos":["AWS Step Functions"],"dificuldade":1,"fonte":"usuario-A41"},{"id":"D3-c-034","dominio":3,"task":"3.8","tipo":"multipla","selecionar":2,"enunciado":"Quais serviços da AWS ajudam a construir uma arquitetura fracamente acoplada (loosely coupled)? (Selecione DUAS.)","alternativas":[{"texto":"AWS Step Functions","correta":true,"porque":"Coordena componentes independentes por meio de um fluxo de trabalho, sem que um chame o outro diretamente."},{"texto":"Amazon Connect","correta":false,"porque":"É um contact center em nuvem; não serve para desacoplar componentes de aplicação."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Dá recomendações de boas práticas; não integra componentes."},{"texto":"Amazon WorkSpaces","correta":false,"porque":"Fornece desktops virtuais para usuários finais."},{"texto":"Amazon SQS","correta":true,"porque":"A fila armazena as mensagens entre produtor e consumidor, que passam a trabalhar e escalar de forma independente."}],"explicacao":"Serviços de integração (SQS, SNS, EventBridge, Step Functions) desacoplam componentes: a falha ou a lentidão de um não derruba o outro.","servicos":["Amazon SQS","AWS Step Functions"],"dificuldade":2,"fonte":"usuario-B44"},{"id":"D3-c-035","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Uma arquitetura serverless precisa receber eventos de várias aplicações, inclusive SaaS de terceiros, e roteá-los por regras para os destinos certos sem escrever código de integração. Qual serviço atende?","alternativas":[{"texto":"AWS Lambda","correta":false,"porque":"Executa código acionado por eventos; usá-lo para rotear exigiria escrever a integração."},{"texto":"Amazon SQS","correta":false,"porque":"É uma fila ponto a ponto; não filtra nem roteia eventos de várias fontes por regras."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas e logs; não é o barramento de eventos entre aplicações."},{"texto":"Amazon EventBridge","correta":true,"porque":"É um barramento de eventos serverless que recebe eventos de serviços da AWS, de aplicações próprias e de SaaS e os roteia por regras."}],"explicacao":"EventBridge conecta produtores e consumidores de eventos por regras (arquitetura orientada a eventos) e também agenda tarefas.","servicos":["Amazon EventBridge"],"dificuldade":2,"fonte":"usuario-B69 (reescrita)"},{"id":"D3-c-036","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Uma aplicação precisa publicar uma mensagem uma única vez e entregá-la imediatamente a vários assinantes ao mesmo tempo, como e-mail, SMS e funções Lambda. Qual serviço deve ser usado?","alternativas":[{"texto":"Amazon SNS","correta":true,"porque":"É um serviço pub/sub: um tópico entrega a mensagem por push a todos os assinantes (fan-out)."},{"texto":"Amazon SQS","correta":false,"porque":"A fila guarda a mensagem até um consumidor buscá-la (pull); não faz push para vários assinantes."},{"texto":"Amazon SES","correta":false,"porque":"Envia e-mails, mas não entrega SMS nem aciona Lambda como assinantes de um tópico."},{"texto":"AWS Step Functions","correta":false,"porque":"Orquestra etapas sequenciais de um fluxo; não é um serviço de notificação pub/sub."}],"explicacao":"SNS = pub/sub com push para muitos assinantes. SQS = fila com pull e retenção. Os dois se combinam no padrão fan-out.","servicos":["Amazon SNS","Amazon SQS"],"dificuldade":3,"fonte":"kananinirav-k23#33 (reescrita)"},{"id":"D3-c-037","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Uma empresa enfrenta problemas com seu contact center tradicional e quer uma central de atendimento omnichannel em nuvem, pagando pelo uso. Qual serviço da AWS deve adotar?","alternativas":[{"texto":"AWS Direct Connect","correta":false,"porque":"Apesar do nome, é um link de rede dedicado entre o on-premises e a AWS."},{"texto":"Amazon Connect","correta":true,"porque":"É o contact center em nuvem da AWS, com voz, chat e tarefas, cobrado pelo uso."},{"texto":"Amazon Lex","correta":false,"porque":"Cria chatbots que podem ser integrados a um contact center, mas não é o contact center em si."},{"texto":"Amazon SNS","correta":false,"porque":"Envia notificações; não gerencia filas de atendimento nem agentes."}],"explicacao":"Amazon Connect = contact center em nuvem; integra-se a Lex, Transcribe e Comprehend para automação e análise.","servicos":["Amazon Connect"],"dificuldade":1,"fonte":"kananinirav-k7#5"},{"id":"D3-c-038","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Um e-commerce precisa enviar e-mails transacionais (confirmação de pedido, redefinição de senha) e campanhas de marketing em grande volume a partir da sua aplicação. Qual serviço da AWS é o MAIS adequado?","alternativas":[{"texto":"Amazon SNS","correta":false,"porque":"Envia notificações simples, mas não é voltado a e-mails transacionais e de marketing personalizados em volume."},{"texto":"Amazon Connect","correta":false,"porque":"É um contact center para atendimento a clientes."},{"texto":"Amazon SES","correta":true,"porque":"É o serviço de envio de e-mail em escala, com alta entregabilidade, para mensagens transacionais e de marketing."},{"texto":"Amazon SQS","correta":false,"porque":"Enfileira mensagens entre componentes de software; não envia e-mails."}],"explicacao":"Amazon SES (Simple Email Service) é o serviço de e-mail em massa da AWS; SNS é para notificações pub/sub.","servicos":["Amazon SES"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-039","dominio":3,"task":"3.8","tipo":"multipla","selecionar":2,"enunciado":"Uma equipe quer automatizar seu pipeline de CI/CD: a cada alteração no repositório, compilar o código, executar os testes e liberar a nova versão por etapas. Quais serviços atendem a esses requisitos? (Selecione DUAS.)","alternativas":[{"texto":"AWS CodeBuild","correta":true,"porque":"Serviço de build gerenciado que compila o código-fonte, roda testes e gera artefatos, sem servidores de build."},{"texto":"AWS X-Ray","correta":false,"porque":"Rastreia requisições em aplicações em execução; não faz build nem pipeline."},{"texto":"AWS CodePipeline","correta":true,"porque":"Orquestra as etapas de origem, build, teste e implantação a cada alteração (entrega contínua)."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra chamadas de API para auditoria; não automatiza entregas."},{"texto":"AWS Config","correta":false,"porque":"Avalia a conformidade das configurações dos recursos; não compila nem libera código."}],"explicacao":"CodePipeline orquestra o fluxo de CI/CD e CodeBuild executa a compilação e os testes dentro dele.","servicos":["AWS CodeBuild","AWS CodePipeline"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-040","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Uma aplicação de microsserviços está lenta e a equipe precisa rastrear as requisições de ponta a ponta para descobrir qual serviço causa o gargalo. Qual serviço da AWS deve ser usado?","alternativas":[{"texto":"AWS X-Ray","correta":true,"porque":"Faz rastreamento distribuído (tracing) e exibe um mapa de serviços com latências e erros de cada componente."},{"texto":"AWS CloudTrail","correta":false,"porque":"Registra quem fez quais chamadas de API na conta, não o desempenho das requisições da aplicação."},{"texto":"VPC Flow Logs","correta":false,"porque":"Registram metadados de tráfego IP; não mostram o tempo gasto em cada serviço."},{"texto":"AWS Config","correta":false,"porque":"Rastreia mudanças de configuração dos recursos, não as requisições da aplicação."}],"explicacao":"X-Ray = tracing distribuído para analisar e depurar aplicações, sobretudo de microsserviços.","servicos":["AWS X-Ray"],"dificuldade":2,"fonte":"autoral"},{"id":"D3-c-041","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Uma empresa quer que funcionários terceirizados acessem aplicações web internas apenas por um navegador, a partir de dispositivos próprios, sem desktop virtual completo e sem guardar dados localmente. Qual serviço é o MAIS adequado?","alternativas":[{"texto":"Amazon WorkSpaces","correta":false,"porque":"Fornece um desktop virtual persistente completo (Windows ou Linux), o que vai além do pedido."},{"texto":"Amazon WorkSpaces Applications (antigo AppStream 2.0)","correta":false,"porque":"Faz streaming de aplicações desktop instaladas, não é o acesso seguro a sites internos pelo navegador."},{"texto":"AWS Client VPN","correta":false,"porque":"Colocaria o dispositivo não gerenciado dentro da rede, aumentando o risco."},{"texto":"Amazon WorkSpaces Secure Browser","correta":true,"porque":"Oferece um navegador isolado e gerenciado para acessar sites e apps web internos, sem dados no dispositivo local."}],"explicacao":"End-user computing: WorkSpaces (desktop virtual completo), WorkSpaces Applications, antigo AppStream 2.0 (streaming de aplicações desktop), e WorkSpaces Secure Browser (acesso seguro a apps web pelo navegador).","servicos":["Amazon WorkSpaces Secure Browser","Amazon WorkSpaces","Amazon WorkSpaces Applications"],"dificuldade":3,"fonte":"autoral"},{"id":"D3-c-042","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Desenvolvedores front-end querem criar, conectar a um back-end e hospedar aplicações web e mobile full-stack rapidamente, com autenticação e CI/CD integrados. Qual serviço da AWS atende?","alternativas":[{"texto":"AWS Amplify","correta":true,"porque":"Reúne ferramentas e hospedagem para construir, implantar e hospedar apps web e mobile full-stack."},{"texto":"AWS Elastic Beanstalk","correta":false,"porque":"Implanta aplicações em servidores gerenciados, mas não é focado em front-end e mobile."},{"texto":"Amazon API Gateway","correta":false,"porque":"Publica APIs; é só uma peça do back-end."},{"texto":"Amazon Lightsail","correta":false,"porque":"Fornece servidores virtuais simples com preço fixo, sem as ferramentas de desenvolvimento front-end."}],"explicacao":"Amplify é o serviço de desenvolvimento e hospedagem front-end web e mobile da AWS.","servicos":["AWS Amplify"],"dificuldade":1,"fonte":"autoral"},{"id":"D3-c-043","dominio":3,"task":"3.8","tipo":"unica","enunciado":"Um fabricante quer conectar com segurança milhões de sensores à nuvem, receber suas mensagens (por exemplo, via MQTT) e encaminhá-las a outros serviços da AWS. Qual serviço deve ser usado?","alternativas":[{"texto":"Amazon Kinesis Data Streams","correta":false,"porque":"Ingere streams de dados, mas não gerencia a conexão, a autenticação e o protocolo dos dispositivos."},{"texto":"AWS IoT Core","correta":true,"porque":"Conecta dispositivos IoT à nuvem com segurança, recebe mensagens MQTT e as roteia por regras a outros serviços."},{"texto":"Amazon SNS","correta":false,"porque":"Envia notificações pub/sub, mas não é a plataforma de conexão de dispositivos."},{"texto":"AWS Direct Connect","correta":false,"porque":"É um link dedicado de rede entre o on-premises e a AWS."}],"explicacao":"AWS IoT Core é o serviço gerenciado para conectar e comunicar dispositivos IoT com a nuvem.","servicos":["AWS IoT Core"],"dificuldade":1,"fonte":"autoral"},{"id":"D4-x-001","dominio":4,"task":"4.1","tipo":"multipla","selecionar":2,"enunciado":"Quais duas dimensões de uso determinam a cobrança do AWS Lambda? (Selecione DUAS.)","alternativas":[{"texto":"A linguagem de runtime usada pela função","correta":false,"porque":"O preço não muda conforme a linguagem; Python, Node.js ou Java são cobrados da mesma forma."},{"texto":"O número de requisições (invocações) da função","correta":true,"porque":"O Lambda cobra por requisição, além da duração da execução."},{"texto":"A quantidade de linhas de código da função","correta":false,"porque":"O tamanho do código-fonte não é dimensão de cobrança."},{"texto":"A duração da execução, proporcional à memória alocada","correta":true,"porque":"A duração é cobrada em milissegundos, ponderada pela memória configurada (GB-segundo)."},{"texto":"O tamanho do pacote de implantação da função","correta":false,"porque":"O tamanho do pacote não é uma das dimensões de preço do Lambda."}],"explicacao":"AWS Lambda é cobrado por número de requisições e pela duração da execução (tempo x memória), sem pagar por servidor ocioso.","servicos":["Lambda"],"dificuldade":1,"fonte":"usuario-A20"},{"id":"D4-x-002","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Qual é o desconto MÁXIMO que as Reserved Instances do Amazon EC2 podem oferecer em relação ao preço On-Demand?","alternativas":[{"texto":"72%","correta":true,"porque":"Standard Reserved Instances de 3 anos com pagamento All Upfront chegam a até 72% de desconto."},{"texto":"50%","correta":false,"porque":"Fica abaixo do desconto máximo publicado para Reserved Instances."},{"texto":"90%","correta":false,"porque":"Até 90% é o desconto das Spot Instances, que podem ser interrompidas."},{"texto":"40%","correta":false,"porque":"Fica bem abaixo do desconto máximo das Reserved Instances."}],"explicacao":"Reserved Instances: até 72% (Standard) ou 66% (Convertible). Spot: até 90%, com risco de interrupção.","servicos":["EC2"],"dificuldade":1,"fonte":"usuario-A45"},{"id":"D4-x-003","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma aplicação executa cargas de trabalho que não podem ser interrompidas, de forma contínua, durante três anos, sem mudanças previstas de configuração. Qual opção de compra do EC2 oferece o MENOR custo total?","alternativas":[{"texto":"On-Demand Instances","correta":false,"porque":"Não exige compromisso, mas é a opção mais cara para uso contínuo e previsível."},{"texto":"Standard Reserved Instances de 3 anos","correta":true,"porque":"Oferecem o maior desconto das RIs (até 72%) para uso estável e previsível."},{"texto":"Spot Instances","correta":false,"porque":"São baratas, mas podem ser interrompidas, o que a carga não tolera."},{"texto":"Convertible Reserved Instances de 3 anos","correta":false,"porque":"Dão flexibilidade de troca, mas com desconto menor (até 66%), desnecessária aqui."}],"explicacao":"Uso estável, contínuo e sem mudanças previstas por longo prazo: Standard RI de 3 anos dá o maior desconto.","servicos":["EC2"],"dificuldade":2,"fonte":"usuario-A49"},{"id":"D4-x-004","dominio":4,"task":"4.1","tipo":"multipla","selecionar":3,"enunciado":"Quais opções de pagamento a AWS oferece na compra de Reserved Instances Standard ou Convertible? (Selecione TRÊS.)","alternativas":[{"texto":"Pagamento adiado (Deferred Payment)","correta":false,"porque":"Não é uma opção de pagamento de Reserved Instances."},{"texto":"All Upfront","correta":true,"porque":"Paga todo o prazo adiantado e obtém o maior desconto."},{"texto":"Pagamento por lance (bid)","correta":false,"porque":"Lances eram associados ao modelo antigo de Spot, não a Reserved Instances."},{"texto":"Partial Upfront","correta":true,"porque":"Paga parte adiantada e o restante em taxa horária reduzida."},{"texto":"Bill-Me-Later","correta":false,"porque":"Não existe essa modalidade para Reserved Instances."},{"texto":"No Upfront","correta":true,"porque":"Nada é pago adiantado; o desconto vem na taxa mensal, com o menor desconto das três."}],"explicacao":"RIs têm 3 opções de pagamento: All Upfront (maior desconto), Partial Upfront e No Upfront (menor desconto), em prazos de 1 ou 3 anos.","servicos":["EC2"],"dificuldade":1,"fonte":"usuario-A63"},{"id":"D4-x-005","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Qual modelo de preço do Amazon EC2 varia de acordo com a oferta e a demanda de capacidade ociosa da AWS?","alternativas":[{"texto":"Standard Reserved Instances","correta":false,"porque":"Têm preço fixo com desconto, definido no momento da compra do compromisso."},{"texto":"On-Demand Instances","correta":false,"porque":"Têm preço fixo por segundo ou hora, sem variação por oferta e demanda."},{"texto":"Spot Instances","correta":true,"porque":"Usam capacidade ociosa da AWS, com preço que se ajusta gradualmente à oferta e à demanda."},{"texto":"Convertible Reserved Instances","correta":false,"porque":"Têm preço com desconto fixo durante o prazo de 1 ou 3 anos."}],"explicacao":"Spot Instances usam capacidade ociosa do EC2, com preço variável e desconto de até 90%, mas podem ser interrompidas com aviso de 2 minutos.","servicos":["EC2"],"dificuldade":1,"fonte":"usuario-B05"},{"id":"D4-x-006","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma instância do Amazon EC2 é iniciada apenas quando um procedimento ad hoc é necessário. Uma vez iniciada, ela deve ficar disponível até o fim do procedimento, sem risco de interrupção. Qual opção de compra é a MAIS adequada?","alternativas":[{"texto":"Dedicated Instances","correta":false,"porque":"Isolam o hardware, mas custam mais e não há requisito de isolamento."},{"texto":"Spot Instances","correta":false,"porque":"Podem ser interrompidas pela AWS, o que o procedimento não tolera."},{"texto":"Reserved Instances","correta":false,"porque":"Exigem compromisso de 1 ou 3 anos, inadequado para uso esporádico."},{"texto":"On-Demand Instances","correta":true,"porque":"Não têm compromisso, cobram só pelo tempo de uso e não são interrompidas pela AWS."}],"explicacao":"Uso esporádico, imprevisível e que não pode ser interrompido: On-Demand.","servicos":["EC2"],"dificuldade":2,"fonte":"usuario-B61"},{"id":"D4-x-007","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa quer reduzir custos de computação de longo prazo que incluem AWS Lambda, AWS Fargate e Amazon EC2 em várias Regiões. Qual opção de compra atende a TODOS esses serviços?","alternativas":[{"texto":"Compute Savings Plans","correta":true,"porque":"Aplicam o desconto ao EC2 de qualquer família e Região, ao Fargate e ao Lambda."},{"texto":"EC2 Instance Savings Plans","correta":false,"porque":"Valem só para uma família de instância EC2 em uma Região; não cobrem Lambda nem Fargate."},{"texto":"Reserved Instances","correta":false,"porque":"Não cobrem AWS Lambda nem AWS Fargate."},{"texto":"Spot Instances","correta":false,"porque":"Não se aplicam ao Lambda e podem ser interrompidas."}],"explicacao":"Compute Savings Plans são o compromisso mais flexível: cobrem EC2 (qualquer família, tamanho, Região e SO), Fargate e Lambda.","servicos":["Savings Plans","Lambda","Fargate","EC2"],"dificuldade":2,"fonte":"usuario-B84"},{"id":"D4-x-008","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa precisa usar licenças de software existentes, vinculadas a sockets e núcleos físicos (BYOL), e um requisito de conformidade exige um servidor físico dedicado a ela. Qual opção do EC2 atende?","alternativas":[{"texto":"Dedicated Instances","correta":false,"porque":"Isolam o hardware, mas não dão visibilidade de sockets e núcleos para licenciamento."},{"texto":"Dedicated Hosts","correta":true,"porque":"Dão um servidor físico inteiro com visibilidade de sockets e núcleos, atendendo BYOL e conformidade."},{"texto":"Spot Instances","correta":false,"porque":"Rodam em hardware compartilhado e podem ser interrompidas."},{"texto":"On-Demand Capacity Reservations","correta":false,"porque":"Reservam capacidade em uma AZ, mas não dedicam um servidor físico."}],"explicacao":"Dedicated Hosts servem para licenças por socket/core/VM (BYOL) e requisitos de conformidade que exigem servidor físico dedicado.","servicos":["EC2"],"dificuldade":2,"fonte":"kananinirav-k10#18 (reescrita)"},{"id":"D4-x-009","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa vai assumir um compromisso de 3 anos com Amazon EC2, mas prevê trocar a família de instâncias durante o período. Qual opção permite trocar a reserva por outra configuração, desde que de valor igual ou maior?","alternativas":[{"texto":"Standard Reserved Instances","correta":false,"porque":"Permitem algumas modificações (como AZ e tamanho na mesma família), mas não trocar de família."},{"texto":"EC2 Instance Savings Plans","correta":false,"porque":"Ficam presos a uma família de instância em uma Região."},{"texto":"Convertible Reserved Instances","correta":true,"porque":"Podem ser trocadas por outras com família, SO ou tenancy diferentes, se o valor for igual ou maior."},{"texto":"On-Demand Capacity Reservations","correta":false,"porque":"Não são compromisso de prazo nem dão desconto; apenas reservam capacidade."}],"explicacao":"Convertible RI troca flexibilidade por desconto menor (até 66% x 72% da Standard): permite trocar atributos por RIs de valor igual ou maior.","servicos":["EC2"],"dificuldade":3,"fonte":"kananinirav-k10#19 (reescrita)"},{"id":"D4-x-010","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma carga de análise de dados roda esporadicamente, é tolerante a falhas e pode ser interrompida sem prejuízo. Qual opção de compra do EC2 oferece o MENOR custo?","alternativas":[{"texto":"On-Demand Instances","correta":false,"porque":"Não têm desconto; servem quando a carga não pode ser interrompida."},{"texto":"Reserved Instances","correta":false,"porque":"Exigem compromisso de 1 ou 3 anos, ruim para uso esporádico."},{"texto":"Dedicated Hosts","correta":false,"porque":"São a opção mais cara, voltada a licenciamento e conformidade."},{"texto":"Spot Instances","correta":true,"porque":"Dão até 90% de desconto para cargas flexíveis que toleram interrupção."}],"explicacao":"Cargas flexíveis, tolerantes a falhas e interrompíveis (batch, análise, renderização) são o caso clássico de Spot Instances.","servicos":["EC2"],"dificuldade":1,"fonte":"kananinirav-k21#41"},{"id":"D4-x-011","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa precisa que suas instâncias EC2 rodem em hardware não compartilhado com outros clientes da AWS, mas não precisa de visibilidade de sockets e núcleos nem controlar o posicionamento no servidor físico. Qual opção atende com MENOR esforço de gestão?","alternativas":[{"texto":"Dedicated Instances","correta":true,"porque":"Rodam em hardware dedicado a uma conta, sem exigir a gestão de um host físico."},{"texto":"Dedicated Hosts","correta":false,"porque":"Também isolam, mas exigem gerenciar o host e só se justificam por BYOL ou controle de posicionamento."},{"texto":"Spot Instances","correta":false,"porque":"Usam capacidade compartilhada e podem ser interrompidas."},{"texto":"Compute Savings Plans","correta":false,"porque":"São um modelo de desconto, não garantem isolamento de hardware."}],"explicacao":"Dedicated Instances: isolamento de hardware sem controle do host. Dedicated Hosts: servidor físico inteiro com visibilidade de sockets/cores para licenças.","servicos":["EC2"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-012","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa precisa garantir capacidade do EC2 em uma Availability Zone específica durante um evento de duas semanas, sem assumir compromisso de 1 ou 3 anos. Qual opção atende?","alternativas":[{"texto":"Standard Reserved Instances zonais","correta":false,"porque":"Reservam capacidade, mas exigem compromisso de 1 ou 3 anos."},{"texto":"On-Demand Capacity Reservations","correta":true,"porque":"Reservam capacidade em uma AZ por qualquer duração, sem prazo mínimo, pagando o preço On-Demand."},{"texto":"Spot Instances","correta":false,"porque":"Não garantem capacidade e podem ser interrompidas."},{"texto":"Compute Savings Plans","correta":false,"porque":"Dão desconto em troca de compromisso de 1 ou 3 anos, mas não reservam capacidade."}],"explicacao":"Capacity Reservations garantem capacidade em uma AZ sem compromisso de prazo e sem desconto (podem ser combinadas com Savings Plans para ter desconto).","servicos":["EC2"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-013","dominio":4,"task":"4.1","tipo":"multipla","selecionar":2,"enunciado":"Quais transferências de dados normalmente NÃO são cobradas pela AWS? (Selecione DUAS.)","alternativas":[{"texto":"Entrada de dados da internet para a AWS","correta":true,"porque":"A transferência de entrada (inbound) da internet é gratuita."},{"texto":"Saída de dados da AWS para a internet","correta":false,"porque":"A saída (outbound) para a internet é cobrada por GB."},{"texto":"Transferência entre Regiões da AWS","correta":false,"porque":"Dados trafegados entre Regiões são cobrados."},{"texto":"Tráfego entre instâncias na mesma AZ usando IPs privados","correta":true,"porque":"Dentro da mesma AZ, por IP privado, a transferência é gratuita."},{"texto":"Transferência entre AZs diferentes da mesma Região","correta":false,"porque":"O tráfego entre AZs na mesma Região normalmente é cobrado por GB em cada sentido."}],"explicacao":"Entrada é gratuita; saída para a internet, entre Regiões e entre AZs é cobrada; mesma AZ por IP privado é gratuita. CloudFront ajuda a reduzir custo de saída.","servicos":["EC2","VPC"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-014","dominio":4,"task":"4.1","tipo":"multipla","selecionar":2,"enunciado":"Quais fatores influenciam o valor cobrado pelo armazenamento de objetos no Amazon S3? (Selecione DUAS.)","alternativas":[{"texto":"A classe de armazenamento usada pelos objetos","correta":true,"porque":"Cada classe (Standard, Standard-IA, Glacier etc.) tem preço por GB diferente."},{"texto":"A quantidade de buckets criados e excluídos","correta":false,"porque":"Criar ou excluir buckets não gera cobrança de armazenamento."},{"texto":"O volume total em GB armazenado","correta":true,"porque":"O armazenamento é cobrado por GB-mês efetivamente guardado."},{"texto":"O uso da criptografia padrão SSE-S3","correta":false,"porque":"A criptografia padrão SSE-S3 não tem custo adicional."},{"texto":"O número de volumes EBS da conta","correta":false,"porque":"Volumes EBS são cobrados no EBS, não afetam o preço do S3."}],"explicacao":"No S3 você paga pelo GB armazenado conforme a classe, além de requisições, recuperação (em algumas classes) e transferência de saída.","servicos":["S3"],"dificuldade":1,"fonte":"kananinirav-k7#3"},{"id":"D4-x-015","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa moveu dados pouco acessados do S3 Standard para o S3 Standard-IA para pagar menos por GB armazenado. Qual cobrança passa a existir que NÃO havia no S3 Standard?","alternativas":[{"texto":"Cobrança pela entrada de dados vindos da internet","correta":false,"porque":"A entrada de dados na AWS é gratuita em qualquer classe."},{"texto":"Taxa mensal fixa por bucket criado","correta":false,"porque":"O S3 não cobra taxa fixa por bucket."},{"texto":"Taxa por GB recuperado (retrieval)","correta":true,"porque":"Standard-IA tem armazenamento mais barato, mas cobra por GB lido e exige mínimo de 30 dias."},{"texto":"Taxa por objeto monitorado para troca automática de camada","correta":false,"porque":"Essa taxa de monitoramento é do S3 Intelligent-Tiering, não do Standard-IA."}],"explicacao":"Classes de acesso infrequente e de arquivamento trocam preço de armazenamento menor por taxa de recuperação e duração mínima de armazenamento.","servicos":["S3"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-016","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa usa há anos a mesma família de instâncias EC2 na mesma Região e não pretende mudar. Ela quer o MAIOR desconto possível assumindo um compromisso de gasto por hora (US$/h) por 3 anos. Qual opção escolher?","alternativas":[{"texto":"Compute Savings Plans","correta":false,"porque":"São mais flexíveis, mas oferecem desconto menor (até 66%)."},{"texto":"Spot Instances","correta":false,"porque":"Não são compromisso de gasto e podem ser interrompidas."},{"texto":"On-Demand Capacity Reservations","correta":false,"porque":"Reservam capacidade sem nenhum desconto."},{"texto":"EC2 Instance Savings Plans","correta":true,"porque":"Dão até 72% de desconto em troca de fixar a família de instância e a Região."}],"explicacao":"Savings Plans: EC2 Instance (família + Região fixas, até 72%) x Compute (qualquer família/Região, Fargate e Lambda, até 66%).","servicos":["Savings Plans","EC2"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-017","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Qual afirmação sobre o AWS Free Tier está correta?","alternativas":[{"texto":"Alguns serviços têm ofertas sempre gratuitas até um limite mensal de uso","correta":true,"porque":"Ex.: o AWS Lambda inclui 1 milhão de requisições gratuitas por mês, sem prazo de expiração."},{"texto":"Todos os serviços são gratuitos e ilimitados no primeiro ano","correta":false,"porque":"As ofertas têm limites de uso e nem todo serviço está incluído."},{"texto":"Exige um compromisso de 1 ano, como as Reserved Instances","correta":false,"porque":"O Free Tier não exige compromisso de prazo."},{"texto":"Vale apenas para o uso de Spot Instances","correta":false,"porque":"Abrange diversos serviços, não um modelo de compra do EC2."}],"explicacao":"O AWS Free Tier oferece uso gratuito limitado: ofertas sempre gratuitas, períodos de avaliação e créditos para novos clientes; acima dos limites, paga-se o preço normal.","servicos":["Lambda"],"dificuldade":1,"fonte":"autoral"},{"id":"D4-x-018","dominio":4,"task":"4.1","tipo":"unica","enunciado":"Uma empresa comprou Reserved Instances em uma de suas contas AWS e quer que instâncias equivalentes em outras contas da empresa também recebam o desconto. Como isso é possível?","alternativas":[{"texto":"Usando Dedicated Instances nas outras contas","correta":false,"porque":"Dedicated Instances tratam de isolamento de hardware, não de compartilhar descontos."},{"texto":"Usando o consolidated billing do AWS Organizations","correta":true,"porque":"Contas da mesma organização compartilham por padrão os descontos de RIs e Savings Plans."},{"texto":"Usando o AWS Cost Explorer","correta":false,"porque":"Cost Explorer visualiza custos e recomenda reservas, mas não compartilha descontos."},{"texto":"Usando o AWS Budgets","correta":false,"porque":"Budgets monitora e alerta sobre gastos, mas não aplica descontos entre contas."}],"explicacao":"No consolidated billing, descontos de RIs e Savings Plans não usados numa conta se aplicam a uso elegível de outras contas da organização (o compartilhamento pode ser desligado).","servicos":["Organizations","EC2"],"dificuldade":2,"fonte":"kananinirav-k12#10"},{"id":"D4-x-019","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Em qual Região ficam armazenadas as métricas de cobrança (billing metrics) do Amazon CloudWatch, usadas para criar alarmes de faturamento?","alternativas":[{"texto":"Na Região em que a conta foi criada","correta":false,"porque":"A Região de criação da conta não define onde ficam as métricas de cobrança."},{"texto":"Na Região em que cada recurso é executado","correta":false,"porque":"Os dados de cobrança são globais e centralizados em uma única Região."},{"texto":"us-east-1 (Norte da Virgínia)","correta":true,"porque":"As métricas de cobrança de todas as Regiões ficam em us-east-1."},{"texto":"us-west-2 (Oregon)","correta":false,"porque":"Não é a Região que armazena as métricas de cobrança."}],"explicacao":"Billing metrics do CloudWatch (EstimatedCharges) ficam em us-east-1; é lá que se cria o alarme de cobrança.","servicos":["CloudWatch"],"dificuldade":2,"fonte":"usuario-A23"},{"id":"D4-x-020","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Com o consolidated billing do AWS Organizations, o uso de todas as contas é somado para alcançar faixas de preço por volume. Qual serviço é um exemplo típico desse benefício?","alternativas":[{"texto":"AWS IAM","correta":false,"porque":"O IAM não tem custo, então não há faixa de volume a alcançar."},{"texto":"AWS CloudFormation","correta":false,"porque":"O CloudFormation não tem custo próprio para recursos da AWS; não há faixa de volume a alcançar."},{"texto":"Amazon SNS","correta":false,"porque":"O SNS cobra por requisição e entrega sem as faixas de armazenamento por volume que são o exemplo clássico; o caso típico é o S3."},{"texto":"Amazon S3","correta":true,"porque":"O preço por GB do S3 cai em faixas de volume, e o uso somado das contas atinge faixas mais baratas."}],"explicacao":"O consolidated billing trata todas as contas como uma só para preços em camadas (ex.: armazenamento S3 e transferência de dados).","servicos":["Organizations","S3"],"dificuldade":2,"fonte":"usuario-A30"},{"id":"D4-x-021","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual ferramenta oferece relatórios de utilização e de cobertura de Reserved Instances, permitindo analisar ao longo do tempo quanto das reservas está sendo aproveitado?","alternativas":[{"texto":"AWS Cost Explorer","correta":true,"porque":"Traz relatórios de utilização e de cobertura de RIs e Savings Plans com histórico."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos de uso futuro; não analisa reservas já compradas."},{"texto":"AWS Price List API","correta":false,"porque":"Consulta preços publicados dos serviços, não o uso das reservas da conta."},{"texto":"AWS Compute Optimizer","correta":false,"porque":"Recomenda tamanhos de recursos (rightsizing), sem relatórios de reservas."}],"explicacao":"Cost Explorer tem relatórios de utilização e cobertura de RIs/SPs; para ser ALERTADO quando ficam abaixo da meta, use AWS Budgets.","servicos":["Cost Explorer"],"dificuldade":3,"fonte":"usuario-A37 (reescrita)"},{"id":"D4-x-022","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma empresa quer definir uma meta percentual de cobertura de Reserved Instances e ser notificada sempre que a cobertura real ficar abaixo dessa meta. Qual serviço atende?","alternativas":[{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz verificações de boas práticas, mas não permite definir meta de cobertura com alerta."},{"texto":"AWS Budgets","correta":true,"porque":"Permite criar orçamentos de cobertura e de utilização de RIs/SPs com alertas por limite."},{"texto":"AWS Cost Anomaly Detection","correta":false,"porque":"Detecta gastos incomuns com ML, sem metas de cobertura de reservas."},{"texto":"AWS Cost and Usage Report","correta":false,"porque":"Entrega dados detalhados de cobrança, mas não envia alertas."}],"explicacao":"AWS Budgets tem tipos de orçamento de custo, uso, utilização e cobertura de RIs/Savings Plans, todos com alertas.","servicos":["Budgets"],"dificuldade":2,"fonte":"usuario-A59"},{"id":"D4-x-023","dominio":4,"task":"4.2","tipo":"multipla","selecionar":2,"enunciado":"Quais duas afirmações sobre as cost allocation tags da AWS estão corretas? (Selecione DUAS.)","alternativas":[{"texto":"Somente as tags definidas pelo usuário precisam ser ativadas antes de aparecer no Cost Explorer","correta":false,"porque":"As tags geradas pela AWS também precisam ser ativadas."},{"texto":"Todos os recursos precisam ter tags antes que qualquer relatório de custo seja gerado","correta":false,"porque":"Relatórios de custo funcionam sem tags; elas apenas permitem agrupar os custos."},{"texto":"Uma mesma chave de tag pode ter vários valores no mesmo recurso","correta":false,"porque":"Cada chave tem um único valor por recurso."},{"texto":"Cada recurso aceita um único valor por chave, e as chaves são únicas naquele recurso","correta":true,"porque":"Em um recurso, cada chave é única e tem apenas um valor."},{"texto":"Tanto as tags geradas pela AWS quanto as definidas pelo usuário precisam ser ativadas no console de Billing","correta":true,"porque":"Só depois de ativadas aparecem no Cost Explorer e no Cost and Usage Report."}],"explicacao":"Cost allocation tags (geradas pela AWS ou definidas pelo usuário) precisam ser ativadas no Billing para aparecerem no Cost Explorer e no CUR.","servicos":["Cost Explorer","Cost and Usage Reports"],"dificuldade":3,"fonte":"usuario-B12"},{"id":"D4-x-024","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual recurso permite categorizar e acompanhar os custos da AWS por projeto, departamento ou centro de custo?","alternativas":[{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos antes da implantação, sem categorizar gastos reais."},{"texto":"AWS Budgets","correta":false,"porque":"Alerta sobre limites de gasto, mas depende de tags para separar por projeto."},{"texto":"Cost allocation tags","correta":true,"porque":"Rótulos chave-valor nos recursos permitem agrupar e filtrar custos por projeto ou departamento."},{"texto":"AWS Cost Explorer sem filtros","correta":false,"porque":"Mostra custos por serviço e conta, mas sem tags não separa por projeto."}],"explicacao":"Cost allocation tags categorizam os custos em nível detalhado (projeto, equipe, ambiente) no Cost Explorer, no Budgets e no CUR.","servicos":["Cost Explorer"],"dificuldade":1,"fonte":"usuario-B23"},{"id":"D4-x-025","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma startup planeja um ambiente híbrido com parte das cargas na AWS e quer estimar os custos ANTES de implantar qualquer recurso. Qual ferramenta deve usar?","alternativas":[{"texto":"AWS Cost Explorer","correta":false,"porque":"Analisa custos de uso que já aconteceu na conta."},{"texto":"AWS Cost and Usage Report","correta":false,"porque":"Detalha custos já incorridos, não estimativas."},{"texto":"AWS Budgets","correta":false,"porque":"Monitora gastos reais contra um orçamento."},{"texto":"AWS Pricing Calculator","correta":true,"porque":"Estima o custo de uma arquitetura planejada antes de criar os recursos."}],"explicacao":"AWS Pricing Calculator: estimar antes de implantar. Cost Explorer, Budgets e CUR trabalham com o uso real.","servicos":["Pricing Calculator"],"dificuldade":1,"fonte":"usuario-B31"},{"id":"D4-x-026","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual ferramenta analisa o uso passado de EC2 da conta e recomenda compras de Reserved Instances, mostrando a economia estimada em relação a continuar no On-Demand?","alternativas":[{"texto":"AWS Cost Explorer","correta":true,"porque":"Gera recomendações de RIs e Savings Plans com base no histórico de uso."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos de cenários informados manualmente, sem analisar o histórico."},{"texto":"AWS Cost and Usage Report","correta":false,"porque":"Entrega dados brutos detalhados, sem recomendações de compra."},{"texto":"AWS Budgets","correta":false,"porque":"Alerta sobre gastos, mas não recomenda compras de reservas."}],"explicacao":"Cost Explorer visualiza o histórico, prevê gastos e recomenda RIs e Savings Plans.","servicos":["Cost Explorer"],"dificuldade":2,"fonte":"usuario-B39"},{"id":"D4-x-027","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual serviço da AWS, sem custo adicional, permite reunir várias contas AWS em uma organização gerenciada centralmente?","alternativas":[{"texto":"AWS Config","correta":false,"porque":"Registra e avalia configurações de recursos, não consolida contas."},{"texto":"AWS Organizations","correta":true,"porque":"Gerencia várias contas de forma central, com consolidated billing e SCPs, sem custo extra."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas e logs, não agrupa contas."},{"texto":"AWS Service Catalog","correta":false,"porque":"Publica produtos aprovados para uso, não consolida contas."}],"explicacao":"AWS Organizations é gratuito e oferece gestão centralizada de contas, consolidated billing e políticas como SCPs.","servicos":["Organizations"],"dificuldade":1,"fonte":"usuario-B43"},{"id":"D4-x-028","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual ferramenta da AWS ajuda a visualizar, entender e gerenciar gastos e uso ao longo do tempo por meio de gráficos e filtros?","alternativas":[{"texto":"AWS Organizations","correta":false,"porque":"Gerencia contas e consolida cobrança, sem gráficos de análise de gastos."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos futuros, não analisa o histórico."},{"texto":"AWS Cost Explorer","correta":true,"porque":"Exibe gráficos de custo e uso por serviço, conta e tag ao longo do tempo."},{"texto":"AWS Service Catalog","correta":false,"porque":"Gerencia catálogos de produtos aprovados, não análise de custos."}],"explicacao":"AWS Cost Explorer é a ferramenta de visualização e análise de custos e uso históricos.","servicos":["Cost Explorer"],"dificuldade":1,"fonte":"usuario-B58"},{"id":"D4-x-029","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma empresa quer prever quanto vai gastar na AWS nos próximos meses com base no seu uso histórico. Qual ferramenta deve usar?","alternativas":[{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima cenários informados manualmente, não projeta o histórico da conta."},{"texto":"AWS Organizations","correta":false,"porque":"Gerencia contas e consolida a fatura, sem previsão de gastos."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Aponta economias e boas práticas, mas não projeta gastos futuros."},{"texto":"AWS Cost Explorer","correta":true,"porque":"Gera previsões de custo para os próximos meses com base no uso histórico da conta."}],"explicacao":"A previsão (forecast) do Cost Explorer projeta gastos futuros com base no histórico da conta.","servicos":["Cost Explorer"],"dificuldade":2,"fonte":"usuario-B86"},{"id":"D4-x-030","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual ferramenta entrega os dados MAIS detalhados de custo e uso da conta, com itens de linha por hora e por recurso, em um bucket do Amazon S3?","alternativas":[{"texto":"AWS Cost and Usage Report","correta":true,"porque":"É o conjunto de dados de cobrança mais granular, entregue no S3 para análise (ex.: com Athena)."},{"texto":"AWS Cost Explorer","correta":false,"porque":"Mostra gráficos e resumos, mas com granularidade menor que o CUR."},{"texto":"AWS Budgets","correta":false,"porque":"Acompanha gastos contra limites e alerta, sem dados linha a linha."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Gera estimativas de custo, não dados reais de uso."}],"explicacao":"O Cost and Usage Report (CUR) é a fonte mais detalhada de dados de cobrança, incluindo tags ativadas, por hora e por recurso.","servicos":["Cost and Usage Reports","S3"],"dificuldade":2,"fonte":"kananinirav-k8#44 (reescrita)"},{"id":"D4-x-031","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma empresa quer que, ao ultrapassar o limite de gasto definido, a AWS aplique automaticamente uma política IAM ou SCP que bloqueie novos recursos, ou pare instâncias EC2 específicas. Qual recurso atende?","alternativas":[{"texto":"AWS Cost Explorer","correta":false,"porque":"Visualiza e prevê custos, mas não executa ações automáticas."},{"texto":"Ações do AWS Budgets (budget actions)","correta":true,"porque":"Executam ações como aplicar políticas IAM/SCP ou parar instâncias EC2 e RDS quando o limite é atingido."},{"texto":"AWS Cost Anomaly Detection","correta":false,"porque":"Alerta sobre gastos incomuns, sem aplicar políticas automaticamente."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Recomenda otimizações, mas não reage a limites de orçamento."}],"explicacao":"AWS Budgets vai além de alertas: as budget actions aplicam políticas IAM/SCP ou param recursos EC2/RDS ao atingir o limite.","servicos":["Budgets"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-032","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma empresa quer ser alertada sobre picos de gasto incomuns sem precisar definir limites fixos, usando machine learning para identificar a causa raiz. Qual serviço atende?","alternativas":[{"texto":"AWS Budgets","correta":false,"porque":"Exige que você defina os limites que disparam os alertas."},{"texto":"AWS Cost and Usage Report","correta":false,"porque":"Entrega dados detalhados, sem detectar nem alertar sobre anomalias."},{"texto":"AWS Cost Anomaly Detection","correta":true,"porque":"Usa ML para detectar gastos fora do padrão e apontar a causa raiz, com alertas."},{"texto":"AWS Pricing Calculator","correta":false,"porque":"Estima custos futuros, não monitora o gasto real."}],"explicacao":"Cost Anomaly Detection monitora gastos com ML e alerta sobre anomalias; Budgets alerta sobre limites definidos por você.","servicos":["Cost Anomaly Detection"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-033","dominio":4,"task":"4.2","tipo":"multipla","selecionar":2,"enunciado":"Quais afirmações sobre o consolidated billing do AWS Organizations estão corretas? (Selecione DUAS.)","alternativas":[{"texto":"A management account é responsável por pagar as cobranças de todas as contas-membro","correta":true,"porque":"A fatura consolidada é paga pela management account."},{"texto":"O recurso tem uma taxa mensal adicional por conta-membro","correta":false,"porque":"Consolidated billing não tem custo adicional."},{"texto":"Cada conta-membro precisa pagar separadamente sua própria fatura","correta":false,"porque":"O pagamento é centralizado na management account."},{"texto":"O compartilhamento de descontos de RIs e Savings Plans pode ser desativado","correta":true,"porque":"O compartilhamento vem ligado, mas pode ser desligado na management account."},{"texto":"Cada conta-membro pode ver as faturas de todas as outras contas","correta":false,"porque":"A visão consolidada é da management account; contas-membro veem só os próprios custos."}],"explicacao":"Consolidated billing: uma fatura paga pela management account, sem custo extra, com descontos por volume e compartilhamento (desativável) de RIs e Savings Plans.","servicos":["Organizations"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-034","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Uma empresa quer que os custos de produção e de desenvolvimento fiquem totalmente isolados, sem depender da marcação correta de cada recurso. Qual abordagem é a MAIS indicada?","alternativas":[{"texto":"Aplicar cost allocation tags por ambiente","correta":false,"porque":"Ajuda, mas depende de todos os recursos estarem marcados corretamente."},{"texto":"Criar VPCs separadas na mesma conta","correta":false,"porque":"VPCs isolam rede, não separam a cobrança."},{"texto":"Usar filtros por serviço no AWS Cost Explorer","correta":false,"porque":"Os dois ambientes usam os mesmos serviços, então o filtro não separa os custos."},{"texto":"Usar contas AWS separadas em uma organização","correta":true,"porque":"Cada conta tem custos próprios, visíveis por conta na fatura consolidada."}],"explicacao":"Contas separadas (no AWS Organizations) são a forma mais forte de isolar custos; tags complementam para granularidade dentro da conta.","servicos":["Organizations"],"dificuldade":2,"fonte":"kananinirav-k18#17 (reescrita)"},{"id":"D4-x-035","dominio":4,"task":"4.2","tipo":"multipla","selecionar":2,"enunciado":"Uma startup com orçamento apertado quer ser notificada quando a fatura mensal da AWS ultrapassar US$ 2.000. Quais opções atendem? (Selecione DUAS.)","alternativas":[{"texto":"Criar um alarme de cobrança no Amazon CloudWatch que notifique via Amazon SNS","correta":true,"porque":"Alarmes sobre a métrica de cobrança estimada disparam notificações SNS."},{"texto":"Configurar o Amazon SES para enviar a fatura diariamente por e-mail","correta":false,"porque":"O SES envia e-mails, mas não monitora limites de gasto."},{"texto":"Criar um orçamento no AWS Budgets com alerta no limite","correta":true,"porque":"Budgets alerta quando o custo real ou previsto ultrapassa o limite."},{"texto":"Configurar o AWS CloudTrail para excluir recursos ao atingir o limite","correta":false,"porque":"CloudTrail registra chamadas de API; não monitora gastos nem age sobre eles."},{"texto":"Gerar uma previsão mensal no AWS Cost Explorer","correta":false,"porque":"A previsão ajuda a planejar, mas não envia alerta ao ultrapassar o valor."}],"explicacao":"Para alertar sobre gastos: AWS Budgets ou alarme de cobrança do CloudWatch (métricas em us-east-1) com SNS.","servicos":["Budgets","CloudWatch","SNS"],"dificuldade":2,"fonte":"kananinirav-k1#20"},{"id":"D4-x-036","dominio":4,"task":"4.2","tipo":"unica","enunciado":"Qual é um exemplo de cost allocation tag GERADA PELA AWS, e não definida pelo usuário?","alternativas":[{"texto":"aws:createdBy, que identifica quem criou o recurso","correta":true,"porque":"Tags com prefixo aws: são criadas pela AWS; createdBy registra o criador do recurso."},{"texto":"CostCenter, definida pela equipe financeira","correta":false,"porque":"É uma tag definida pelo usuário."},{"texto":"Project, aplicada por uma política de tags","correta":false,"porque":"Mesmo imposta por política, a chave é definida pelo usuário."},{"texto":"Name, preenchida ao criar a instância no console","correta":false,"porque":"A tag Name é definida pelo usuário, ainda que o console a sugira."}],"explicacao":"Tags geradas pela AWS usam o prefixo aws: (ex.: aws:createdBy); as demais são definidas pelo usuário. Ambos os tipos precisam ser ativados no Billing.","servicos":["Cost Explorer"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-037","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Qual recurso da AWS mostra a saúde geral dos serviços da AWS e alerta os clientes sobre eventos que afetam os recursos da própria conta?","alternativas":[{"texto":"AWS Config","correta":false,"porque":"Registra e avalia configurações de recursos, não a saúde dos serviços da AWS."},{"texto":"AWS Health Dashboard","correta":true,"porque":"Mostra o status dos serviços e eventos personalizados que afetam a conta; dados também disponíveis pela AWS Health API."},{"texto":"Amazon CloudWatch","correta":false,"porque":"Monitora métricas dos seus recursos, não incidentes dos serviços da AWS."},{"texto":"AWS Trusted Advisor","correta":false,"porque":"Faz verificações de boas práticas, não informa indisponibilidade de serviços."}],"explicacao":"AWS Health Dashboard (sucessor do Personal e do Service Health Dashboard) informa saúde dos serviços e eventos da conta; a AWS Health API permite automação.","servicos":["Health Dashboard"],"dificuldade":1,"fonte":"usuario-A12"},{"id":"D4-x-038","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Qual oferta da AWS disponibiliza especialistas da própria AWS, contratados em projetos pagos, para ajudar organizações a alcançar resultados de negócio específicos na adoção da nuvem?","alternativas":[{"texto":"AWS Managed Services","correta":false,"porque":"Opera a infraestrutura do cliente de forma contínua; não é o foco de projetos de adoção e está fora do escopo da prova."},{"texto":"AWS Enterprise Support","correta":false,"porque":"É um plano de suporte com TAM, não um serviço de consultoria por projeto."},{"texto":"AWS Professional Services","correta":true,"porque":"É a equipe global de especialistas da AWS que atua em projetos pagos de adoção e migração."},{"texto":"AWS Partner Network","correta":false,"porque":"Reúne empresas parceiras terceiras, não especialistas da própria AWS."}],"explicacao":"AWS Professional Services: consultores da AWS em projetos pagos. APN: parceiros terceiros. Solutions architects da AWS também orientam clientes no desenho de soluções.","servicos":["Professional Services"],"dificuldade":2,"fonte":"usuario-A15"},{"id":"D4-x-039","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Um cliente quer iniciar 100 instâncias EC2, número que excede a cota padrão da conta. O que ele deve fazer?","alternativas":[{"texto":"Habilitar enhanced networking nas instâncias","correta":false,"porque":"Melhora o desempenho de rede, mas não altera cotas."},{"texto":"Usar o AWS Trusted Advisor para aumentar a cota","correta":false,"porque":"Trusted Advisor só monitora o uso das cotas; não as aumenta."},{"texto":"Aguardar, pois a AWS eleva a cota automaticamente","correta":false,"porque":"O aumento precisa ser solicitado pelo cliente."},{"texto":"Pedir aumento pelo Service Quotas ou no AWS Support Center","correta":true,"porque":"Aumentos de cota são solicitados pelo Service Quotas ou por um caso no Support Center, inclusive no plano Basic."}],"explicacao":"Cotas (limites de serviço) são aumentadas sob solicitação via Service Quotas ou caso no AWS Support Center.","servicos":["Service Quotas","AWS Support"],"dificuldade":1,"fonte":"usuario-A43"},{"id":"D4-x-040","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Qual é o plano do AWS Support de MENOR custo que inclui acesso programático à AWS Support API?","alternativas":[{"texto":"AWS Business Support+","correta":true,"porque":"É o plano mais barato com Support API, casos ilimitados, Trusted Advisor completo e resposta em menos de 30 min para sistema crítico fora do ar."},{"texto":"Basic","correta":false,"porque":"É gratuito, mas não inclui a AWS Support API nem casos técnicos."},{"texto":"AWS Enterprise Support","correta":false,"porque":"Inclui a Support API, mas custa mais (mínimo de US$ 5.000/mês)."},{"texto":"AWS Unified Operations","correta":false,"porque":"É a camada mais alta e cara; inclui a API, mas não é a de menor custo."}],"explicacao":"Na nomenclatura atual (Basic, Business Support+, Enterprise, Unified Operations), Business Support+ é o primeiro com Support API.","servicos":["AWS Support"],"dificuldade":2,"fonte":"usuario-A52 (reescrita)"},{"id":"D4-x-041","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma empresa quer um Technical Account Manager (TAM) designado e o AWS Security Incident Response incluído no plano de suporte, pelo MENOR custo. Qual plano deve escolher?","alternativas":[{"texto":"AWS Business Support+","correta":false,"porque":"Não inclui TAM designado nem o AWS Security Incident Response."},{"texto":"AWS Enterprise Support","correta":true,"porque":"É o plano de menor custo com TAM designado, resposta em 15 min para produção crítica e Security Incident Response."},{"texto":"Basic","correta":false,"porque":"Não oferece casos técnicos, TAM nem resposta a incidentes."},{"texto":"AWS Unified Operations","correta":false,"porque":"Também inclui TAM, mas é a camada mais cara, acima do Enterprise."}],"explicacao":"Enterprise Support: TAM designado, 15 min para caso crítico de produção, Security Incident Response e revisões estratégicas. Unified Operations acrescenta mais especialistas designados.","servicos":["AWS Support"],"dificuldade":2,"fonte":"usuario-A53 (reescrita)"},{"id":"D4-x-042","dominio":4,"task":"4.3","tipo":"unica","enunciado":"No AWS Partner Network (APN), qual tipo de parceiro oferece produtos de software (de ISVs, SaaS e ferramentas de segurança e de gestão) que rodam na AWS ou se integram a ela?","alternativas":[{"texto":"AWS Professional Services","correta":false,"porque":"É a consultoria da própria AWS, não parceiros que vendem software."},{"texto":"Parceiros de serviços (consultorias e system integrators)","correta":false,"porque":"São consultorias e system integrators que prestam serviços, não fornecedores de software."},{"texto":"Parceiros de software (ISVs e fornecedores de SaaS)","correta":true,"porque":"São ISVs e fornecedores de software, SaaS e ferramentas que rodam na AWS ou se integram a ela."},{"texto":"Technical Account Manager","correta":false,"porque":"É o contato técnico designado no Enterprise Support, não um tipo de parceiro."}],"explicacao":"APN: parceiros de software (ISVs, SaaS; antes chamados Technology Partners) x parceiros de serviços (consultorias, system integrators, MSPs; antes Consulting Partners).","servicos":["APN"],"dificuldade":2,"fonte":"usuario-B14"},{"id":"D4-x-043","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma instância EC2 roda sem parar há mais de 30 dias e o custo mensal subiu muito. O responsável quer identificar recursos subutilizados e confirmar se o ambiente segue as boas práticas da AWS. Qual serviço atende aos dois objetivos?","alternativas":[{"texto":"Amazon CloudWatch","correta":false,"porque":"Mostra métricas de uso, mas não compara o ambiente com boas práticas."},{"texto":"AWS Config","correta":false,"porque":"Avalia configurações contra regras, mas não recomenda economia de custos."},{"texto":"AWS Cost Explorer","correta":false,"porque":"Mostra a evolução do custo, mas não verifica boas práticas."},{"texto":"AWS Trusted Advisor","correta":true,"porque":"Aponta instâncias subutilizadas e verifica boas práticas de custo, segurança, performance e mais."}],"explicacao":"Trusted Advisor faz verificações automáticas de boas práticas, incluindo otimização de custos (ex.: instâncias EC2 ociosas).","servicos":["Trusted Advisor"],"dificuldade":2,"fonte":"usuario-B40"},{"id":"D4-x-044","dominio":4,"task":"4.3","tipo":"multipla","selecionar":2,"enunciado":"O AWS Trusted Advisor apresenta verificações de boas práticas em quais destas categorias? (Selecione DUAS.)","alternativas":[{"texto":"Documentação","correta":false,"porque":"Não é uma categoria do Trusted Advisor."},{"texto":"Limites de serviço (Service Limits)","correta":true,"porque":"Alerta quando o uso se aproxima das cotas de serviço."},{"texto":"Elasticidade","correta":false,"porque":"Não é uma categoria do Trusted Advisor."},{"texto":"Gerenciamento de mudanças","correta":false,"porque":"Não é uma categoria do Trusted Advisor."},{"texto":"Otimização de custos","correta":true,"porque":"Identifica recursos ociosos ou subutilizados e oportunidades de economia."}],"explicacao":"Categorias do Trusted Advisor: Cost Optimization, Performance, Security, Fault Tolerance, Service Limits e Operational Excellence.","servicos":["Trusted Advisor"],"dificuldade":1,"fonte":"usuario-B42"},{"id":"D4-x-045","dominio":4,"task":"4.3","tipo":"multipla","selecionar":3,"enunciado":"Quais recursos estão incluídos no plano Basic do AWS Support, disponível para todos os clientes? (Selecione TRÊS.)","alternativas":[{"texto":"Atendimento 24/7 para dúvidas de conta e cobrança","correta":true,"porque":"O Basic inclui atendimento ao cliente para conta e cobrança, além de pedidos de aumento de cota."},{"texto":"Casos técnicos com Cloud Support Engineers","correta":false,"porque":"Casos técnicos começam no Business Support+."},{"texto":"Documentação, whitepapers e AWS re:Post","correta":true,"porque":"Esses recursos de autoatendimento são gratuitos para todos."},{"texto":"Technical Account Manager (TAM) designado","correta":false,"porque":"TAM é exclusivo do Enterprise Support e do Unified Operations."},{"texto":"Verificações principais do AWS Trusted Advisor","correta":true,"porque":"O Basic inclui as verificações principais; o conjunto completo vem no Business Support+."},{"texto":"Acesso à AWS Support API","correta":false,"porque":"A Support API exige Business Support+ ou superior."}],"explicacao":"Basic: conta e cobrança 24/7, aumento de cotas, documentação, whitepapers, re:Post, AWS Health Dashboard e verificações principais do Trusted Advisor; sem casos técnicos.","servicos":["AWS Support","Trusted Advisor"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-046","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Um desenvolvedor no plano Basic quer tirar dúvidas técnicas com a comunidade e com especialistas, em um serviço de perguntas e respostas mantido pela AWS. O que ele deve usar?","alternativas":[{"texto":"AWS re:Post","correta":true,"porque":"É a comunidade gerenciada de perguntas e respostas da AWS, aberta a todos e sem custo."},{"texto":"Technical Account Manager","correta":false,"porque":"Só está disponível nos planos Enterprise e Unified Operations."},{"texto":"AWS Prescriptive Guidance","correta":false,"porque":"Publica estratégias e padrões prontos, não é um fórum de perguntas."},{"texto":"AWS Professional Services","correta":false,"porque":"É consultoria paga por projeto, não um canal de dúvidas da comunidade."}],"explicacao":"AWS re:Post é o fórum de perguntas e respostas da AWS (substituiu os antigos AWS Forums) e inclui o Knowledge Center.","servicos":["re:Post"],"dificuldade":1,"fonte":"kananinirav-k11#42 (reescrita)"},{"id":"D4-x-047","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma equipe procura estratégias, guias e padrões testados pela AWS e por parceiros para acelerar projetos de migração e modernização. Qual recurso atende?","alternativas":[{"texto":"AWS Knowledge Center","correta":false,"porque":"Reúne respostas às dúvidas mais frequentes de clientes ao suporte, não guias de migração."},{"texto":"AWS Prescriptive Guidance","correta":true,"porque":"Oferece estratégias, guias e padrões validados para migração, modernização e otimização."},{"texto":"AWS Health Dashboard","correta":false,"porque":"Informa a saúde dos serviços e eventos da conta."},{"texto":"AWS Artifact","correta":false,"porque":"Fornece relatórios de conformidade e acordos, não guias técnicos."}],"explicacao":"Prescriptive Guidance: estratégias e padrões prontos. Knowledge Center: respostas a perguntas frequentes. Whitepapers, documentação e blogs completam as fontes técnicas.","servicos":["Prescriptive Guidance"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-048","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma empresa está recebendo spam e tentativas de ataque vindas de endereços IP que pertencem à AWS. O que ela deve fazer?","alternativas":[{"texto":"Habilitar o AWS Shield Advanced na própria conta","correta":false,"porque":"Protege contra DDoS, mas não comunica à AWS o abuso cometido por outro cliente."},{"texto":"Registrar o problema no AWS Health Dashboard","correta":false,"porque":"O Health Dashboard só informa eventos; não recebe denúncias."},{"texto":"Denunciar o abuso à equipe AWS Trust & Safety","correta":true,"porque":"É a equipe que recebe denúncias de uso abusivo de recursos da AWS, como spam e ataques."},{"texto":"Pedir a um solutions architect da AWS que bloqueie a origem","correta":false,"porque":"Solutions architects orientam o desenho de soluções, não tratam denúncias de abuso."}],"explicacao":"Abuso vindo de recursos da AWS (spam, varredura, DDoS, conteúdo ilegal) deve ser denunciado ao AWS Trust & Safety.","servicos":["Trust & Safety"],"dificuldade":2,"fonte":"autoral"},{"id":"D4-x-049","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma empresa quer comprar software de terceiros que roda na AWS, pagar por ele na própria fatura da AWS e controlar centralmente quais produtos e licenças (entitlements) as equipes podem usar. Qual recurso atende?","alternativas":[{"texto":"AWS Service Catalog","correta":false,"porque":"Publica produtos internos aprovados, mas não vende software de terceiros."},{"texto":"AWS License Manager","correta":false,"porque":"Acompanha o uso de licenças, mas não é um canal de compra de software."},{"texto":"AWS Professional Services","correta":false,"porque":"É consultoria da AWS, não loja de software."},{"texto":"AWS Marketplace","correta":true,"porque":"Catálogo de software de terceiros com cobrança na fatura AWS, gestão de entitlements e Private Marketplace para governança."}],"explicacao":"AWS Marketplace: comprar software de terceiros com cobrança consolidada, controle de licenças (entitlement) e governança via Private Marketplace.","servicos":["Marketplace"],"dificuldade":3,"fonte":"autoral"},{"id":"D4-x-050","dominio":4,"task":"4.3","tipo":"unica","enunciado":"Uma consultoria (system integrator) que ajuda clientes a migrar para a AWS quer acesso a treinamentos, eventos e programas de incentivo da AWS e ser encontrada por novos clientes. O que ela deve fazer?","alternativas":[{"texto":"Ingressar no AWS Partner Network (APN)","correta":true,"porque":"O APN oferece treinamento, benefícios de marketing, eventos, financiamento e visibilidade para parceiros."},{"texto":"Contratar o AWS Professional Services","correta":false,"porque":"É a consultoria da própria AWS; não dá benefícios de parceiro."},{"texto":"Assinar o AWS Enterprise Support","correta":false,"porque":"É um plano de suporte técnico, não um programa de parceiros."},{"texto":"Publicar respostas no AWS re:Post","correta":false,"porque":"Contribui com a comunidade, mas não dá benefícios de parceiro."}],"explicacao":"APN reúne parceiros de serviços (system integrators, MSPs) e parceiros de software (ISVs), com benefícios como treinamento, eventos, descontos e marketing.","servicos":["APN"],"dificuldade":2,"fonte":"autoral"}];
